// ── Story engine ──────────────────────────────────────────────────────────────
// A scenario is a set of named scenes. A scene narrates, asks for a roll, and
// branches on the outcome; an ending stops the run and hands out rewards.
//
// Branches key off the same bands as a `?` success check, so a story reads the
// way the rest of the bot already rolls. Merits are awarded automatically to
// everyone who took part; anything else a GM writes is announced for them to
// hand out by hand, exactly as quest rewards work — that way an ending can give
// "2 merits" or "a tarnished silver key" without the bot needing to model items.
const STORY_BANDS = ['CRIT', 'PASS', 'PARTIAL', 'FAIL', 'FUMBLE'];
const STORY_BAND_LABEL = { CRIT: '🌟 Critical Success', PASS: '✅ Success', PARTIAL: '⚡ Partial Success', FAIL: '❌ Fail', FUMBLE: '💀 Critical Fail' };

// Map a rolled result onto a branch, falling back sensibly when a story doesn't
// define every band: a crit reads as a pass, a fumble as a fail.
function storyBandFor(outcomes, total, nat, sides) {
  const res = getSuccessResult(total, nat, sides);
  const order = res.crit === 'crit' ? ['CRIT', 'PASS']
              : res.crit === 'fail' ? ['FUMBLE', 'FAIL']
              : res.label === 'Success' ? ['PASS']
              : res.label === 'Partial Success' ? ['PARTIAL', 'PASS']
              : ['FAIL'];
  for (const b of order) if (outcomes[b]) return { band: b, res };
  return { band: null, res };
}

function getStory(gid, name) {
  return db.prepare('SELECT * FROM stories WHERE guild_id=? AND name=? COLLATE NOCASE').get(gid, name);
}
function listStories(gid) {
  return db.prepare('SELECT * FROM stories WHERE guild_id=? ORDER BY name').all(gid);
}
function getScene(gid, story, scene) {
  return db.prepare('SELECT * FROM story_scenes WHERE guild_id=? AND story=? COLLATE NOCASE AND scene=? COLLATE NOCASE').get(gid, story, scene);
}
function listScenes(gid, story) {
  return db.prepare('SELECT * FROM story_scenes WHERE guild_id=? AND story=? COLLATE NOCASE ORDER BY ord').all(gid, story);
}
function deleteStory(gid, name) {
  db.prepare('DELETE FROM story_scenes WHERE guild_id=? AND story=? COLLATE NOCASE').run(gid, name);
  return db.prepare('DELETE FROM stories WHERE guild_id=? AND name=? COLLATE NOCASE').run(gid, name).changes > 0;
}
function getRun(gid, cid, uid) {
  return db.prepare('SELECT * FROM story_runs WHERE guild_id=? AND channel_id=? AND user_id=?').get(gid, cid, uid);
}
function setRun(gid, cid, uid, fields) {
  if (!getRun(gid, cid, uid)) {
    db.prepare('INSERT INTO story_runs (guild_id, channel_id, user_id, story, scene) VALUES (?,?,?,?,?)')
      .run(gid, cid, uid, fields.story ?? '', fields.scene ?? '');
  }
  const keys = Object.keys(fields || {});
  if (keys.length) db.prepare(`UPDATE story_runs SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND channel_id=? AND user_id=?`)
    .run(...keys.map(k => fields[k]), gid, cid, uid);
  return getRun(gid, cid, uid);
}
// Claim a run before acting on it. Two clicks land as two separate handler
// invocations, and the second can start while the first is awaiting Discord —
// without this, a double-tap spends two rerolls and advances the tale twice.
// The UPDATE is the claim: SQLite reports how many rows it changed, so exactly
// one caller can ever win.
function claimRun(gid, cid, uid) {
  return db.prepare('UPDATE story_runs SET busy=1 WHERE guild_id=? AND channel_id=? AND user_id=? AND busy=0')
    .run(gid, cid, uid).changes === 1;
}
function releaseRun(gid, cid, uid) {
  db.prepare('UPDATE story_runs SET busy=0 WHERE guild_id=? AND channel_id=? AND user_id=?').run(gid, cid, uid);
}

// A looping activity is the point — fishing should be repeatable — but nothing
// should loop for ever. This bounds a single run so a stuck script, or someone
// tapping Carry on for an hour, can't spin without end or bank a tally
// indefinitely.
const ACTIVITY_MAX_STEPS = 200;

function endRun(gid, cid, uid) {
  db.prepare('DELETE FROM story_runs WHERE guild_id=? AND channel_id=? AND user_id=?').run(gid, cid, uid);
}
// Everyone currently playing in this channel — used by /activity stop and to
// tell a GM what is in flight.
function runsIn(gid, cid) {
  return db.prepare('SELECT * FROM story_runs WHERE guild_id=? AND channel_id=?').all(gid, cid);
}

// Parse a pasted activity script. Returns { name, start, tally, scenes[] }
// or { error }. The format grew out of a fishing loop, so it has to express:
// difficulty classes, ranges on the natural die, a random pick between flavour
// lines, a run of descending rolls, natural-20/1 overrides, plain button
// choices with no roll at all, and a tally that accumulates across a loop and
// cashes out at the end.
// Parse + validate + store in one motion; every authoring route — chat
// paste, /activity create modal, or an attached .txt — lands here.
function storeActivityScript(gid, uid, text) {
  const parsed = parseStoryScript(text);
  if (parsed.error) return { error: parsed.error };
  const count = saveStory(gid, uid, parsed);
  return { name: parsed.name, saved: [`🎮 **${parsed.name}** saved — **${count}** scene${count === 1 ? '' : 's'}, starting at \`${parsed.start}\`.`,
    `Run it with \`/activity run name:${parsed.name}\`, or read it back with \`/activity show name:${parsed.name}\`.`].join('\n') };
}

function parseStoryScript(text) {
  const lines = String(text || '').split(/\r?\n/);
  const head = lines.findIndex(l => /^\s*\[(STORY|ACTIVITY)\]/i.test(l));
  if (head === -1) return { error: 'No `[ACTIVITY] Name` line found.' };
  const name = lines[head].replace(/^\s*\[(STORY|ACTIVITY)\]\s*/i, '').trim();
  if (!name) return { error: 'Give it a name on the `[ACTIVITY]` line.' };

  const scenes = [];
  let cur = null, tally = null, oneOfInto = null;
  const flush = () => { if (cur) { cur.say = (cur.say || '').trim(); scenes.push(cur); } cur = null; oneOfInto = null; };

  for (const raw of lines.slice(head + 1)) {
    const line = raw.trim();
    if (!line) { oneOfInto = null; continue; }
    let m;

    if ((m = line.match(/^TALLY\s+(\w+)/i))) { tally = m[1].toLowerCase(); continue; }

    if ((m = line.match(/^SCENE\s+(\S+)/i))) {
      flush();
      cur = { scene: m[1], say: '', npc: null, roll: null, dc: null, gauntlet: null,
              outcomes: {}, ranges: [], choices: [], gain: 0, nat20: null, nat1: null,
              ending: 0, merits: 0, rewards: null, cashTally: 0 };
      continue;
    }
    if (!cur) continue;

    // A bare line while collecting a ONE OF block is another flavour variant.
    // A bare line inside a ONE OF block is another variant — but a band name
    // ends the block, so `FAIL -> find` after `FAIL ONE OF` still branches.
    if (oneOfInto && !new RegExp(`^(SAY|AS|ROLL|GAUNTLET|CHOICE|GAIN|END|NAT20|NAT1|SCENE|TALLY|${STORY_BANDS.join('|')}|\\d)\\b`, 'i').test(line)) {
      oneOfInto.push(line); continue;
    }
    oneOfInto = null;

    if ((m = line.match(/^SAY\s+([\s\S]*)$/i)))  { cur.say += (cur.say ? '\n' : '') + m[1]; continue; }
    if ((m = line.match(/^AS\s+(.+)$/i)))        { cur.npc = m[1].trim(); continue; }

    // ROLL str|dex|wis DC15   — the roller picks from the offered stats.
    if ((m = line.match(/^ROLL\s+([a-z|]+)(?:\s+DC\s*(\d+))?\s*$/i))) {
      cur.roll = m[1].toLowerCase();
      if (m[2]) cur.dc = parseInt(m[2]);
      continue;
    }
    // A run of rolls, each with its own DC. Two forms:
    //   GAUNTLET str|con 14 12 10           same stats every step
    //   GAUNTLET 14:str 12:str|con 10:dex   a different check each step
    if ((m = line.match(/^GAUNTLET\s+([a-z|]+)\s+([\d\s]+)$/i))) {
      cur.roll = m[1].toLowerCase();
      cur.gauntlet = m[2].trim().split(/\s+/).map(Number).filter(Number.isFinite)
        .map(dc => ({ dc, stats: cur.roll }));
      continue;
    }
    if ((m = line.match(/^GAUNTLET\s+((?:\d+:[a-z|]+\s*)+)$/i))) {
      cur.gauntlet = m[1].trim().split(/\s+/).map(tok => {
        const [dc, stats] = tok.split(':');
        return { dc: parseInt(dc), stats: String(stats || '').toLowerCase() };
      });
      // The scene's roll line becomes the union, so validation and `show` have
      // something to work from even when every step differs.
      cur.roll = [...new Set(cur.gauntlet.flatMap(g => g.stats.split('|')))].join('|');
      continue;
    }
    if ((m = line.match(/^GAIN\s+(\w+)\s+(-?\d+)/i))) {
      if (tally && m[1].toLowerCase() !== tally) return { error: `\`GAIN ${m[1]}\` but the tally is called \`${tally}\`.` };
      cur.gain = parseInt(m[2]); continue;
    }
    if (/^CHOICE\s*$/i.test(line)) { cur.isChoice = true; continue; }
    if (cur.isChoice && (m = line.match(/^(.+?)\s*->\s*(\S+)\s*$/))) {
      cur.choices.push({ label: m[1].trim(), next: m[2] }); continue;
    }
    if ((m = line.match(/^NAT20\s+(.*?)\s*->\s*(\S+)\s*$/i))) { cur.nat20 = { text: m[1].trim(), next: m[2] }; continue; }
    if ((m = line.match(/^NAT1\s+(.*?)\s*->\s*(\S+)\s*$/i)))  { cur.nat1  = { text: m[1].trim(), next: m[2] }; continue; }

    if ((m = line.match(/^END\b\s*(.*)$/i))) {
      cur.ending = 1;
      let rest = m[1] || '';
      if (/TALLY/i.test(rest)) { cur.cashTally = 1; rest = rest.replace(/TALLY\s*\w*/i, ''); }
      const mm = rest.match(/merits:\s*(\d+)/i);
      if (mm) cur.merits = parseInt(mm[1]);
      const rw = rest.replace(/merits:\s*\d+/i, '').replace(/^\s*rewards:\s*/i, '').trim();
      if (rw) cur.rewards = rw;
      continue;
    }

    // Numeric range on the natural die: "1-5 Small fry. -> fight_small"
    if ((m = line.match(/^(\d+)\s*(?:-|–|to)\s*(\d+|\+)?\s*(.*?)\s*->\s*(\S+)\s*$/i))
        || (m = line.match(/^(\d+)\s*(\+)\s*(.*?)\s*->\s*(\S+)\s*$/))) {
      const lo = parseInt(m[1]);
      // 9999 rather than Infinity: this is stored as JSON, and JSON has no way
      // to represent Infinity — it serialises to null and the range dies.
      const hi = (!m[2] || m[2] === '+') ? 9999 : parseInt(m[2]);
      cur.ranges.push({ lo, hi, text: (m[3] || '').trim(), next: m[4] });
      continue;
    }

    // Band outcome, optionally opening a ONE OF block of flavour variants.
    if ((m = line.match(new RegExp(`^(${STORY_BANDS.join('|')})\\s+ONE OF\\s*$`, 'i')))) {
      const band = m[1].toUpperCase();
      cur.outcomes[band] = cur.outcomes[band] || { text: '', variants: [], next: null };
      oneOfInto = (cur.outcomes[band].variants = cur.outcomes[band].variants || []);
      continue;
    }
    if ((m = line.match(new RegExp(`^(${STORY_BANDS.join('|')})\\s*->\\s*(\\S+)\\s*$`, 'i')))) {
      const band = m[1].toUpperCase();
      cur.outcomes[band] = Object.assign(cur.outcomes[band] || { text: '', variants: [] }, { next: m[2] });
      continue;
    }
    if ((m = line.match(new RegExp(`^(${STORY_BANDS.join('|')})\\s+([\\s\\S]*?)\\s*->\\s*(\\S+)\\s*$`, 'i')))) {
      const band = m[1].toUpperCase();
      cur.outcomes[band] = Object.assign(cur.outcomes[band] || { variants: [] },
        { text: m[2].trim(), next: m[3] });
      continue;
    }
    cur.say += (cur.say ? '\n' : '') + line;
  }
  flush();

  if (!scenes.length) return { error: 'No `SCENE` blocks found.' };
  const names = scenes.map(sc => sc.scene.toLowerCase());
  const dupe = names.find((v, i) => names.indexOf(v) !== i);
  if (dupe) return { error: `Two scenes are both called \`${dupe}\`.` };

  const targets = (sc) => [
    ...Object.values(sc.outcomes).map(o => o.next),
    ...sc.ranges.map(r => r.next), ...sc.choices.map(c => c.next),
    sc.nat20?.next, sc.nat1?.next,
  ].filter(Boolean);

  for (const sc of scenes) {
    for (const t of targets(sc)) {
      if (!names.includes(String(t).toLowerCase())) {
        return { error: `Scene \`${sc.scene}\` points at \`${t}\`, which doesn't exist.` };
      }
    }
    const asks = sc.roll || sc.choices.length;
    if (!sc.ending && !asks) return { error: `Scene \`${sc.scene}\` has no \`ROLL\`, \`CHOICE\` or \`END\` — a run would stop there.` };
    if (sc.roll && !targets(sc).length) return { error: `Scene \`${sc.scene}\` asks for a roll but nothing follows it.` };
    if (sc.isChoice && !sc.choices.length) return { error: `Scene \`${sc.scene}\` has a \`CHOICE\` with no options.` };
    if (sc.gauntlet && sc.gauntlet.length > 8) return { error: `Scene \`${sc.scene}\` has a gauntlet of ${sc.gauntlet.length} rolls — 8 is the most.` };
    for (const g of (sc.gauntlet || [])) {
      if (!Number.isFinite(g.dc)) return { error: `Scene \`${sc.scene}\` has a gauntlet step with no DC.` };
      for (const st of String(g.stats || '').split('|').filter(Boolean)) {
        if (!resolveStatWord(st)) return { error: `Scene \`${sc.scene}\` rolls \`${st}\` in its gauntlet, which isn't a stat.` };
      }
    }
    for (const st of String(sc.roll || '').split('|').filter(Boolean)) {
      if (!resolveStatWord(st) && !/^\d+d\d+/.test(st)) return { error: `Scene \`${sc.scene}\` rolls \`${st}\`, which isn't a stat.` };
    }
  }
  if (scenes.some(sc => sc.cashTally || sc.gain) && !tally) {
    return { error: 'Add a `TALLY renown` line at the top — a scene gains or cashes out a tally that has no name.' };
  }
  return { name, start: scenes[0].scene, tally, scenes };
}

// Change one part of one scene without re-pasting the whole activity. Values
// use the same grammar as the script itself, so a GM edits with the syntax they
// already wrote in — and every branch target is checked before anything saves,
// exactly as a full paste is, so an edit can't strand a run.
function applySceneEdit(gid, story, scene, field, raw) {
  const sc = getScene(gid, story, scene);
  if (!sc) return { error: `**${story}** has no scene \`${scene}\`.` };
  const value = String(raw ?? '').trim();
  const names = listScenes(gid, story).map(x => x.scene.toLowerCase());
  const target = (t) => names.includes(String(t).toLowerCase());
  const clearing = /^(none|clear|off|-)$/i.test(value);
  const upd = {};

  const arrow = (v) => {
    const m = v.match(/^([\s\S]*?)\s*->\s*(\S+)$/);
    return m ? { text: m[1].trim(), next: m[2] } : null;
  };

  switch (field) {
    case 'dc': {
      if (clearing) { upd.dc = null; break; }
      if (!/^\d+$/.test(value)) return { error: 'A DC must be a whole number, or `none` to remove it.' };
      upd.dc = parseInt(value); break;
    }
    case 'gauntlet': {
      if (clearing) { upd.gauntlet = null; break; }
      let g = null;
      let m = value.match(/^([a-z|]+)\s+([\d\s]+)$/i);
      if (m) g = m[2].trim().split(/\s+/).map(Number).filter(Number.isFinite).map(dc => ({ dc, stats: m[1].toLowerCase() }));
      else if (/^(?:\d+:[a-z|]+\s*)+$/i.test(value)) {
        g = value.trim().split(/\s+/).map(tok => { const [dc, st] = tok.split(':'); return { dc: parseInt(dc), stats: String(st).toLowerCase() }; });
      }
      if (!g || !g.length) return { error: 'Write it as `str|con 14 12 10` or `14:str 12:str|con 10:con`.' };
      if (g.length > 8) return { error: 'Eight rolls is the most a gauntlet can have.' };
      for (const step of g) for (const st of step.stats.split('|')) {
        if (!resolveStatWord(st)) return { error: `\`${st}\` isn't a stat.` };
      }
      upd.gauntlet = JSON.stringify(g);
      upd.roll = [...new Set(g.flatMap(x => x.stats.split('|')))].join('|');
      break;
    }
    case 'outcome': {
      const m = value.match(new RegExp(`^(${STORY_BANDS.join('|')})\\s+([\\s\\S]*)$`, 'i'));
      if (!m) return { error: `Write it as \`PASS some text -> scene\` (bands: ${STORY_BANDS.join(', ')}).` };
      const band = m[1].toUpperCase();
      const outcomes = JSON.parse(sc.outcomes || '{}');
      if (/^(none|clear|off|-)$/i.test(m[2].trim())) { delete outcomes[band]; upd.outcomes = JSON.stringify(outcomes); break; }
      const a = arrow(m[2]);
      if (!a) return { error: 'Missing the `-> scene` part.' };
      if (!target(a.next)) return { error: `There is no scene \`${a.next}\`.` };
      outcomes[band] = Object.assign(outcomes[band] || { variants: [] }, { text: a.text, next: a.next });
      upd.outcomes = JSON.stringify(outcomes); break;
    }
    case 'range': {
      if (clearing) { upd.ranges = '[]'; break; }
      const m = value.match(/^(\d+)\s*(?:-|–|to)?\s*(\d+|\+)?\s*([\s\S]*)$/);
      if (!m) return { error: 'Write it as `1-5 some text -> scene`, or `16+ text -> scene`.' };
      const a = arrow(m[3] || '');
      if (!a) return { error: 'Missing the `-> scene` part.' };
      if (!target(a.next)) return { error: `There is no scene \`${a.next}\`.` };
      const lo = parseInt(m[1]);
      const hi = (!m[2] || m[2] === '+') ? 9999 : parseInt(m[2]);
      const ranges = JSON.parse(sc.ranges || '[]').filter(r => r.lo !== lo);
      ranges.push({ lo, hi, text: a.text, next: a.next });
      ranges.sort((x, y) => x.lo - y.lo);
      upd.ranges = JSON.stringify(ranges); break;
    }
    case 'choice': {
      if (clearing) { upd.choices = '[]'; break; }
      const a = arrow(value);
      if (!a || !a.text) return { error: 'Write it as `Carry on -> scene`.' };
      if (!target(a.next)) return { error: `There is no scene \`${a.next}\`.` };
      const choices = JSON.parse(sc.choices || '[]').filter(c => c.label.toLowerCase() !== a.text.toLowerCase());
      choices.push({ label: a.text, next: a.next });
      if (choices.length > 5) return { error: 'Five options is the most a choice can offer.' };
      upd.choices = JSON.stringify(choices); break;
    }
    case 'nat20': case 'nat1': {
      if (clearing) { upd[field] = null; break; }
      const a = arrow(value);
      if (!a) return { error: 'Write it as `some text -> scene`.' };
      if (!target(a.next)) return { error: `There is no scene \`${a.next}\`.` };
      upd[field] = JSON.stringify(a); break;
    }
    case 'gain': {
      if (!/^-?\d+$/.test(value)) return { error: 'A gain must be a whole number.' };
      upd.gain = parseInt(value); break;
    }
    case 'say': case 'npc': case 'roll': case 'rewards':
      upd[field] = clearing ? null : value; break;
    case 'merits': {
      if (!/^\d+$/.test(value)) return { error: 'Merits must be a whole number.' };
      upd.merits = parseInt(value); break;
    }
    default: return { error: `Don't know how to change \`${field}\`.` };
  }

  const keys = Object.keys(upd);
  db.prepare(`UPDATE story_scenes SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND story=? COLLATE NOCASE AND scene=? COLLATE NOCASE`)
    .run(...keys.map(k => upd[k]), gid, story, sc.scene);
  return { scene: sc.scene, changed: keys };
}

function saveStory(gid, uid, parsed) {
  db.prepare('DELETE FROM story_scenes WHERE guild_id=? AND story=? COLLATE NOCASE').run(gid, parsed.name);
  db.prepare(`INSERT INTO stories (guild_id, name, author_id, start_scene, tally, created_at) VALUES (?,?,?,?,?,?)
              ON CONFLICT(guild_id, name) DO UPDATE SET author_id=excluded.author_id, start_scene=excluded.start_scene, tally=excluded.tally`)
    .run(gid, parsed.name, uid, parsed.start, parsed.tally ?? null, Date.now());
  const ins = db.prepare(`INSERT INTO story_scenes
    (guild_id, story, scene, say, npc, roll, dc, outcomes, ranges, choices, gauntlet, nat20, nat1, gain, cash_tally, ending, merits, rewards, ord)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`);
  parsed.scenes.forEach((sc, i) => ins.run(gid, parsed.name, sc.scene, sc.say || null, sc.npc, sc.roll, sc.dc ?? null,
    JSON.stringify(sc.outcomes), JSON.stringify(sc.ranges || []), JSON.stringify(sc.choices || []),
    sc.gauntlet ? JSON.stringify(sc.gauntlet) : null,
    sc.nat20 ? JSON.stringify(sc.nat20) : null, sc.nat1 ? JSON.stringify(sc.nat1) : null,
    sc.gain || 0, sc.cashTally || 0, sc.ending, sc.merits, sc.rewards, i));
  return listScenes(gid, parsed.name).length;
}

// Render one scene: narration, then whatever it asks for — a roll (with the
// stats it accepts), a plain choice of buttons, or an ending.
async function postScene(guild, cid, run, sc) {
  const gid = guild.id;
  const owner = run.user_id;
  const ownerName = await getDisplayName(guild, owner);
  const channel = await guild.client.channels.fetch(cid);
  const lines = [];
  if (sc.say) lines.push(sc.say);

  if (sc.npc && sc.say) {
    // Speak in the NPC's voice where the script asked for one; if that NPC has
    // no webhook the narration just stays in the bot's own voice.
    try {
      const npc = getNpc(gid, sc.npc);
      const hook = await npcWebhookIn(channel, gid, sc.npc, npcFace(gid, npc));
      if (hook) { await hook.send({ content: sc.say }); lines.length = 0; }
    } catch (err) { console.error('[activity] npc voice failed:', err?.message || err); }
  }

  const story = getStory(gid, run.story);
  const tallyName = story?.tally || null;
  const tallyState = JSON.parse(run.tally_state || '{}');

  if (sc.ending) {
    lines.push('', '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    // The tally belongs to whoever played this run.
    const cashing = !!(sc.cash_tally && tallyName);
    const banked = cashing ? (tallyState[owner] || 0) : 0;
    // Coming home empty-handed from a trip that pays out earns nothing at all —
    // not the rewards, and not the merits for turning up. An ending that has no
    // tally to cash still awards its merits, since there was nothing to catch.
    const emptyHanded = cashing && banked === 0;

    if (sc.merits > 0 && !emptyHanded) {
      addMerits(gid, owner, sc.merits);
      lines.push(`🏅 **${sc.merits} merit${sc.merits === 1 ? '' : 's'}** to <@${owner}>.`);
    }
    if (cashing) {
      if (banked) {
        const bal = addRenown(gid, owner, banked, `${run.story}`);
        lines.push(`💠 **${tallyName}** earned — <@${owner}> **+${banked}**${bal !== null ? ` (now ${bal})` : ''}`);
      } else {
        lines.push(`💠 Nothing to show for it — no ${tallyName}${sc.merits > 0 ? ' and no merits' : ''} this time.`);
      }
    }
    if (sc.rewards && !emptyHanded) lines.push(`🎁 **For the GM to hand out:** ${sc.rewards}`);
    endRun(gid, cid, owner);
    await sendLong(channel, [`🎮 **${ownerName}**`, ...lines]);
    return;
  }

  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  const choices = JSON.parse(sc.choices || '[]');
  if (choices.length) {
    const row = new ActionRowBuilder().addComponents(...choices.slice(0, 5).map((c, k) =>
      new ButtonBuilder().setCustomId(`storypick:${owner}:${sc.scene}:${k}`).setLabel(c.label.slice(0, 78)).setStyle(ButtonStyle.Secondary)));
    await postWithButtons(channel, [`🎮 **${ownerName}**`, ...lines], row);
    return;
  }

  // A roll. Offer one button per stat the scene accepts, and say what's needed.
  const gauntlet = sc.gauntlet ? JSON.parse(sc.gauntlet) : null;
  let stepStats = String(sc.roll || '');
  if (gauntlet) {
    const step = Number(run.gauntlet_at) || 0;
    const g = gauntlet[step] || {};
    lines.push('', `🎣 **Keep at it** — roll ${step + 1} of ${gauntlet.length}, **DC ${g.dc}**.`);
    stepStats = String(g.stats || sc.roll || '');
  } else if (sc.dc) {
    lines.push('', `🎲 Roll **DC ${sc.dc}**.`);
  } else {
    lines.push('', '🎲 Roll.');
  }
  const stats = stepStats.split('|').filter(Boolean);
  const names = stats.map(x => (resolveStatWord(x) || x).toUpperCase());
  lines.push(`_<@${owner}> — press a button, or type **${names[0].toLowerCase()}** and add your own flavour `
    + `after it: \`${names[0].toLowerCase()} I cast into the deep pools\`._`
    + (names.length > 1 ? `\n_This step takes ${names.join(', ')}._` : ''));
  const row = new ActionRowBuilder().addComponents(...stats.slice(0, 5).map(st =>
    new ButtonBuilder().setCustomId(`storyroll:${owner}:${sc.scene}:${st}`)
      .setLabel(`Roll ${(resolveStatWord(st) || st).toUpperCase()}`).setStyle(ButtonStyle.Primary)));
  await postWithButtons(channel, [`🎮 **${ownerName}**`, ...lines], row);
}

// Send the narration, hanging the buttons off the final chunk.
async function postWithButtons(channel, lines, row) {
  const chunks = chunkLines(lines.length ? lines : ['…']);
  for (const c of chunks.slice(0, -1)) await channel.send(c).catch(()=>{});
  await channel.send({ content: chunks[chunks.length - 1], components: [row] }).catch(()=>{});
}

// Shared guard: is there a live run here, still on the scene this button came
// from, and may this person take part?
function activeSceneFor(interaction, owner, sceneName) {
  const gid = interaction.guild.id, cid = interactionChannelId(interaction), uid = interaction.user.id;
  // Runs are per-player, so a button only answers for the person it belongs to.
  // Everyone can watch; only its owner can act on it.
  if (owner && owner !== uid) return { error: '🎮 That is someone else\'s run. Start your own with `/activity run`.' };
  const run = getRun(gid, cid, uid);
  if (!run) return { error: '❌ You have nothing running here. Start one with `/activity run`.' };
  if (String(run.scene).toLowerCase() !== String(sceneName).toLowerCase()) {
    return { error: '⏰ That moment has already passed.' };
  }
  const gate = sheetGate(gid, uid);
  if (gate) return { error: gate };
  const ch = getChar(gid, uid);
  if (!ch) return { error: '❌ You need a character sheet to take part — `/char create`.' };
  const sc = getScene(gid, run.story, run.scene);
  if (!sc) { endRun(gid, cid, uid); return { error: '❌ That scene has gone missing; the run has stopped.' }; }
  return { gid, cid, uid, run, ch, sc };
}

async function advance(io, ctx, nextName, tallyState, gauntletAt = 0) {
  const { gid, cid, uid, run } = ctx;
  const next = getScene(gid, run.story, nextName);
  if (!next) { endRun(gid, cid, uid); return; }

  // A looping activity is the point, but nothing loops for ever. Past the cap
  // the run is closed out where it stands — the tally still pays, so a long
  // honest session isn't punished, but a script that can't reach an ending and
  // someone tapping a button all afternoon both stop here.
  const steps = (Number(run.steps) || 0) + 1;
  if (steps > ACTIVITY_MAX_STEPS) {
    const story = getStory(gid, run.story);
    const banked = tallyState[uid] || 0;
    if (banked && story?.tally) addRenown(gid, uid, banked, `${run.story} (ran long)`);
    endRun(gid, cid, uid);
    try {
      const ch = await io.guild.client.channels.fetch(cid);
      await ch?.send(`🛑 **${run.story}** has run ${ACTIVITY_MAX_STEPS} scenes and been closed out.`
        + (banked ? ` <@${uid}> keeps **${banked}** ${story.tally}.` : ''));
    } catch {}
    return;
  }

  // Credit the arriving scene's GAIN to whoever got them there.
  if (next.gain) tallyState[uid] = (tallyState[uid] || 0) + next.gain;
  const updated = setRun(gid, cid, uid, { scene: next.scene,
    tally_state: JSON.stringify(tallyState), gauntlet_at: gauntletAt, steps });
  await new Promise(r => setTimeout(r, 900));
  await postScene(io.guild, cid, updated, next);
}

// A plain choice — no dice, just a fork.
async function handleStoryPickButton(interaction) {
  const [, owner, sceneName, idx] = interaction.customId.split(':');
  const ctx = activeSceneFor(interaction, owner, sceneName);
  if (ctx.error) return interaction.reply({ content: ctx.error, ephemeral: true });
  if (!claimRun(ctx.gid, ctx.cid, ctx.uid)) return interaction.reply({ content: '⏳ Still working on your last one.', ephemeral: true });
  const choices = JSON.parse(ctx.sc.choices || '[]');
  const pick = choices[Number(idx)];
  if (!pick) return interaction.reply({ content: '❌ That option has gone.', ephemeral: true });
  const name = await getDisplayName(interaction.guild, ctx.uid);
  await interaction.reply({ content: `➡️ **${name}** — ${pick.label}` });
  try { await interaction.message.edit({ components: [] }); } catch {}
  try {
    await advance({ guild: interaction.guild }, ctx, pick.next, JSON.parse(ctx.run.tally_state || '{}'), 0);
  } finally { releaseRun(ctx.gid, ctx.cid, ctx.uid); }
}

// A roll. Anyone in the channel may answer; the only gate is that the run is
// still on this scene.
// The stats a scene will accept right now — a gauntlet narrows to the current
// step, everything else offers whatever the ROLL line listed.
function sceneStats(sc, run) {
  const g = sc.gauntlet ? JSON.parse(sc.gauntlet) : null;
  if (g) return String(g[Number(run.gauntlet_at) || 0]?.stats || sc.roll || '').split('|').filter(Boolean);
  return String(sc.roll || '').split('|').filter(Boolean);
}

// A compact sheet line, so a reader can see where the modifier came from
// without the full card being reprinted on every roll of a loop.
// Roll card modes. Kept on profile_enabled so nothing needed migrating:
// 0 = off, 1 = full (the long-standing default), 2 = compressed.
const CARD_OFF = 0, CARD_FULL = 1, CARD_COMPACT = 2;
function cardMode(ch) {
  // NULL and undefined both mean "never chose" and must read as the long-standing
  // default. Coercing first would turn a NULL into 0 and silently switch an old
  // character's card off.
  const raw = ch?.profile_enabled;
  if (raw === null || raw === undefined || raw === '') return CARD_FULL;
  const v = Number(raw);
  return v === CARD_COMPACT ? CARD_COMPACT : v === CARD_OFF ? CARD_OFF : CARD_FULL;
}
const CARD_NAME = { [CARD_OFF]: 'Off', [CARD_FULL]: 'Full', [CARD_COMPACT]: 'Compressed' };

function statLine(ch, gid) {
  return `💪 ${ch.str ?? 0} · 🫀 ${ch.con ?? 0} · ⚡ ${ch.dex ?? 0} · 🧠 ${ch.wis ?? 0} · 🍀 ${ch.lck ?? 0}`
    + `  ·  ❤️ ${ch.hp_current ?? 0}/${maxHp(ch, gid)}  ·  🔄 ${ch.rerolls_current ?? 0}/${maxRerolls(ch)}`;
}

// Spend a reroll on the result just posted. One per roll — the reroll's own
// result stands, so this button is never offered again for it.
async function handleStoryRerollButton(interaction) {
  const [, owner, scene, statWord, next, gaAt] = interaction.customId.split(':');
  const ctx = activeSceneFor(interaction, owner, scene);
  if (ctx.error) return interaction.reply({ content: ctx.error, ephemeral: true });
  const { gid, cid, uid, ch, run } = ctx;
  if (!claimRun(gid, cid, uid)) return interaction.reply({ content: '⏳ Still working on your last one.', ephemeral: true });
  // A demo is a dry run — it should not quietly drain a player's real rerolls
  // just because they wanted to see what the button does.
  const dry = !!run?.is_demo;
  if (!dry) {
    if ((ch.rerolls_current ?? 0) <= 0) return interaction.reply({ content: '❌ No rerolls remaining.', ephemeral: true });
    upsertChar(gid, uid, { rerolls_current: ch.rerolls_current - 1 });
  }
  try { await interaction.message.edit({ components: [] }); } catch {}
  const fresh = { ...ctx, ch: getChar(gid, uid) };
  try {
    return await resolveActivityRoll(fresh, statWord, null, {
      guild: interaction.guild,
      reply: async (c) => { await interaction.reply(asPayload(c)); },
      interaction,
    }, true);
  } finally { releaseRun(gid, cid, uid); }
}

// Take the result as it stands and move on.
async function handleStoryCarryOnButton(interaction) {
  const [, owner, next, gaAt] = interaction.customId.split(':');
  const gid = interaction.guild.id, cid = interactionChannelId(interaction), uid = interaction.user.id;
  if (owner !== uid) return interaction.reply({ content: '🎮 That is someone else\'s run.', ephemeral: true });
  const run = getRun(gid, cid, uid);
  if (!run) return interaction.reply({ content: '❌ You have nothing running here.', ephemeral: true });
  const sc = getScene(gid, run.story, run.scene);
  if (!sc) { endRun(gid, cid, uid); return interaction.reply({ content: '❌ That scene has gone missing.', ephemeral: true }); }
  // Carry on advances the tale, so it needs the same one-at-a-time guard the
  // other buttons have — a double tap would otherwise skip a scene and credit
  // an arriving GAIN twice.
  if (!claimRun(gid, cid, uid)) return interaction.reply({ content: '⏳ Still working on your last one.', ephemeral: true });
  try {
    await interaction.reply({ content: '▶️ Onward.' });
    try { await interaction.message.edit({ components: [] }); } catch {}
    await advance({ guild: interaction.guild }, { gid, cid, uid, run, ch: getChar(gid, uid), sc },
      next, JSON.parse(run.tally_state || '{}'), Number(gaAt) || 0);
  } finally { releaseRun(gid, cid, uid); }
}

async function handleStoryRollButton(interaction) {
  const [, owner, sceneName, statWord] = interaction.customId.split(':');
  const ctx = activeSceneFor(interaction, owner, sceneName);
  if (ctx.error) return interaction.reply({ content: ctx.error, ephemeral: true });
  if (!claimRun(ctx.gid, ctx.cid, ctx.uid)) return interaction.reply({ content: '⏳ Still working on your last one.', ephemeral: true });
  try {
    return await resolveActivityRoll(ctx, statWord, null, {
      guild: interaction.guild,
      reply: async (c) => { await interaction.reply(asPayload(c)); try { await interaction.message.edit({ components: [] }); } catch {} },
      interaction,
    });
  } finally { releaseRun(ctx.gid, ctx.cid, ctx.uid); }
}

// Answer the scene by typing instead of pressing: "wis I cast into the deep
// pools" rolls WIS and prints the rest as flavour. Returns false when the
// message isn't an answer, so the normal roll handling carries on.
async function tryActivityTypedRoll(message, content) {
  const gid = message.guild.id, cid = message.channel.id, uid = message.author.id;
  const run = getRun(gid, cid, uid);
  if (!run) return false;
  const sc = getScene(gid, run.story, run.scene);
  if (!sc || !sc.roll) return false;

  const m = content.match(new RegExp(`^(${STAT_WORD_RE})(?:\\s+([\\s\\S]*))?$`, 'i'));
  if (!m) return false;
  const stat = resolveStatWord(m[1]);
  if (!sceneStats(sc, run).map(resolveStatWord).includes(stat)) return false;   // wrong stat for this step

  const gate = sheetGate(gid, uid);
  if (gate) { await replyQuietly(message, gate); return true; }
  const ch = getChar(gid, uid);
  if (!ch) { await message.reply('❌ You need a character sheet to take part — `/char create`.').catch(()=>{}); return true; }

  await resolveActivityRoll({ gid, cid, uid, run, ch, sc }, stat, (m[2] || '').trim() || null, {
    guild: message.guild,
    reply: async (c) => { await message.reply(asPayload(c)).catch(()=>{}); },
  });
  return true;
}

// A scene reply is sometimes just text and sometimes text plus buttons. Every
// shim goes through this so it cannot matter which one a caller sent — passing
// an object where a string was expected was what broke the roll buttons.
const asPayload = (c) => (typeof c === 'string' ? { content: c } : c);

async function resolveActivityRoll(ctx, statWord, flavour, io, rerolled = false) {
  const { gid, cid, uid, run, ch, sc } = ctx;
  const say = io.reply;

  const stat = resolveStatWord(statWord);
  const mod = stat ? (ch[stat] ?? 0) : 0;
  const mode = applyNextMark(gid, uid, stat ? applySignatureMode(ch, stat, 'normal') : 'normal');
  const result = mode === 'adv' ? rollAdvantage(`1d20+${mod}`)
               : mode === 'dis' ? rollDisadvantage(`1d20+${mod}`)
               : rollNotation(`1d20+${mod}`);
  if (!result) return say(`❌ \`${statWord}\` isn't a stat.`);
  const nat = mode === 'normal' ? result.rolls?.[0] : result.chosen;
  const sides = result.sides ?? 20;
  const name = await getDisplayName(io.guild, uid);
  const label = (stat || statWord).toUpperCase();

  recordRoll(gid, { userId: uid, channelId: cid, interaction: io.interaction ?? null, result,
    input: `${run.story} · ${run.scene}`, rollLine: buildRollLine(result, mode, detectCrit(result, mode), null),
    context: `activity roll (${label})` });

  // GAIN is credited on arrival by advance(), not here, or a scene reached by a
  // choice would never pay and a scene with a roll would pay twice.
  const tallyState = JSON.parse(run.tally_state || '{}');

  const gauntlet = sc.gauntlet ? JSON.parse(sc.gauntlet) : null;
  const ranges = JSON.parse(sc.ranges || '[]');
  const outcomes = JSON.parse(sc.outcomes || '{}');
  const nat20 = sc.nat20 ? JSON.parse(sc.nat20) : null;
  const nat1 = sc.nat1 ? JSON.parse(sc.nat1) : null;
  const lines = [`🎲 **${name}** rolls **${label}**${rerolled ? ' *(reroll)*' : ''} — ${fightTotalStr(result.total, nat, sides)}`,
                 statLine(ch, gid)];
  if (flavour) lines.push('', `*${flavour}*`);

  // Offer a second chance before the tale moves on. One reroll per roll, and
  // only if they have one to spend — otherwise it advances as before.
  const finish = async (text, next, gaAt = 0) => {
    if (text) lines.push('', text);
    const dryRun = !!run?.is_demo;
    const canReroll = next && !rerolled && (dryRun || (ch.rerolls_current ?? 0) > 0);
    if (canReroll) {
      const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
      const token = `${sc.scene}:${statWord}:${next}:${gaAt}`;
      const row = new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`storyrr:${uid}:${token}`)
          .setLabel(dryRun ? 'Reroll (free — demo)' : `Reroll (${ch.rerolls_current} left)`)
          .setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId(`storygo:${uid}:${next}:${gaAt}`)
          .setLabel('Carry on').setStyle(ButtonStyle.Primary),
      );
      setRun(gid, cid, uid, { tally_state: JSON.stringify(tallyState) });
      await say({ content: lines.join('\n'), components: [row] });
      return;
    }
    await say(lines.join('\n'));
    if (next) await advance(io, ctx, next, tallyState, gaAt);
    else setRun(gid, cid, uid, { tally_state: JSON.stringify(tallyState) });
  };
  // A ONE OF block picks a different line each time, so a loop doesn't repeat.
  // A ONE OF block picks a different line each time, so a loop doesn't repeat.
  const pickText = (o) => (o?.variants?.length ? o.variants[Math.floor(Math.random() * o.variants.length)] : (o?.text || ''));

  // Natural 20 / 1 override everything else where the script defines them.
  if (nat === sides && nat20) return finish(nat20.text, nat20.next, 0);
  if (nat === 1 && nat1) return finish(nat1.text, nat1.next, 0);

  if (gauntlet) {
    const step = Number(run.gauntlet_at) || 0;
    const need = gauntlet[step]?.dc ?? 0;
    if (result.total >= need) {
      const last = step + 1 >= gauntlet.length;
      if (!last) {
        lines.push('', `✅ **${result.total}** beats DC ${need} — it's still fighting. ${gauntlet.length - step - 1} to go.`);
        await say(lines.join('\n'));
        const updated = setRun(gid, cid, uid, {
          tally_state: JSON.stringify(tallyState), gauntlet_at: step + 1 });
        await new Promise(r => setTimeout(r, 700));
        return postScene(io.guild, cid, updated, sc);
      }
      const o = outcomes.PASS;
      return finish(`✅ **${result.total}** beats DC ${need}. ${pickText(o)}`, o?.next, 0);
    }
    const o = outcomes.FAIL;
    return finish(`❌ **${result.total}** misses DC ${need}. ${pickText(o)}`, o?.next, 0);
  }

  if (ranges.length) {
    const hit = ranges.find(r => result.total >= r.lo && result.total <= r.hi);
    if (hit) return finish(hit.text, hit.next, 0);
    return finish('*Nothing in the script covers that total.*', null);
  }

  if (sc.dc) {
    const band = result.total >= sc.dc ? 'PASS' : 'FAIL';
    const o = outcomes[band];
    if (!o) return finish('*That branch is missing from the script.*', null);
    return finish(`${band === 'PASS' ? '✅' : '❌'} **${result.total}** vs DC ${sc.dc}. ${pickText(o)}`, o.next, 0);
  }

  const { band, res } = storyBandFor(outcomes, result.total, nat, sides);
  lines[0] += `  ${res.emoji} **${res.label}**`;
  if (!band) return finish('*Nothing in the script answers to that.*', null);
  return finish(pickText(outcomes[band]), outcomes[band].next, 0);
}

// ── Scheduled recovery ────────────────────────────────────────────────────────
// A guild can run any number of named schedules, each with its own interval and
// its own strength. "half HP every 6 hours" and "everything back every 24" can
// sit side by side. Amounts use the same tokens as /config mechanics rest — 100%, 50%, a
// flat number, or 0% to leave that resource alone — so they round down the same
// way and there's one format to learn.
const AUTOREST_HOURS_DEFAULT = 6;
const AUTOREST_TICK_MS = 5 * 60 * 1000;   // how often we ask whether anything is due

function listSchedules(gid) {
  return db.prepare('SELECT * FROM autorest_schedules WHERE guild_id=? ORDER BY name').all(gid);
}
function getSchedule(gid, name) {
  return db.prepare('SELECT * FROM autorest_schedules WHERE guild_id=? AND name=? COLLATE NOCASE').get(gid, name);
}
function upsertSchedule(gid, name, fields) {
  const ex = getSchedule(gid, name);
  if (!ex) {
    db.prepare('INSERT INTO autorest_schedules (guild_id, name, last_run) VALUES (?,?,?)').run(gid, name, Date.now());
  }
  const keys = Object.keys(fields || {});
  if (keys.length) {
    db.prepare(`UPDATE autorest_schedules SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND name=? COLLATE NOCASE`)
      .run(...keys.map(k => fields[k]), gid, ex ? ex.name : name);
  }
  return getSchedule(gid, name);
}
function deleteSchedule(gid, name) {
  return db.prepare('DELETE FROM autorest_schedules WHERE guild_id=? AND name=? COLLATE NOCASE').run(gid, name).changes > 0;
}
// Plain-English summary of what a schedule actually does.
function describeSchedule(sc) {
  const bit = (tok, what) => {
    const t = String(tok ?? '0%');
    if (t === '0%' || t === '0') return null;
    if (t === '100%') return `full ${what}`;
    if (t.startsWith('+')) return t.endsWith('%')
      ? `${t.slice(1)} of max ${what} added (rounded down)`
      : `${t.slice(1)} ${what} added`;
    if (t.endsWith('%')) return `set to ${t} ${what} (rounded down)`;
    return `set to ${t} ${what}`;
  };
  const parts = [bit(sc.hp, 'HP'), bit(sc.rerolls, 'rerolls'), bit(sc.heal, 'heal charges')].filter(Boolean);
  return parts.length ? parts.join(' · ') : 'nothing (every amount is 0%)';
}

// Everyone currently on the party of a quest that's underway.
function questBusyUsers(gid) {
  const rows = db.prepare(`SELECT DISTINCT m.user_id FROM quest_members m
                           JOIN quests q ON q.guild_id = m.guild_id AND q.number = m.number
                           WHERE m.guild_id = ? AND m.state = 'party' AND q.status = 'active'`).all(gid);
  return new Set(rows.map(r => r.user_id));
}

// Everyone standing in an active fight anywhere on this server. Healing them
// on a timer would undo an exchange partway through — the one thing a scheduled
// rest must never do.
function fightBusyUsers(gid) {
  const out = new Set();
  let rows;
  try { rows = db.prepare(`SELECT turn_order FROM fights WHERE guild_id=? AND state='active'`).all(gid); }
  catch { return out; }
  for (const r of rows) {
    let order = [];
    try { order = JSON.parse(r.turn_order || '[]'); } catch {}
    for (const fid of order) if (!isNpcFighter(fid)) out.add(fid);
  }
  return out;
}

// The NPC half of the same question. Kept separate because a fight stores NPCs
// by their prefixed id and the roster works in plain names.
function fightingNpcNames(gid) {
  const out = new Set();
  let rows;
  try { rows = db.prepare(`SELECT turn_order FROM fights WHERE guild_id=? AND state='active'`).all(gid); }
  catch { return out; }
  for (const r of rows) {
    let order = [];
    try { order = JSON.parse(r.turn_order || '[]'); } catch {}
    for (const fid of order) {
      const name = npcNameFromFighter(fid);
      if (name) out.add(name);
    }
  }
  return out;
}

// Apply one schedule to everyone not out on a quest or mid-fight.
async function runAutoRest(guild, sc) {
  const gid = guild.id;
  const cfg = getConfig(gid) || {};
  const maxCharges = cfg.heal_charges ?? 3;
  const busy = questBusyUsers(gid);
  const fighting = fightBusyUsers(gid);
  const sheets = db.prepare('SELECT * FROM characters WHERE guild_id=?').all(gid);
  const restored = [], skipped = [], inFight = [];
  for (const ch of sheets) {
    const name = await getDisplayName(guild, ch.user_id);
    // The fallen do not recover. Healing them to full while still dead leaves a
    // character in a state the rest of the bot can't read.
    if (ch.died_at) continue;
    if (busy.has(ch.user_id)) { skipped.push(name); continue; }
    if (fighting.has(ch.user_id)) { inFight.push(name); continue; }
    const updates = {};
    const hpR = resolveRestToken(sc.hp, maxHp(ch, gid), '0%', ch.hp_current ?? 0);
    if (hpR.changed) updates.hp_current = hpR.value;
    const rR = resolveRestToken(sc.rerolls, maxRerolls(ch), '0%', ch.rerolls_current ?? 0);
    if (rR.changed) updates.rerolls_current = rR.value;
    if (Object.keys(updates).length) upsertChar(gid, ch.user_id, updates);
    // Heal charges only mean anything to a White Knight with WIS 5+.
    const healR = resolveRestToken(sc.heal, maxCharges, '0%', getHealCharges(gid, ch.user_id, maxCharges).current);
    const healed = healR.changed && isWhiteKnight(ch);
    if (healed) setHealCharges(gid, ch.user_id, healR.value);
    // A schedule that touches nothing shouldn't claim to have restored anyone —
    // a charges-only rest was listing every player on the server.
    if (Object.keys(updates).length || healed) restored.push(name);
  }

  // NPCs rest too. They have only HP — no rerolls, no heal charges — so a
  // schedule's HP setting is the whole of it. The same two exclusions apply:
  // the fallen stay fallen, and nobody is healed out of a fight in progress.
  const npcFighting = fightingNpcNames(gid);
  for (const npc of getAllNpcs(gid)) {
    if (npc.died_at) continue;
    if (npcFighting.has(npc.name)) { inFight.push(`${npc.name} 🎭`); continue; }
    const max = maxHpFromCon(gid, npc.con);
    const hpR = resolveRestToken(sc.hp, max, '0%', npc.hp_current ?? 0);
    if (!hpR.changed) continue;
    upsertNpc(gid, npc.name, { hp_current: hpR.value });
    setFighterHp(gid, npcFighterId(npc.name), hpR.value);
    restored.push(`${npc.name} 🎭`);
  }

  upsertSchedule(gid, sc.name, { last_run: Date.now() });
  return { restored, skipped, inFight };
}

// Post the result where the GM asked for it, if anywhere.
async function announceAutoRest(guild, sc, result) {
  if (!sc.channel) return;
  const lines = [`🌙 **${sc.name}** — every ${sc.hours}h · ${describeSchedule(sc)}`];
  lines.push(result.restored.length
    ? `❤️ Restored: **${result.restored.length}** — ${result.restored.join(', ')}`
    : '❤️ Nobody to restore.');
  if (result.inFight?.length) {
    lines.push(`⚔️ Mid-fight, left as they are: **${result.inFight.length}** — ${result.inFight.join(', ')}`);
  }
  if (result.skipped.length) {
    lines.push(`🎒 Out on a quest, left as they are: **${result.skipped.length}** — ${result.skipped.join(', ')}`);
  }
  try {
    const ch = await guild.client.channels.fetch(sc.channel);
    await sendLong(ch, lines);
  } catch (err) { console.error('[autorest] could not announce:', err?.message || err); }
}

// The scheduler. Short tick, and every schedule carries its own stored last-run,
// so a redeploy can neither skip a cycle nor fire one early.
function startAutoRest(client) {
  const tick = async () => {
    for (const guild of client.guilds.cache.values()) {
      for (const sc of listSchedules(guild.id)) {
        try {
          if (!sc.enabled) continue;
          const hours = Number(sc.hours) > 0 ? Number(sc.hours) : AUTOREST_HOURS_DEFAULT;
          const last = Number(sc.last_run) || 0;
          if (!last) { upsertSchedule(guild.id, sc.name, { last_run: Date.now() }); continue; }
          if (Date.now() < last + hours * 3600 * 1000) continue;
          const result = await runAutoRest(guild, sc);
          await announceAutoRest(guild, sc, result);
          await reportJobRecovered(client, guild.id, sc?.channel || null, `Scheduled recovery (${sc?.name ?? '?'})`);
          console.log(`[autorest] ${guild.id}/${sc.name}: restored ${result.restored.length}, skipped ${result.skipped.length}`);
        } catch (err) {
          console.error('[autorest] tick failed for', guild.id, sc?.name, '-', err?.message || err);
          await reportJobFailure(client, guild.id, sc?.channel || null, `Scheduled recovery (${sc?.name ?? '?'})`, err);
        }
      }
    }
  };
  setInterval(tick, AUTOREST_TICK_MS);
  setTimeout(tick, 30 * 1000);   // first look shortly after boot
}

// How a GM runs a table, so players applying know what they are signing up for.
const GM_STYLES = {
  mechanics: '⚙️ Mechanics-focused',
  rp:        '🎭 Roleplay-focused',
  mixed:     '⚖️ Mixed elements',
  combat:    '⚔️ Combat-heavy',
  puzzle:    '🧩 Puzzle & investigation',
  sandbox:   '🗺️ Sandbox — led by the players',
};
const gmStyleLabel = (k) => GM_STYLES[k] ?? null;

// ── Death & memorial ─────────────────────────────────────────────────────────
// A character's deeds are not written by hand — they are what the bot already
// watched them do. Quests finished, merit earned and why, standing won, and the
// dice they were remembered for.
// Each deed is kept as { icon, text, detail, ledger }: `text` is what happened,
// `detail` the figures behind it, and `ledger` marks the bookkeeping entries a
// public memorial leaves out. Storing them apart is what lets the same record
// be told plainly to a hall and in full to the GMs.
function compileDeeds(gid, id) {
  const out = [];
  const quests = db.prepare(`SELECT quest_name, duration_ms FROM quest_summaries
                             WHERE guild_id=? AND user_id=? ORDER BY ended_at`).all(gid, id);
  for (const q of quests) {
    out.push({ icon: '📜', text: `Saw **${q.quest_name}** through`, detail: fmtElapsed(q.duration_ms) });
  }
  const merits = db.prepare(`SELECT amount, reason FROM history
                             WHERE guild_id=? AND kind='merit' AND user_id=? AND amount > 0
                             ORDER BY amount DESC LIMIT 5`).all(gid, id);
  for (const m of merits) if (m.reason) out.push({ icon: '🎖️', text: m.reason, detail: `**+${m.amount}** merit` });

  const renown = db.prepare(`SELECT delta, reason FROM renown_log
                             WHERE guild_id=? AND user_id=? AND delta > 0
                             ORDER BY delta DESC LIMIT 3`).all(gid, id);
  for (const r of renown) if (r.reason) out.push({ icon: '💠', text: r.reason, detail: `**+${r.delta}** renown` });

  const t = rollTally(gid, id, 20);
  if (t.total) {
    out.push({ ledger: true, icon: '🎲', text: `Rolled **${t.total}** times`,
      detail: `🌟 ${t.by[20] || 0} perfect, 💀 ${t.by[1] || 0} disastrous` });
  }
  const items = listItems(gid, id);
  if (items.length) {
    out.push({ ledger: true, icon: '🎒', text: `Carried ${items.map(i => `**${i.item}**`).join(', ')}` });
  }
  return out;
}

// How many times this character has been laid to rest and walked back.
function deathCount(gid, id) {
  const r = db.prepare(`SELECT COUNT(*) AS deaths, SUM(revived_at IS NOT NULL) AS revivals
                        FROM deaths WHERE guild_id=? AND subject_id=?`).get(gid, id);
  return { deaths: r?.deaths ?? 0, revivals: r?.revivals ?? 0 };
}

// One card for the fallen, whoever they were.
// `publicView` tells the same life without the ledger: no merit or renown
// totals, no dice, no inventory, and no figures or dates hanging off the deeds.
// A hall should hear what someone did, not what they were worth.
async function buildMemorial(guild, gid, id, rec, { publicView = false } = {}) {
  const lines = [
    '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
    `🕯️  **${rec.name}**${id.startsWith(NPC_PREFIX) ? ' 🎭' : ''}`,
  ];
  if (rec.order_name) lines.push(`${KNIGHT_EMOJIS[rec.order_name] ?? '⚪'}  ${rec.order_name}`);
  if (rec.rank_name) lines.push(`🏅  ${rec.rank_name}`);
  if (!publicView) lines.push(`🎖️ ${rec.merits ?? 0} merit${(rec.merits ?? 0) === 1 ? '' : 's'}  ·  💠 ${rec.renown ?? 0} renown`);
  lines.push('─────────────────────────────');
  if (rec.cause) lines.push(`⚰️ **Cause of death**`, rec.cause, '');

  // Older records stored deeds as plain strings; read both shapes.
  const raw = JSON.parse(rec.deeds || '[]');
  const deeds = raw.map(d => typeof d === 'string' ? { icon: '•', text: d } : d)
                   .filter(d => !(publicView && d.ledger));
  lines.push(deeds.length ? '📖 **Deeds**' : '📖 **Deeds** — _none recorded._');
  for (const d of deeds) {
    lines.push(`${d.icon ?? '•'} ${d.text}${!publicView && d.detail ? ` — ${d.detail}` : ''}`);
  }

  if (rec.quote) lines.push('', `> *“${rec.quote}”*`);
  if (rec.flavour) lines.push('', rec.flavour);
  if (!publicView) lines.push('', `_Fell <t:${Math.floor(rec.at / 1000)}:D>._`);
  lines.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  return lines;
}

// The revive button, with the tally of how often this one has come back.
function memorialButtons(gid, id, deathId) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  const { deaths, revivals } = deathCount(gid, id);
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`revive:${deathId}`).setLabel('Revive').setStyle(ButtonStyle.Success));
  if (deaths > 1 || revivals > 0) {
    row.addComponents(new ButtonBuilder().setCustomId('revivecount').setDisabled(true)
      .setLabel(`Fallen ${deaths}× · revived ${revivals}×`).setStyle(ButtonStyle.Secondary));
  }
  return row;
}

// ── Command PDFs from GitHub ─────────────────────────────────────────────────
// The three books are built outside the bot and committed to a repository. This
// watches them and keeps a single, current post in a GM channel: when a new
// build lands, the old post is deleted and replaced rather than the channel
// filling up with stale copies.
const DOC_FILES = [
  'DDice-Commands-GameMaster.pdf',
  'DDice-Commands-Player.pdf',
  'DDice-Commands-Parchment.pdf',
];
const DOCS_POLL_MS = 15 * 60 * 1000;
const DOC_PLAYER_FILE = 'DDice-Commands-Player.pdf';

function docsSettings(gid) {
  const cfg = getConfig(gid) || {};
  return {
    channel: cfg.docs_channel || null,
    repo: cfg.docs_repo || null,
    branch: cfg.docs_branch || 'main',
    path: (cfg.docs_path || '').replace(/^\/+|\/+$/g, ''),
    msgId: cfg.docs_msg_id || null,
    sha: cfg.docs_sha || null,
    playerChannel: cfg.docs_player_channel || null,
    playerMsgId: cfg.docs_player_msg_id || null,
  };
}
const docFileUrl = (st, file) =>
  `https://raw.githubusercontent.com/${st.repo}/${st.branch}/${st.path ? st.path + '/' : ''}${file}`;

// The player handbook, wherever this server keeps it: the copy published into
// a player channel when one exists, else the raw file straight from GitHub.
// Null when docs aren't configured — the help link simply stays off.
function playerHandbookLink(gid) {
  const st = docsSettings(gid);
  if (st.playerChannel && st.playerMsgId)
    return `https://discord.com/channels/${gid}/${st.playerChannel}/${st.playerMsgId}`;
  if (st.repo) return docFileUrl(st, DOC_PLAYER_FILE);
  return null;
}

// A fingerprint of the three files as they currently stand on GitHub. Uses the
// contents API rather than downloading, so a poll that finds nothing new costs
// three small requests instead of half a megabyte.
// A fingerprint of the three files as they currently stand.
//
// This deliberately avoids GitHub's REST API. That is rate-limited to 60 calls
// an hour per IP unauthenticated, and a Railway container shares its outbound
// address with other tenants — so the budget is often already spent by someone
// else and every check comes back 403. The raw CDN has no such limit, and a
// HEAD gives us an ETag that changes exactly when the file does.
async function fetchDocsFingerprint(st) {
  const parts = [];
  for (const file of DOC_FILES) {
    const url = docFileUrl(st, file);
    const res = await fetch(url, { method: 'HEAD', headers: docsHeaders() });
    if (!res.ok) {
      throw new Error(res.status === 404
        ? `${file}: not found at ${st.repo}/${st.branch}${st.path ? '/' + st.path : ''} — check the branch, path and that the file is committed`
        : `${file}: GitHub returned ${res.status}`);
    }
    // ETag is what we want; fall back to the length so a mirror without one
    // still detects a change rather than never updating.
    const tag = res.headers.get('etag') || res.headers.get('last-modified') || res.headers.get('content-length');
    parts.push(`${file}:${tag ?? '?'}`);
  }
  return parts.join('|');
}

// A token is optional and only needed for a private repository. With one, the
// raw host will serve files it otherwise refuses.
function docsHeaders() {
  // The raw host sits behind a CDN that will happily serve a few-minute-old
  // copy. Asking it not to means a commit is seen when it lands rather than
  // whenever the edge decides to expire.
  const h = { 'User-Agent': 'DDice-bot', 'Cache-Control': 'no-cache', 'Pragma': 'no-cache' };
  if (process.env.GITHUB_TOKEN) h.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  return h;
}

async function fetchDocFiles(st, only = DOC_FILES) {
  const { AttachmentBuilder } = require('discord.js');
  const files = [];
  for (const file of only) {
    const res = await fetch(docFileUrl(st, file), { headers: docsHeaders() });
    if (!res.ok) throw new Error(`${file}: download returned ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    if (!buf.length) throw new Error(`${file}: downloaded nothing`);
    files.push(new AttachmentBuilder(buf, { name: file }));
  }
  return files;
}

// Replace the standing post with a fresh one. Returns a short outcome line.
async function publishDocs(client, guild, { reason = 'a new build', force = false } = {}) {
  const gid = guild.id;
  const st = docsSettings(gid);
  if (!st.channel || !st.repo) return { skipped: 'not configured' };

  const fingerprint = await fetchDocsFingerprint(st);
  if (!force && fingerprint === st.sha) return { skipped: 'unchanged' };

  const files = await fetchDocFiles(st);
  const channel = await client.channels.fetch(st.channel);
  const roles = getGmRoleIds(gid);

  // Post the new one first, then remove the old — that way a failure leaves the
  // channel with a copy rather than none at all.
  const msg = await channel.send({
    content: `${roles.map(r => `<@&${r}>`).join(' ')} 📚 **Command reference updated** — ${reason}.\n`
      + `_Latest build from \`${st.repo}\`. The previous post has been removed._`,
    files, allowedMentions: { roles },
  });
  if (st.msgId) {
    try { const old = await channel.messages.fetch(st.msgId); await old.delete(); } catch {}
  }
  setConfig(gid, { docs_msg_id: msg.id, docs_sha: fingerprint });
  const out = { posted: true, url: `https://discord.com/channels/${gid}/${channel.id}/${msg.id}` };

  // The player book on its own, somewhere players can find it. Deliberately
  // silent: no roles pinged, no notification raised, and mentions suppressed
  // entirely — a reference channel should stay current without nagging anyone.
  if (st.playerChannel) {
    try {
      const pCh = await client.channels.fetch(st.playerChannel);
      const [playerFile] = await fetchDocFiles(st, [DOC_PLAYER_FILE]);
      const pMsg = await pCh.send({
        content: '📘 **Player command reference** — latest version.',
        files: [playerFile],
        allowedMentions: { parse: [] },
        flags: MessageFlags.SuppressNotifications,
      });
      if (st.playerMsgId) {
        try { const old = await pCh.messages.fetch(st.playerMsgId); await old.delete(); } catch {}
      }
      setConfig(gid, { docs_player_msg_id: pMsg.id });
      out.playerUrl = `https://discord.com/channels/${gid}/${pCh.id}/${pMsg.id}`;
    } catch (err) {
      console.error('[docs] player copy failed:', err?.message || err);
      out.playerError = err?.message || String(err);
    }
  }
  return out;
}

function startDocsWatch(client) {
  const tick = async () => {
    for (const guild of client.guilds.cache.values()) {
      const st = docsSettings(guild.id);
      if (!st.channel || !st.repo) continue;
      try {
        const out = await publishDocs(client, guild);
        setConfig(guild.id, { docs_checked_at: Date.now(),
          docs_result: out.posted ? 'published a new build' : (out.skipped === 'unchanged' ? 'nothing new' : String(out.skipped)) });
        if (out.posted) console.log(`[docs] ${guild.id}: published a new build`);
        // Recovered — say so if we had complained.
        if (getConfig(guild.id)?.docs_error) {
          setConfig(guild.id, { docs_error: null });
          try {
            const ch = await client.channels.fetch(st.channel);
            await ch.send('📚 _Reading the command books again — whatever was wrong has cleared._');
          } catch {}
        }
      } catch (err) {
        const msg = err?.message || String(err);
        setConfig(guild.id, { docs_checked_at: Date.now(), docs_result: `failed — ${msg}` });
        console.error('[docs] check failed for', guild.id, '-', msg);
        // Tell the channel once per distinct problem, not every 15 minutes.
        if (getConfig(guild.id)?.docs_error === msg) continue;
        setConfig(guild.id, { docs_error: msg });
        try {
          const ch = await client.channels.fetch(st.channel);
          await ch.send({ allowedMentions: { parse: [] }, content:
            `⚠️ **Can't fetch the command books** from \`${st.repo}\` (${st.branch}${st.path ? `, /${st.path}` : ''}).\n`
            + `\`${msg}\`\n`
            + '_I will keep trying every 15 minutes and say so when it works. '
            + 'Check the repository is public, the branch and path are right, and the PDFs are committed. '
            + 'For a private repository, set a `GITHUB_TOKEN` on the host._' });
        } catch {}
      }
    }
  };
  setInterval(tick, DOCS_POLL_MS);
  setTimeout(tick, 30 * 1000);   // look soon after boot, not a minute and a half later
}

// ── Quest stopwatch & event log ──────────────────────────────────────────────
const QUEST_REMIND_MS = 15 * 60 * 1000;   // public "how long we've been at it"
const QUEST_RECAP_MS  = 60 * 60 * 1000;   // hourly summary of what happened

function questElapsed(q) {
  if (!q) return 0;
  const banked = Number(q.elapsed_ms) || 0;
  if (q.paused || !q.started_at) return banked;
  return banked + Math.max(0, Date.now() - Number(q.started_at));
}
function fmtElapsed(ms) {
  const total = Math.max(0, Math.floor(ms / 60000));
  return `${Math.floor(total / 60)}h ${String(total % 60).padStart(2, '0')}m`;
}

function logQuestEvent(gid, number, kind, text, actor = null) {
  const q = getQuest(gid, number);
  if (!q) return null;
  db.prepare('INSERT INTO quest_events (guild_id,number,at_ms,kind,text,actor,wall_at) VALUES (?,?,?,?,?,?,?)')
    .run(gid, number, questElapsed(q), kind, text ?? null, actor, Date.now());
  return true;
}
function questEvents(gid, number, sinceMs = null) {
  return sinceMs === null
    ? db.prepare('SELECT * FROM quest_events WHERE guild_id=? AND number=? ORDER BY at_ms, id').all(gid, number)
    : db.prepare('SELECT * FROM quest_events WHERE guild_id=? AND number=? AND at_ms > ? ORDER BY at_ms, id').all(gid, number, sinceMs);
}
const QUEST_EVENT_ICON = {
  start: '🚩', pause: '⏸️', resume: '▶️', remind: '⏱️', recap: '📻',
  combat: '⚔️', rp: '🎭', activity: '🎮', note: '📝', end: '🏁',
};
function questEventLine(e) {
  return `\`${fmtElapsed(e.at_ms).padStart(7)}\` ${QUEST_EVENT_ICON[e.kind] ?? '•'} ${e.text || e.kind}`;
}

// Every quest currently underway in this channel — used to attach combat and
// roleplay to the right quest without a GM having to say which.
function activeQuestsInChannel(gid, cid) {
  return db.prepare(`SELECT * FROM quests WHERE guild_id=? AND run_channel_id=? AND status='active'`).all(gid, cid);
}
// Note something against whichever quest is running in this channel, if any.
function noteQuestActivity(gid, cid, kind, text, actor = null) {
  for (const q of activeQuestsInChannel(gid, cid)) {
    if (q.paused) continue;               // a paused quest records nothing
    logQuestEvent(gid, q.number, kind, text, actor);
  }
}

// The quest clock. Ticks every minute so a 15-minute reminder lands close to
// the mark; both counters are stored on the quest, so a redeploy mid-session
// resumes exactly where it left off rather than restarting the count.
const QUEST_TICK_MS = 60 * 1000;

async function questTick(client) {
  for (const guild of client.guilds.cache.values()) {
    let running;
    try { running = db.prepare(`SELECT * FROM quests WHERE guild_id=? AND status='active' AND paused=0`).all(guild.id); }
    catch { continue; }
    for (const q of running) {
      try {
        if (!q.run_channel_id) continue;
        const now = questElapsed(q);

        // Hourly recap first — it also satisfies the quarter-hour mark, so the
        // two don't both fire on the hour and say the same thing twice.
        if (now - (Number(q.last_recap_ms) || 0) >= QUEST_RECAP_MS) {
          const since = Number(q.last_recap_ms) || 0;
          const events = questEvents(guild.id, q.number, since)
            .filter(e => !['remind', 'recap'].includes(e.kind));
          const lines = [`📻 **${questTag(q)}** — **${fmtElapsed(now)}** in. The last hour:`];
          lines.push(...(events.length ? events.map(questEventLine) : ['`      ` _Quiet hour — nothing logged._']));
          logQuestEvent(guild.id, q.number, 'recap', `Hourly recap — ${events.length} event${events.length === 1 ? '' : 's'}`);
          updateQuest(guild.id, q.number, { last_recap_ms: now, last_tick_ms: now });
          const ch = await client.channels.fetch(q.run_channel_id).catch(() => null);
          if (ch) await sendLong(ch, lines);
          continue;
        }

        if (now - (Number(q.last_tick_ms) || 0) >= QUEST_REMIND_MS) {
          logQuestEvent(guild.id, q.number, 'remind', `Time check — ${fmtElapsed(now)}`);
          updateQuest(guild.id, q.number, { last_tick_ms: now });
          const ch = await client.channels.fetch(q.run_channel_id).catch(() => null);
          if (ch) await ch.send(`⏱️ **${questTag(q)}** — **${fmtElapsed(now)}** elapsed.`).catch(()=>{});
        }
      } catch (err) { console.error('[quest] tick failed for', q.number, '-', err?.message || err); }
    }
  }
}
function startQuestClock(client) {
  setInterval(() => questTick(client).catch(e => console.error('[quest] tick:', e?.message || e)), QUEST_TICK_MS);
}

// ── Tag helpers ──────────────────────────────────────────────────────────────
const PRESET_TAGS = {
  'Hero of Kalidale': '⚜️',
  'Expeditioners': '📜',
};

function getPlayerTags(gid, uid) {
  return db.prepare('SELECT tag_name FROM player_tags WHERE guild_id=? AND user_id=?').all(gid, uid).map(r => r.tag_name);
}
function assignTag(gid, uid, tagName) {
  db.prepare('INSERT OR IGNORE INTO player_tags (guild_id, user_id, tag_name) VALUES (?,?,?)').run(gid, uid, tagName);
}
function removeTag(gid, uid, tagName) {
  db.prepare('DELETE FROM player_tags WHERE guild_id=? AND user_id=? AND tag_name=?').run(gid, uid, tagName);
}
function getCustomTags(gid) {
  return db.prepare('SELECT * FROM custom_tags WHERE guild_id=?').all(gid);
}
function addCustomTag(gid, tagName, emoji) {
  db.prepare('INSERT OR REPLACE INTO custom_tags (guild_id, tag_name, emoji) VALUES (?,?,?)').run(gid, tagName, emoji);
}
function deleteCustomTag(gid, tagName) {
  db.prepare('DELETE FROM custom_tags WHERE guild_id=? AND tag_name=?').run(gid, tagName);
  // Also remove from all players
  db.prepare('DELETE FROM player_tags WHERE guild_id=? AND tag_name=?').run(gid, tagName);
}
function resolveTagEmoji(gid, tagName) {
  if (PRESET_TAGS[tagName]) return PRESET_TAGS[tagName];
  const custom = db.prepare('SELECT emoji FROM custom_tags WHERE guild_id=? AND tag_name=?').get(gid, tagName);
  return custom ? custom.emoji : '🏷️';
}
// ── NPC helpers ───────────────────────────────────────────────────────────────
function getNpc(gid, name) {
  // Exact match first, then fall back to case-insensitive so "goblin" finds "Goblin"
  let row = db.prepare('SELECT * FROM npcs WHERE guild_id=? AND name=?').get(gid, name);
  if (!row && name) {
    row = db.prepare('SELECT * FROM npcs WHERE guild_id=? AND LOWER(name)=LOWER(?)').get(gid, name);
  }
  return row;
}
function getAllNpcs(gid) {
  return db.prepare('SELECT * FROM npcs WHERE guild_id=? ORDER BY name').all(gid);
}
function upsertNpc(gid, name, fields) {
  const ex = getNpc(gid, name);
  if (!ex) {
    db.prepare('INSERT INTO npcs (guild_id, name, order_name, str, con, dex, wis, lck, hp_current, image_url, webhook_id, webhook_token) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')
      .run(gid, name, fields.order_name??null, fields.str??0, fields.con??0, fields.dex??0, fields.wis??0, fields.lck??0,
        (fields.con??0)+2, fields.image_url??null, fields.webhook_id??null, fields.webhook_token??null);
  } else {
    const sets = Object.entries(fields).map(([k])=>`${k}=?`).join(',');
    db.prepare(`UPDATE npcs SET ${sets} WHERE guild_id=? AND name=?`).run(...Object.values(fields), gid, name);
  }
  if ('hp_current' in fields) {
    const canonical = getNpc(gid, name)?.name ?? name;
    syncFightHp(gid, npcFighterId(canonical), fields.hp_current);
  }
  return getNpc(gid, name);
}
function deleteNpc(gid, name) {
  purgeSubjectRecords(gid, npcFighterId(name));
  db.prepare('DELETE FROM npcs WHERE guild_id=? AND name=?').run(gid, name);
}
// An NPC written "Black Knight | Lady Ciara Nightveil" belongs to the Black
// Knight order — the pipe says so, and nothing is guessed from shared words,
// so "The Horse" and "The Hollow Sister" never collide.
function npcOrderOf(name) {
  const i = String(name || '').indexOf('|');
  if (i === -1) return null;
  const p = name.slice(0, i).trim();
  return p || null;
}
function getOrderImage(gid, prefix) {
  if (!prefix) return null;
  try {
    const r = db.prepare('SELECT image_url FROM npc_orders WHERE guild_id=? AND prefix=? COLLATE NOCASE').get(gid, prefix);
    return r?.image_url ?? null;
  } catch { return null; }
}
function setOrderImage(gid, prefix, url, uid) {
  db.prepare('INSERT INTO npc_orders (guild_id, prefix, image_url, set_by, set_at) VALUES (?,?,?,?,?) '
    + 'ON CONFLICT(guild_id, prefix) DO UPDATE SET image_url=excluded.image_url, set_by=excluded.set_by, set_at=excluded.set_at')
    .run(gid, prefix, url, uid ?? null, Date.now());
}
// Which orders actually have members, and how many — an image is only
// accepted for an order somebody belongs to.
function ordersWithMembers(gid) {
  const seen = new Map();
  for (const n of getAllNpcs(gid)) {
    const p = npcOrderOf(n.name);
    if (p) seen.set(p.toLowerCase(), (seen.get(p.toLowerCase()) ?? 0) + 1);
  }
  return seen;
}
// The face an NPC speaks with: their own portrait first, their order's
// second, nothing third.
function npcFace(gid, npc) {
  if (!npc) return null;
  return npc.image_url ?? getOrderImage(gid, npcOrderOf(npc.name)) ?? null;
}

function setNpcImage(gid, name, url) {
  db.prepare('UPDATE npcs SET image_url=? WHERE guild_id=? AND name=?').run(url, gid, name);
}
// Per-channel webhook lookup. Falls back to nothing if the NPC has never
// posted in this channel before, so a fresh one gets made here.
function getNpcWebhookFor(gid, channelId, name) {
  return db.prepare('SELECT webhook_id, webhook_token, avatar_url FROM npc_webhooks WHERE guild_id=? AND channel_id=? AND npc_name=?')
    .get(gid, channelId, name);
}
function setNpcWebhookFor(gid, channelId, name, webhookId, webhookToken, avatarUrl = null) {
  db.prepare(`INSERT INTO npc_webhooks (guild_id, channel_id, npc_name, webhook_id, webhook_token, avatar_url)
              VALUES (?,?,?,?,?,?)
              ON CONFLICT(guild_id, channel_id, npc_name)
              DO UPDATE SET webhook_id=excluded.webhook_id, webhook_token=excluded.webhook_token, avatar_url=excluded.avatar_url`)
    .run(gid, channelId, name, webhookId, webhookToken, avatarUrl);
}
function clearNpcWebhooks(gid, name) {
  db.prepare('DELETE FROM npc_webhooks WHERE guild_id=? AND npc_name=?').run(gid, name);
}

// Resolve (or create) the webhook this NPC should use in THIS channel.
// Webhooks live on the parent when the target is a thread or forum post.
function webhookHost(channel) {
  return (channel && typeof channel.isThread === 'function' && channel.isThread())
    ? (channel.parent ?? null) : (channel ?? null);
}

// The name every NPC in a channel speaks through. One webhook, reused by
// all of them — each message carries its own username and avatar, so a
// hundred NPCs cost a single hook. (Discord caps a channel at fifteen; the
// old one-per-NPC scheme hit that wall and dropped to plain bot messages.)
const SHARED_HOOK = '\u0000shared';

async function npcWebhookIn(channel, gid, npcName, imageUrl) {
  const { WebhookClient } = require('discord.js');

  // A thread cannot own a webhook. Discord requires one on the parent channel,
  // with posts routed in by thread id — so a /npc say inside any thread or forum
  // post used to throw here and quietly fall back to speaking as the bot.
  // Webhooks are therefore stored against the parent and shared by its threads.
  const inThread = typeof channel.isThread === 'function' && channel.isThread();
  const host = inThread ? channel.parent : channel;
  if (!host) return null;
  const threadId = inThread ? channel.id : null;

  // Every send wears the NPC's own face, whichever hook carries it.
  const bind = (client) => ({
    send: (payload) => client.send({
      ...(typeof payload === 'string' ? { content: payload } : payload),
      username: npcName,
      avatarURL: imageUrl ?? BLANK_AVATAR,
      ...(threadId ? { threadId } : {}),
    }),
  });

  // 1 · the channel's shared hook, if we've already got one.
  const shared = getNpcWebhookFor(gid, host.id, SHARED_HOOK);
  if (shared?.webhook_id && shared?.webhook_token) {
    return bind(new WebhookClient({ id: shared.webhook_id, token: shared.webhook_token }));
  }

  // 2 · an NPC-specific hook left over from the old scheme, or any other the
  // bot owns here — adopting one un-jams a channel already at the cap.
  const mine = getNpcWebhookFor(gid, host.id, npcName);
  if (mine?.webhook_id && mine?.webhook_token) {
    setNpcWebhookFor(gid, host.id, SHARED_HOOK, mine.webhook_id, mine.webhook_token, null);
    return bind(new WebhookClient({ id: mine.webhook_id, token: mine.webhook_token }));
  }
  try {
    const hooks = await host.fetchWebhooks();
    const own = hooks.find(h => h.owner?.id === host.client.user.id && h.token);
    if (own) {
      setNpcWebhookFor(gid, host.id, SHARED_HOOK, own.id, own.token, null);
      return bind(new WebhookClient({ id: own.id, token: own.token }));
    }
  } catch { /* no Manage Webhooks to read them — try creating below */ }

  // 3 · nothing to adopt: mint the one this channel will use from now on.
  const webhook = await host.createWebhook({
    name: 'DDice',
    avatar: BLANK_AVATAR,
    reason: 'Shared NPC voice for this channel',
  });
  setNpcWebhookFor(gid, host.id, SHARED_HOOK, webhook.id, webhook.token, null);
  return bind(new WebhookClient({ id: webhook.id, token: webhook.token }));
}

// A stored hook can be deleted server-side; forget it so the next call
// adopts or mints afresh. Threads share their parent's, so clear both.
function forgetChannelWebhook(gid, channel) {
  const ids = [channel?.id, channel?.parentId].filter(Boolean);
  for (const id of ids) {
    try { db.prepare('DELETE FROM npc_webhooks WHERE guild_id=? AND channel_id=?').run(gid, id); } catch {}
  }
}

function setNpcWebhook(gid, name, webhookId, webhookToken) {
  db.prepare('UPDATE npcs SET webhook_id=?, webhook_token=? WHERE guild_id=? AND name=?').run(webhookId, webhookToken, gid, name);
}

// Blank silhouette as base64 data URI fallback
const BLANK_AVATAR = 'https://cdn.discordapp.com/embed/avatars/0.png';

// ── Weapon helpers ────────────────────────────────────────────────────────────
function getWeapons(gid) {
  return db.prepare('SELECT name FROM weapons WHERE guild_id=? ORDER BY name').all(gid).map(r=>r.name);
}
function addWeapon(gid, name) {
  db.prepare('INSERT OR IGNORE INTO weapons (guild_id, name) VALUES (?,?)').run(gid, name);
}
function removeWeapon(gid, name) {
  db.prepare('DELETE FROM weapons WHERE guild_id=? AND name=?').run(gid, name);
}

// ── Weapon emoji validation ───────────────────────────────────────────────────
const STANDARD_WEAPON_EMOJIS = ['⚔️', '🗡️', '🏹', '🔱', '⛏️', '🛡️', '🪄'];
// Accept a standard emoji, OR a custom emoji tag (<:name:id> / <a:name:id>) that
// belongs to this guild. Returns the cleaned value to store, or null if invalid.
function validateWeaponEmoji(guild, value) {
  if (!value) return null;
  const v = value.trim();
  if (STANDARD_WEAPON_EMOJIS.includes(v)) return v;
  // Custom emoji tag?
  const m = v.match(/^<(a?):(\w+):(\d+)>$/);
  if (m) {
    const id = m[3];
    // Confirm the emoji exists on this server
    if (guild?.emojis?.cache?.has(id)) return v;
    return null;
  }
  // Allow any single standard unicode emoji the user typed (lenient fallback)
  // Reject long strings / plain text
  if (v.length <= 8 && !/[a-zA-Z0-9]/.test(v)) return v;
  return null;
}

// ── NPC Category helpers ──────────────────────────────────────────────────────
function getCategories(gid) {
  return db.prepare('SELECT name FROM npc_categories WHERE guild_id=? ORDER BY name').all(gid).map(r=>r.name);
}
function createCategory(gid, name) {
  db.prepare('INSERT OR IGNORE INTO npc_categories (guild_id, name) VALUES (?,?)').run(gid, name);
}
function deleteCategory(gid, name) {
  db.prepare('DELETE FROM npc_categories WHERE guild_id=? AND name=?').run(gid, name);
  db.prepare('DELETE FROM npc_category_members WHERE guild_id=? AND category=?').run(gid, name);
}
function assignNpcToCategory(gid, npcName, category) {
  db.prepare('INSERT OR IGNORE INTO npc_category_members (guild_id, category, npc_name) VALUES (?,?,?)').run(gid, category, npcName);
}
function removeNpcFromCategory(gid, npcName, category) {
  db.prepare('DELETE FROM npc_category_members WHERE guild_id=? AND category=? AND npc_name=?').run(gid, category, npcName);
}
function getNpcsInCategory(gid, category) {
  return db.prepare('SELECT npc_name FROM npc_category_members WHERE guild_id=? AND category=? ORDER BY npc_name').all(gid, category).map(r=>r.npc_name);
}
// One page of the roster. Full pages carry the stat line every GM reads at
// a glance; compact pages are a roll call — names, four to a row — for
// servers with more NPCs than a screen can hold. Returns null when the
// category named no longer exists, so the caller can say so.
const NPC_PAGE_FULL = 15, NPC_PAGE_COMPACT = 60;
function buildNpcPage(gid, { page = 0, compact = false, cat = '' } = {}) {
  let npcs = getAllNpcs(gid);
  let header = '**🎭 NPCs on this server';
  if (cat) {
    const real = getCategories(gid).find(c => c.toLowerCase() === cat.toLowerCase());
    if (!real) return null;
    const members = new Set(getNpcsInCategory(gid, real));
    npcs = npcs.filter(n => members.has(n.name));
    header = `**🎭 NPCs — 📁 ${real}`;
  }
  const total = npcs.length;
  const per = compact ? NPC_PAGE_COMPACT : NPC_PAGE_FULL;
  const pages = Math.max(1, Math.ceil(total / per));
  const p = Math.min(Math.max(0, page), pages - 1);
  const slice = npcs.slice(p * per, p * per + per);
  const lines = [`${header} — ${total}${pages > 1 ? ` · page ${p + 1}/${pages}` : ''}:**`, ''];
  if (!total) lines.push('_Nobody yet._');
  else if (compact) {
    for (let i = 0; i < slice.length; i += 4) {
      lines.push(slice.slice(i, i + 4).map(n => '`' + n.name + '`').join(' · '));
    }
  } else {
    for (const n of slice) {
      const order = n.order_name ? ` ${KNIGHT_EMOJIS[n.order_name] ?? '⚪'} ${n.order_name}` : '';
      const img = n.image_url ? ' 🖼️' : (getOrderImage(gid, npcOrderOf(n.name)) ? ' 🛡️' : '');
      lines.push(`• **${n.name}**${order}${img} — STR ${n.str} CON ${n.con} DEX ${n.dex} WIS ${n.wis} LCK ${n.lck} | ❤️ ${n.hp_current}/${maxHpFromCon(gid, n.con)}`);
    }
  }
  return { content: lines.join('\n').slice(0, 1990), page: p, pages, total, compact, cat };
}

// ◀ ▶ and the view toggle. Everything the press needs is in the id:
// npclist:<page>:<c|f>:<category, colons and all>.
function npcPageRows(pg) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  if (pg.pages <= 1 && pg.total <= NPC_PAGE_FULL) return [];
  const id = (page, compact) => `npclist:${page}:${compact ? 'c' : 'f'}:${pg.cat}`.slice(0, 100);
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(id(pg.page - 1, pg.compact)).setLabel('◀').setStyle(ButtonStyle.Secondary).setDisabled(pg.page === 0),
    new ButtonBuilder().setCustomId('npcpage').setLabel(`${pg.page + 1} / ${pg.pages}`).setStyle(ButtonStyle.Secondary).setDisabled(true),
    new ButtonBuilder().setCustomId(id(pg.page + 1, pg.compact)).setLabel('▶').setStyle(ButtonStyle.Secondary).setDisabled(pg.page >= pg.pages - 1),
    new ButtonBuilder().setCustomId(id(0, !pg.compact))
      .setLabel(pg.compact ? '📖 Full sheets' : '🔤 Names only').setStyle(ButtonStyle.Primary),
  );
  return [row];
}

function getCategoriesForNpc(gid, npcName) {
  return db.prepare('SELECT category FROM npc_category_members WHERE guild_id=? AND npc_name=? ORDER BY category').all(gid, npcName).map(r=>r.category);
}
function getUncategorisedNpcs(gid) {
  const all = getAllNpcs(gid).map(n=>n.name);
  const categorised = db.prepare('SELECT DISTINCT npc_name FROM npc_category_members WHERE guild_id=?').all(gid).map(r=>r.npc_name);
  return all.filter(n => !categorised.includes(n));
}

// ── Fight helpers ─────────────────────────────────────────────────────────────
// The grapple map lives on the fight row: { heldId: holderId }. It dies with
// the fight, and any knockout purges the holds it was part of.
function fightGrapples(fight) {
  try { const m = JSON.parse(fight?.grapples || '{}'); return m && typeof m === 'object' ? m : {}; }
  catch { return {}; }
}
function setFightGrapples(gid, cid, map) {
  upsertFight(gid, cid, { grapples: JSON.stringify(map) });
}
function grappleHolderOf(fight, id) { return fightGrapples(fight)[id] ?? null; }
// A shield in either hand — by name, any type.
function hasShieldEquipped(subject) {
  return [subject?.weapon1, subject?.weapon2].filter(Boolean)
    .some(w => /\b(shield|buckler|targe|kite|tower|pavise|aegis)\b/i.test(w));
}
// A blade in either hand — swords, polearms, daggers and kin. Maces,
// shields and firearms do not qualify.
function hasBladeEquipped(subject) {
  return [subject?.weapon1, subject?.weapon2].filter(Boolean)
    .some(w => /\b(\w*sword|\w*blade|sabre|saber|katana|scimitar|rapier|falchion|claymore|glaive|halberd|spear|pike|naginata|partisan|lance|polearm|dagger|dirk|knife|kris|estoc|cutlass)\b/i.test(w));
}
// Pull and clear a per-fighter effect flag from the fight's effect_state.
function consumeEffectFlag(gid, cid, fid, key) {
  const fight = getFight(gid, cid);
  const all = JSON.parse(fight?.effect_state || '{}');
  const on = !!all[fid]?.[key];
  if (on) {
    delete all[fid][key];
    if (!Object.keys(all[fid]).length) delete all[fid];
    upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
  }
  return on;
}
const consumeFlatAtk = (gid, cid, fid) => consumeEffectFlag(gid, cid, fid, 'flatAtk');
// A successful feint: the target's very next rolled action is a straight d20.
const consumeFooled = (gid, cid, fid) => consumeEffectFlag(gid, cid, fid, 'fooled');
// A called check can mark a character's NEXT roll — 🔼 or 🔽 — and the
// mark is GENERAL: it rides the sheet, not any fight, and bites the very
// next roll anywhere — a chat `!r`, an activity, any fight path, a check
// press. Consumed once, replacing the mode outright (signature already
// folded — even a flat roll can be thrown at advantage). NPC ids pass
// through untouched: the autopilot rolls its own weather.
function applyNextMark(gid, uid, mode) {
  if (!uid || String(uid).startsWith('npc_')) return mode;
  const ch = getChar(gid, uid);
  if (!ch?.next_mark) return mode;
  upsertChar(gid, uid, { next_mark: null });
  return ch.next_mark === 'adv' ? 'adv' : ch.next_mark === 'dis' ? 'dis' : mode;
}
// Set a per-fighter effect flag (the mirror of consumeEffectFlag).
function setEffectFlag(gid, cid, fid, key) {
  const fight = getFight(gid, cid);
  const all = JSON.parse(fight?.effect_state || '{}');
  (all[fid] = all[fid] || {})[key] = true;
  upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
}
// The once-per-round abilities clear when the fighter's own turn comes round.
function clearRoundFlag(gid, cid, fid) {
  consumeEffectFlag(gid, cid, fid, 'deflected');
  consumeEffectFlag(gid, cid, fid, 'disarmUsed');
}
// One write for a round ability's after-effects: the used flag and the flat
// penalty it trades for.
function markRoundSpecial(gid, cid, fid, usedKey, flatKey) {
  const fight = getFight(gid, cid);
  const all = JSON.parse(fight?.effect_state || '{}');
  (all[fid] = all[fid] || {})[usedKey] = true;
  all[fid][flatKey] = true;
  upsertFight(gid, cid, { effect_state: JSON.stringify(all) });
}
const markDisarmUsed = (gid, cid, fid) => markRoundSpecial(gid, cid, fid, 'disarmUsed', 'flatDef');

function grappleHeldTargetOf(fight, id) {
  for (const [t, h] of Object.entries(fightGrapples(fight))) if (h === id) return t;
  return null;
}

function getFight(gid, cid) {
  return db.prepare('SELECT * FROM fights WHERE guild_id=? AND channel_id=?').get(gid, cid);
}
// Insert a bare row then apply the caller's fields. Every non-key column has a
// default, so the bare INSERT is safe. The previous version listed columns
// explicitly and silently dropped anything added later (auto_npc, rr_state,
// floor_hp) whenever a channel's very first fight was created.
function upsertFight(gid, cid, fields) {
  if (!getFight(gid, cid)) {
    db.prepare('INSERT INTO fights (guild_id, channel_id) VALUES (?,?)').run(gid, cid);
  }
  const keys = Object.keys(fields || {});
  if (keys.length) {
    const sets = keys.map(k => `${k}=?`).join(',');
    db.prepare(`UPDATE fights SET ${sets} WHERE guild_id=? AND channel_id=?`).run(...keys.map(k => fields[k]), gid, cid);
  }
  return getFight(gid, cid);
}
function getAllAvailableTags(gid) {
  const customs = getCustomTags(gid).map(t => t.tag_name);
  return [...Object.keys(PRESET_TAGS), ...customs];
}

function saveProfile(gid, uid, slot, snap) {
  db.prepare(`INSERT OR REPLACE INTO profile_saves (guild_id,user_id,slot_name,snapshot,saved_at) VALUES (?,?,?,?,datetime('now'))`).run(gid, uid, slot, JSON.stringify(snap));
}
function loadProfile(gid, uid, slot) {
  const r = db.prepare('SELECT * FROM profile_saves WHERE guild_id=? AND user_id=? AND slot_name=?').get(gid, uid, slot);
  return r ? JSON.parse(r.snapshot) : null;
}
function listProfiles(gid, uid) {
  return db.prepare('SELECT slot_name,saved_at FROM profile_saves WHERE guild_id=? AND user_id=? ORDER BY saved_at DESC').all(gid, uid);
}
// ── Max HP ────────────────────────────────────────────────────────────────────
// max HP = CON + a flat base, set per guild with /config mechanics hpbase. The base used
// to be a hard-coded 2 written out at fourteen separate sites; it lives here now
// so a server can run CON+3 (or CON+0) without any of them drifting apart.
const HP_BASE_DEFAULT = 2;
function hpBase(gid) {
  const v = Number(getConfig(gid)?.hp_base);
  return Number.isFinite(v) && v >= 0 ? v : HP_BASE_DEFAULT;
}
function maxHpFromCon(gid, con) { return (Number(con) || 0) + hpBase(gid); }
function maxHp(ch, gid) { return maxHpFromCon(gid, ch?.con ?? 0); }
function maxRerolls(ch) { return ch?.lck ?? 0; }
function isWhiteKnight(ch) { return ch?.order_name === 'White Knight' && ch?.wis >= 5; }

// ─────────────────────────────────────────────
//  DICE
// ─────────────────────────────────────────────

function parseNotation(n) {
  const m = n.trim().match(/^(\d+)d(\d+)([+-]\d+)?$/i);
  if (!m) return null;
  const dice = parseInt(m[1]), sides = parseInt(m[2]);
  // Sane limits to prevent abuse (e.g. r999999d999999)
  if (dice < 1 || dice > 100) return null;
  if (sides < 1 || sides > 1000) return null;
  return { dice, sides, modifier: m[3] ? parseInt(m[3]) : 0 };
}
function rollDie(sides) { return Math.floor(Math.random() * sides) + 1; }
function rollNotation(notation) {
  const p = parseNotation(notation);
  if (!p) return null;
  const rolls = Array.from({ length: p.dice }, () => rollDie(p.sides));
  const sum = rolls.reduce((a, b) => a + b, 0);
  return { dice: p.dice, sides: p.sides, modifier: p.modifier, rolls, sum, total: sum + p.modifier, notation };
}
function rollAdvantage(notation) {
  const p = parseNotation(notation); if (!p) return null;
  const r1 = rollDie(p.sides), r2 = rollDie(p.sides);
  const chosen = Math.max(r1, r2), dropped = Math.min(r1, r2);
  return { chosen, dropped, rolls: [r1, r2], modifier: p.modifier, total: chosen + p.modifier, sides: p.sides, notation };
}
function rollDisadvantage(notation) {
  const p = parseNotation(notation); if (!p) return null;
  const r1 = rollDie(p.sides), r2 = rollDie(p.sides);
  const chosen = Math.min(r1, r2), dropped = Math.max(r1, r2);
  return { chosen, dropped, rolls: [r1, r2], modifier: p.modifier, total: chosen + p.modifier, sides: p.sides, notation };
}

// ─────────────────────────────────────────────
//  CRIT DETECTION
// ─────────────────────────────────────────────

function detectCrit(result, mode) {
  if (mode === 'adv' || mode === 'dis') {
    if (result.chosen === result.sides) return 'crit';
    if (result.chosen === 1) return 'fail';
    return null;
  }
  if (result.rolls.length === 1) {
    if (result.rolls[0] === result.sides) return 'crit';
    if (result.rolls[0] === 1) return 'fail';
  }
  return null;
}

// ─────────────────────────────────────────────
//  SUCCESS SYSTEM
// ─────────────────────────────────────────────

function getSuccessResult(total, naturalRoll, sides) {
  // Natural max or min override modifiers
  if (naturalRoll === sides) return { label: 'Critical Success', emoji: '🌟', crit: 'crit' };
  if (naturalRoll === 1)     return { label: 'Critical Fail',    emoji: '💀', crit: 'fail' };
  // Final total determines outcome
  if (total >= 15) return { label: 'Success',         emoji: '✅',  crit: null };
  if (total >= 10) return { label: 'Partial Success', emoji: '⚡',  crit: null };
  return            { label: 'Fail',            emoji: '❌',  crit: null };
}

// ─────────────────────────────────────────────
//  EMBED BUILDER
// ─────────────────────────────────────────────

const KNIGHT_EMOJIS = {
  'White Knight':'⚪','Black Knight':'⚫','Gold Knight':'🟡',
  'Grey Knight':'🩶','Blue Knight':'🔵','Purple Knight':'🟣',
  'Green Knight':'🟢','Red Knight':'🔴',
};

function pad(val, w=10) {
  const s = String(val??0);
  return ' '.repeat(Math.max(1, w - s.length)) + s;
}

function critPrefix(critType) {
  if (critType === 'crit') return '🟡 ';
  if (critType === 'fail') return '🔴 ';
  return '';
}

function totalStr(total, critType) {
  if (critType === 'crit') return `🟡 **${total}**`;
  if (critType === 'fail') return `🔴 **${total}**`;
  return `**${total}**`;
}

function buildRollLine(result, mode, critType, successResult) {
  const mod = result.modifier;
  const modStr = mod > 0 ? ` +${mod}` : mod < 0 ? ` ${mod}` : '';
  const ts = totalStr(result.total, critType);
  const suffix = successResult ? `  ${successResult.emoji} ${successResult.label}` : '';
  if (mode === 'normal') return `🎲  ${result.notation} → [${result.rolls.join(', ')}]${modStr} = ${ts}${suffix}`;
  const ml = mode === 'adv' ? '(advantage)' : '(disadvantage)';
  return `🎲  ${result.notation} ${ml} → [${result.chosen}, ~~${result.dropped}~~]${modStr} = ${ts}${suffix}`;
}

// Trailing RP flavour: collapse the lines, then restate the result above it.
// Used by both the embed card and the plain-text card.
function flavourBlock(flavour, label, total, critType) {
  const clean = flavour.split(/\n/).map(l => l.trim()).filter(l => l.length > 0).join('\n\n');
  return ['', '─────────────────────────────', `**${label??'roll'}** — ${totalStr(total, critType)}`, '', clean];
}

function buildRollEmbed({ rollLine, label, isReroll, char, healCharges, maxCharges, flavour, total, critType, tags, gid, reveal = false }) {
  const lines = [];
  const lc = critPrefix(critType);
  if (label) lines.push(`${lc}**${label}**${isReroll ? ' *(reroll)*' : ''}`);
  else if (isReroll) lines.push('*(reroll)*');
  lines.push(rollLine, '');
  lines.push('─────────────────────────────');
  lines.push(`⚔️  ${char.displayName}`);
  // Tags above knight order
  if (tags && tags.length > 0 && gid) {
    tags.forEach(t => lines.push(`${resolveTagEmoji(gid, t)}  ${t}`));
  }
  if (char.order_name) lines.push(`${KNIGHT_EMOJIS[char.order_name]??'⚪'}  ${char.order_name}`);
  if (char.class) lines.push(`🏅  ${char.class}`);
  { const sig = signatureLine(char); if (sig && !char._isNpc) lines.push(sig); }
  // NPC stat blocks are hidden from players by default so their capabilities stay
  // a mystery. A GM can reveal them with /config mechanics npcstats enabled:true.
  // `reveal` builds the GM-grade audit copy: nothing is hidden there.
  const hideNpcStats = !reveal && char._isNpc && !(gid && getConfig(gid)?.npc_stats_visible);
  if (hideNpcStats) lines.push(`❤️  ${hpCondition(char.hp_current, maxHp(char, gid))}`);
  else lines.push(`❤️  HP${pad(char.hp_current)} / ${maxHp(char, gid)}`);
  if (!char._isNpc) lines.push(`🔄  Rerolls${pad(char.rerolls_current)} / ${maxRerolls(char)}`);
  if (isWhiteKnight(char)) lines.push(`🛡️  Heal${pad(healCharges)} / ${maxCharges}`);
  if (!hideNpcStats) {
    lines.push('');
    lines.push(`💪  STR${pad(char.str)}`);
    lines.push(`🫀  CON${pad(char.con)}`);
    lines.push(`⚡  DEX${pad(char.dex)}`);
    lines.push(`🧠  WIS${pad(char.wis)}`);
    lines.push(`🍀  LCK${pad(char.lck)}`);
  }
  if (char.weapon1 || char.weapon2) {
    lines.push('');
    if (char.weapon1) lines.push(`${char.weapon1emoji??'⚔️'}  ${char.weapon1}`);
    if (char.weapon2) lines.push(`${char.weapon2emoji??'🗡️'}  ${char.weapon2}`);
  }
  if (flavour) lines.push(...flavourBlock(flavour, label, total, critType));
  return lines.join('\n');
}

function buildPlainRoll({ rollLine, label, isReroll, flavour, total, critType }) {
  const lines = [];
  const lc = critPrefix(critType);
  if (label) lines.push(`${lc}**${label}**${isReroll ? ' *(reroll)*' : ''}`);
  else if (isReroll) lines.push('*(reroll)*');
  lines.push(rollLine);
  if (flavour) lines.push(...flavourBlock(flavour, label, total, critType));
  return lines.join('\n');
}

// ─────────────────────────────────────────────
//  HELPERS
// ─────────────────────────────────────────────

const STATS = ['str','con','dex','wis','lck'];

// Roll by the long name as readily as the short one: "strength" is the same
// roll as "str". Written out rather than derived so the matching alternation
// stays longest-first — "con" must not win against "constitution".
const STAT_ALIASES = {
  strength: 'str', str: 'str',
  constitution: 'con', con: 'con',
  dexterity: 'dex', dex: 'dex',
  wisdom: 'wis', wis: 'wis',
  luck: 'lck', lck: 'lck',
};
// Longest first so the regex can't stop early on a prefix.
const STAT_WORDS = Object.keys(STAT_ALIASES).sort((a, b) => b.length - a.length);
const STAT_WORD_RE = STAT_WORDS.join('|');
const resolveStatWord = (w) => STAT_ALIASES[String(w || '').toLowerCase()] ?? null;

// ── Character creation budget ─────────────────────────────────────────────────
// A player building their own sheet spends exactly the guild's allowance across
// the five stats, with a minimum in each. GMs are exempt entirely — building for
// a player, adjusting one, or making their own sheet. Both numbers are set per
// guild with /config mechanics statallowance; these are the defaults.
const STAT_BUDGET_DEFAULT = 15;
const STAT_MIN_DEFAULT = 1;
function statRules(gid) {
  const cfg = getConfig(gid) || {};
  const budget = Number(cfg.stat_budget);
  const min = Number(cfg.stat_min);
  return {
    budget: Number.isFinite(budget) && budget > 0 ? budget : STAT_BUDGET_DEFAULT,
    min: Number.isFinite(min) && min >= 0 ? min : STAT_MIN_DEFAULT,
  };
}
const statTotal = (stats) => STATS.reduce((t, k) => t + (Number(stats?.[k]) || 0), 0);

// Every rule the given stat block breaks, as ready-to-print lines; empty means
// it's legal. Both problems are reported together so a player fixing one isn't
// sent straight back for the other.
//
// `exact` is the difference between a finished sheet and one being edited: a
// complete character must spend the allowance exactly, but mid-edit only the
// ceiling applies — otherwise lowering one stat to raise another is impossible,
// since every single step would leave the total short.
function statBudgetProblems(gid, stats, { requireAll = true, exact = true } = {}) {
  const { budget, min } = statRules(gid);
  const out = [];
  const total = statTotal(stats);
  if (total > budget) {
    out.push(`📊 That's **${total} points** — you have **${budget}** to spend. Take **${total - budget}** back off somewhere.`);
  } else if (exact && total < budget) {
    out.push(`📊 That's only **${total} points** — you have **${budget}** to spend. **${budget - total}** still to place.`);
  }
  if (requireAll && min > 0) {
    const short = STATS.filter(k => (Number(stats?.[k]) || 0) < min);
    if (short.length) {
      out.push(`0️⃣ Every stat needs at least **${min}** point${min === 1 ? '' : 's'} — ${short.map(k => `**${k.toUpperCase()}**`).join(', ')} ${short.length === 1 ? 'is' : 'are'} below that.`);
    }
  }
  return out;
}

// A sheet isn't finished until both weapons are named and both emojis chosen.
// Kept separate from the stat budget so a player is told about everything at
// once rather than fixing one thing and being sent back for the next.
function sheetKitProblems(ch) {
  const out = [];
  const missing = [];
  if (!String(ch?.weapon1 || '').trim()) missing.push('**Weapon 1**');
  if (!String(ch?.weapon2 || '').trim()) missing.push('**Weapon 2**');
  if (missing.length) out.push(`⚔️ Name your weapons — ${missing.join(' and ')} ${missing.length === 1 ? 'is' : 'are'} empty.`);

  const noEmoji = [];
  if (!ch?.weapon1emoji_set) noEmoji.push('**Weapon 1**');
  if (!ch?.weapon2emoji_set) noEmoji.push('**Weapon 2**');
  if (noEmoji.length) out.push(`🎨 Pick an emoji for ${noEmoji.join(' and ')} — \`/char weaponemoji\`.`);
  return out;
}

// One refusal covering everything that's wrong, with the spend so far.
function statBudgetReply(gid, problems, stats) {
  const { budget } = statRules(gid);
  const spread = STATS.map(k => `${k.toUpperCase()} ${Number(stats?.[k]) || 0}`).join(' · ');
  return [`❌ **That sheet can't be submitted yet.**`, '', ...problems, '',
          `Your spread: ${spread}  →  **${statTotal(stats)}/${budget}**`,
          `Set them all in one go with \`/char create str:… con:… dex:… wis:… lck:… weapon1:… weapon2:…\`.`].join('\n');
}

// Everything standing between this sheet and a GM seeing it.
function sheetSubmissionProblems(gid, ch) {
  return [...statBudgetProblems(gid, ch), ...sheetKitProblems(ch)];
}

// Post a reply and hand back the message it produced, so an audit or approval
// entry can link straight to it. Four call sites needed the same three lines.
const replyThenFetch = (interaction) => async (c) => {
  await interaction.reply({ content: c });
  try { return await interaction.fetchReply(); } catch { return null; }
};

// Refuse an illegal spread in the channel the player is working in, then copy
// the same note to the approval channel with a jump link, so the GMs can see
// who is wrestling with the budget without being in that channel. `reply` posts
// the refusal and returns the sent message (or null) so the link can point at
// it. Silent when no approval channel is configured.
async function refuseStatBudget({ src, gid, uid, problems, stats, reply, jumpId = null }) {
  const sent = await reply(statBudgetReply(gid, problems, stats));
  const chId = approvalDestination(gid, 'sheets');
  if (!chId) return sent;
  const srcCh = interactionChannelId(src);
  const msgId = jumpId ?? sent?.id ?? null;
  try {
    const nm = await getDisplayName(src.guild, uid);
    const { budget } = statRules(gid);
    const spread = STATS.map(k => `${k.toUpperCase()} ${Number(stats?.[k]) || 0}`).join(' · ');
    const link = (srcCh && msgId) ? `\n[↗ Jump to the attempt](https://discord.com/channels/${gid}/${srcCh}/${msgId})` : '';
    const ch = await approvalChannelFor(src.client, gid, 'sheets');
    await ch.send({
      content: [`📊 **Sheet turned back — point allowance**`,
                `👤 <@${uid}> (**${nm}**)${srcCh ? ` in <#${srcCh}>` : ''}`,
                '─────────────────────────────',
                ...problems,
                `Their spread: ${spread}  →  **${statTotal(stats)}/${budget}**`,
                `_Nothing was submitted. They can fix it and try again._${link}`].join('\n'),
      allowedMentions: { parse: [] },
    });
  } catch (err) {
    console.error('[statbudget] could not mirror refusal:', err?.message || err);
  }
  return sent;
}

// The stat block a sheet would have after applying `updates`.
function statsAfter(existing, updates = {}) {
  const out = {};
  for (const k of STATS) out[k] = updates[k] !== undefined ? updates[k] : (existing?.[k] ?? 0);
  return out;
}

function parseRollInput(input, char) {
  const [rollPart, ...fp] = input.split('\n');
  const flavour = fp.join('\n').trim() || null;
  const trimmed = rollPart.trim();
  // Stat quick roll — "str" or "strength" alone, or with a label after it.
  // `stat` comes back on the result so the card can be forced to show the
  // roller's stat block: a stat roll is only readable next to the numbers.
  const statMatch = trimmed.match(new RegExp(`^(${STAT_WORD_RE})(?:\\s+(.*))?$`, 'i'));
  if (statMatch) {
    const stat = resolveStatWord(statMatch[1]);
    const val = char?.[stat] ?? 0;
    return { notation: `1d20+${val}`, label: statMatch[2]?.trim() || statMatch[1].toLowerCase(), flavour, stat };
  }
  const m = rollPart.trim().match(/^(\d+d\d+(?:[+-]\d+)?)\s*(.*)?$/i);
  if (!m) return null;
  return { notation: m[1], label: m[2]?.trim() || null, flavour };
}

async function getDisplayName(guild, uid) {
  try { const mb = await guild.members.fetch(uid); return mb.nickname || mb.user.username; }
  catch { return 'Unknown'; }
}

// Cache display-name lookups within a single command so a 5-person roster is 5
// fetches, not 10+. Pass the same `cache` object (a Map) through one handler call.
async function getDisplayNameCached(guild, uid, cache) {
  if (cache && cache.has(uid)) return cache.get(uid);
  const name = await getDisplayName(guild, uid);
  if (cache) cache.set(uid, name);
  return name;
}

// interaction.channel is null when Discord omits the channel object from the
// payload (common in threads or uncached channels). interaction.channelId is
// always present, so derive the id from it and lazily fetch the channel only
// when we actually need to send something.
function interactionChannelId(interaction) {
  return interaction.channelId || interaction.channel?.id || null;
}
async function interactionChannel(interaction) {
  if (interaction.channel) return interaction.channel;
  const id = interaction.channelId;
  if (!id) return null;
  return await interaction.client.channels.fetch(id).catch(() => null);
}

// Post content to a channel that may exceed Discord's 2000-char hard limit.
// Same line-boundary chunking as replyLong, for paths that aren't replying to
// an interaction (auto fights, end-of-fight announcements).
// Split content on line boundaries into pieces that fit Discord's 2000-char
// hard limit. Shared by sendLong and replyLong so the two can't drift.
function chunkLines(content, limit = 1900) {
  const src = Array.isArray(content) ? content : String(content).split('\n');
  const chunks = [];
  let buf = '';
  for (const line of src) {
    const piece = line.length > limit ? line.slice(0, limit) : line;
    if (buf.length + piece.length + 1 > limit) { chunks.push(buf); buf = piece; }
    else { buf = buf ? buf + '\n' + piece : piece; }
  }
  if (buf) chunks.push(buf);
  return chunks;
}

async function sendLong(channel, content) {
  if (!channel) return;
  for (const c of chunkLines(content)) await channel.send(c).catch(()=>{});
}

// Reply with content that may exceed Discord's 2000-char hard limit. Splits on
// line boundaries so long lists (quest board, npc list, recaps) never fail
// silently. First chunk is the reply; the rest are follow-ups. Pass an array of
// lines OR a pre-joined string.
// Chunked delivery to any channel or user — the career summary and long
// sheets overflow one message. Files ride the last chunk so nothing arrives
// after the attachment.
async function sendLong(target, content, { files = null, ...opts } = {}) {
  const chunks = chunkLines(content);
  for (let i = 0; i < chunks.length; i++) {
    await target.send({ content: chunks[i], ...(i === chunks.length - 1 && files ? { files } : {}), ...opts });
  }
}

async function replyLong(interaction, content, opts = {}) {
  const LIMIT = 1900; // headroom under 2000 for safety
  const text = Array.isArray(content) ? content.join('\n') : String(content);
  // A deferred interaction has already been answered, so the first message has
  // to be an edit — replying again throws "already acknowledged".
  const first = (payload) => interaction.deferred || interaction.replied
    ? interaction.editReply(payload)
    : interaction.reply(payload);
  if (text.length <= LIMIT) {
    return first({ content: text, ...opts });
  }
  // Chunk by lines, never mid-line unless a single line is itself too long.
  const chunks = chunkLines(Array.isArray(content) ? content : text, LIMIT);
  await first({ content: chunks[0], ...opts });
  for (let i = 1; i < chunks.length; i++) {
    await interaction.followUp({ content: chunks[i], ...opts }).catch(() => {});
  }
}

// Every configured GM role. gm_role_ids (JSON list) is the modern store; the
// legacy single gm_role_id is folded in so older setups keep working.
function getGmRoleIds(gid) {
  const cfg = getConfig(gid);
  let ids = [];
  try { ids = JSON.parse(cfg.gm_role_ids || '[]'); } catch { ids = []; }
  if (!Array.isArray(ids)) ids = [];
  if (cfg.gm_role_id && !ids.includes(cfg.gm_role_id)) ids = [cfg.gm_role_id, ...ids];
  return ids;
}
function setGmRoleIds(gid, ids) {
  const uniq = [...new Set(ids.filter(Boolean))];
  // Keep the legacy column pointing at the first role so nothing else breaks.
  setConfig(gid, { gm_role_ids: JSON.stringify(uniq), gm_role_id: uniq[0] ?? null });
  return uniq;
}

async function isGm(guild, uid) {
  let mb;
  try { mb = await guild.members.fetch(uid); }
  catch { return false; }
  // Server admins are always GMs — this prevents ever locking yourself out of
  // the bot by mis-setting the role.
  if (mb.permissions?.has?.(PermissionFlagsBits.ManageGuild)) return true;
  const ids = getGmRoleIds(guild.id);
  if (!ids.length) return false;
  return ids.some(id => mb.roles.cache.has(id));
}

// `forceCard` is set for stat rolls. A 1d20+4 means nothing on its own — the
// reader has to know it was DEX and that DEX is 4 — so a stat roll always shows
// the roller's sheet, even with the profile embed switched off.
async function sendRollEmbed(message, rollLine, label, isReroll, uid, flavour, total, critType, forceCard = false) {
  const gid = message.guild.id;
  const char = getChar(gid, uid);
  // A stat roll always shows something, because 1d20+4 explains nothing on its
  // own — but it respects a compressed setting rather than overriding it, and
  // only falls back to compressed for someone who has cards off entirely.
  const mode = char ? (forceCard && cardMode(char) === CARD_OFF ? CARD_COMPACT : cardMode(char)) : CARD_OFF;

  if (char && mode === CARD_COMPACT) {
    const lines = [];
    if (label) lines.push(`${critPrefix(critType)}**${label}**`);
    lines.push(rollLine, statLine(char, gid));
    if (flavour) lines.push(...flavourBlock(flavour, label, total, critType));
    const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
    return message.reply({ content: lines.join('\n'), components: [new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`sheetview:${uid}`).setLabel('📖 Full sheet').setStyle(ButtonStyle.Secondary))] });
  }
  if (char && mode === CARD_FULL) {
    const cfg = getConfig(gid);
    const maxCharges = cfg.heal_charges ?? 3;
    const healRow = getHealCharges(gid, uid, maxCharges);
    const displayName = await getDisplayName(message.guild, uid);
    const tags = getPlayerTags(gid, uid);
    return message.reply(buildRollEmbed({ rollLine, label, isReroll, char: { ...char, displayName }, healCharges: healRow.current, maxCharges, flavour, total, critType, tags, gid }));
  }
  return message.reply(buildPlainRoll({ rollLine, label, isReroll, flavour, total, critType }));
}


// ─────────────────────────────────────────────
//  CHARACTER SHEET EXPORT
// ─────────────────────────────────────────────

const ORDER_PALETTE = {
  'White Knight':  { bg: '#f5f0e8', accent: '#c0c0c0', text: '#2a2a2a', border: '#a0a0a0', crest: '⚪' },
  'Black Knight':  { bg: '#1a1a1a', accent: '#4a4a4a', text: '#e8e8e8', border: '#666666', crest: '⚫' },
  'Gold Knight':   { bg: '#fdf3d0', accent: '#c8971a', text: '#2a1a00', border: '#c8971a', crest: '🟡' },
  'Grey Knight':   { bg: '#e8e8e8', accent: '#7a8a9a', text: '#2a2a2a', border: '#7a8a9a', crest: '🩶' },
  'Blue Knight':   { bg: '#e8f0f8', accent: '#1a5fa8', text: '#0a1a2a', border: '#1a5fa8', crest: '🔵' },
  'Purple Knight': { bg: '#f0e8f8', accent: '#6a1a9a', text: '#1a0a2a', border: '#6a1a9a', crest: '🟣' },
  'Green Knight':  { bg: '#e8f5e8', accent: '#1a7a3a', text: '#0a1a0a', border: '#1a7a3a', crest: '🟢' },
  'Red Knight':    { bg: '#f8e8e8', accent: '#9a1a1a', text: '#2a0a0a', border: '#9a1a1a', crest: '🔴' },
};
const DEFAULT_PALETTE = { bg: '#f5f0e8', accent: '#8b7355', text: '#2a2a2a', border: '#8b7355', crest: '⚔️' };


// ── Written props (/gm scroll) ──────────────────────────────────────────────────
// The guild's font, registered with the canvas once per process. Returns the
// family name to draw with, or null when no font is configured. The cache is
// dropped by /config mechanics scrollfont so a replacement takes effect immediately.
const scrollFontCache = new Map(); // gid -> family
function ensureScrollFont(gid) {
  if (scrollFontCache.has(gid)) return scrollFontCache.get(gid);
  const cfg = getConfig(gid) || {};
  if (!cfg.scroll_font) return null;
  let GlobalFonts;
  try { ({ GlobalFonts } = require('@napi-rs/canvas')); }
  catch { return null; } // canvas not available
  const family = `Scroll-${gid}`;
  const tmp = require('path').join(require('os').tmpdir(), `ddice-scroll-${gid}.font`);
  require('fs').writeFileSync(tmp, cfg.scroll_font);
  GlobalFonts.registerFromPath(tmp, family);
  scrollFontCache.set(gid, family);
  return family;
}

// The scroll's weave: what /gm scroll wrote rides invisibly inside the PNG it
// posts, so the image can be handed back later and read out again — the
// same trailer trick the sheet exports use, under its own mark.
const SCROLL_WEAVE_MARK = 'DDICESCROLLv1';
function embedScrollData(png, obj) {
  return Buffer.concat([png, Buffer.from('\n' + SCROLL_WEAVE_MARK + JSON.stringify(obj), 'utf8')]);
}
function extractScrollData(buf) {
  const i = buf.indexOf(SCROLL_WEAVE_MARK);
  if (i === -1) return null;
  try { const o = JSON.parse(buf.slice(i + SCROLL_WEAVE_MARK.length).toString('utf8')); return o && typeof o === 'object' ? o : null; }
  catch { return null; }
}
// An archive-safe file stem: lowercase, dashes for everything else, never
// empty. What a GM types becomes what the files are called.
function fileSlug(s, fallback) {
  const slug = String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 48);
  return slug || fallback;
}

function validateScrollData(o) {
  if (!o || o.v !== 1 || o.kind !== 'scroll') return null;
  if (typeof o.body !== 'string' || !o.body.trim()) return null;
  const str_ = (v, cap) => (typeof v === 'string' && v.trim()) ? v.trim().slice(0, cap) : null;
  return { title: str_(o.title, 80), body: o.body.trim().slice(0, 1600), flavour: str_(o.flavour, 200),
    name: str_(o.name, 48) };
}

// A standard face the process can ALWAYS reach: the live box ships no system
// fonts, so any canvas text falls back to whichever OTF happens to be
// registered — T watched the readable edition come out in fantasy glyphs.
// This is DejaVu Sans (Bitstream Vera licence, embedding-free), subset to
// Latin + common typographic marks, ~17 KB, registered once per process.
const STANDARD_FONT_B64 = '';
let standardFontReady = null; // null = untried, true/false = outcome
function ensureStandardFont() {
  if (standardFontReady !== null) return standardFontReady ? 'DDice-Standard' : null;
  try {
    const { GlobalFonts } = require('@napi-rs/canvas');
    const tmp = require('path').join(require('os').tmpdir(), 'ddice-standard.ttf');
    require('fs').writeFileSync(tmp, Buffer.from(STANDARD_FONT_B64, 'base64'));
    GlobalFonts.registerFromPath(tmp, 'DDice-Standard');
    standardFontReady = true;
  } catch (err) {
    console.error('[fonts] standard face failed to register -', err?.message || err);
    standardFontReady = false;
  }
  return standardFontReady ? 'DDice-Standard' : null;
}

// Greedy word wrap against a real measurer, hard-breaking any single word
// wider than the line. Blank lines split paragraphs.
function wrapScrollLines(measure, text, maxWidth) {
  const out = [];
  for (const para of String(text ?? '').split(/\n/)) {
    const words = para.trim().split(/\s+/).filter(Boolean);
    if (!words.length) { out.push(''); continue; }
    let line = '';
    for (let word of words) {
      while (measure(word) > maxWidth && word.length > 1) {
        // Peel off as much of an overlong word as fits on its own line.
        let cut = word.length - 1;
        while (cut > 1 && measure(word.slice(0, cut)) > maxWidth) cut--;
        if (line) { out.push(line); line = ''; }
        out.push(word.slice(0, cut));
        word = word.slice(cut);
      }
      const tryLine = line ? `${line} ${word}` : word;
      if (line && measure(tryLine) > maxWidth) { out.push(line); line = word; }
      else line = tryLine;
    }
    if (line) out.push(line);
  }
  // A trailing blank from a trailing newline adds nothing.
  while (out.length && out[out.length - 1] === '') out.pop();
  return out;
}

// The parchment itself: cream ground, burnt corners, speckle, a double gold
// rule with maroon diamond cornerstones — the DDice parchment look. Shared
// by the /gm scroll prop and the parchment sheet export.
function paintParchment(ctx, W, H) {
  ctx.fillStyle = '#f3e9d2';
  ctx.fillRect(0, 0, W, H);
  // Burnt corners: one soft radial stain in each.
  for (const [cx, cy] of [[0, 0], [W, 0], [0, H], [W, H]]) {
    const g = ctx.createRadialGradient(cx, cy, 10, cx, cy, 360);
    g.addColorStop(0, 'rgba(112, 78, 40, 0.28)');
    g.addColorStop(1, 'rgba(112, 78, 40, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
  }
  // Speckle: age spots, deterministic enough not to matter.
  ctx.fillStyle = 'rgba(94, 72, 43, 0.06)';
  for (let i = 0; i < 140; i++) {
    ctx.beginPath();
    ctx.arc(Math.random() * W, Math.random() * H, 1 + Math.random() * 2.4, 0, Math.PI * 2);
    ctx.fill();
  }
  // Double gold rule with diamond cornerstones.
  ctx.strokeStyle = '#8a6d3b';
  ctx.lineWidth = 3;
  ctx.strokeRect(26, 26, W - 52, H - 52);
  ctx.lineWidth = 1.5;
  ctx.strokeRect(38, 38, W - 76, H - 76);
  ctx.fillStyle = '#6b1f1f';
  for (const [dx, dy] of [[26, 26], [W - 26, 26], [26, H - 26], [W - 26, H - 26]]) {
    ctx.save(); ctx.translate(dx, dy); ctx.rotate(Math.PI / 4);
    ctx.fillRect(-7, -7, 14, 14); ctx.restore();
  }
}

// A one-page PDF around one JPEG, rolled by hand with exact xref offsets.
// Discord scrubs images on re-upload but passes PDFs byte-exact — so a
// payload woven after %%EOF survives every round trip, Scriptorium-style.
function makeImagePdf(jpeg, w, h) {
  const chunks = []; let off = 0; const offs = [];
  const push = (x) => { const b = Buffer.isBuffer(x) ? x : Buffer.from(x, 'latin1'); chunks.push(b); off += b.length; };
  const obj = (x) => { offs.push(off); push(x); };
  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  obj('1 0 obj\n<</Type/Catalog/Pages 2 0 R>>\nendobj\n');
  obj('2 0 obj\n<</Type/Pages/Kids[3 0 R]/Count 1>>\nendobj\n');
  obj(`3 0 obj\n<</Type/Page/Parent 2 0 R/MediaBox[0 0 ${w} ${h}]/Resources<</XObject<</Im0 4 0 R>>>>/Contents 5 0 R>>\nendobj\n`);
  offs.push(off);
  push(`4 0 obj\n<</Type/XObject/Subtype/Image/Width ${w}/Height ${h}/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length ${jpeg.length}>>\nstream\n`);
  push(jpeg); push('\nendstream\nendobj\n');
  const content = `q ${w} 0 0 ${h} 0 0 cm /Im0 Do Q`;
  obj(`5 0 obj\n<</Length ${content.length}>>\nstream\n${content}\nendstream\nendobj\n`);
  const xref = off;
  push('xref\n0 6\n0000000000 65535 f \n' + offs.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join(''));
  push(`trailer\n<</Size 6/Root 1 0 R>>\nstartxref\n${xref}\n%%EOF\n`);
  return Buffer.concat(chunks);
}

// Base-14 text into a PDF string: escape the delimiters, tame the common
// typographic marks, drop the rest to '?'. The full unicode body always
// arrives in the text reply — this is the printed edition.
function pdfEscape(t) {
  return String(t).replace(/[\u2014\u2013]/g, '-').replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"').replace(/\u2026/g, '...')
    .replace(/[^\x20-\x7E]/g, '?').replace(/([\\()])/g, '\\$1');
}
// Character-count wrap for fixed-metric layouts.
function wrapByCount(text, maxChars) {
  const out = [];
  for (const para of String(text ?? '').split(/\n/)) {
    const words = para.trim().split(/\s+/).filter(Boolean);
    if (!words.length) { out.push(''); continue; }
    let line = '';
    for (let w of words) {
      while (w.length > maxChars) {
        if (line) { out.push(line); line = ''; }
        out.push(w.slice(0, maxChars)); w = w.slice(maxChars);
      }
      const t = line ? line + ' ' + w : w;
      if (line && t.length > maxChars) { out.push(line); line = w; }
      else line = t;
    }
    if (line) out.push(line);
  }
  while (out.length && out[out.length - 1] === '') out.pop();
  return out;
}
// The readable edition as NATIVE PDF text: built-in Helvetica, cream ground,
// gold rules, maroon diamonds and title — no font files involved anywhere,
// so no registered OTF can leak in. The text is selectable, too.
function makeTextPdf({ title, body }) {
  const W = 760, PAD = 80, bodySize = 16, lineH = 24, titleSize = 26;
  const bodyLines = wrapByCount(body, 72);
  const titleLines = title ? wrapByCount(title, 42) : [];
  const titleBlock = titleLines.length ? titleLines.length * 36 + 24 : 0;
  const H = Math.min(2200, PAD * 2 + titleBlock + Math.max(bodyLines.length, 1) * lineH);
  const ops = [];
  ops.push(`0.953 0.914 0.824 rg 0 0 ${W} ${H} re f`);
  ops.push(`0.541 0.427 0.231 RG 3 w 26 26 ${W - 52} ${H - 52} re S`);
  ops.push(`1.5 w 38 38 ${W - 76} ${H - 76} re S`);
  for (const [dx, dy] of [[26, 26], [W - 26, 26], [26, H - 26], [W - 26, H - 26]])
    ops.push(`0.42 0.12 0.12 rg ${dx} ${dy - 10} m ${dx + 10} ${dy} l ${dx} ${dy + 10} l ${dx - 10} ${dy} l f`);
  let y = H - PAD;
  if (titleLines.length) {
    ops.push('0.42 0.12 0.12 rg');
    for (const tl of titleLines) {
      const x = Math.max(PAD, (W - tl.length * titleSize * 0.5) / 2);
      ops.push(`BT /F2 ${titleSize} Tf 1 0 0 1 ${x.toFixed(1)} ${y} Tm (${pdfEscape(tl)}) Tj ET`);
      y -= 36;
    }
    y -= 24;
  }
  ops.push('0.22 0.17 0.10 rg');
  for (const ln of bodyLines) {
    if (ln) ops.push(`BT /F1 ${bodySize} Tf 1 0 0 1 ${PAD} ${y} Tm (${pdfEscape(ln)}) Tj ET`);
    y -= lineH;
  }
  const content = ops.join('\n');
  const chunks = []; let off = 0; const offs = [];
  const push = (x) => { const b = Buffer.isBuffer(x) ? x : Buffer.from(x, 'latin1'); chunks.push(b); off += b.length; };
  const obj = (x) => { offs.push(off); push(x); };
  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  obj('1 0 obj\n<</Type/Catalog/Pages 2 0 R>>\nendobj\n');
  obj('2 0 obj\n<</Type/Pages/Kids[3 0 R]/Count 1>>\nendobj\n');
  obj(`3 0 obj\n<</Type/Page/Parent 2 0 R/MediaBox[0 0 ${W} ${H}]/Resources<</Font<</F1 5 0 R/F2 6 0 R>>>>/Contents 4 0 R>>\nendobj\n`);
  obj(`4 0 obj\n<</Length ${content.length}>>\nstream\n${content}\nendstream\nendobj\n`);
  obj('5 0 obj\n<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>\nendobj\n');
  obj('6 0 obj\n<</Type/Font/Subtype/Type1/BaseFont/Helvetica-Bold>>\nendobj\n');
  const xref = off;
  push('xref\n0 7\n0000000000 65535 f \n' + offs.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join(''));
  push(`trailer\n<</Size 7/Root 1 0 R>>\nstartxref\n${xref}\n%%EOF\n`);
  return Buffer.concat(chunks);
}

function renderScroll({ family, title, body, pdf = false }) {
  const { createCanvas } = require('@napi-rs/canvas');
  const W = 1000, PAD = 90;
  const titleSize = 62, bodySize = 40, lineH = Math.round(bodySize * 1.35);
  // 'standard' asks for the embedded plain face — a REGISTERED family is the
  // only reliable target on a box with no system fonts. Unquoted generic
  // remains the last resort if registration ever fails.
  const std = family === 'standard' ? ensureStandardFont() : null;
  const fontOf = (px) => family === 'standard'
    ? (std ? `${px}px "${std}"` : `${px}px sans-serif`)
    : `${px}px "${family}"`;

  // Measure with a scratch canvas so the real one can be sized to fit.
  const scratch = createCanvas(8, 8).getContext('2d');
  scratch.font = fontOf(bodySize);
  const lines = wrapScrollLines(t => scratch.measureText(t).width, body, W - PAD * 2);
  scratch.font = fontOf(titleSize);
  const titleLines = title ? wrapScrollLines(t => scratch.measureText(t).width, title, W - PAD * 2) : [];

  const titleBlock = titleLines.length ? titleLines.length * Math.round(titleSize * 1.25) + 34 : 0;
  const H = Math.min(2600, PAD * 2 + titleBlock + Math.max(lines.length, 1) * lineH);
  const canvas = createCanvas(W, H);
  const ctx = canvas.getContext('2d');
  paintParchment(ctx, W, H);

  let y = PAD + (titleLines.length ? titleSize : bodySize) * 0.2;
  if (titleLines.length) {
    ctx.fillStyle = '#6b1f1f';
    ctx.font = fontOf(titleSize);
    ctx.textAlign = 'center';
    for (const tl of titleLines) { y += Math.round(titleSize * 1.25); ctx.fillText(tl, W / 2, y); }
    y += 34;
  }
  ctx.fillStyle = '#382c19';
  ctx.font = fontOf(bodySize);
  ctx.textAlign = 'left';
  for (const ln of lines) { y += lineH; if (ln) ctx.fillText(ln, PAD, y); }

  return pdf ? makeImagePdf(canvas.toBuffer('image/jpeg'), W, H) : canvas.toBuffer('image/png');
}

// ── Sheet round-trip weave ───────────────────────────────────────────────────
// Every image export carries the sheet itself, woven after the PNG bytes —
// image viewers ignore the tail, Discord preserves it, and /char import reads
// it back. The same trick Scriptorium plays with its PDFs.
const SHEET_WEAVE_MARK = 'DDICESHEETv1';
function exportPayloadObj(char, displayName) {
  return { v: 1, name: displayName,
    order: char.order_name || null, class: char.class || null,
    str: char.str ?? 0, con: char.con ?? 0, dex: char.dex ?? 0, wis: char.wis ?? 0, lck: char.lck ?? 0,
    weapon1: char.weapon1 || null, weapon1emoji: char.weapon1emoji || null,
    weapon2: char.weapon2 || null, weapon2emoji: char.weapon2emoji || null };
}
function embedSheetData(png, obj) {
  return Buffer.concat([png, Buffer.from('\n' + SHEET_WEAVE_MARK + JSON.stringify(obj), 'utf8')]);
}
// Returns the woven sheet, or null when the file carries none / it's mangled.
function extractSheetData(buf) {
  const i = buf.indexOf(SHEET_WEAVE_MARK);
  if (i === -1) return null;
  try { const o = JSON.parse(buf.slice(i + SHEET_WEAVE_MARK.length).toString('utf8')); return o && typeof o === 'object' ? o : null; }
  catch { return null; }
}
// ── The career summary ───────────────────────────────────────────────────────
// Everything a character has done here, as lines for replyLong: rank and
// merits, renown, the dice tally per die size, inventory, completed quests
// and lore — closed by a [TTRPG SUMMARY] machine block that /char import
// reads back. The block carries merits, renown, the full tally by-map,
// items and lore; quests and rank ride only in the readable part.
const SUMMARY_MARK = '[TTRPG SUMMARY]';
function careerPayloadObj(gid, uid, displayName) {
  const tally = rollTallyAll(gid, uid);
  const t = {};
  for (const [sides, b] of Object.entries(tally.bySize)) t[sides] = b.by;
  const items = listItems(gid, uid).slice(0, 40).map(r => r.note ? { i: r.item, n: r.note } : { i: r.item });
  const loreRow = getLore(gid, uid);
  return { v: 1, kind: 'summary', name: displayName,
    merits: getMerits(gid, uid), renown: getRenown(gid, uid),
    tally: t, items,
    lore: loreRow?.state === 'approved' ? loreRow.body.slice(0, 900) : null };
}
function buildCareerSummary(gid, uid, displayName, { plain = false } = {}) {
  // plain: no markdown, no emoji — lines fit base-14 type on the career PDF.
  const B = (t) => plain ? t : `**${t}**`;
  const ch = getChar(gid, uid) || {};
  const tally = rollTallyAll(gid, uid);
  const quests = getPlayerCompletedQuests(gid, uid);
  const items = listItems(gid, uid);
  const lines = plain ? [] : [`📜 **${displayName} — the record so far**${isFallen(gid, uid) ? ' 🕯️' : ''}`];
  const standing = [];
  if (ch.rank_name) standing.push(ch.rank_name);
  standing.push(plain ? `${getMerits(gid, uid)} merits` : `🎖️ ${getMerits(gid, uid)} merits`,
                plain ? `${getRenown(gid, uid)} renown` : `🪙 ${getRenown(gid, uid)} renown`);
  if (plain && isFallen(gid, uid)) standing.push('fallen');
  lines.push(standing.join(' · '));
  lines.push('');
  if (tally.total) {
    lines.push(`${B('Dice')} — ${tally.total} rolled lifetime`);
    for (const [sides, b] of Object.entries(tally.bySize).sort((a, z) => z[0] - a[0])) {
      const avg = (b.sum / b.total).toFixed(1);
      const bits = [`${b.total} rolled`, `avg ${avg}`];
      if (b.by[sides]) bits.push(`${sides}s ×${b.by[sides]}`);
      if (b.by[1]) bits.push(`1s ×${b.by[1]}`);
      lines.push(`d${sides} — ${bits.join(' · ')}`);
    }
    lines.push('');
  }
  if (items.length) {
    lines.push(`${B('Pack')} — ${items.length} item${items.length === 1 ? '' : 's'}`);
    for (const r of items.slice(0, 15)) lines.push(`${plain ? '-' : '•'} ${r.item}${r.note ? ` — ${r.note}` : ''}`);
    if (items.length > 15) lines.push(`…and ${items.length - 15} more`);
    lines.push('');
  }
  if (quests.length) {
    lines.push(`${B('Quests completed')} — ${quests.length}`);
    for (const q of quests.slice(0, 10)) lines.push(`${plain ? '-' : '•'} #${q.number} ${q.name}`);
    if (quests.length > 10) lines.push(`…and ${quests.length - 10} more`);
    lines.push('');
  }
  const loreRow = getLore(gid, uid);
  if (loreRow?.state === 'approved') lines.push(`${B('Lore')} — on file, travels with the block`, '');
  // The machine tail. If a prodigious tally makes it too long to paste, the
  // dice history is dropped from the block (never from the reading above).
  if (plain) return lines; // the PDF weaves its payload after the EOF instead
  const payload = careerPayloadObj(gid, uid, displayName);
  let json = JSON.stringify(payload);
  if (json.length > 1500) { payload.tally = {}; json = JSON.stringify(payload);
    lines.push('_Dice history too long to travel — the block below carries everything else._'); }
  lines.push('```', SUMMARY_MARK, json, '```');
  return lines;
}
// Read a pasted career block back. Same tolerance as the sheet parser.
function parseCareerSummary(text) {
  const t = String(text ?? '');
  const i = t.indexOf(SUMMARY_MARK);
  if (i === -1) return null;
  const rest = t.slice(i + SUMMARY_MARK.length);
  const line = rest.split('\n').map(l => l.trim()).find(l => l.startsWith('{'));
  if (!line) return null;
  try { const o = JSON.parse(line); return o && o.kind === 'summary' ? o : null; }
  catch { return null; }
}
// A career block is outside input too: totals clamped, tally shape checked.
function validateImportedSummary(o) {
  if (!o || o.v !== 1 || o.kind !== 'summary') return null;
  const int = (n, lo, hi) => Number.isInteger(n) && n >= lo && n <= hi;
  if (!int(o.merits ?? 0, 0, 1_000_000) || !int(o.renown ?? 0, -1_000_000, 1_000_000)) return null;
  const tally = {};
  if (o.tally && typeof o.tally === 'object') {
    for (const [sides, by] of Object.entries(o.tally)) {
      const sd = Number(sides);
      if (!int(sd, 2, 100) || !by || typeof by !== 'object') continue;
      const clean = {};
      for (const [nat, count] of Object.entries(by)) {
        const n = Number(nat);
        if (int(n, 1, sd) && int(count, 1, 1_000_000)) clean[n] = count;
      }
      if (Object.keys(clean).length) tally[sd] = clean;
    }
  }
  const items = Array.isArray(o.items) ? o.items.slice(0, 40)
    .map(it => ({ i: typeof it?.i === 'string' ? it.i.trim().slice(0, 60) : '',
                  n: (typeof it?.n === 'string' && it.n.trim()) ? it.n.trim().slice(0, 120) : null }))
    .filter(it => it.i) : [];
  return { kind: 'summary',
    name: (typeof o.name === 'string' && o.name.trim()) ? o.name.trim().slice(0, 64) : 'Unnamed',
    merits: o.merits ?? 0, renown: o.renown ?? 0, tally, items,
    lore: (typeof o.lore === 'string' && o.lore.trim()) ? o.lore.trim().slice(0, 900) : null };
}

// The text twin of the weave: read a pasted [TTRPG SHEET] block back into
// the same shape the woven JSON takes. Tolerant of code fences and stray
// whitespace; stops at the blank line before the pretty section.
function parseSheetSummary(text) {
  const t = String(text ?? '');
  const i = t.indexOf('[TTRPG SHEET]');
  if (i === -1) return null;
  const map = { NAME: 'name', ORDER: 'order', CLASS: 'class',
    STR: 'str', CON: 'con', DEX: 'dex', WIS: 'wis', LCK: 'lck',
    WEAPON1: 'weapon1', WEAPON1EMOJI: 'weapon1emoji', WEAPON2: 'weapon2', WEAPON2EMOJI: 'weapon2emoji' };
  const nums = ['str', 'con', 'dex', 'wis', 'lck'];
  const o = { v: 1 };
  for (const raw of t.slice(i).split('\n').slice(1)) {
    const line = raw.trim();
    if (!line || line.startsWith('```')) break;
    const m = line.match(/^([A-Z0-9]+):(.*)$/);
    if (!m) break;
    const key = map[m[1]];
    if (!key) continue; // HP/REROLLS travel in the block but never import
    const val = m[2].trim();
    o[key] = nums.includes(key) ? Number(val) : (val || null);
  }
  return o.name !== undefined ? o : null;
}

// NPCs travel too: the same weave, their own kind. The whole villain —
// stats, class, hero flag, signature, auto-pilot preferences, lore — rides
// a parchment PDF and lands on any server by /npc import, GM-direct.
function npcPayloadObj(npc) {
  return { v: 1, kind: 'npc', name: npc.name,
    order: npc.order_name || null, class: npc.class || null,
    str: npc.str ?? 0, con: npc.con ?? 0, dex: npc.dex ?? 0, wis: npc.wis ?? 0, lck: npc.lck ?? 0,
    weapon1: npc.weapon1 || null, weapon2: npc.weapon2 || null,
    is_hero: npc.is_hero ? 1 : 0, signature: npc.signature_stat || null,
    atk: npc.preferred_atk || null, def: npc.preferred_def || null,
    lore: npc.lore ? String(npc.lore).slice(0, 900) : null };
}
function validateImportedNpc(o) {
  if (!o || o.v !== 1 || o.kind !== 'npc') return null;
  const stat = (n) => Number.isInteger(n) && n >= 0 && n <= 99;
  if (![o.str, o.con, o.dex, o.wis, o.lck].every(stat)) return null;
  const str_ = (v, cap) => (typeof v === 'string' && v.trim()) ? v.trim().slice(0, cap) : null;
  const st = (v) => ['str', 'con', 'dex', 'wis', 'lck'].includes(v) ? v : null;
  return { name: str_(o.name, 60) || 'Unnamed',
    order: str_(o.order, 40), class: str_(o.class, 40),
    str: o.str, con: o.con, dex: o.dex, wis: o.wis, lck: o.lck,
    weapon1: str_(o.weapon1, 60), weapon2: str_(o.weapon2, 60),
    is_hero: o.is_hero ? 1 : 0, signature: st(o.signature), atk: st(o.atk), def: st(o.def),
    lore: str_(o.lore, 900) };
}

// Requote a pasted block for the queue post, fenced and bounded.
function sheetSummaryQuote(block) {
  const body = String(block).replace(/```/g, '').trim().slice(0, 500);
  return '```\n' + body + '\n```';
}

// A woven sheet is still outside input: every field is checked and clamped
// before a GM is even asked to look at it.
function validateImportedSheet(o) {
  if (!o || o.v !== 1) return null;
  if (o.kind && o.kind !== 'sheet') return null; // careers and NPCs read elsewhere
  const stat = (n) => Number.isInteger(n) && n >= 0 && n <= 99;
  if (![o.str, o.con, o.dex, o.wis, o.lck].every(stat)) return null;
  const str_ = (v, cap) => (typeof v === 'string' && v.trim()) ? v.trim().slice(0, cap) : null;
  return { name: str_(o.name, 64) || 'Unnamed',
    order: str_(o.order, 40), class: str_(o.class, 40),
    str: o.str, con: o.con, dex: o.dex, wis: o.wis, lck: o.lck,
    weapon1: str_(o.weapon1, 60), weapon1emoji: str_(o.weapon1emoji, 8),
    weapon2: str_(o.weapon2, 60), weapon2emoji: str_(o.weapon2emoji, 8) };
}

// The sheet on parchment: same ground as /gm scroll, in the guild's scroll font
// when one is stored, a plain serif otherwise.
function renderSheetParchment(char, displayName, gid, healLine = null, pdf = false) {
  const { createCanvas } = require('@napi-rs/canvas');
  // No stored font → the embedded standard face; unquoted generic only if
  // even that failed to register. Never a quoted unknown — GlobalFonts is
  // process-global and could hand back ANOTHER guild's OTF.
  const fam = ensureScrollFont(gid) || ensureStandardFont();
  const fontOf = (px) => fam ? `${px}px "${fam}"` : `${px}px serif`;
  const W = 760, PAD = 80, lineH = 52;
  const rows = [];
  rows.push(char.order_name || 'No Order');
  if (char.class) rows.push(char.class);
  rows.push('');
  rows.push(`HP        ${char.hp_current} / ${maxHp(char, gid)}`);
  rows.push(`Rerolls   ${char.rerolls_current} / ${maxRerolls(char)}`);
  if (healLine) rows.push(healLine);
  rows.push('');
  rows.push(`STR   ${char.str}`); rows.push(`CON   ${char.con}`); rows.push(`DEX   ${char.dex}`);
  rows.push(`WIS   ${char.wis}`); rows.push(`LCK   ${char.lck}`);
  if (char.weapon1 || char.weapon2) {
    rows.push('');
    if (char.weapon1) rows.push(char.weapon1);
    if (char.weapon2) rows.push(char.weapon2);
  }
  const H = Math.min(1800, PAD * 2 + 96 + rows.length * lineH);
  const canvas = createCanvas(W, H);
  const ctx = canvas.getContext('2d');
  paintParchment(ctx, W, H);
  ctx.fillStyle = '#6b1f1f';
  ctx.font = fontOf(56);
  ctx.textAlign = 'center';
  ctx.fillText(displayName, W / 2, PAD + 40);
  ctx.fillStyle = '#382c19';
  ctx.font = fontOf(36);
  ctx.textAlign = 'left';
  let y = PAD + 96;
  for (const r of rows) { y += lineH; if (r) ctx.fillText(r, PAD, y); }
  return pdf ? makeImagePdf(canvas.toBuffer('image/jpeg'), W, H) : canvas.toBuffer('image/png');
}

async function generateCharImage(char, displayName, healCharges, maxCharges, gid) {
  let createCanvas;
  try {
    ({ createCanvas } = require('@napi-rs/canvas'));
  } catch {
    return null; // canvas not available
  }

  const pal = ORDER_PALETTE[char.order_name] || DEFAULT_PALETTE;
  const W = 420;
  // Dynamic height: base + extra for class line + weapon lines
  let H = 620;
  if (char.class) H += 18;
  const weaponCount = (char.weapon1?1:0) + (char.weapon2?1:0);
  if (weaponCount) H += 16 + weaponCount * 26;
  const canvas = createCanvas(W, H);
  const ctx = canvas.getContext('2d');

  // ── Background ──────────────────────────────────────────────────────────────
  ctx.fillStyle = pal.bg;
  ctx.fillRect(0, 0, W, H);

  // Parchment texture overlay (subtle noise via gradient bands)
  for (let i = 0; i < H; i += 3) {
    const alpha = (Math.random() * 0.03).toFixed(3);
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    ctx.fillRect(0, i, W, 1);
  }

  // ── Outer border ────────────────────────────────────────────────────────────
  ctx.strokeStyle = pal.border;
  ctx.lineWidth = 6;
  ctx.strokeRect(10, 10, W - 20, H - 20);

  // Inner border
  ctx.lineWidth = 1.5;
  ctx.strokeRect(16, 16, W - 32, H - 32);

  // ── Corner ornaments ────────────────────────────────────────────────────────
  const corners = [[22,22],[W-22,22],[22,H-22],[W-22,H-22]];
  ctx.fillStyle = pal.accent;
  corners.forEach(([x,y]) => {
    ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill();
  });

  // ── Crest / Order symbol ─────────────────────────────────────────────────────
  ctx.font = '52px serif';
  ctx.textAlign = 'center';
  ctx.fillText(pal.crest, W/2, 90);

  // ── Player name ──────────────────────────────────────────────────────────────
  ctx.fillStyle = pal.text;
  ctx.font = 'bold 26px serif';
  ctx.textAlign = 'center';
  ctx.fillText(displayName, W/2, 125);

  // ── Order name ───────────────────────────────────────────────────────────────
  ctx.fillStyle = pal.accent;
  ctx.font = 'italic 16px serif';
  ctx.fillText(char.order_name || 'No Order', W/2, 148);

  // ── Class ────────────────────────────────────────────────────────────────────
  if (char.class) {
    ctx.fillStyle = pal.text;
    ctx.font = '13px serif';
    ctx.fillText(`🏅 ${char.class}`, W/2, 168);
  }

  // ── Divider ──────────────────────────────────────────────────────────────────
  ctx.strokeStyle = pal.border;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(30, char.class ? 180 : 162); ctx.lineTo(W-30, char.class ? 180 : 162); ctx.stroke();

  // ── Tracker rows ─────────────────────────────────────────────────────────────
  const trackers = [
    { label: '❤️  HP', value: `${char.hp_current} / ${maxHp(char, gid)}` },
    { label: '🔄  Rerolls', value: `${char.rerolls_current} / ${maxRerolls(char)}` },
  ];
  if (isWhiteKnight(char)) trackers.push({ label: '🛡️  Heal', value: `${healCharges} / ${maxCharges}` });

  let y = char.class ? 213 : 195;
  trackers.forEach(({ label, value }) => {
    ctx.fillStyle = pal.text;
    ctx.font = '16px serif';
    ctx.textAlign = 'left'; ctx.fillText(label, 40, y);
    ctx.font = 'bold 16px serif';
    ctx.textAlign = 'right'; ctx.fillText(value, W-40, y);
    y += 30;
  });

  // ── Divider ──────────────────────────────────────────────────────────────────
  y += 8;
  ctx.strokeStyle = pal.border; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(30, y); ctx.lineTo(W-30, y); ctx.stroke();
  y += 20;

  // ── Stat rows ────────────────────────────────────────────────────────────────
  const stats = [
    { label: '💪  STR', value: char.str },
    { label: '🫀  CON', value: char.con },
    { label: '⚡  DEX', value: char.dex },
    { label: '🧠  WIS', value: char.wis },
    { label: '🍀  LCK', value: char.lck },
  ];
  stats.forEach(({ label, value }) => {
    ctx.fillStyle = pal.text;
    ctx.font = '16px serif';
    ctx.textAlign = 'left'; ctx.fillText(label, 40, y);
    ctx.font = 'bold 20px serif';
    ctx.fillStyle = pal.accent;
    ctx.textAlign = 'right'; ctx.fillText(String(value), W-40, y);
    y += 32;
  });

  // ── Weapons ──────────────────────────────────────────────────────────────────
  if (char.weapon1 || char.weapon2) {
    // Canvas can't render Discord custom emojis (<:name:id>) — fall back to a sword glyph
    const imgEmoji = (e, fallback) => (e && /^<a?:\w+:\d+>$/.test(e)) ? fallback : (e || fallback);
    y += 4;
    ctx.strokeStyle = pal.border; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(30, y-12); ctx.lineTo(W-30, y-12); ctx.stroke();
    y += 6;
    if (char.weapon1) {
      ctx.fillStyle = pal.text; ctx.font = '15px serif'; ctx.textAlign = 'left';
      ctx.fillText(`${imgEmoji(char.weapon1emoji, '⚔️')}  ${char.weapon1}`, 40, y); y += 26;
    }
    if (char.weapon2) {
      ctx.fillStyle = pal.text; ctx.font = '15px serif'; ctx.textAlign = 'left';
      ctx.fillText(`${imgEmoji(char.weapon2emoji, '🗡️')}  ${char.weapon2}`, 40, y); y += 26;
    }
  }

  // ── Footer ───────────────────────────────────────────────────────────────────
  ctx.strokeStyle = pal.border; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(30, H-35); ctx.lineTo(W-30, H-35); ctx.stroke();
  ctx.fillStyle = pal.accent;
  ctx.font = 'italic 11px serif';
  ctx.textAlign = 'center';
  ctx.fillText('Knight Order Registry', W/2, H-18);

  return canvas.toBuffer('image/png');
}

async function handleCharExport(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const mode = interaction.options.getString('format') || 'text';
  const tu = interaction.options.getUser('user') || interaction.user;
  const tid = tu.id;
  const char = getChar(gid, tid);
  if (!char) return interaction.reply({ content: '❌ No character found. Use `/char set` to get started.', ephemeral: true });

  const dn = await getDisplayName(interaction.guild, tid);
  const cfg = getConfig(gid); const mc = cfg.heal_charges ?? 3;
  const hr = getHealCharges(gid, tid, mc);
  const hm = maxHp(char, gid), rm = maxRerolls(char);

  // ── Text export ──────────────────────────────────────────────────────────────
  const textLines = [
    '```',
    '[TTRPG SHEET]',
    `NAME:${dn}`,
    `ORDER:${char.order_name || ''}`,
    `CLASS:${char.class || ''}`,
    `STR:${char.str}`,
    `CON:${char.con}`,
    `DEX:${char.dex}`,
    `WIS:${char.wis}`,
    `LCK:${char.lck}`,
    `HP:${char.hp_current}`,
    `REROLLS:${char.rerolls_current}`,
    `WEAPON1:${char.weapon1 || ''}`,
    `WEAPON1EMOJI:${char.weapon1emoji || '⚔️'}`,
    `WEAPON2:${char.weapon2 || ''}`,
    `WEAPON2EMOJI:${char.weapon2emoji || '🗡️'}`,
    '',
    `  ${dn}`,
    `  ${char.order_name || 'No Order'}`,
  ];
  if (char.class) textLines.push(`  ${char.class}`);
  { const sig = signatureLine(char, true); if (sig) textLines.push(sig); }
  if (approvalEnabled(gid) && char.approval_state === 'pending') textLines.push('  ⏳ Awaiting GM approval');
  if (approvalEnabled(gid) && char.approval_state === 'rejected') textLines.push('  🚫 Rejected by a GM');
  textLines.push(
    '',
    `  HP       ${char.hp_current} / ${hm}`,
    `  Rerolls  ${char.rerolls_current} / ${rm}`,
  );
  if (isWhiteKnight(char)) textLines.push(`  Heal     ${hr.current} / ${mc}`);
  textLines.push('', `  STR  ${char.str}`, `  CON  ${char.con}`, `  DEX  ${char.dex}`, `  WIS  ${char.wis}`, `  LCK  ${char.lck}`);
  if (char.weapon1 || char.weapon2) {
    textLines.push('');
    if (char.weapon1) textLines.push(`  ${char.weapon1emoji||'⚔️'}  ${char.weapon1}`);
    if (char.weapon2) textLines.push(`  ${char.weapon2emoji||'🗡️'}  ${char.weapon2}`);
  }
  textLines.push('```');
  const textContent = textLines.join('\n');


  // With approvals on, a player's own export goes to the GMs first — they only
  // get the block once a GM releases it. GMs export straight away (they're the
  // ones doing the releasing), and so does anyone exporting on a server that
  // isn't using approvals at all.
  const isGmUser = await isGm(interaction.guild, uid);
  if (approvalEnabled(gid) && !isGmUser && tid === uid) {
    const chId = approvalDestination(gid, 'exports');
    await interaction.reply({ ephemeral: true, content:
      `📤 **Export sent to <#${chId}> for a GM to look over.**\n`
      + `You'll get your sheet as soon as one releases it — by DM, or back here if your DMs are closed.\n`
      + `_This doesn't change your sheet or stop you rolling._` });
    const posted = await requestSheetExport(interaction, gid, uid,
      mode === 'summary' ? buildCareerSummary(gid, uid, dn).join('\n') : textContent, mode);
    if (!posted) {
      await interaction.followUp({ ephemeral: true, content: '⚠️ Couldn\'t reach the approval channel — ask a GM to check `/config channels approvals`.' }).catch(()=>{});
    }
    return;
  }

  if (mode === 'text') {
    return interaction.reply({ content: textContent });
  }
  if (mode === 'summary') {
    return replyLong(interaction, buildCareerSummary(gid, tid, dn));
  }
  if (mode === 'careerpdf') {
    // The record as a native-text PDF, career woven after the EOF — imports
    // back through /char import like any other carrier.
    const buf = embedSheetData(
      makeTextPdf({ title: `${dn} — the record so far`, body: buildCareerSummary(gid, tid, dn, { plain: true }).join('\n') }),
      careerPayloadObj(gid, tid, dn));
    const { AttachmentBuilder } = require('discord.js');
    return interaction.reply({ files: [new AttachmentBuilder(buf, { name: `${dn.replace(/\s+/g,'-')}-career.pdf` })] });
  }

  // ── Image export ─────────────────────────────────────────────────────────────
  await interaction.deferReply();
  let imgBuffer = null;
  try {
    imgBuffer = (mode === 'parchment' || mode === 'pdf')
      ? renderSheetParchment(char, dn, gid, isWhiteKnight(char) ? `Heal      ${hr.current} / ${mc}` : null, mode === 'pdf')
      : await generateCharImage(char, dn, hr.current, mc, gid);
  } catch (err) { console.error('[export] image render failed -', err?.message || err); }
  if (!imgBuffer) {
    return interaction.editReply({ content: textContent + '\n*Image generation unavailable — install `@napi-rs/canvas` to enable.*' });
  }

  const { AttachmentBuilder } = require('discord.js');
  // The sheet rides inside the file — /char import reads it back out. The
  // PDF is the carrier that survives Discord re-uploads.
  const woven = embedSheetData(imgBuffer, exportPayloadObj(char, dn));
  const attachment = new AttachmentBuilder(woven, { name: `${dn.replace(/\s+/g,'-')}-sheet.${mode === 'pdf' ? 'pdf' : 'png'}` });
  return interaction.editReply({ content: textContent, files: [attachment] });
}

// A player hands back an exported sheet image. The woven sheet is read out,
// validated, and queued for the Sheets book with the image attached — the GM
// sees exactly what would be written, including anything off this server's
// allowance, before a single field changes.
// Attachment bytes with a hard ceiling on patience — a wedged CDN fetch after
// a defer otherwise leaves the interaction "thinking" forever.
async function fetchBytes(url, ms = 15_000) {
  const res = await fetch(url, { signal: AbortSignal.timeout(ms) });
  return Buffer.from(await res.arrayBuffer());
}

// One reading for both paste entrances: whichever block arrived, validated.
function readImportBlock(pasted) {
  return validateImportedSheet(parseSheetSummary(pasted))
      ?? validateImportedSummary(parseCareerSummary(pasted));
}
const IMPORT_BLOCK_REFUSAL = '❌ That doesn\'t read as a sheet or career block — paste the whole `[TTRPG SHEET]` block from `/char export format:Text`, or the `[TTRPG SUMMARY]` block from `format:Summary`.';

async function handleCharImport(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const att = interaction.options.getAttachment('image');
  const pasted = interaction.options.getString('summary');
  const dest = approvalDestination(gid, 'sheets');
  if (!dest) {
    return interaction.reply({ content: '❌ This server has no approval destination set — ask a GM to run `/config channels approvals` or `/config channels approvalforum`.', ephemeral: true });
  }
  // Nothing given: open the paste modal — slash options mangle multiline text.
  if (!att && !pasted) {
    const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
    const modal = new ModalBuilder().setCustomId('importpaste').setTitle('Paste the sheet summary');
    modal.addComponents(new ActionRowBuilder().addComponents(
      new TextInputBuilder().setCustomId('summary').setLabel('The [TTRPG SHEET] block')
        .setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(1600)
        .setPlaceholder('[TTRPG SHEET] or [TTRPG SUMMARY] block')));
    return interaction.showModal(modal);
  }
  if (att && !/\.(png|pdf)$/i.test(att.name || '')) {
    return interaction.reply({ content: '❌ That isn\'t a .png or .pdf — use a file exported by `/char export`.', ephemeral: true });
  }
  if (att && (att.size ?? 0) > 8_000_000) {
    return interaction.reply({ content: '❌ That file is over 8 MB — not one of mine.', ephemeral: true });
  }
  await interaction.deferReply({ ephemeral: true });
  let bytes = null, sheet = null;
  if (att) {
    try { bytes = await fetchBytes(att.url); }
    catch (err) {
      console.error('[import] fetch failed -', err?.message || err);
      return interaction.editReply({ content: `❌ Couldn't read that attachment — ${err?.message || err}` });
    }
    const woven = extractSheetData(bytes);
    sheet = validateImportedSheet(woven) ?? validateImportedSummary(woven);
    if (!sheet) {
      return interaction.editReply({ content:
        '❌ No sheet survives in that file — Discord strips hidden data whenever an IMAGE is re-uploaded, so only PDF exports make the trip. The other carrier that always works is text: `/char export format:Text` (or Summary) on the source server, then paste its block here.' });
    }
  } else {
    sheet = readImportBlock(pasted);
    if (!sheet) return interaction.editReply({ content: IMPORT_BLOCK_REFUSAL });
  }
  return queueSheetImport(interaction, gid, uid, sheet, bytes, att?.name || null, att ? null : pasted);
}

// Everything after validation, shared by image, option and modal entrances.
async function queueSheetImport(interaction, gid, uid, sheet, bytes, attName, pastedBlock) {
  const dest = approvalDestination(gid, 'sheets'); // gated by callers; needed for the supersede edit

  // One live request per player: a resubmission retires the queued post.
  const prev = getImportRequest(gid, uid);
  if (prev?.msg_id) {
    try {
      const oldCh = await wakeThread(await interaction.client.channels.fetch(prev.ch_id || dest));
      const old = await oldCh.messages.fetch(prev.msg_id);
      await old.edit({ content: `${old.content}\n\n↻ **Superseded** — a newer import replaced this one.`, components: [] });
    } catch (err) { console.error('[import] supersede edit failed -', err?.message || err); }
  }
  setImportRequest(gid, uid, sheet, interactionChannelId(interaction));

  const isCareer = sheet.kind === 'summary';
  const problems = isCareer ? [] : statBudgetProblems(gid, sheet, { requireAll: true, exact: true });
  const src_ = pastedBlock ? sheetSummaryQuote(pastedBlock) : null;
  const dn = await getDisplayName(interaction.guild, uid);
  const roles = getGmRoleIds(gid);
  const ping = roles.length ? roles.map(r => `<@&${r}>`).join(' ') + ' ' : '';
  const lines = isCareer ? [
    `${ping}📥 **Career import** — <@${uid}> (${dn})`,
    `Standing of **${sheet.name}**: 🎖️ ${sheet.merits} merits · 🪙 ${sheet.renown} renown`,
    `🎲 ${Object.values(sheet.tally).reduce((a, by) => a + Object.values(by).reduce((x, c) => x + c, 0), 0)} dice of history · 🎒 ${sheet.items.length} item${sheet.items.length === 1 ? '' : 's'}${sheet.lore ? ' · 📜 lore travels' : ''}`,
  ] : [
    `${ping}📥 **Sheet import** — <@${uid}> (${dn})`,
    `Written as **${sheet.name}**${sheet.order ? ` · ${sheet.order}` : ''}${sheet.class ? ` · ${sheet.class}` : ''}`,
    `STR ${sheet.str} · CON ${sheet.con} · DEX ${sheet.dex} · WIS ${sheet.wis} · LCK ${sheet.lck}`,
  ];
  if (!isCareer && (sheet.weapon1 || sheet.weapon2)) lines.push([sheet.weapon1, sheet.weapon2].filter(Boolean).join(' · '));
  // Importing over someone who already exists: show precisely what changes.
  const cur = getChar(gid, uid);
  if (cur) {
    if (isCareer) {
      const dm = getMerits(gid, uid), dr = getRenown(gid, uid);
      if (dm !== sheet.merits || dr !== sheet.renown)
        lines.push(`↺ **Over their current standing:** 🎖️ ${dm}→${sheet.merits} · 🪙 ${dr}→${sheet.renown}`);
    } else {
      const diffs = [];
      for (const k of ['str', 'con', 'dex', 'wis', 'lck'])
        if ((cur[k] ?? 0) !== sheet[k]) diffs.push(`${k.toUpperCase()} ${cur[k] ?? 0}→${sheet[k]}`);
      if ((cur.order_name || null) !== sheet.order) diffs.push(`${cur.order_name || 'No Order'}→${sheet.order || 'No Order'}`);
      if ((cur.class || null) !== sheet.class) diffs.push(`${cur.class || 'no class'}→${sheet.class || 'no class'}`);
      const w = (a, b) => (a || '—') + '→' + (b || '—');
      if ((cur.weapon1 || null) !== sheet.weapon1) diffs.push(w(cur.weapon1, sheet.weapon1));
      if ((cur.weapon2 || null) !== sheet.weapon2) diffs.push(w(cur.weapon2, sheet.weapon2));
      lines.push(diffs.length
        ? `↺ **Over their current sheet:** ${diffs.join(' · ')}`
        : '↺ _Identical to their current sheet._');
    }
  }
  if (problems.length) lines.push(`⚠️ **Off this server's allowance:** ${problems.join('; ')}`);
  if (src_) lines.push(src_); // text imports: the GM sees exactly what arrived
  lines.push(isCareer
    ? '_Approving moves their merits and renown to these totals (logged as an import), adds the dice history and items, and files the lore approved. Sheet, rank, quests and tags are untouched._'
    : '_Approving writes this sheet in — HP refilled, rerolls set to LCK — and it arrives already approved._');
  const { ButtonBuilder, ButtonStyle, ActionRowBuilder, AttachmentBuilder } = require('discord.js');
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`impok:${uid}`).setLabel('Approve import').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`impno:${uid}`).setLabel('Decline').setStyle(ButtonStyle.Danger));
  try {
    const ch = await approvalChannelFor(interaction.client, gid, 'sheets');
    const msg = await ch.send({ content: lines.join('\n'), components: [row],
      files: bytes ? [new AttachmentBuilder(bytes, { name: attName || 'imported-sheet.png' })] : [],
      allowedMentions: { roles } });
    setImportRequestMsg(gid, uid, msg.id, ch.id);
    return interaction.editReply({ content: `📥 **Import sent to <#${ch.id}> for a GM to look over.**\nYou'll hear back here or by DM once one decides.` });
  } catch (err) {
    console.error('[import] queue post failed -', err?.message || err);
    return interaction.editReply({ content: `❌ Couldn't reach the approval destination — ${err?.message || err}` });
  }
}

async function handleImportPasteModal(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  await interaction.deferReply({ ephemeral: true });
  const dest = approvalDestination(gid, 'sheets');
  if (!dest) return interaction.editReply({ content: '❌ This server has no approval destination set.' });
  const pasted = interaction.fields.getTextInputValue('summary');
  const sheet = readImportBlock(pasted);
  if (!sheet) return interaction.editReply({ content: IMPORT_BLOCK_REFUSAL });
  return queueSheetImport(interaction, gid, uid, sheet, null, null, pasted);
}

async function handleImportRequestButton(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decide sheet imports.', ephemeral: true });
  const [action, uid] = interaction.customId.split(':');
  const req = getImportRequest(gid, uid);
  if (!req) {
    await interaction.message.edit({ components: [] }).catch(()=>{});
    return interaction.reply({ content: '⏰ That import is no longer pending — it was already handled or superseded.', ephemeral: true });
  }
  if (action === 'impno') {
    return showRejectReasonModal(interaction, `importreject:${uid}`,
      'Decline sheet import', 'e.g. rebuild it under our allowance.');
  }
  // Claim the row before ANY await: parse and clear are synchronous, so a
  // second click a beat later finds nothing pending instead of applying twice.
  let sheet;
  try {
    const raw = JSON.parse(req.payload);
    sheet = raw.kind === 'summary' ? validateImportedSummary({ v: 1, ...raw })
                                   : validateImportedSheet({ v: 1, ...raw });
  } catch { sheet = null; }
  clearImportRequest(gid, uid);
  await interaction.deferReply({ ephemeral: true });
  if (!sheet) { return interaction.editReply({ content: '❌ That stored import no longer reads — ask them to run `/char import` again.' }); }
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  if (sheet.kind === 'summary') {
    // Move standing to the imported totals — the ledgers show the jump.
    const meritDelta = sheet.merits - getMerits(gid, uid);
    if (meritDelta) { addMerits(gid, uid, meritDelta); logHistory(gid, { kind: 'merit', userId: uid, amount: meritDelta, reason: `imported by ${gmName}`, actorId: interaction.user.id }); }
    const renownDelta = sheet.renown - getRenown(gid, uid);
    if (renownDelta) addRenown(gid, uid, renownDelta, `imported by ${gmName}`, { allowNegative: true });
    // Dice history and pack ADD to whatever is already here.
    const addTally = db.prepare(`INSERT INTO roll_tally (guild_id,user_id,sides,nat,count) VALUES (?,?,?,?,?)
      ON CONFLICT(guild_id,user_id,sides,nat) DO UPDATE SET count = count + excluded.count`);
    for (const [sides, by] of Object.entries(sheet.tally))
      for (const [nat, count] of Object.entries(by)) addTally.run(gid, uid, Number(sides), Number(nat), count);
    for (const it of sheet.items) addItem(gid, uid, it.i, { note: it.n, source: 'import', by: interaction.user.id });
    if (sheet.lore) db.prepare(`INSERT INTO lore (guild_id,user_id,body,state,submitted_at,decided_by,decided_at)
      VALUES (?,?,?,'approved',?,?,?)
      ON CONFLICT(guild_id,user_id) DO UPDATE SET body=excluded.body, state='approved', decided_by=excluded.decided_by, decided_at=excluded.decided_at`)
      .run(gid, uid, sheet.lore, Date.now(), interaction.user.id, Date.now());
    try {
      await interaction.message.edit({ content: `${interaction.message.content}\n\n✅ **Imported** by ${gmName}`, components: [] });
    } catch {}
    const notice2 = `✅ **Your career import was approved** by ${gmName} in **${interaction.guild.name}** — standing, dice history, pack${sheet.lore ? ' and lore' : ''} carried over.`;
    try { await (await interaction.client.users.fetch(uid)).send({ content: notice2 }); }
    catch {
      try { const src = await interaction.client.channels.fetch(req.src_channel); await src.send({ content: `<@${uid}> ${notice2}` }); }
      catch (err) { console.error('[import] notify failed -', err?.message || err); }
    }
    return interaction.editReply({ content: `✅ Career imported for <@${uid}>.` });
  }
  // A new arrival takes over a fallen slot: the memorial stays as history,
  // but the death gate lifts — nobody imports into a character they can't play.
  const tookOverFallen = isFallen(gid, uid);
  // Write the sheet in, then refill from what it became.
  upsertChar(gid, uid, {
    ...(tookOverFallen ? { died_at: null } : {}),
    str: sheet.str, con: sheet.con, dex: sheet.dex, wis: sheet.wis, lck: sheet.lck,
    order_name: sheet.order, class: sheet.class,
    weapon1: sheet.weapon1, weapon1emoji: sheet.weapon1emoji,
    weapon2: sheet.weapon2, weapon2emoji: sheet.weapon2emoji,
    approval_state: 'approved', approval_reason: null,
    approval_msg_id: interaction.message.id, approval_ch_id: interaction.channelId, approval_post_ok: 1,
  });
  const fresh = getChar(gid, uid);
  upsertChar(gid, uid, { hp_current: maxHp(fresh, gid), rerolls_current: fresh.lck ?? 0 });
  try {
    await interaction.message.edit({ content: `${interaction.message.content}\n\n✅ **Imported** by ${gmName}`, components: [] });
  } catch {}
  const notice = `✅ **Your sheet import was approved** by ${gmName} in **${interaction.guild.name}** — **${sheet.name}** stands ready, HP full, rerolls at LCK.`;
  try { await (await interaction.client.users.fetch(uid)).send({ content: notice }); }
  catch {
    try { const src = await interaction.client.channels.fetch(req.src_channel); await src.send({ content: `<@${uid}> ${notice}` }); }
    catch (err) { console.error('[import] notify failed -', err?.message || err); }
  }
  return interaction.editReply({ content: `✅ Imported — <@${uid}> now plays **${sheet.name}**.${tookOverFallen ? '\n🕯️ _Their fallen character\'s slot was taken over — the memorial stands, the death gate is lifted._' : ''}` });
}

async function handleImportRejectModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decline imports.', ephemeral: true });
  const uid = interaction.customId.split(':')[1];
  const req = getImportRequest(gid, uid);
  if (!req) return interaction.reply({ content: '⏰ That import is no longer pending.', ephemeral: true });
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  const reason = cleanReason(interaction.fields.getTextInputValue('reason'));
  clearImportRequest(gid, uid);
  try {
    await interaction.message?.edit({ content: `${interaction.message.content}\n\n🚫 **Declined** by ${gmName}${reason ? `\n💬 ${reason}` : ''}`, components: [] });
  } catch {}
  const notice = `🚫 **Your sheet import was declined** by ${gmName} in **${interaction.guild.name}**.`
    + (reason ? `\n💬 **Reason:** ${reason}` : '')
    + `\nYou can \`/char import\` again, or build a sheet here with \`/char create\`.`;
  try { await (await interaction.client.users.fetch(uid)).send({ content: notice }); }
  catch {
    try { const src = await interaction.client.channels.fetch(req.src_channel); await src.send({ content: `<@${uid}> ${notice}` }); }
    catch (err) { console.error('[import] notify failed -', err?.message || err); }
  }
  return interaction.reply({ content: `🚫 Declined.`, ephemeral: true });
}

// Release or decline a queued export. Delivery mirrors sheet decisions: DM
// first, then the channel they ran /char export in, so a closed DM doesn't
// swallow the sheet silently.
async function handleExportRequestButton(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can release sheet exports.', ephemeral: true });
  const [action, uid] = interaction.customId.split(':');
  const req = getExportRequest(gid, uid);
  if (!req) {
    await interaction.message.edit({ components: [] }).catch(()=>{});
    return interaction.reply({ content: '⏰ That export request is no longer pending — it was already handled or superseded.', ephemeral: true });
  }
  if (action === 'exportno') {
    return showRejectReasonModal(interaction, `exportreject:${uid}`,
      'Decline sheet export', 'e.g. not while the campaign is running.');
  }
  const released = true;
  // Claim the row, then ack — the regen and delivery below can be slow, and
  // the three-second window is what the generic banner punishes.
  clearExportRequest(gid, uid);
  await interaction.deferReply({ ephemeral: true });
  const nm = await getDisplayName(interaction.guild, uid);
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);

  // Mark the request as decided so the queue reads cleanly.
  try {
    await interaction.message.edit({
      content: `${interaction.message.content}\n\n${released ? '✅' : '🚫'} **${released ? 'Released' : 'Declined'}** by ${gmName}`,
      components: [],
    });
  } catch {}

  let files = [];
  if (released && req.fmt === 'careerpdf') {
    const nm2 = await getDisplayName(interaction.guild, uid).catch(() => 'them');
    const buf = embedSheetData(
      makeTextPdf({ title: `${nm2} — the record so far`, body: buildCareerSummary(gid, uid, nm2, { plain: true }).join('\n') }),
      careerPayloadObj(gid, uid, nm2));
    const { AttachmentBuilder } = require('discord.js');
    files = [new AttachmentBuilder(buf, { name: `${nm2.replace(/\s+/g,'-')}-career.pdf` })];
  } else if (released && req.fmt && req.fmt !== 'text' && req.fmt !== 'summary') {
    // The image is drawn fresh at release time; the text block is exactly what
    // the GM read in the queue.
    const ch = getChar(gid, uid);
    if (ch) {
      const cfg = getConfig(gid); const mc = cfg.heal_charges ?? 3;
      const hr = getHealCharges(gid, uid, mc);
      let buf = null;
      try {
        buf = (req.fmt === 'parchment' || req.fmt === 'pdf')
          ? renderSheetParchment(ch, nm, gid, isWhiteKnight(ch) ? `Heal      ${hr.current} / ${mc}` : null, req.fmt === 'pdf')
          : await generateCharImage(ch, nm, hr.current, mc, gid);
      } catch (err) { console.error('[export] release render failed -', err?.message || err); }
      if (buf) {
        const { AttachmentBuilder } = require('discord.js');
        files = [new AttachmentBuilder(embedSheetData(buf, exportPayloadObj(ch, nm)), { name: `${nm.replace(/\s+/g,'-')}-sheet.${req.fmt === 'pdf' ? 'pdf' : 'png'}` })];
      }
    }
  }

  const notice = released
    ? `📤 **Your sheet export was released** by ${gmName} in **${interaction.guild.name}**:\n${req.payload}`
    : `🚫 **Your sheet export was declined** by ${gmName} in **${interaction.guild.name}**.\n`
      + `You can ask again whenever you like — run \`/char export\` and it goes back to the GMs.`;

  let told = 'DM';
  try {
    const user = await interaction.client.users.fetch(uid);
    await sendLong(user, notice, { files });
  } catch {
    told = null;
    if (req.src_channel) {
      try {
        const srcChan = await interaction.client.channels.fetch(req.src_channel);
        await sendLong(srcChan, `<@${uid}> ${notice}`, { files, allowedMentions: { users: [uid] } });
        told = 'channel';
      } catch {}
    }
  }
  const delivery = told === 'DM' ? ' _(sent by DM)_'
                 : told === 'channel' ? ' _(DM blocked — posted in the channel they exported from)_'
                 : ' ⚠️ _couldn\'t reach the player — send it to them directly._';
  return interaction.editReply({ content: (released
    ? `✅ Export released to <@${uid}> (**${nm}**).`
    : `🚫 Export declined for <@${uid}> (**${nm}**).`) + delivery,
    allowedMentions: { parse: [] } });
}

