// ─────────────────────────────────────────────
//  SLASH HANDLERS
// ─────────────────────────────────────────────

// Lore is written in a modal, then queued to the same channel sheets go to.
async function handleLoreSubmit(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const body = String(interaction.fields.getTextInputValue('body') || '').trim();
  if (!body) return interaction.reply({ content: '❌ Nothing to send.', ephemeral: true });
  const chId = approvalDestination(gid, 'lore');
  setLore(gid, uid, { body, state: 'pending', reason: null, submitted_at: Date.now(),
    src_channel: interactionChannelId(interaction) });
  await interaction.reply({ ephemeral: true, content: chId
    ? `📜 **Lore sent to <#${chId}> for a GM to read.** You'll hear back once they decide.`
    : '📜 Lore saved, but no approval channel is set — ask a GM to run `/config channels approvals`.' });
  if (!chId) return;
  try {
    const nm = await getDisplayName(interaction.guild, uid);
    const roles = getGmRoleIds(gid);
    const ch = await approvalChannelFor(interaction.client, gid, 'lore');
    const prev = getLore(gid, uid);
    if (prev?.msg_id) {
      try { const oldCh = (prev.ch_id && prev.ch_id !== ch.id)
          ? await wakeThread(await interaction.client.channels.fetch(prev.ch_id)) : ch;
        const old = await oldCh.messages.fetch(prev.msg_id);
        await old.edit({ content: `~~📜 Lore from <@${uid}>~~\n↩️ *Superseded — they rewrote it.*`, components: [] }); } catch {}
    }
    await ch.send({ content: `${roles.map(r => `<@&${r}>`).join(' ')} 📜 **Lore submitted** by <@${uid}> (**${nm}**)`,
      allowedMentions: { roles } });
    const msg = await ch.send({ content: body.length > 1900 ? body.slice(0, 1900) + '…' : body,
      components: [loreButtons(uid)], allowedMentions: { parse: [] } });
    setLore(gid, uid, { msg_id: msg.id, ch_id: ch.id });
  } catch (err) { console.error('[lore] could not queue:', err?.message || err); }
}

async function handleLoreButton(interaction) {
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decide on lore.', ephemeral: true });
  const [action, uid] = interaction.customId.split(':');
  if (action === 'loreno') {
    return showRejectReasonModal(interaction, `lorereject:${uid}`, 'Reject lore', 'e.g. this contradicts the setting.');
  }
  const gid = interaction.guild.id;
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  setLore(gid, uid, { state: 'approved', reason: null, decided_by: interaction.user.id, decided_at: Date.now() });
  try { await interaction.message.edit({ content: `${interaction.message.content}\n\n✅ **Approved** by ${gmName}`, components: [] }); } catch {}
  const told = await notifyPlayer(interaction, gid, uid,
    `✅ **Your lore was approved** by ${gmName} in **${interaction.guild.name}** — it shows on \`/char view showlore\` now.`);
  return interaction.reply({ content: `✅ Lore approved for <@${uid}>.` + deliveryNote(told), allowedMentions: { parse: [] } });
}

async function handleLoreRejectModal(interaction) {
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decide on lore.', ephemeral: true });
  const gid = interaction.guild.id;
  const uid = interaction.customId.split(':')[1];
  const reason = cleanReason(interaction.fields.getTextInputValue('reason'));
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  setLore(gid, uid, { state: 'rejected', reason, decided_by: interaction.user.id, decided_at: Date.now() });
  try { await interaction.message?.edit({ content: `${interaction.message.content}\n\n🚫 **Rejected** by ${gmName}${reason ? `\n💬 ${reason}` : ''}`, components: [] }); } catch {}
  const told = await notifyPlayer(interaction, gid, uid,
    `🚫 **Your lore was turned down** by ${gmName} in **${interaction.guild.name}**.\n`
    + (reason ? `💬 **Reason:** ${reason}\n` : '')
    + 'Rewrite it with `/char lore` and it goes straight back to them.');
  return interaction.reply({ content: `🚫 Lore rejected for <@${uid}>${reason ? ` — “${reason}”` : ''}.` + deliveryNote(told),
    allowedMentions: { parse: [] } });
}

// A player offers merit; nothing moves until a GM approves it.
async function handleMeritGive(interaction) {
  const gid = interaction.guild.id, from = interaction.user.id;
  const to = interaction.options.getUser('user');
  const amount = interaction.options.getInteger('amount');
  const reason = (interaction.options.getString('reason') || '').trim() || null;

  if (to.id === from) return interaction.reply({ content: '❌ You can\'t trade merit with yourself.', ephemeral: true });
  if (to.bot) return interaction.reply({ content: '❌ Pick a character, not a bot.', ephemeral: true });
  const mine = getChar(gid, from);
  if (!mine) return interaction.reply({ content: '❌ You need a character sheet first — `/char create`.', ephemeral: true });
  // The fallen settle no debts. Receiving is allowed — an estate can still be
  // paid into — but a dead character cannot hand their merit away.
  if (mine.died_at) return interaction.reply({ content: '🕯️ Your character has fallen and can no longer trade. A GM can bring them back with `/gm revive`.', ephemeral: true });
  if (!getChar(gid, to.id)) return interaction.reply({ content: `❌ **${await getDisplayName(interaction.guild, to.id)}** has no character sheet.`, ephemeral: true });

  // Checked now and again at approval — merit can be spent in between.
  const have = mine.merits ?? 0;
  if (have < amount) return interaction.reply({ content: `❌ You have **${have}** merit — not enough to give ${amount}.`, ephemeral: true });

  const chId = approvalDestination(gid, 'trades');
  const fromName = await getDisplayName(interaction.guild, from);
  const toName = await getDisplayName(interaction.guild, to.id);
  const trade = createMeritTrade(gid, from, to.id, amount, reason, interactionChannelId(interaction));

  await interaction.reply({ content:
    `🤝 **${fromName}** offers **${amount} merit** to **${toName}**${reason ? ` — ${reason}` : ''}.\n`
    + (chId ? `_Held for a GM to sign off${chId ? ` in <#${chId}>` : ''}. Nothing moves until then._`
            : '_⚠️ No approval channel is set, so no GM has been told — ask one to run `/config channels approvals`._') });
  if (!chId) return;

  try {
    const roles = getGmRoleIds(gid);
    const ch = await approvalChannelFor(interaction.client, gid, 'trades');
    const msg = await ch.send({
      content: [`${roles.map(r => `<@&${r}>`).join(' ')} 🤝 **Merit trade — trade #${trade.id}**`,
        `From <@${from}> (**${fromName}**) — holds ${have}`,
        `To <@${to.id}> (**${toName}**)`,
        `Amount: **${amount} merit**`,
        reason ? `Reason: ${reason}` : 'No reason given',
      ].join('\n'),
      components: [meritTradeButtons(trade.id)], allowedMentions: { roles } });
    setMeritTrade(gid, trade.id, { msg_id: msg.id, ch_id: ch.id });
  } catch (err) {
    console.error('[merit] could not queue trade:', err?.message || err);
    await interaction.followUp({ ephemeral: true, content: '⚠️ Couldn\'t reach the approval channel — ask a GM to check `/config channels approvals`.' }).catch(()=>{});
  }
}

async function handleMeritTradeButton(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decide on merit trades.', ephemeral: true });
  const [action, idRaw] = interaction.customId.split(':');
  const trade = getMeritTrade(gid, Number(idRaw));
  if (!trade || trade.state !== 'pending') {
    try { await interaction.message.edit({ components: [] }); } catch {}
    return interaction.reply({ content: '⏰ That trade has already been settled.', ephemeral: true });
  }
  if (action === 'tradeno') {
    return showRejectReasonModal(interaction, `traderej:${trade.id}`, 'Refuse merit trade', 'e.g. not while they owe the guild.');
  }

  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  const fromName = await getDisplayName(interaction.guild, trade.from_user);
  const toName = await getDisplayName(interaction.guild, trade.to_user);
  // Re-check the balance: merit may have moved since the offer was made.
  const sender = getChar(gid, trade.from_user);
  if (sender?.died_at) {
    db.prepare(`UPDATE merit_trades SET state='void', decided_by=?, decided_at=? WHERE guild_id=? AND id=? AND state='pending'`)
      .run(interaction.user.id, Date.now(), gid, trade.id);
    try { await interaction.message.edit({ content: `${interaction.message.content}\n\n⚠️ **Void** — ${fromName} has fallen.`, components: [] }); } catch {}
    return interaction.reply({ content: `⚠️ **${fromName}** has fallen since offering this. The trade is void.` });
  }
  const have = sender?.merits ?? 0;
  if (have < trade.amount) {
    setMeritTrade(gid, trade.id, { state: 'void', decided_by: interaction.user.id, decided_at: Date.now() });
    try { await interaction.message.edit({ content: `${interaction.message.content}\n\n⚠️ **Void** — they no longer have the merit.`, components: [] }); } catch {}
    return interaction.reply({ content: `⚠️ **${fromName}** only has **${have}** merit now — the trade can't go through.` });
  }

  // Claim the trade before moving anything. Two GMs pressing Approve at the
  // same moment would otherwise both pass the pending check and pay twice.
  const claimed = db.prepare(`UPDATE merit_trades SET state='approved', decided_by=?, decided_at=?
                              WHERE guild_id=? AND id=? AND state='pending'`)
    .run(interaction.user.id, Date.now(), gid, trade.id).changes === 1;
  if (!claimed) return interaction.reply({ content: '⏰ Someone got there first — that trade is already settled.', ephemeral: true });
  addMerits(gid, trade.from_user, -trade.amount);
  addMerits(gid, trade.to_user, trade.amount);
  try { await interaction.message.edit({ content: `${interaction.message.content}\n\n✅ **Approved** by ${gmName}`, components: [] }); } catch {}

  const notice = `🤝 **Merit trade approved** by ${gmName} in **${interaction.guild.name}** — `
    + `**${trade.amount}** merit from **${fromName}** to **${toName}**${trade.reason ? ` (${trade.reason})` : ''}.`;
  await notifyPlayer(interaction, gid, trade.from_user, notice);
  await notifyPlayer(interaction, gid, trade.to_user, notice);
  // Say it where it was offered, so the table sees the trade land.
  if (trade.src_channel) {
    try { const ch = await interaction.client.channels.fetch(trade.src_channel);
      await ch.send({ content: notice, allowedMentions: { parse: [] } }); } catch {}
  }
  return interaction.reply({ content:
    `✅ Trade #${trade.id} approved — **${trade.amount}** merit moved from **${fromName}** to **${toName}**.` });
}

async function handleMeritTradeRejectModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decide on merit trades.', ephemeral: true });
  const trade = getMeritTrade(gid, Number(interaction.customId.split(':')[1]));
  if (!trade || trade.state !== 'pending') return interaction.reply({ content: '⏰ That trade has already been settled.', ephemeral: true });
  const reason = cleanReason(interaction.fields.getTextInputValue('reason'));
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  const claimedRefusal = db.prepare(`UPDATE merit_trades SET state='refused', reason=?, decided_by=?, decided_at=?
                                     WHERE guild_id=? AND id=? AND state='pending'`)
    .run(reason, interaction.user.id, Date.now(), gid, trade.id).changes === 1;
  if (!claimedRefusal) return interaction.reply({ content: '⏰ Someone got there first — that trade is already settled.', ephemeral: true });
  try { await interaction.message?.edit({ content: `${interaction.message.content}\n\n🚫 **Refused** by ${gmName}${reason ? `\n💬 ${reason}` : ''}`, components: [] }); } catch {}
  const notice = `🚫 **Your merit trade was refused** by ${gmName} in **${interaction.guild.name}**.`
    + (reason ? `\n💬 **Reason:** ${reason}` : '') + '\nNo merit changed hands.';
  await notifyPlayer(interaction, gid, trade.from_user, notice);
  return interaction.reply({ content: `🚫 Trade #${trade.id} refused${reason ? ` — “${reason}”` : ''}. No merit moved.`,
    allowedMentions: { parse: [] } });
}

// An NPC's record, built from the same tables a player's pages read.
async function handleNpcPages(interaction, sub) {
  const gid = interaction.guild.id;
  const name = interaction.options.getString('name').trim();
  const npc = getNpc(gid, name);
  if (!npc) return interaction.reply({ content: `❌ No NPC called **${name}**.`, ephemeral: true });
  const id = npcFighterId(npc.name);

  if (sub === 'give') {
    const item = interaction.options.getString('item').trim();
    addItem(gid, id, item, { note: interaction.options.getString('note'), source: 'given by a GM', by: interaction.user.id });
    return interaction.reply({ content: `🎒 **${npc.name}** 🎭 receives **${item}**.` });
  }
  if (sub === 'take') {
    const itemId = interaction.options.getInteger('id');
    return interaction.reply({ content: removeItem(gid, itemId, id)
      ? `🎒 Item \`#${itemId}\` taken from **${npc.name}** 🎭.`
      : `❌ **${npc.name}** has no item \`#${itemId}\`.`, ephemeral: true });
  }
  if (sub === 'npclore') {
    const text = interaction.options.getString('text').trim();
    const clearing = /^(none|clear|-)$/i.test(text);
    db.prepare('UPDATE npcs SET lore=? WHERE guild_id=? AND name=?').run(clearing ? null : text, gid, npc.name);
    return interaction.reply({ content: clearing
      ? `📜 Cleared **${npc.name}**'s lore.` : `📜 Lore written for **${npc.name}** 🎭.` });
  }

  // sheet — the whole record on one page
  const max = maxHpFromCon(gid, npc.con);
  const lines = [`⚔️  **${npc.name}** 🎭`];
  if (npc.order_name) lines.push(`${KNIGHT_EMOJIS[npc.order_name] ?? '⚪'}  ${npc.order_name}`);
  if (npc.class) lines.push(`🏅  ${npc.class}`);
  if (isHero(npc) && npc.signature_stat) lines.push(`${STAT_EMOJIS[npc.signature_stat] ?? '✨'}:  ${STAT_LABELS[npc.signature_stat]} advantage`);
  lines.push(`❤️  HP          ${npc.hp_current} / ${max}`);
  lines.push('', `💪  STR         ${npc.str ?? 0}`, `🫀  CON         ${npc.con ?? 0}`,
             `⚡  DEX         ${npc.dex ?? 0}`, `🧠  WIS         ${npc.wis ?? 0}`, `🍀  LCK         ${npc.lck ?? 0}`);
  if (npc.weapon1 || npc.weapon2) {
    lines.push('');
    for (const w of [npc.weapon1, npc.weapon2].filter(Boolean)) {
      const row = getWeaponRow(gid, w);
      const bits = [];
      if (row?.atk_stats) bits.push(`⚔️ ${parseStatList(row.atk_stats).map(x => x.toUpperCase()).join('/')}`);
      if (row?.def_stats) bits.push(`🛡️ ${parseStatList(row.def_stats).map(x => x.toUpperCase()).join('/')}`);
      lines.push(`⚔️  ${w}${bits.length ? `  ·  ${bits.join(' ')}` : ''}`);
    }
  }

  if (npc.preferred_atk || npc.preferred_def) {
    lines.push('', `🎯  Auto — ⚔️ ${npc.preferred_atk ? STAT_LABELS[npc.preferred_atk] : 'best allowed'}`
      + ` · 🛡️ ${npc.preferred_def ? STAT_LABELS[npc.preferred_def] : 'best allowed'}`);
  }
  lines.push('', `🏅 **Standing** — **${npc.merits ?? 0}** merit${(npc.merits ?? 0) === 1 ? '' : 's'} · 💠 **${npc.renown ?? 0}** renown`);
  const ev = standingEvents(gid, id, 10);
  for (const e of ev) {
    lines.push(`${e.kind === 'merit' ? '🏅' : '💠'} ${e.delta > 0 ? '+' : ''}${e.delta} · ${e.reason || 'no reason given'}`
      + (e.at ? ` · <t:${Math.floor(e.at / 1000)}:R>` : ''));
  }

  const items = listItems(gid, id);
  lines.push('', items.length ? '🎒 **Inventory**' : '🎒 **Inventory** — empty.');
  for (const i of items) lines.push(`\`#${i.id}\` **${i.item}**${i.note ? ` — ${i.note}` : ''}`);

  const t = rollTally(gid, id, 20);
  lines.push('', t.total
    ? `🎲 **Rolls** — ${t.total} lifetime · 🌟 ${t.by[20] || 0} nat-20${(t.by[20] || 0) === 1 ? '' : 's'} · 💀 ${t.by[1] || 0} nat-1${(t.by[1] || 0) === 1 ? '' : 's'}`
    : '🎲 **Rolls** — nothing recorded yet.');

  if (npc.lore) lines.push('', '📜 **Lore**', npc.lore);
  return replyLong(interaction, lines);
}

// Everything here is prefixed and disposable. It exists so a GM can exercise
// the board, the timer, the pages and the summary without inventing a real
// quest or an NPC they will then have to tidy out of the world.
const GMTEST_PREFIX = '[test] ';

// Resolve the target of a death or revival to a page subject.
async function resolveMortal(interaction) {
  const gid = interaction.guild.id;
  const user = interaction.options.getUser('user');
  const npcName = (interaction.options.getString('npc') || '').trim();
  if (!!user === !!npcName) return { error: '❌ Name exactly one of `user` or `npc`.' };
  if (user) {
    const ch = getChar(gid, user.id);
    if (!ch) return { error: `❌ <@${user.id}> has no character sheet.` };
    return { id: user.id, subject: ch, name: await getDisplayName(interaction.guild, user.id) };
  }
  const npc = getNpc(gid, npcName);
  if (!npc) return { error: `❌ No NPC called **${npcName}**.` };
  return { id: npcFighterId(npc.name), subject: npc, name: npc.name };
}

// Work waiting on a decision lived in four different commands, and pending lore
// had no listing at all — a submission whose queue post was deleted was simply
// invisible. This is the one place to look.
// Search the roster. Reads in the same order everything else does, with each
// character's forum page hung off their line where they have one.
// Raise one. A player gets a single open proposal at a time — the limit is the
// whole reason this is a command rather than free-form messages.
async function handleDuel(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const gate = sheetGate(gid, uid);
  if (gate) return interaction.reply({ content: gate, ephemeral: true });
  if (!getChar(gid, uid)) return interaction.reply({ content: '❌ You need a character sheet first — `/char create`.', ephemeral: true });

  const mine = openDuelFor(gid, uid);
  if (mine) {
    const where = mine.msg_id ? `https://discord.com/channels/${gid}/${mine.channel_id}/${mine.msg_id}` : null;
    return interaction.reply({ ephemeral: true, content:
      `⚔️ You already have a duel open${mine.state === 'pending' ? ' and with the GMs' : ''}.\n`
      + (where ? `${where}\n` : '') + '_Withdraw it there before raising another._' });
  }
  const elsewhere = duelElsewhere(gid, uid);
  if (elsewhere) return interaction.reply({ ephemeral: true, content:
    '⚔️ You are already standing in someone else\'s duel. Step out of that one first.' });

  const terms = (interaction.options.getString('terms') || '').trim() || null;
  const info = db.prepare(`INSERT INTO duels (guild_id,channel_id,opener,fighters,terms,created_at)
                           VALUES (?,?,?,?,?,?)`)
    .run(gid, interactionChannelId(interaction), uid, JSON.stringify([uid]), terms, Date.now());
  const d = getDuel(gid, info.lastInsertRowid);
  const lines = await renderDuel(interaction.guild, d);
  await interaction.reply({ content: lines.join('\n'), components: duelButtons(d), allowedMentions: { parse: [] } });
  const msg = await interaction.fetchReply();
  setDuel(gid, d.id, { msg_id: msg.id });
}

async function handleDuelButton(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const [action, idRaw] = interaction.customId.split(':');
  const d = getDuel(gid, Number(idRaw));
  if (!d) return interaction.reply({ content: '❌ That duel has gone.', ephemeral: true });
  if (!DUEL_LIVE.includes(d.state)) return interaction.reply({ content: `❌ That duel is already ${d.state}.`, ephemeral: true });

  const fighters = duelFighters(d);

  if (action === 'dueljoin') {
    if (d.state !== 'open') return interaction.reply({ content: '⏳ That one is already with the GMs.', ephemeral: true });
    const g2 = sheetGate(gid, uid);
    if (g2) return interaction.reply({ content: g2, ephemeral: true });
    if (!getChar(gid, uid)) return interaction.reply({ content: '❌ You need a character sheet to duel — `/char create`.', ephemeral: true });
    if (fighters.includes(uid)) return interaction.reply({ content: 'You are already standing in this one.', ephemeral: true });
    const busy = duelElsewhere(gid, uid, d.id) || openDuelFor(gid, uid);
    if (busy) return interaction.reply({ content: '⚔️ You are already in another duel. Step out of that one first.', ephemeral: true });
    if (fighters.length >= 8) return interaction.reply({ content: '❌ Eight is as many as one duel takes.', ephemeral: true });
    fighters.push(uid);
    const updated = setDuel(gid, d.id, { fighters: JSON.stringify(fighters) });
    await interaction.reply({ content: `⚔️ <@${uid}> stands in.`, allowedMentions: { parse: [] } });
    return refreshDuel(interaction.client, interaction.guild, updated);
  }

  if (action === 'duelout') {
    if (uid === d.opener) return interaction.reply({ content: '❌ You raised this one — withdraw it instead.', ephemeral: true });
    if (!fighters.includes(uid)) return interaction.reply({ content: 'You are not in this one.', ephemeral: true });
    const updated = setDuel(gid, d.id, { fighters: JSON.stringify(fighters.filter(x => x !== uid)) });
    await interaction.reply({ content: `↩️ <@${uid}> steps out.`, allowedMentions: { parse: [] } });
    return refreshDuel(interaction.client, interaction.guild, updated);
  }

  if (action === 'duelcancel') {
    const isGmUser = await isGm(interaction.guild, uid);
    if (uid !== d.opener && !isGmUser) return interaction.reply({ content: '❌ Only whoever raised it, or a GM, can withdraw it.', ephemeral: true });
    const updated = setDuel(gid, d.id, { state: 'cancelled', decided_by: uid, decided_at: Date.now() });
    await interaction.reply({ content: '↩️ Duel withdrawn.' });
    await refreshDuel(interaction.client, interaction.guild, updated);
    if (d.approval_msg_id) {
      // Edit the queue post wherever it was actually made.
      const chId = d.approval_ch_id || approvalDestination(gid, 'duels');
      try {
        const ch = await wakeThread(await interaction.client.channels.fetch(chId));
        const m = await ch.messages.fetch(d.approval_msg_id);
        await m.edit({ content: `~~⚔️ Duel #${d.id}~~\n↩️ *Withdrawn.*`, components: [] });
      } catch {}
    }
    return;
  }

  if (action === 'duelsend') {
    if (uid !== d.opener) return interaction.reply({ content: '❌ Only whoever raised it can send it.', ephemeral: true });
    if (fighters.length < 2) return interaction.reply({ content: '❌ A duel needs at least two.', ephemeral: true });
    const chId = approvalDestination(gid, 'duels');
    if (!chId) return interaction.reply({ content: '❌ No approval channel is set — ask a GM to run `/config channels approvals`.', ephemeral: true });

    const updated = setDuel(gid, d.id, { state: 'pending' });
    await interaction.reply({ content: '📨 Sent to the GMs.', ephemeral: true });
    await refreshDuel(interaction.client, interaction.guild, updated);
    try {
      const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
      const roles = getGmRoleIds(gid);
      const ch = await approvalChannelFor(interaction.client, gid, 'duels');
      const names = [];
      for (const f of fighters) names.push(`<@${f}> (**${await getDisplayName(interaction.guild, f)}**)`);
      const row = new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`duelok:${d.id}`).setLabel('Allow it').setStyle(ButtonStyle.Success),
        new ButtonBuilder().setCustomId(`duelno:${d.id}`).setLabel('Decline').setStyle(ButtonStyle.Danger));
      const m = await ch.send({ allowedMentions: { roles }, components: [row], content: [
        `${roles.map(r => `<@&${r}>`).join(' ')} ⚔️ **Duel #${d.id}** — raised by <@${d.opener}>`,
        d.terms ? `📜 ${d.terms}` : '_No terms set._',
        `**Standing in:** ${names.join(' · ')}`,
        `_In <#${d.channel_id}>._`,
      ].join('\n') });
      setDuel(gid, d.id, { approval_msg_id: m.id, approval_ch_id: ch.id });
    } catch (err) {
      console.error('[duel] could not queue:', err?.message || err);
      await interaction.followUp({ ephemeral: true, content: `⚠️ Couldn't reach the approval channel: ${err?.message || err}` }).catch(()=>{});
    }
    return;
  }

  // A GM's decision
  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can decide on a duel.', ephemeral: true });
  if (action === 'duelno') {
    return showRejectReasonModal(interaction, `duelrej:${d.id}`, 'Decline duel', 'e.g. not while the siege is on.');
  }
  const gmName = await getDisplayName(interaction.guild, uid);
  const updated = setDuel(gid, d.id, { state: 'approved', decided_by: uid, decided_at: Date.now() });
  bookLog(gid, 'duels', `🤺 **Duel #${d.id} allowed** by <@${uid}> — ${fighters.map(f => `<@${f}>`).join(' vs ')}`);
  try { await interaction.message.edit({ content: `${interaction.message.content}\n\n✅ **Allowed** by ${gmName}`, components: [] }); } catch {}
  await refreshDuel(interaction.client, interaction.guild, updated);
  await interaction.reply({ content: `✅ Duel #${d.id} allowed. Start it with \`/fight start players:${fighters.map(f => `<@${f}>`).join(' ')}\`` });
  try {
    const ch = await interaction.client.channels.fetch(d.channel_id);
    await ch.send({ content: `⚔️ **Duel #${d.id} is allowed** — ${fighters.map(f => `<@${f}>`).join(' vs ')}. A GM will start it.`,
      allowedMentions: { users: mentionList(fighters) } });
  } catch {}
}

async function handleDuelRejectModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decide on a duel.', ephemeral: true });
  const d = getDuel(gid, Number(interaction.customId.split(':')[1]));
  if (!d || !DUEL_LIVE.includes(d.state)) return interaction.reply({ content: '⏰ That duel has already been settled.', ephemeral: true });
  const reason = cleanReason(interaction.fields.getTextInputValue('reason'));
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  const updated = setDuel(gid, d.id, { state: 'declined', reason, decided_by: interaction.user.id, decided_at: Date.now() });
  bookLog(gid, 'duels', `🤺 **Duel #${d.id} declined** by <@${interaction.user.id}>${reason ? ` — _${reason}_` : ''}`);
  try { await interaction.message?.edit({ content: `${interaction.message.content}\n\n🚫 **Declined** by ${gmName}${reason ? `\n💬 ${reason}` : ''}`, components: [] }); } catch {}
  await refreshDuel(interaction.client, interaction.guild, updated);
  await interaction.reply({ content: `🚫 Duel #${d.id} declined${reason ? ` — “${reason}”` : ''}.` });
  try {
    const ch = await interaction.client.channels.fetch(d.channel_id);
    await ch.send({ content: `🚫 **Duel #${d.id} was declined** by ${gmName}${reason ? ` — ${reason}` : ''}.`, allowedMentions: { parse: [] } });
  } catch {}
}

async function handleGmSearch(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can search the roster.', ephemeral: true });
  await interaction.deferReply({ ephemeral: true });

  const wantOrder = interaction.options.getString('order');
  const wantClass = interaction.options.getString('class');
  const wantHero = interaction.options.getBoolean('hero');
  const who = interaction.options.getString('who') ?? 'both';
  const withFallen = interaction.options.getBoolean('fallen') ?? false;
  const nameBit = (interaction.options.getString('name') || '').trim().toLowerCase();

  const matches = (row, name) => {
    if (!withFallen && row?.died_at) return false;
    if (wantOrder === '__none__' ? !!row?.order_name : (wantOrder && row?.order_name !== wantOrder)) return false;
    if (wantClass === '__none__' ? !!row?.class : (wantClass && row?.class !== wantClass)) return false;
    if (wantHero !== null && wantHero !== undefined && isHero(row) !== wantHero) return false;
    if (nameBit && !String(name).toLowerCase().includes(nameBit)) return false;
    return true;
  };

  const entries = [];
  if (who !== 'npcs') {
    for (const ch of db.prepare('SELECT * FROM characters WHERE guild_id=?').all(gid)) {
      const nm = await getDisplayName(interaction.guild, ch.user_id);
      if (!matches(ch, nm)) continue;
      const bits = [];
      if (ch.class) bits.push(ch.class);
      if (isHero(ch)) bits.push('🦸 Hero');
      if (ch.died_at) bits.push('🕯️ fallen');
      const link = charPageLink(gid, ch.user_id, 'page');
      entries.push({ row: ch, name: nm,
        text: `**${nm}**${bits.length ? ` — ${bits.join(' · ')}` : ''}${link ? ` · 📖 ${link}` : ''}` });
    }
  }
  if (who !== 'players') {
    for (const npc of getAllNpcs(gid)) {
      if (!matches(npc, npc.name)) continue;
      const bits = [];
      if (npc.class) bits.push(npc.class);
      if (isHero(npc)) bits.push('🦸 Hero');
      if (npc.died_at) bits.push('🕯️ fallen');
      entries.push({ row: npc, name: npc.name, isNpc: true,
        text: `**${npc.name}**${bits.length ? ` — ${bits.join(' · ')}` : ''}` });
    }
  }

  const filters = [
    wantOrder && (wantOrder === '__none__' ? 'no order' : wantOrder),
    wantClass && (wantClass === '__none__' ? 'no class' : wantClass),
    wantHero === true ? 'Heroes' : wantHero === false ? 'not Heroes' : null,
    who !== 'both' ? who : null,
    nameBit ? `name contains “${nameBit}”` : null,
    withFallen ? 'including the fallen' : null,
  ].filter(Boolean);

  if (!entries.length) {
    return interaction.editReply({ content: `🔍 **Nothing matched.**${filters.length ? `\n_${filters.join(' · ')}_` : ''}` });
  }
  const lines = [`🔍 **${entries.length} character${entries.length === 1 ? '' : 's'}**`
    + (filters.length ? ` — ${filters.join(' · ')}` : ''), ''];
  for (const g of groupRoster(entries)) {
    lines.push(`**${g.label}**`);
    for (const e of g.rows) lines.push(`  ${e.text}`);
    lines.push('');
  }
  if (lines[lines.length - 1] === '') lines.pop();
  return replyLong(interaction, lines, { ephemeral: true });
}

async function handleGmQueue(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can see the queue.', ephemeral: true });
  await interaction.deferReply({ ephemeral: true });

  const jump = (chId, msgId) => (chId && msgId) ? ` · [jump](https://discord.com/channels/${gid}/${chId}/${msgId})` : '';
  const ago = (t) => t ? ` · <t:${Math.floor(t / 1000)}:R>` : '';
  const lines = [];
  let total = 0;

  // Character sheets
  const sheets = listPendingSheets(gid);
  if (sheets.length) {
    total += sheets.length;
    lines.push(`📋 **Character sheets** — ${sheets.length}`);
    for (const p of sheets) {
      lines.push(`• <@${p.user_id}>${ago(p.approval_requested_at)}`
        + (p.approval_post_ok === 0 ? ' ⚠️ _queue post never landed_' : ''));
    }
    lines.push('');
  }

  // Lore
  const lore = db.prepare(`SELECT * FROM lore WHERE guild_id=? AND state='pending' ORDER BY submitted_at`).all(gid);
  if (lore.length) {
    total += lore.length;
    lines.push(`📜 **Lore** — ${lore.length}`);
    for (const l of lore) {
      lines.push(`• <@${l.user_id}>${ago(l.submitted_at)}${jump(l.ch_id || approvalDestination(gid, 'lore'), l.msg_id)}`);
    }
    lines.push('');
  }

  // Duels
  const duels = db.prepare(`SELECT * FROM duels WHERE guild_id=? AND state='pending' ORDER BY created_at`).all(gid);
  if (duels.length) {
    total += duels.length;
    lines.push(`⚔️ **Duels** — ${duels.length}`);
    for (const d of duels) {
      lines.push(`• \`#${d.id}\` <@${d.opener}> · ${duelFighters(d).length} standing in`
        + ago(d.created_at) + jump(d.approval_ch_id || approvalDestination(gid, 'duels'), d.approval_msg_id));
    }
    lines.push('');
  }

  // Merit trades
  const trades = pendingMeritTrades(gid);
  if (trades.length) {
    total += trades.length;
    lines.push(`🤝 **Merit trades** — ${trades.length}`);
    for (const t of trades) {
      lines.push(`• \`#${t.id}\` <@${t.from_user}> → <@${t.to_user}> · **${t.amount}**${ago(t.created_at)}${jump(t.ch_id, t.msg_id)}`);
    }
    lines.push('');
  }

  // Quest applicants
  const openQuests = db.prepare(`SELECT * FROM quests WHERE guild_id=? AND status IN ('open','posted') ORDER BY number`).all(gid);
  const withApplicants = [];
  for (const q of openQuests) {
    const applied = getQuestMembers(gid, q.number, 'applied');
    if (applied.length) withApplicants.push([q, applied]);
  }
  if (withApplicants.length) {
    const count = withApplicants.reduce((a, [, ap]) => a + ap.length, 0);
    total += count;
    lines.push(`🧭 **Quest applicants** — ${count}`);
    for (const [q, applied] of withApplicants) {
      lines.push(`• **${questTag(q)}** — ${applied.map(u => `<@${u}>`).join(', ')}`);
    }
    lines.push('');
  }

  // Anything that has gone wrong in the background
  const fails = db.prepare('SELECT * FROM job_failures WHERE guild_id=? ORDER BY at').all(gid);
  if (fails.length) {
    lines.push(`⚠️ **Background jobs failing** — ${fails.length}`);
    for (const f of fails) lines.push(`• **${f.job}** — \`${f.message}\`${ago(f.at)}`);
    lines.push('');
  }

  if (!total && !fails.length) {
    return interaction.editReply({ content: '✅ **Nothing waiting.** No sheets, lore, trades or applicants outstanding.' });
  }
  lines.unshift(`🗂️ **${total} thing${total === 1 ? '' : 's'} waiting on a GM**`, '');
  lines.push('_Sheets and lore are decided on their queue posts · `/standing merit cancel` or the trade buttons · `/quest approve`._');
  return replyLong(interaction, lines, { ephemeral: true });
}

async function handleGmKill(interaction) {
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can call a death.', ephemeral: true });
  const t = await resolveMortal(interaction);
  if (t.error) return interaction.reply({ content: t.error, ephemeral: true });
  if (t.subject.died_at) return interaction.reply({ content: `❌ **${t.name}** has already fallen.`, ephemeral: true });

  // A death normally follows being brought down. `anyway` covers the rest —
  // execution, a story beat, a character written out while still standing.
  const hp = t.subject.hp_current ?? 0;
  if (hp > 0 && !interaction.options.getBoolean('anyway')) {
    return interaction.reply({ ephemeral: true, content:
      `❌ **${t.name}** is still on **${hp}** HP. Use \`anyway:true\` if they are to die regardless.` });
  }

  const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
  const modal = new ModalBuilder().setCustomId(`gmkill:${t.id}`).setTitle(`The fall of ${t.name}`.slice(0, 45));
  modal.addComponents(
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('cause')
      .setLabel('Cause of death').setPlaceholder('Cut down holding the north gate.')
      .setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(500)),
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('quote')
      .setLabel('Last words (optional)').setPlaceholder('Hold the line.')
      .setStyle(TextInputStyle.Short).setRequired(false).setMaxLength(200)),
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('flavour')
      .setLabel('Epitaph (optional)').setPlaceholder('They never did learn to duck.')
      .setStyle(TextInputStyle.Paragraph).setRequired(false).setMaxLength(1000)),
  );
  return interaction.showModal(modal);
}

async function handleGmKillModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can call a death.', ephemeral: true });
  const id = interaction.customId.split(':').slice(1).join(':');
  const subject = pageSubject(gid, id);
  if (!subject) return interaction.reply({ content: '❌ That character no longer exists.', ephemeral: true });
  if (subject.died_at) return interaction.reply({ content: `❌ **${subject.displayName ?? subject.name}** has already fallen.`, ephemeral: true });

  const isNpc = isNpcFighter(id);
  const name = isNpc ? subject.name : await getDisplayName(interaction.guild, id);
  const cause = cleanReason(interaction.fields.getTextInputValue('cause'));
  const quote = cleanReason(interaction.fields.getTextInputValue('quote'));
  const flavour = cleanReason(interaction.fields.getTextInputValue('flavour'));
  const rank = rankProgress(gid, subject.merits ?? 0)?.current?.name ?? null;
  const deeds = compileDeeds(gid, id);
  const at = Date.now();

  const info = db.prepare(`INSERT INTO deaths (guild_id,subject_id,name,order_name,rank_name,cause,quote,flavour,
                            deeds,merits,renown,killed_by,at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`)
    .run(gid, id, name, subject.order_name ?? null, rank, cause, quote, flavour,
         JSON.stringify(deeds), subject.merits ?? 0, subject.renown ?? 0, interaction.user.id, at);
  bookLog(gid, 'fallen', `🕯️ **${name}** fell${rank ? ` — ${rank}` : ''}${cause ? ` · ${cause}` : ''} · recorded by <@${interaction.user.id}>`);

  // Mark them fallen. Nothing is deleted — the sheet, deeds and standing all
  // remain, so a revival costs nothing and the memorial can be rebuilt.
  if (isNpc) db.prepare('UPDATE npcs SET died_at=?, hp_current=0 WHERE guild_id=? AND name=?').run(at, gid, subject.name);
  else upsertChar(gid, id, { died_at: at, hp_current: 0 });

  const rec = db.prepare('SELECT * FROM deaths WHERE guild_id=? AND id=?').get(gid, info.lastInsertRowid);
  const cfg = getConfig(gid) || {};
  const gmChId = cfg.memorial_channel, pubChId = cfg.memorial_public_channel;

  const trouble = [];
  const gmLines = await buildMemorial(interaction.guild, gid, id, rec);
  await interaction.reply({ content: `🕯️ **${name}** has fallen.`
    + (gmChId ? ` Recorded in <#${gmChId}>.` : '') + (pubChId ? ` Remembered in <#${pubChId}>.` : '') });
  if (!gmChId && !pubChId) {
    return interaction.followUp({ ephemeral: true,
      content: '⚠️ No memorial channel is set, so nothing was posted — `/config channels memorial channel:#gm-records public:#the-fallen`.\n\n'
        + gmLines.join('\n') });
  }

  // The GM copy carries the full account and the means to undo it.
  if (gmChId) {
    try {
      const ch = await interaction.client.channels.fetch(gmChId);
      const chunks = chunkLines(gmLines);
      let first = null;
      for (const [i, c] of chunks.entries()) {
        const last = i === chunks.length - 1;
        const m = await ch.send({ content: c, allowedMentions: { parse: [] },
          ...(last ? { components: [memorialButtons(gid, id, rec.id)] } : {}) });
        if (i === 0) first = m;
      }
      if (first) db.prepare('UPDATE deaths SET msg_id=? WHERE guild_id=? AND id=?').run(first.id, gid, rec.id);
    } catch (err) {
      console.error('[memorial] GM copy failed:', err?.message || err);
      trouble.push(`the GM record in <#${gmChId}> — \`${err?.message || err}\``);
    }
  }

  // The public one is the story alone. It only runs if a channel is set — a
  // memorial that quietly went to one of two places was indistinguishable from
  // one that had no public channel configured at all.
  if (pubChId) {
    try {
      const ch = await interaction.client.channels.fetch(pubChId);
      const pubLines = await buildMemorial(interaction.guild, gid, id, rec, { publicView: true });
      const chunks = chunkLines(pubLines);
      let first = null;
      for (const [i, c] of chunks.entries()) {
        const m = await ch.send({ content: c, allowedMentions: { parse: [] } });
        if (i === 0) first = m;
      }
      if (first) db.prepare('UPDATE deaths SET public_msg_id=? WHERE guild_id=? AND id=?').run(first.id, gid, rec.id);
    } catch (err) {
      console.error('[memorial] public copy failed:', err?.message || err);
      trouble.push(`the public hall in <#${pubChId}> — \`${err?.message || err}\``);
    }
  }

  // Say what didn't land. A memorial that reached one channel of two used to
  // look identical to one where no second channel was configured.
  if (trouble.length) {
    await interaction.followUp({ ephemeral: true, content:
      `⚠️ **The memorial didn't reach everywhere.**\nCouldn't post to ${trouble.join('; and ')}.\n`
      + '_Check I can **View Channel**, **Send Messages** and **Embed Links** there._' }).catch(()=>{});
  } else if (gmChId && !pubChId) {
    await interaction.followUp({ ephemeral: true, content:
      '📋 _Posted to the GM record only — no public hall is set. `/config channels memorial public:#the-fallen` adds one._' }).catch(()=>{});
  }
}

// Revive from the memorial itself: brings them back and clears both posts, so
// the record of a death that was undone doesn't linger in the hall.
async function handleReviveButton(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can bring someone back.', ephemeral: true });
  const deathId = Number(interaction.customId.split(':')[1]);
  const rec = db.prepare('SELECT * FROM deaths WHERE guild_id=? AND id=?').get(gid, deathId);
  if (!rec) return interaction.reply({ content: '❌ That record has gone.', ephemeral: true });
  if (rec.revived_at) return interaction.reply({ content: `❌ **${rec.name}** has already been brought back.`, ephemeral: true });

  const subject = pageSubject(gid, rec.subject_id);
  if (!subject) return interaction.reply({ content: '❌ That character no longer exists.', ephemeral: true });
  const isNpc = isNpcFighter(rec.subject_id);
  const max = isNpc ? maxHpFromCon(gid, subject.con) : maxHp(subject, gid);
  if (isNpc) db.prepare('UPDATE npcs SET died_at=NULL, hp_current=? WHERE guild_id=? AND name=?').run(max, gid, subject.name);
  else upsertChar(gid, rec.subject_id, { died_at: null, hp_current: max });
  db.prepare('UPDATE deaths SET revived_at=? WHERE guild_id=? AND id=?').run(Date.now(), gid, deathId);
  bookLog(gid, 'fallen', `✨ ${isNpc ? '**' + subject.name + '**' : '<@' + rec.subject_id + '>'} returns — brought back by <@${interaction.user.id}>.`);

  await interaction.reply({ content: `✨ **${rec.name}** walks again — back on **${max}** HP. Both memorials cleared.` });

  const cfg = getConfig(gid) || {};
  for (const [chId, msgId] of [[cfg.memorial_channel, rec.msg_id], [cfg.memorial_public_channel, rec.public_msg_id]]) {
    if (!chId || !msgId) continue;
    try {
      const ch = await interaction.client.channels.fetch(chId);
      const m = await ch.messages.fetch(msgId);
      await m.delete();
    } catch {}
  }
}

async function handleGmRevive(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can bring someone back.', ephemeral: true });
  const t = await resolveMortal(interaction);
  if (t.error) return interaction.reply({ content: t.error, ephemeral: true });
  if (!t.subject.died_at) return interaction.reply({ content: `❌ **${t.name}** is not dead.`, ephemeral: true });
  const isNpc = isNpcFighter(t.id);
  const max = isNpc ? maxHpFromCon(gid, t.subject.con) : maxHp(t.subject, gid);
  if (isNpc) db.prepare('UPDATE npcs SET died_at=NULL, hp_current=? WHERE guild_id=? AND name=?').run(max, gid, t.subject.name);
  else upsertChar(gid, t.id, { died_at: null, hp_current: max });
  return interaction.reply({ content: `✨ **${t.name}** walks again — back on **${max}** HP. The memorial stands.` });
}

async function handleGmTest(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can use the test tools.', ephemeral: true });
  const sub = interaction.options.getSubcommand();

  if (sub === 'quest') {
    const number = createQuest(gid, {
      name: `${GMTEST_PREFIX}Trial of the Sunken Vault`,
      lore: 'A test quest. Nothing here is canon.',
      objectives: 'Try the board, the clock and the summary.',
      details: 'Made by /gm test — delete it with /gm test clean.',
      rewards: 'A tarnished silver key (test)',
      merit_reward: 1, party_size: 4, party_hard: false, created_by: uid,
    });
    updateQuest(gid, number, { gm_id: uid, gm_style: 'mixed', run_channel_id: interactionChannelId(interaction) });
    setQuestMember(gid, number, uid, 'party');   // so it can be started immediately
    const quest = getQuest(gid, number);
    return interaction.reply({ ephemeral: true, content: [
      `🧪 Created **${questTag(quest)}** with you on the party, running in this channel.`,
      '',
      `Try: \`/quest run start number:${number}\` → \`/quest run note number:${number} text:Something happened\``,
      `→ \`/quest run timeline number:${number}\` → \`/quest run pause\` / \`/quest run resume\` → \`/quest run complete number:${number}\``,
      '',
      '_Reminders land every 15 minutes and a recap on the hour. `/gm test clean` removes it._',
    ].join('\n') });
  }

  if (sub === 'npc') {
    const name = `${GMTEST_PREFIX}Vault Warden`;
    upsertNpc(gid, name, { str: 6, con: 5, dex: 3, wis: 4, lck: 2, order_name: 'Black Knight',
      hp_current: maxHpFromCon(gid, 5) });
    const id = npcFighterId(name);
    // Give it a record worth looking at, rather than an empty page.
    db.prepare('DELETE FROM inventory WHERE guild_id=? AND user_id=?').run(gid, id);
    addItem(gid, id, 'Rusted vault key', { note: 'Warm to the touch', source: 'test data' });
    addItem(gid, id, 'Ledger of names', { source: 'test data' });
    addMerits(gid, id, 3);
    addRenown(gid, id, 5, 'test data');
    db.prepare('DELETE FROM roll_tally WHERE guild_id=? AND user_id=?').run(gid, id);
    for (const [face, times] of [[20, 2], [13, 4], [7, 3], [1, 1]]) {
      for (let i = 0; i < times; i++) tallyRoll(gid, id, face, 20);
    }
    db.prepare('UPDATE npcs SET lore=? WHERE guild_id=? AND name=?')
      .run('Kept the vault long after the last of the order had gone.', gid, name);
    return interaction.reply({ ephemeral: true, content: [
      `🧪 Created **${name}** 🎭 with items, standing, a roll history and lore.`,
      '',
      `Try: \`/npc sheet name:${name}\` → \`/npc give name:${name} item:…\` → \`/fight start npcs:${name}\``,
      '',
      '_`/gm test clean` removes it._',
    ].join('\n') });
  }

  if (sub === 'list') {
    const quests = db.prepare(`SELECT number, name, status FROM quests WHERE guild_id=? AND name LIKE ? ORDER BY number`)
      .all(gid, GMTEST_PREFIX + '%');
    const npcs = db.prepare('SELECT name FROM npcs WHERE guild_id=? AND name LIKE ? ORDER BY name')
      .all(gid, GMTEST_PREFIX + '%');
    if (!quests.length && !npcs.length) return interaction.reply({ content: '🧪 Nothing has been made by `/gm test`.', ephemeral: true });
    const lines = ['🧪 **Test data**', ''];
    for (const q of quests) lines.push(`📜 ${questTag(q)} — ${q.status}`);
    for (const npcRow of npcs) lines.push(`🎭 ${npcRow.name}`);
    return replyLong(interaction, lines, { ephemeral: true });
  }

  // clean
  const quests = db.prepare('SELECT number FROM quests WHERE guild_id=? AND name LIKE ?').all(gid, GMTEST_PREFIX + '%');
  const npcs = db.prepare('SELECT name FROM npcs WHERE guild_id=? AND name LIKE ?').all(gid, GMTEST_PREFIX + '%');
  if (!quests.length && !npcs.length) return interaction.reply({ content: '🧪 Nothing to clean.', ephemeral: true });
  return requestConfirm(interaction,
    `Delete ${quests.length} test quest${quests.length === 1 ? '' : 's'} and ${npcs.length} test NPC${npcs.length === 1 ? '' : 's'}?`,
    async () => {
      for (const q of quests) {
        for (const t of ['quests', 'quest_members', 'quest_events', 'quest_summaries']) {
          db.prepare(`DELETE FROM ${t} WHERE guild_id=? AND number=?`).run(gid, q.number);
        }
      }
      for (const npcRow of npcs) {
        purgeSubjectRecords(gid, npcFighterId(npcRow.name));
        db.prepare('DELETE FROM npcs WHERE guild_id=? AND name=?').run(gid, npcRow.name);
      }
      return `🧪 Cleaned up ${quests.length} quest${quests.length === 1 ? '' : 's'} and ${npcs.length} NPC${npcs.length === 1 ? '' : 's'}.`;
    });
}

async function handleRenown(interaction) {
  const gid = interaction.guild.id;
  const sub = interaction.options.getSubcommand();
  const isGmUser = await isGm(interaction.guild, interaction.user.id);
  const target = interaction.options.getUser('user');
  const amount = interaction.options.getInteger('amount');
  const reason = interaction.options.getString('reason') || null;

  if (sub === 'view' || sub === 'history') {
    const uid = target?.id ?? interaction.user.id;
    const nm = await getDisplayName(interaction.guild, uid);
    if (!getChar(gid, uid)) return interaction.reply({ content: `❌ **${nm}** has no character sheet.`, ephemeral: true });
    if (sub === 'view') return interaction.reply({ content: `💠 **${nm}** — **${getRenown(gid, uid)}** renown.` });
    const rows = renownHistory(gid, uid);
    if (!rows.length) return interaction.reply({ content: `💠 **${nm}** has no renown history yet.`, ephemeral: true });
    return replyLong(interaction, [`💠 **${nm}** — renown history (now **${getRenown(gid, uid)}**)`, '',
      ...rows.map(r => `${r.delta > 0 ? '➕' : '➖'} **${Math.abs(r.delta)}** · ${r.reason || 'no reason given'} · <t:${Math.floor(r.at/1000)}:R>`)],
      { ephemeral: true });
  }

  if (sub === 'leaderboard') {
    const rows = db.prepare('SELECT user_id, renown FROM characters WHERE guild_id=? AND renown > 0 ORDER BY renown DESC LIMIT 15').all(gid);
    if (!rows.length) return interaction.reply({ content: '💠 Nobody has any renown yet.', ephemeral: true });
    const lines = ['💠 **Renown**', ''];
    for (const [i, r] of rows.entries()) {
      lines.push(`${['🥇','🥈','🥉'][i] ?? `${i+1}.`} **${await getDisplayName(interaction.guild, r.user_id)}** — ${r.renown}`);
    }
    return replyLong(interaction, lines);
  }

  if (!isGmUser) return interaction.reply({ content: '❌ Only GMs can move renown around.', ephemeral: true });
  const nm = await getDisplayName(interaction.guild, target.id);
  if (!getChar(gid, target.id)) return interaction.reply({ content: `❌ **${nm}** has no character sheet.`, ephemeral: true });

  if (sub === 'gain') {
    const now = addRenown(gid, target.id, amount, reason ?? 'awarded by GM');
    return interaction.reply({ content: `💠 **${nm}**'s standing rises by **+${amount}**${reason ? ` — ${reason}` : ''}. Renown: **${now}**.` });
  }
  if (sub === 'loss') {
    // Standing is a tally, not a purse — it can be knocked down to nothing but
    // never below, so a heavy blow simply floors it.
    const before = getRenown(gid, target.id);
    const now = addRenown(gid, target.id, -amount, reason ?? 'standing lost', { allowNegative: true });
    const note = amount > before ? ` _(they only had ${before})_` : '';
    return interaction.reply({ content: `💠 **${nm}**'s standing falls by **−${amount}**${reason ? ` — ${reason}` : ''}.${note} Renown: **${now}**.` });
  }
  if (sub === 'set') {
    const cur = getRenown(gid, target.id);
    addRenown(gid, target.id, amount - cur, 'set by GM', { allowNegative: true });
    return interaction.reply({ content: `💠 **${nm}**'s renown set to **${amount}**.` });
  }
}

async function handleStory(interaction) {
  const gid = interaction.guild.id, cid = interactionChannelId(interaction);
  const sub = interaction.options.getSubcommand();
  const isGmUser = await isGm(interaction.guild, interaction.user.id);
  // Writing, tweaking and deleting always need a GM. Running one is a separate
  // question, and stays GM-only until a server opens it up.
  const AUTHORING = ['create', 'delete', 'set', 'demo'];
  if (AUTHORING.includes(sub) && !isGmUser)
    return interaction.reply({ content: '❌ Only GMs can write or change activities.', ephemeral: true });
  if (!isGmUser && !(getConfig(gid)?.activity_players))
    return interaction.reply({ content: '❌ Activities are GM-led on this server for now. Ask a GM to start one.', ephemeral: true });

  if (sub === 'create') {
    const file = interaction.options.getAttachment('file');
    if (file) {
      // A long script arrives as a text file — same validation, same storage.
      await interaction.deferReply();
      try {
        const bytes = await fetchBytes(file.url, 512 * 1024);
        const r = storeActivityScript(gid, interaction.user.id, bytes.toString('utf8'));
        return interaction.editReply({ content: r.error ? `❌ **Couldn't read that activity.** ${r.error}` : r.saved });
      } catch (err) {
        return interaction.editReply({ content: `❌ Couldn't read the file — ${err?.message || err}. Plain \`.txt\` works best.` });
      }
    }
    const { ModalBuilder, ActionRowBuilder, TextInputBuilder, TextInputStyle } = require('discord.js');
    const modal = new ModalBuilder().setCustomId('activitycreate').setTitle('Write an activity').addComponents(
      new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('script')
        .setLabel('Your script — over 4000? use file:')
        .setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(4000)
        .setPlaceholder('[ACTIVITY] Fishing\nSCENE find\nSAY 🎣 You survey the water...\nROLL wis DC12\n  PASS -> cast')),
    );
    return interaction.showModal(modal);
  }

  // A throwaway copy of the fishing loop for trying the system out. Saved under
  // a reserved name with every reward stripped, so a demo run can't move
  // anyone's renown, merits or items.
  if (sub === 'demo') {
    if (getRun(gid, cid, interaction.user.id)) return interaction.reply({ content: '❌ You already have something running here. `/activity stop` first.', ephemeral: true });
    const parsed = parseStoryScript(DEMO_FISHING);
    if (parsed.error) return interaction.reply({ content: `❌ The built-in demo failed to parse: ${parsed.error}`, ephemeral: true });
    saveStory(gid, interaction.user.id, parsed);
    const first = getScene(gid, parsed.name, parsed.start);
    const run = setRun(gid, cid, interaction.user.id, { story: parsed.name, scene: first.scene,
      started_at: Date.now(), tally_state: '{}', gauntlet_at: 0, is_demo: 1 });
    await interaction.reply({ content: '🎣 **Fishing (demo)** — a dry run. Nothing you catch will be awarded, and rerolls here are free.\nThis one is yours; others can start their own alongside it.' });
    return postScene(interaction.guild, cid, run, first);
  }

  if (sub === 'list') {
    const all = listStories(gid);
    if (!all.length) return interaction.reply({ ephemeral: true, content:
      '🎮 No activities yet. Write one and paste it into any channel I can read — start the message with `[ACTIVITY] Name`.' });
    return replyLong(interaction, ['🎮 **Activities**', '',
      ...all.map(st => `• **${st.name}** — ${listScenes(gid, st.name).length} scenes, starts at \`${st.start_scene}\``)], { ephemeral: true });
  }

  const name = interaction.options.getString('name');

  if (sub === 'stop') {
    const mine = getRun(gid, cid, interaction.user.id);
    const others = runsIn(gid, cid).filter(r => r.user_id !== interaction.user.id);
    if (!mine && !others.length) return interaction.reply({ content: '❌ Nothing is running here.', ephemeral: true });
    if (mine) {
      endRun(gid, cid, interaction.user.id);
      const note = others.length ? ` ${others.length} other run${others.length === 1 ? ' is' : 's are'} still going.` : '';
      return interaction.reply({ content: `🛑 Stopped your run of **${mine.story}**.${note}` });
    }
    // Only other people's runs are live — a GM may clear them, a player may not.
    if (!isGmUser) return interaction.reply({ content: '❌ You have nothing running here. Only a GM can stop someone else\'s.', ephemeral: true });
    for (const r of others) endRun(gid, cid, r.user_id);
    return interaction.reply({ content: `🛑 Stopped ${others.length} run${others.length === 1 ? '' : 's'} in this channel.` });
  }

  const story = getStory(gid, name);
  if (!story) return interaction.reply({ content: `❌ No activity called **${name}**.`, ephemeral: true });

  if (sub === 'delete') {
    return requestConfirm(interaction, `Delete the activity **${story.name}** and all its scenes?`, async () => {
      deleteStory(gid, story.name);
      return `🗑️ Deleted **${story.name}**.`;
    });
  }

  if (sub === 'show') {
    const statList = (r) => String(r || '').split('|').filter(Boolean)
      .map(x => (resolveStatWord(x) || x).toUpperCase()).join(' / ');
    const lines = [`🎮 **${story.name}** — starts at \`${story.start_scene}\``
      + (story.tally ? ` · tally: **${story.tally}**` : ''), ''];
    for (const sc of listScenes(gid, story.name)) {
      lines.push(`**\`${sc.scene}\`**${sc.npc ? ` · spoken by *${sc.npc}*` : ''}${sc.gain ? ` · 💠 +${sc.gain}` : ''}`);
      if (sc.say) lines.push(sc.say.split('\n').map(l => `> ${l}`).join('\n'));

      const gauntlet = sc.gauntlet ? JSON.parse(sc.gauntlet) : null;
      const ranges = JSON.parse(sc.ranges || '[]');
      const choices = JSON.parse(sc.choices || '[]');
      const outcomes = JSON.parse(sc.outcomes || '{}');

      if (gauntlet) {
        const same = gauntlet.every(g => g.stats === gauntlet[0].stats);
        lines.push(same
          ? `🎣 gauntlet **${statList(gauntlet[0].stats)}** — DC ${gauntlet.map(g => g.dc).join(' → ')}`
          : `🎣 gauntlet — ${gauntlet.map(g => `DC ${g.dc} **${statList(g.stats)}**`).join(' → ')}`);
      }
      else if (sc.roll) lines.push(`🎲 roll **${statList(sc.roll)}**${sc.dc ? ` · DC ${sc.dc}` : ''}`);

      if (sc.nat20) { const o = JSON.parse(sc.nat20); lines.push(`   🌟 nat 20 → \`${o.next}\`${o.text ? ` — ${o.text}` : ''}`); }
      if (sc.nat1)  { const o = JSON.parse(sc.nat1);  lines.push(`   💀 nat 1 → \`${o.next}\`${o.text ? ` — ${o.text}` : ''}`); }
      for (const r of ranges) {
        lines.push(`   🔢 ${r.lo}${r.hi >= 9999 ? '+' : `–${r.hi}`} → \`${r.next}\`${r.text ? ` — ${r.text}` : ''}`);
      }
      for (const [band, o] of Object.entries(outcomes)) {
        const label = sc.dc || gauntlet ? (band === 'PASS' ? '✅ pass' : band === 'FAIL' ? '❌ fail' : STORY_BAND_LABEL[band] ?? band)
                                        : (STORY_BAND_LABEL[band] ?? band);
        lines.push(`   ${label} → \`${o.next}\`${o.text ? ` — ${o.text}` : ''}`);
        for (const v of (o.variants || [])) lines.push(`      • ${v}`);
      }
      for (const c of choices) lines.push(`   🔘 ${c.label} → \`${c.next}\``);

      if (sc.ending) {
        const bits = [];
        if (sc.merits) bits.push(`🏅 ${sc.merits} merits`);
        if (sc.cash_tally) bits.push(`💠 pays out the ${story.tally || 'tally'}`);
        if (sc.rewards) bits.push(`🎁 ${sc.rewards}`);
        lines.push(`🏁 ending${bits.length ? ` · ${bits.join(' · ')}` : ''}`);
      }
      lines.push('');
    }
    return replyLong(interaction, lines, { ephemeral: true });
  }

  if (sub === 'set') {
    const sceneName = interaction.options.getString('scene');
    const field = interaction.options.getString('field');
    const value = interaction.options.getString('value');
    const res = applySceneEdit(gid, story.name, sceneName, field, value);
    if (res.error) return interaction.reply({ content: `❌ ${res.error}`, ephemeral: true });
    return interaction.reply({ content:
      `✏️ **${story.name}** · \`${res.scene}\` — **${field}** updated.\n`
      + `_Read it back with \`/activity show name:${story.name}\`._` });
  }

  if (sub === 'run') {
    if (getRun(gid, cid, interaction.user.id)) return interaction.reply({ content: '❌ You already have an activity running here. `/activity stop` first.', ephemeral: true });
    const first = getScene(gid, story.name, story.start_scene);
    if (!first) return interaction.reply({ content: `❌ **${story.name}** has no starting scene.`, ephemeral: true });
    const run = setRun(gid, cid, interaction.user.id, { story: story.name, scene: first.scene,
      started_at: Date.now(), tally_state: '{}', gauntlet_at: 0 });
    const alongside = runsIn(gid, cid).length - 1;
    await interaction.reply({ content: `🎮 **${story.name}** begins for <@${interaction.user.id}>…`
      + (alongside > 0 ? `\n_${alongside} other run${alongside === 1 ? ' is' : 's are'} going in here too — each is its own._` : '') });
    return postScene(interaction.guild, cid, run, first);
  }
}

async function handleConfig(interaction, forced) {
  const sub = forced?.sub ?? interaction.options.getSubcommand(), gid = interaction.guild.id;
  if (sub === 'gmrole') {
    const role = interaction.options?.getRole?.('role');
    const remove = interaction.options?.getBoolean?.('remove') ?? false;
    const replace = interaction.options?.getBoolean?.('replace') ?? false;
    const current = getGmRoleIds(gid);

    // No role given → list what's configured
    if (!role) {
      if (!current.length) return interaction.reply({ content: '📋 No GM roles set. Add one with `/config mechanics gmrole role:@Role`.\n_Server admins (Manage Server) always count as GMs._', ephemeral: true });
      const names = current.map(id => `<@&${id}>`).join(', ');
      return interaction.reply({ content: `📋 GM roles: ${names}\n_Server admins (Manage Server) always count as GMs._`, ephemeral: true, allowedMentions: { parse: [] } });
    }

    if (remove) {
      if (!current.includes(role.id)) return interaction.reply({ content: `❌ **${role.name}** isn't a GM role.`, ephemeral: true });
      const next = setGmRoleIds(gid, current.filter(id => id !== role.id));
      return interaction.reply({ content: next.length
        ? `✅ Removed **${role.name}**. GM roles: ${next.map(id => `<@&${id}>`).join(', ')}`
        : `✅ Removed **${role.name}**. No GM roles remain — only server admins can use GM commands now.`,
        ephemeral: true, allowedMentions: { parse: [] } });
    }

    if (replace) {
      setGmRoleIds(gid, [role.id]);
      return interaction.reply({ content: `✅ **${role.name}** is now the only GM role.`, ephemeral: true });
    }

    if (current.includes(role.id)) return interaction.reply({ content: `**${role.name}** is already a GM role.`, ephemeral: true });
    const next = setGmRoleIds(gid, [...current, role.id]);
    return interaction.reply({ content: `✅ Added **${role.name}** as a GM role. GM roles: ${next.map(id => `<@&${id}>`).join(', ')}`, ephemeral: true, allowedMentions: { parse: [] } });
  }
  if (sub === 'fightping') {
    const v = interaction.options?.getBoolean?.('enabled');
    if (v === null) {
      const cur = !!getConfig(gid)?.fight_ping;
      return interaction.reply({ content: `🔔 Turn pings are **${cur ? 'on' : 'off'}**${cur ? '' : ' (default)'}. Set with \`/config mechanics fightping enabled:true\`.`, ephemeral: true });
    }
    setConfig(gid, { fight_ping: v ? 1 : 0 });
    return interaction.reply({ content: v ? '🔔 Turn pings **on** — players get an @mention when it\'s their turn.' : '🔕 Turn pings **off**.' });
  }
  if (sub === 'npcstats') {
    const v = interaction.options?.getBoolean?.('enabled');
    if (v === null) {
      const cur = !!getConfig(gid)?.npc_stats_visible;
      return interaction.reply({ content: `🎭 NPC stat blocks are **${cur ? 'visible' : 'hidden'}**${cur ? '' : ' (default)'} on roll cards. Change with \`/config mechanics npcstats enabled:true\`.`, ephemeral: true });
    }
    setConfig(gid, { npc_stats_visible: v ? 1 : 0 });
    return interaction.reply({ content: v
      ? '🎭 NPC stat blocks are now **visible** to everyone on roll cards.'
      : '🎭 NPC stat blocks are now **hidden** — players see the name, order and HP, but not STR/CON/DEX/WIS/LCK.' });
  }
  if (sub === 'approvals') {
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    const disable = interaction.options?.getBoolean?.('disable');

    // The authoritative queue: read from the database, not from whatever
    // messages happen to still exist. A request that failed to post, was
    // deleted, or landed in a channel nobody watches still shows up here.
    if (interaction.options?.getBoolean?.('list')) {
      const rows = listPendingSheets(gid);
      if (!rows.length) return interaction.reply({ content: '✅ No sheets are waiting for approval.', ephemeral: true });
      const lines = [`📋 **${rows.length} sheet${rows.length === 1 ? '' : 's'} awaiting approval**`, ''];
      for (const r of rows) {
        const nm = await getDisplayName(interaction.guild, r.user_id);
        const when = r.approval_requested_at ? `<t:${Math.floor(r.approval_requested_at / 1000)}:R>` : 'unknown time';
        const where = r.approval_src_channel ? `<#${r.approval_src_channel}>` : 'unknown channel';
        const flag = r.approval_post_ok ? '' : '  ⚠️ **never reached the approval channel**';
        lines.push(`• <@${r.user_id}> (**${nm}**) — submitted ${when} from ${where}${flag}`);
      }
      const broken = rows.filter(r => !r.approval_post_ok).length;
      if (broken) lines.push('', `⚠️ ${broken} request${broken === 1 ? '' : 's'} never posted — check I can **View Channel** and **Send Messages** in the approval channel, then ask them to edit their sheet to resubmit.`);
      return replyLong(interaction, lines, { ephemeral: true, allowedMentions: { parse: [] } });
    }

    if (disable) {
      setConfig(gid, { approval_channel_id: null });
      return interaction.reply({ content: '✅ Sheet approval **disabled** — new sheets work immediately.' });
    }
    if (!channel) {
      const cur = approvalChannelId(gid);
      return interaction.reply({ content: cur
        ? `📋 New sheets await approval in <#${cur}>. Turn off with \`/config channels approvals disable:true\`.`
        : '📋 Sheet approval is **off**. Set a channel with `/config channels approvals channel:#x`.', ephemeral: true });
    }
    if (!channel.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel or thread.', ephemeral: true });
    setConfig(gid, { approval_channel_id: channel.id });
    return interaction.reply({ content: `📋 New character sheets will await GM approval in <#${channel.id}>.\n⚠️ Players can't roll or fight until approved, and stats become GM-only once a sheet exists.` });
  }
  if (sub === 'approvalforum') {
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { approval_routes: null });
      return interaction.reply({ content: '📋 Approval routing **off** — everything goes to the single approval channel again. The forum threads stay where they are, and anything already posted in them keeps working.' });
    }
    const forum = interaction.options?.getChannel?.('forum');
    if (!forum) {
      const r = approvalRoutes(gid);
      if (!r) return interaction.reply({ ephemeral: true, content:
        '📋 No approval forum set. `/config channels approvalforum forum:#gm-approvals` — I\'ll make a thread per approval type in it.' });
      const rows = Object.entries(APPROVAL_TYPES).map(([k, t]) => `${t.name} → ${r[k] ? `<#${r[k]}>` : '_missing — rerun setup_'}`);
      return interaction.reply({ ephemeral: true, content: [`📋 Approvals route into <#${r.forum}>:`, ...rows].join('\n') });
    }
    // A forum is channel type 15; anything else has no threads to make.
    if (forum.type !== 15) {
      return interaction.reply({ ephemeral: true, content:
        `❌ <#${forum.id}> is not a forum channel. Make a **Forum** and point me at that — each approval type gets its own thread in it.` });
    }
    await interaction.deferReply();
    const prev = approvalRoutes(gid) || {};
    const routes = { forum: forum.id };
    const lines = [];
    for (const [key, t] of Object.entries(APPROVAL_TYPES)) {
      let thread = null;
      // Re-running setup reuses a surviving thread in this same forum, so ids
      // (and every link already pointing at them) stay stable.
      if (prev[key]) {
        try {
          const old = await interaction.client.channels.fetch(prev[key]);
          if (old?.isThread?.() && old.parentId === forum.id) thread = await wakeThread(old);
        } catch (err) { console.error('[approvalforum] stale thread', key, '-', err?.message || err); }
      }
      if (!thread) {
        try {
          thread = await forum.threads.create({ name: t.name, autoArchiveDuration: 10080,
            message: { content: `${t.about}\n_I wake this thread whenever something new arrives — no need to keep it active._` } });
        } catch (err) {
          console.error('[approvalforum] create failed', key, '-', err?.message || err);
          return interaction.editReply({ content:
            `❌ Couldn't create the **${t.name}** thread — ${err?.message || err}\nCheck I can **View Channel**, **Create Posts** and **Send Messages in Posts** there, then run this again. Nothing was saved.` });
        }
      }
      routes[key] = thread.id;
      lines.push(`${t.name} → <#${thread.id}>`);
    }
    setConfig(gid, { approval_routes: JSON.stringify(routes) });
    return interaction.editReply({ content: [
      `📋 **Approvals now route into <#${forum.id}>:**`, ...lines, '',
      '_New requests land in their thread. Anything already pending stays where it was posted — its links and buttons keep working._',
      approvalChannelId(gid) ? null : 'ℹ️ _No single approval channel is set — that\'s fine, the forum covers everything, and sheet approval now counts as **on**._',
    ].filter(Boolean).join('\n') });
  }
  if (sub === 'scrollfont') {
    if (interaction.options?.getBoolean?.('remove')) {
      setConfig(gid, { scroll_font: null, scroll_font_name: null });
      scrollFontCache.delete(gid);
      return interaction.reply({ content: '📜 Scroll font forgotten — `/gm scroll` is off until a new one is uploaded.' });
    }
    const att = interaction.options?.getAttachment?.('font');
    if (!att) {
      const cfg = getConfig(gid) || {};
      return interaction.reply({ ephemeral: true, content: cfg.scroll_font
        ? `📜 Scroll font: **${cfg.scroll_font_name || 'unnamed'}** (${Math.round(cfg.scroll_font.length / 1024)} KB). Upload another to replace it, or \`remove:true\`.`
        : '📜 No scroll font stored. `/config mechanics scrollfont font:<file>` with an .otf or .ttf — then any GM can `/gm scroll`.' });
    }
    if (!/\.(otf|ttf)$/i.test(att.name || '')) {
      return interaction.reply({ ephemeral: true, content: '❌ That isn\'t an .otf or .ttf file.' });
    }
    if ((att.size ?? 0) > 2_000_000) {
      return interaction.reply({ ephemeral: true, content: '❌ Font files are capped at 2 MB — that one is bigger.' });
    }
    await interaction.deferReply();
    try {
      const bytes = await fetchBytes(att.url);
      setConfig(gid, { scroll_font: bytes, scroll_font_name: att.name });
      scrollFontCache.delete(gid); // the next /gm scroll registers the new face
      // Prove the face works NOW, not at the first /gm scroll: a one-line sample.
      let files = [];
      try {
        const family = ensureScrollFont(gid);
        if (family) {
          const { AttachmentBuilder } = require('discord.js');
          files = [new AttachmentBuilder(
            renderScroll({ family, title: null, body: 'The quick brown fox — 0123456789' }),
            { name: 'font-sample.png' })];
        }
      } catch (err) { console.error('[scrollfont] sample failed -', err?.message || err); }
      return interaction.editReply({ content: `📜 Scroll font set: **${att.name}** (${Math.round(bytes.length / 1024)} KB). Any GM can now \`/gm scroll\`.${files.length ? '' : '\n⚠️ _No sample — the face stored, but rendering it here failed; watch the first /gm scroll._'}`, files });
    } catch (err) {
      console.error('[scrollfont] store failed -', err?.message || err);
      return interaction.editReply({ content: `❌ Couldn't fetch that attachment — ${err?.message || err}` });
    }
  }
  if (sub === 'scrollarchive') {
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { scroll_archive_id: null });
      return interaction.reply({ content: '📚 Manual archive channel cleared. If the roll-audit forum is set, its 📜 Scrolls book keeps archiving — that\'s the automatic default.' });
    }
    const ch = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    if (!ch) {
      const cur = getConfig(gid)?.scroll_archive_id;
      const book = auditRoutes(gid)?.scrolls;
      return interaction.reply({ ephemeral: true, content: cur
        ? `📚 Scroll archive: <#${cur}> (manual override). \`disable:true\` falls back to the audit forum's 📜 Scrolls book${book ? ` (<#${book}>)` : ' when one is set'}.`
        : book
          ? `📚 Archiving to the audit forum's 📜 Scrolls book: <#${book}> — automatic. Point me at a channel here to override.`
          : '📚 No archive yet. Set the roll-audit forum and its 📜 Scrolls book archives automatically — or `/config channels scrollarchive channel:#library` for a plain channel.' });
    }
    setConfig(gid, { scroll_archive_id: ch.id });
    const { ChannelType: CT } = require('discord.js');
    if (ch.type === CT.GuildForum) {
      return interaction.reply({ content: `📚 Scroll archive is now the forum <#${ch.id}> — **each GM's scrolls file in their own 📜 thread**, opened automatically on first use.` });
    }
    return interaction.reply({ content: `📚 Scroll archive set: <#${ch.id}> — every \`/gm scroll\` now also files its named PDF there. _(Point at a forum instead for per-GM threads.)_` });
  }
  if (sub === 'rollauditforum') {
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { audit_routes: null });
      return interaction.reply({ content: '🎲 Audit routing **off** — every mirror goes to the single audit channel again. The forum threads stay where they are.' });
    }
    const forum = interaction.options?.getChannel?.('forum');
    if (!forum) {
      const r = auditRoutes(gid);
      if (!r) return interaction.reply({ ephemeral: true, content:
        '🎲 No audit forum set. `/config channels rollauditforum forum:#roll-audit` — I\'ll make a thread per book: player rolls, GM rolls, NPC rolls, NPC say, and the 📜 Scrolls archive.' });
      const rows = Object.entries(AUDIT_KINDS).map(([k, t]) => `${t.name} → ${r[k] ? `<#${r[k]}>` : '_missing — rerun setup_'}`);
      return interaction.reply({ ephemeral: true, content: [`🎲 Roll audit routes into <#${r.forum}>:`, ...rows].join('\n') });
    }
    // A forum is channel type 15; anything else has no threads to make.
    if (forum.type !== 15) {
      return interaction.reply({ ephemeral: true, content:
        `❌ <#${forum.id}> is not a forum channel. Make a **Forum** and point me at that — each audit book gets its own thread in it.` });
    }
    await interaction.deferReply();
    const prev = auditRoutes(gid) || {};
    const routes = { forum: forum.id };
    const lines = [];
    for (const [key, t] of Object.entries(AUDIT_KINDS)) {
      let thread = null;
      // Re-running setup reuses a surviving thread in this same forum, so ids
      // (and every link already pointing at them) stay stable.
      if (prev[key]) {
        try {
          const old = await interaction.client.channels.fetch(prev[key]);
          if (old?.isThread?.() && old.parentId === forum.id) thread = await wakeThread(old);
        } catch (err) { console.error('[rollauditforum] stale thread', key, '-', err?.message || err); }
      }
      if (!thread) {
        try {
          thread = await forum.threads.create({ name: t.name, autoArchiveDuration: 10080,
            message: { content: `${t.about}\n_I wake this thread whenever a new entry arrives — no need to keep it active._` } });
        } catch (err) {
          console.error('[rollauditforum] create failed', key, '-', err?.message || err);
          return interaction.editReply({ content:
            `❌ Couldn't create the **${t.name}** thread — ${err?.message || err}\nCheck I can **View Channel**, **Create Posts** and **Send Messages in Posts** there, then run this again. Nothing was saved.` });
        }
      }
      routes[key] = thread.id;
      lines.push(`${t.name} → <#${thread.id}>`);
    }
    setConfig(gid, { audit_routes: JSON.stringify(routes) });
    return interaction.editReply({ content: [
      `🎲 **Roll audit now routes into <#${forum.id}>:**`, ...lines, '',
      '_Player, GM and NPC rolls split into their books, and NPC Say starts recording who spoke as whom — it only records while this forum is set._',
      getConfig(gid)?.roll_audit_channel_id ? null : 'ℹ️ _No single audit channel is set — that\'s fine, the forum alone turns mirroring on._',
    ].filter(Boolean).join('\n') });
  }
  if (sub === 'rollaudit') {
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    const disable = interaction.options?.getBoolean?.('disable');
    const test = interaction.options?.getBoolean?.('test');

    if (test) {
      const r = auditRoutes(gid);
      const plain = getConfig(gid)?.roll_audit_channel_id || null;
      if (!r && !plain) return interaction.reply({ content: '🔇 No audit destination is set. `/config channels rollaudit channel:#x` or `/config channels rollauditforum forum:#x` first.', ephemeral: true });
      // With the forum, every book is exercised; without it, the one channel.
      // Four fetch-and-sends can outlast the ack window — answer first.
      await interaction.deferReply({ ephemeral: true });
      const targets = r
        ? Object.entries(AUDIT_KINDS).map(([k, t]) => [t.name, r[k] || plain])
        : [['🎲 Roll audit', plain]];
      const report = [];
      for (const [label, id] of targets) {
        if (!id) { report.push(`⚠️ ${label} — no destination`); continue; }
        try {
          const target = await wakeThread(await interaction.client.channels.fetch(id));
          if (!target) throw new Error('channel not found');
          await target.send({ content: `🧪 **Audit test** — ${label} entries land here.` });
          report.push(`✅ ${label} → <#${id}>`);
        } catch (e) { report.push(`❌ ${label} → <#${id}> — ${e?.message || e}\nCheck **View Channel** + **Send Messages** (in Posts, for threads).`); }
      }
      return interaction.editReply({ content: [
        '**Roll audit test:**', ...report, '',
        '_Mirrored: every roll — players, GMs (secret ones included), GM-as-NPC and the bot\'s auto-pilot — plus NPC Say while its thread exists._',
      ].join('\n') });
    }
    if (disable) {
      setConfig(gid, { roll_audit_channel_id: null });
      return interaction.reply({ content: '🔇 Roll mirroring **disabled**.' });
    }
    if (!channel) {
      const cur = getConfig(gid)?.roll_audit_channel_id;
      if (!cur) return interaction.reply({ content: '🔇 Roll mirroring is **off**. Set a channel with `/config channels rollaudit channel:#x`.', ephemeral: true });
      let reach = '❓ unknown';
      try {
        const t = await interaction.client.channels.fetch(cur);
        reach = t ? `✅ reachable (**#${t.name ?? '?'}**)` : '❌ fetch returned nothing';
      } catch (e) { reach = `❌ cannot access — ${e?.message || e}`; }
      return interaction.reply({ content: `🎲 Audit channel: <#${cur}>\nStored id: \`${cur}\`\nBot access: ${reach}\n\nSend a live test with \`/config channels rollaudit test:true\`.`, ephemeral: true });
    }
    if (!channel.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel or thread.', ephemeral: true });
    setConfig(gid, { roll_audit_channel_id: channel.id });
    return interaction.reply({ content: `🎲 Rolls will be mirrored to <#${channel.id}> — raw input, result, and a jump link.\nCovers player rolls **and GM rolls, including secret ones**, so GMs are accountable to each other.\n⚠️ Make sure that channel's permissions only let GMs view it; the bot can't set that for you.` });
  }
  if (sub === 'autorest') {
    const action = interaction.options?.getString?.('action') || 'list';
    const name = (interaction.options?.getString?.('name') || '').trim();
    const hours = interaction.options?.getInteger?.('hours');
    const hp = interaction.options?.getString?.('hp');
    const rerolls = interaction.options?.getString?.('rerolls');
    const heal = interaction.options?.getString?.('heal');
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    const line = (sc) => `• **${sc.name}** — every **${sc.hours}h** · ${describeSchedule(sc)}`
      + (sc.channel ? ` · <#${sc.channel}>` : '')
      + (sc.enabled ? '' : ' · ⏸️ **paused**')
      + (sc.last_run ? `\n   next <t:${Math.floor((sc.last_run + sc.hours * 3600 * 1000) / 1000)}:R>` : '');

    if (action === 'list') {
      const all = listSchedules(gid);
      if (!all.length) return interaction.reply({ ephemeral: true, content:
        '🌙 No recovery schedules yet.\n'
        + 'Add one with `/config mechanics autorest action:Add or update name:Breather hours:6 hp:50% rerolls:0% heal:0%`.\n'
        + 'Amounts take `100%`, `50%`, a flat number, or `0%` to leave that resource alone. Percentages round down.' });
      return replyLong(interaction, ['🌙 **Recovery schedules**', '', ...all.map(line), '',
        '_Anyone on an in-progress quest is skipped by every schedule._'], { ephemeral: true });
    }

    if (!name) return interaction.reply({ content: '❌ Give the schedule a `name:` — e.g. `name:Breather`.', ephemeral: true });

    if (action === 'remove') {
      return interaction.reply({ content: deleteSchedule(gid, name)
        ? `🗑️ Removed recovery schedule **${name}**.`
        : `❌ No schedule called **${name}**.`, ephemeral: true });
    }

    const existing = getSchedule(gid, name);
    if (action === 'pause' || action === 'resume') {
      if (!existing) return interaction.reply({ content: `❌ No schedule called **${name}**.`, ephemeral: true });
      const sc = upsertSchedule(gid, name, { enabled: action === 'resume' ? 1 : 0,
        ...(action === 'resume' ? { last_run: Date.now() } : {}) });
      return interaction.reply({ content: `${action === 'resume' ? '▶️ Resumed' : '⏸️ Paused'} **${sc.name}**.` });
    }

    if (action === 'run') {
      if (!existing) return interaction.reply({ content: `❌ No schedule called **${name}**.`, ephemeral: true });
      await interaction.reply({ content: `🌙 Running **${existing.name}** now…` });
      const result = await runAutoRest(interaction.guild, existing);
      await announceAutoRest(interaction.guild, existing, result);
      return interaction.followUp({ content:
        `✅ **${existing.name}** — restored **${result.restored.length}**`
        + (result.skipped.length ? `, left **${result.skipped.length}** out on quests` : '')
        + (result.inFight?.length ? `, left **${result.inFight.length}** mid-fight` : '')
        + '.' });
    }

    // Add or update. Every amount is validated up front so a typo can't sit in
    // the table silently doing nothing at 3am.
    const fields = {};
    for (const [key, val] of [['hp', hp], ['rerolls', rerolls], ['heal', heal]]) {
      if (val === null || val === undefined) continue;
      const t = String(val).trim();
      if (!/^\+?\d+%?$/.test(t)) return interaction.reply({ content: `❌ **${key}** must be like \`100%\`, \`50%\`, \`+4\`, \`+25%\`, \`0%\` or a plain number — got \`${t}\`.\n_A bare number **sets** the value; a **+** adds to what they already have._`, ephemeral: true });
      fields[key] = t;
    }
    if (hours !== null) fields.hours = hours;
    if (channel) {
      if (!channel.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel or thread.', ephemeral: true });
      fields.channel = channel.id;
    }
    if (!existing && !Object.keys(fields).length) {
      return interaction.reply({ content: '❌ New schedules need at least `hours:` or one amount. Defaults are every 6h at 100% of everything.', ephemeral: true });
    }
    const sc = upsertSchedule(gid, name, fields);
    return interaction.reply({ content: [
      `${existing ? '✏️ Updated' : '🌙 Added'} recovery schedule:`, line(sc), '',
      'Everyone not on an in-progress quest is covered. Quest parties keep whatever they have until they finish.',
    ].join('\n') });
  }

  if (sub === 'questinstances') {
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { quest_instance_forum: null });
      return interaction.reply({ content: '⚔️ Started quests will no longer open a room. Existing rooms stay where they are.' });
    }
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    if (!channel) {
      const cur = getConfig(gid)?.quest_instance_forum;
      return interaction.reply({ ephemeral: true, content: cur
        ? `⚔️ Each started quest opens its party's room in <#${cur}>.`
        : '⚔️ No instance forum set — started quests use their run channel. `/config channels questinstances channel:#your-forum` gives every party its own room.' });
    }
    if (channel.type !== 15) {
      return interaction.reply({ ephemeral: true, content:
        `❌ <#${channel.id}> is not a forum channel. Make a **Forum** — each started quest opens a thread there for its party and DM.` });
    }
    setConfig(gid, { quest_instance_forum: channel.id });
    return interaction.reply({ content: `⚔️ Started quests now open their party's room in <#${channel.id}> — the DM and every member pulled in, the clock and reminders following them there.` });
  }

  if (sub === 'questthreads') {
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { quest_thread_forum: null });
      // The stage tags follow the threads home to the planning forum.
      const planId = getConfig(gid)?.quest_plan_forum;
      let back = '';
      if (planId) {
        try { await ensurePlanTags(await interaction.client.channels.fetch(planId), gid); back = ' Pipeline tags restored there.'; }
        catch { back = ' ⚠️ Couldn\'t restore the pipeline tags there — re-run `/config channels questplanning`.'; }
      }
      return interaction.reply({ content: `🗺️ Quest threads will open in the planning forum again.${back} Existing threads stay where they are.` });
    }
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    if (!channel) {
      const cur = getConfig(gid)?.quest_thread_forum;
      return interaction.reply({ ephemeral: true, content: cur
        ? `🗺️ Per-quest planning threads open in <#${cur}>.`
        : '🗺️ No secondary forum set — quest threads open in the planning forum. `/config channels questthreads channel:#your-forum` splits them out.' });
    }
    if (channel.type !== 15) {
      return interaction.reply({ ephemeral: true, content:
        `❌ <#${channel.id}> is not a forum channel. Make a **Forum** — each quest's planning thread opens there.` });
    }
    await interaction.deferReply();
    setConfig(gid, { quest_thread_forum: channel.id });
    let tagNote = '';
    try {
      await ensurePlanTags(channel, gid);
      tagNote = '\n🏷️ Pipeline tags moved here — they ride the quest threads, so the books keep the planning forum clean.';
    } catch (err) {
      tagNote = `\n⚠️ Couldn't set the pipeline tags — ${err?.message || err}. I need **Manage Channel** here; run this again once granted.`;
    }
    return interaction.editReply({ content: `🗺️ Quest planning threads now open in <#${channel.id}> — the planning forum keeps only the books.${tagNote}\n_Existing quest threads stay where they are._` });
  }

  if (sub === 'questforum' || sub === 'questplanning') {
    const key = sub === 'questforum' ? 'quest_forum' : 'quest_plan_forum';
    const noun = sub === 'questforum' ? 'public quest board' : 'GM quest planning';
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { [key]: null });
      return interaction.reply({ content: `🗺️ ${noun[0].toUpperCase()}${noun.slice(1)} forum unset. Existing threads stay where they are.` });
    }
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    if (!channel) {
      const cur = getConfig(gid)?.[key];
      return interaction.reply({ ephemeral: true, content: cur
        ? `🗺️ The ${noun} forum is <#${cur}>.`
        : `🗺️ No ${noun} forum set. \`/config ${sub} channel:#your-forum\`` });
    }
    // A forum is channel type 15; anything else has no threads to create.
    if (channel.type !== 15) {
      return interaction.reply({ ephemeral: true, content:
        `❌ <#${channel.id}> is not a forum channel. Make a **Forum** and point me at that — each quest gets a thread in it.` });
    }
    setConfig(gid, { [key]: channel.id });
    if (sub === 'questplanning') {
      await interaction.deferReply();
      let tagNote = '', dmNote = '';
      const splitForum = getConfig(gid)?.quest_thread_forum;
      if (splitForum) {
        tagNote = `\n🏷️ Pipeline tags live on the quest-threads forum — <#${splitForum}>.`;
      } else {
        try {
          const map = await ensurePlanTags(channel, gid);
          tagNote = `\n🏷️ Pipeline tags ready: ${QUEST_STAGES.map(([k, e, l]) => map[k] ? `${e} ${l}` : `⚠️ ${l}`).join(' · ')}`;
        } catch (err) {
          tagNote = `\n⚠️ Couldn't set the pipeline tags — ${err?.message || err}. I need **Manage Channel** on the forum; run this again once granted.`;
        }
      }
      // The pipeline books — idempotent: existing books keep their ids, the
      // rest are created, exactly like the roll-audit forum's setup.
      try {
        const prev = questBooks(gid);
        const legacyRoster = getConfig(gid)?.quest_dm_thread;
        const map = {};
        const made = [];
        for (const [bkey, emoji, label, about] of QUEST_BOOKS) {
          let thread = null;
          const knownId = prev[bkey] ?? (bkey === 'dms' ? legacyRoster : null);
          if (knownId) {
            try {
              const old = await interaction.client.channels.fetch(knownId);
              if (old?.isThread?.() && old.parentId === channel.id) thread = await wakeThread(old);
            } catch { /* stale — remake below */ }
          }
          if (!thread) {
            thread = await channel.threads.create({ name: `${emoji} ${label}`, autoArchiveDuration: 10080,
              message: { content: `${emoji} **${label}**\n${about}\n_I wake this book whenever something new arrives — no need to keep it active._` } });
            await thread.pin().catch(() => {});
            made.push(label);
          }
          map[bkey] = thread.id;
        }
        setConfig(gid, { quest_plan_books: JSON.stringify(map), quest_dm_thread: map.dms });
        await refreshDmRoster(interaction.client, interaction.guild, gid);
        dmNote = `\n📚 Books: ${QUEST_BOOKS.map(([k, e, l]) => `${e} <#${map[k]}>`).join(' · ')}${made.length ? `\n_(new: ${made.join(', ')})_` : ''}`;
      } catch (err) {
        dmNote = `\n⚠️ Couldn't make the pipeline books — ${err?.message || err}. Check **Create Posts** and **Send Messages in Posts**, then run this again.`;
      }
      return interaction.editReply({ content: `🗺️ GM planning forum set to <#${channel.id}> — \`/quest create\` opens a planning thread there; \`/quest post\` flips the quest onto the public board.${tagNote}${dmNote}` });
    }
    return interaction.reply({ content:
      `🗺️ Quest board forum set to <#${channel.id}> — \`/quest post\` now opens a thread there per quest.` });
  }

  if (sub === 'charforum') {
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { char_forum: null });
      return interaction.reply({ content: '📖 No new character pages will be made. Existing ones stay linked.' });
    }
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    if (!channel) {
      const cur = getConfig(gid)?.char_forum;
      const count = db.prepare('SELECT COUNT(*) AS c FROM char_pages WHERE guild_id=?').get(gid).c;
      return interaction.reply({ ephemeral: true, content: cur
        ? `📖 Character pages live in <#${cur}> — ${count} linked so far.`
        : '📖 No character forum set. `/config channels charforum channel:#character-sheets`' });
    }
    // A forum is channel type 15; anything else has no threads to create.
    if (channel.type !== 15) {
      return interaction.reply({ ephemeral: true, content:
        `❌ <#${channel.id}> is not a forum channel. Make a **Forum** and point me at that — each character gets a post in it.` });
    }
    setConfig(gid, { char_forum: channel.id });
    return interaction.reply({ content:
      `📖 Character pages will be made in <#${channel.id}> when a sheet is approved.\n`
      + '_`/char page` links an existing thread by hand, or makes one now._' });
  }

  if (sub === 'memorial') {
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    const pub = interaction.options?.getChannel?.('public');
    if (interaction.options?.getBoolean?.('disable')) {
      setConfig(gid, { memorial_channel: null, memorial_public_channel: null });
      return interaction.reply({ content: '🕯️ Memorials will no longer be posted.' });
    }
    if (!channel && !pub) {
      const cfg = getConfig(gid) || {};
      const bits = [];
      if (cfg.memorial_channel) bits.push(`📋 GM record in <#${cfg.memorial_channel}> — full account, with a Revive button.`);
      if (cfg.memorial_public_channel) bits.push(`🕯️ Public hall in <#${cfg.memorial_public_channel}> — the story alone.`);
      return interaction.reply({ ephemeral: true, content: bits.length ? bits.join('\n')
        : '🕯️ No memorial channels set. `/config channels memorial channel:#gm-records public:#the-fallen`' });
    }
    const fields = {};
    for (const [opt, key, what] of [[channel, 'memorial_channel', 'GM record'], [pub, 'memorial_public_channel', 'public hall']]) {
      if (!opt) continue;
      if (!opt.isTextBased?.()) return interaction.reply({ content: `❌ Pick a text channel or thread for the ${what}.`, ephemeral: true });
      fields[key] = opt.id;
    }
    setConfig(gid, fields);
    const out = [];
    if (channel) out.push(`📋 The full account goes to <#${channel.id}>, with a Revive button.`);
    if (pub) out.push(`🕯️ The fallen are remembered in <#${pub.id}> — no figures, no dice, no ledger.`);
    return interaction.reply({ content: out.join('\n') });
  }

  if (sub === 'docs') {
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    const playerChannel = interaction.options?.getChannel?.('player_channel');
    const repo = interaction.options?.getString?.('repo');
    const branch = interaction.options?.getString?.('branch');
    const path = interaction.options?.getString?.('path');
    const push = interaction.options?.getBoolean?.('push');
    const disable = interaction.options?.getBoolean?.('disable');

    if (disable) {
      setConfig(gid, { docs_channel: null, docs_msg_id: null, docs_sha: null,
        docs_player_channel: null, docs_player_msg_id: null });
      return interaction.reply({ content: '📚 Stopped watching for new command books. The last posts are left where they are.' });
    }

    const fields = {};
    if (channel) {
      if (!channel.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel or thread.', ephemeral: true });
      fields.docs_channel = channel.id;
      fields.docs_msg_id = null;   // a new home means a new standing post
    }
    if (playerChannel) {
      if (!playerChannel.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel or thread for the player copy.', ephemeral: true });
      fields.docs_player_channel = playerChannel.id;
      fields.docs_player_msg_id = null;
    }
    if (repo) {
      if (!/^[\w.-]+\/[\w.-]+$/.test(repo.trim()))
        return interaction.reply({ content: '❌ Give the repository as `owner/name` — for example `wolffewrought/ddice`.', ephemeral: true });
      fields.docs_repo = repo.trim();
    }
    if (branch) fields.docs_branch = branch.trim();
    if (path !== null && path !== undefined) fields.docs_path = path.trim();
    if (Object.keys(fields).length) setConfig(gid, fields);

    const st = docsSettings(gid);
    if (!st.channel || !st.repo) {
      return interaction.reply({ ephemeral: true, content: (st.channel || st.repo)
        ? `📚 Half set up — ${st.channel ? 'no repository yet' : 'no channel yet'}.\n\`/config channels docs channel:#gm-books repo:owner/name\``
        : '📚 Not set up. `/config channels docs channel:#gm-books repo:owner/name`\n_The three PDFs are fetched from that repository and kept as a single, current post._' });
    }

    const cfg0 = getConfig(gid) || {};
    if (!push && !Object.keys(fields).length) {
      return interaction.reply({ ephemeral: true, content:
        `📚 Watching \`${st.repo}\` (${st.branch}${st.path ? `, /${st.path}` : ''}) → <#${st.channel}>, checked every 15 minutes.\n`
        + (st.playerChannel ? `📘 Player book also posted quietly in <#${st.playerChannel}>.\n` : '')
        + (cfg0.docs_checked_at
            ? `🕘 Last looked <t:${Math.floor(cfg0.docs_checked_at / 1000)}:R> — ${cfg0.docs_result || 'no result recorded'}.\n`
            : '🕘 _Not checked yet — the first look is about 30 seconds after the bot starts._\n')
        + (st.msgId ? `Current post: https://discord.com/channels/${gid}/${st.channel}/${st.msgId}` : '_Nothing posted yet._') });
    }

    await interaction.deferReply({ ephemeral: true });
    try {
      const out = await publishDocs(interaction.client, interaction.guild,
        { reason: push ? 'pushed by a GM' : 'settings changed', force: !!push });
      if (out.skipped === 'unchanged') {
        setConfig(gid, { docs_error: null, docs_checked_at: Date.now(), docs_result: 'nothing new' });
        return interaction.editReply({ content:
          `📚 Already up to date — the files in \`${st.repo}\` are the same ones already posted in <#${st.channel}>.\n`
          + '_If you have just committed new books, give the CDN a minute and try again. '
          + 'If it keeps saying this, check the commit actually landed on '
          + `\`${st.branch}\`${st.path ? ` under \`${st.path}/\`` : ' at the repository root'}._` });
      }
      const extra = out.playerUrl ? `\n📘 Player book posted quietly in <#${st.playerChannel}>.`
                  : out.playerError ? `\n⚠️ Player copy failed: ${out.playerError}` : '';
      setConfig(gid, { docs_error: null, docs_checked_at: Date.now(), docs_result: 'published by a GM' });
      return interaction.editReply({ content: `📚 Published to <#${st.channel}> and the GMs pinged.\n${out.url}${extra}` });
    } catch (err) {
      return interaction.editReply({ content:
        `❌ Couldn't publish: ${err?.message || err}\n`
        + `_Check the repository is public, the branch is right, and the three files sit at \`${st.path ? st.path + '/' : ''}DDice-Commands-*.pdf\`._` });
    }
  }

  if (sub === 'questlog') {
    const channel = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    const disable = interaction.options?.getBoolean?.('disable');
    if (disable) { setConfig(gid, { quest_log_channel: null }); return interaction.reply({ content: '📜 Quest summaries will no longer be posted.' }); }
    if (!channel) {
      const cur = getConfig(gid)?.quest_log_channel;
      return interaction.reply({ ephemeral: true, content: cur
        ? `📜 Quest summaries are posted in <#${cur}>.`
        : '📜 No quest log channel set. `/config channels questlog channel:#chronicle`' });
    }
    if (!channel.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel or thread.', ephemeral: true });
    setConfig(gid, { quest_log_channel: channel.id });
    return interaction.reply({ content: `📜 Finished quests will be written up in <#${channel.id}>, and linked on each player's \`/char view standing\`.` });
  }

  if (sub === 'activities') {
    const players = interaction.options?.getBoolean?.('players');
    if (players === null) {
      return interaction.reply({ ephemeral: true, content: getConfig(gid)?.activity_players
        ? '🎮 Anyone can start an activity. Writing and deleting them is still GM-only.'
        : '🎮 Activities are **GM-led** — only a GM can start one. Open it up with `/config mechanics activities players:true`.' });
    }
    setConfig(gid, { activity_players: players ? 1 : 0 });
    return interaction.reply({ content: players
      ? '🎮 Players can now start activities themselves. Writing and deleting them is still GM-only.'
      : '🎮 Activities are now **GM-led** — only a GM can start one.' });
  }

  if (sub === 'hpbase') {
    const base = interaction.options?.getInteger?.('base');
    const cur = hpBase(gid);
    if (base === null) {
      return interaction.reply({ content:
        `❤️ Max HP is **CON + ${cur}**. Change it with \`/config mechanics hpbase base:3\`.`, ephemeral: true });
    }
    setConfig(gid, { hp_base: base });
    return interaction.reply({ content:
      `❤️ Max HP is now **CON + ${base}**.\n`
      + `Everyone's ceiling moves immediately; current HP is left alone, so run a rest or \`hpfull @user\` to top people up`
      + `${base < cur ? ' — anyone now above their new maximum is trimmed on their next heal or rest' : ''}.` });
  }

  if (sub === 'statallowance') {
    const points = interaction.options?.getInteger?.('points');
    const minimum = interaction.options?.getInteger?.('minimum');
    const cur = statRules(gid);
    if (points === null && minimum === null) {
      return interaction.reply({ content:
        `📊 Players spend exactly **${cur.budget} points** across the 5 stats, minimum **${cur.min}** in each.\n`
        + `Change it with \`/config mechanics statallowance points:20 minimum:2\`. GMs are never limited.`, ephemeral: true });
    }
    const budget = points ?? cur.budget;
    const min = minimum ?? cur.min;
    // A floor that can't fit inside the budget would make every sheet illegal.
    if (min * STATS.length > budget) {
      return interaction.reply({ content: `❌ A minimum of **${min}** across ${STATS.length} stats needs **${min * STATS.length}** points, more than the **${budget}** allowance. Raise the points or lower the minimum.`, ephemeral: true });
    }
    setConfig(gid, { stat_budget: budget, stat_min: min });
    return interaction.reply({ content:
      `📊 Players now spend exactly **${budget} points** across the 5 stats, minimum **${min}** in each.\n`
      + `Existing sheets are untouched — this applies the next time one is built or submitted. GMs are never limited.` });
  }

  if (sub === 'npcreroll') {
    const v = interaction.options?.getInteger?.('threshold');
    if (v === null) {
      const cur = getNpcRrThreshold(gid);
      const state = cur === 0 ? '**disabled**' : `natural die **≤ ${cur}**`;
      return interaction.reply({ content: `🔁 NPC auto-rerolls: ${state}${cur === NPC_RR_NAT_MAX ? ' (default)' : ''}. Set with \`/config mechanics npcreroll threshold:N\` — 0 disables.`, ephemeral: true });
    }
    setConfig(gid, { npc_rr_threshold: v });
    return interaction.reply({ content: v === 0 ? '✅ NPC auto-rerolls **disabled**.' : `✅ NPCs now auto-reroll on a natural die of **${v} or less**.`, ephemeral: true });
  }
  if (sub === 'heal') {
    const charges = interaction.options?.getInteger?.('charges');
    setConfig(gid, { heal_charges: charges });
    return interaction.reply({ content: `✅ White Knight Heal charges set to **${charges}**.`, ephemeral: true });
  }
  if (sub === 'npcchannel') {
    const chan = (forced?.channel ?? interaction.options?.getChannel?.('channel'));
    if (!chan?.isTextBased?.()) return interaction.reply({ content: '❌ Pick a text channel.', ephemeral: true });
    setConfig(gid, { npc_channel_id: chan.id });
    return interaction.reply({ content: `✅ NPC image channel set to <#${chan.id}> (id \`${chan.id}\`).\nUpload an image there with the NPC's name as the message text to set their avatar.\n⚠️ I need **View Channel**, **Send Messages** and **Read Message History** there.`, ephemeral: true });
  }

  if (sub === 'rest') {
    const type = interaction.options?.getString?.('type'); // lrest or srest
    const hp = interaction.options?.getString?.('hp');
    const rerolls = interaction.options?.getString?.('rerolls');
    const heal = interaction.options?.getString?.('heal');
    const cfg = getConfig(gid);
    const restName = type === 'lrest' ? 'Long Rest' : 'Short Rest';

    // Defaults for display when a column is null
    const dFallback = type === 'lrest' ? {hp:'100%',rr:'100%',heal:'100%'} : {hp:'50%',rr:'0%',heal:'0%'};
    const cur = {
      hp:   cfg[`${type}_hp`]      ?? dFallback.hp,
      rr:   cfg[`${type}_rerolls`] ?? dFallback.rr,
      heal: cfg[`${type}_heal`]    ?? dFallback.heal,
    };

    // Describe a stored token in plain language
    const describe = (tok) => {
      const t = String(tok).trim();
      if (t.endsWith('%')) return t === '0%' ? 'nothing' : `${t} of max`;
      return `set to ${t}`;
    };

    // If no values supplied, just show current settings
    if (hp === null && rerolls === null && heal === null) {
      return interaction.reply({ content: `⚙️ **${restName}** currently restores:\n❤️ HP: **${describe(cur.hp)}**\n🔄 Rerolls: **${describe(cur.rr)}**\n🛡️ Heal: **${describe(cur.heal)}**\n\nProvide \`hp\`, \`rerolls\`, and/or \`heal\` to change them. Use a percentage like \`50%\` or a flat number like \`3\`.`, ephemeral: true });
    }

    // Validate a token: must be "N%" or a plain whole number N (>= 0)
    const validTok = (v) => {
      const t = String(v).trim();
      if (/^\d+%$/.test(t)) return t;
      if (/^\d+$/.test(t)) return t;
      return null;
    };

    const updates = {};
    for (const [opt, col, key] of [[hp,'hp','hp'],[rerolls,'rerolls','rr'],[heal,'heal','heal']]) {
      if (opt === null) continue;
      const v = validTok(opt);
      if (v === null) {
        return interaction.reply({ content: `❌ \`${opt}\` isn't valid. Use a percentage like \`50%\` or a flat whole number like \`3\`.`, ephemeral: true });
      }
      updates[`${type}_${col}`] = v;
      cur[key] = v;
    }
    setConfig(gid, updates);
    return interaction.reply({ content: `✅ **${restName}** now restores:\n❤️ HP: **${describe(cur.hp)}**\n🔄 Rerolls: **${describe(cur.rr)}**\n🛡️ Heal: **${describe(cur.heal)}**`, ephemeral: true });
  }

  if (sub === 'questspinoff') {
    const on = interaction.options?.getBoolean?.('enabled');
    setConfig(gid, { quest_spinoff: on ? 1 : 0 });
    return interaction.reply({ content: on
      ? '⚔️ **Spin-off on.** The first approval on a board quest births a numbered run — `#002.2` — carrying that player and anyone still waiting. The board entry clears for the next group, and the run recruits through the ➕ button in its own room.'
      : '📋 **Spin-off off.** Approvals fill the board entry\'s own party, as before.' });
  }

  if (sub === 'cleanwebhooks') {
    await interaction.deferReply({ ephemeral: true });
    try {
      // Gather webhook IDs currently in use by NPCs
      // In use = the channel voices DDice speaks through now. Everything
      // else is a leftover from the old one-hook-per-NPC scheme and can go —
      // which is what frees a channel sitting at Discord's cap of fifteen.
      const activeWebhookIds = new Set([
        ...db.prepare('SELECT webhook_id FROM npc_webhooks WHERE guild_id=? AND npc_name=?').all(gid, SHARED_HOOK).map(r => r.webhook_id),
      ].filter(Boolean));
      let removed = 0, checked = 0;
      // Scan all text channels for webhooks created by this bot
      const channels = await interaction.guild.channels.fetch();
      for (const [, ch] of channels) {
        if (!ch || typeof ch.fetchWebhooks !== 'function') continue;
        let hooks;
        try { hooks = await ch.fetchWebhooks(); } catch { continue; }
        for (const [, hook] of hooks) {
          // Only touch webhooks this bot owns
          if (hook.owner?.id !== client.user.id) continue;
          checked++;
          if (!activeWebhookIds.has(hook.id)) {
            try { await hook.delete('DDice orphaned webhook cleanup'); removed++; } catch {}
          }
        }
      }
      // Rows pointing at hooks we just deleted would send into the void.
      try { db.prepare('DELETE FROM npc_webhooks WHERE guild_id=? AND npc_name<>?').run(gid, SHARED_HOOK); } catch {}
      return interaction.editReply({ content: `🧹 Webhook cleanup complete. Checked ${checked} bot webhook(s), removed ${removed} spare one(s).\n_DDice now speaks through one shared webhook per channel, so NPCs no longer eat Discord's limit of fifteen._` });
    } catch (err) {
      console.error('Webhook cleanup error:', err);
      return interaction.editReply({ content: `❌ Cleanup failed: ${err.message}` });
    }
  }

}

async function handleChar(interaction) {
  const sub = interaction.options.getSubcommand(), gid = interaction.guild.id, callerId = interaction.user.id;
  if (sub === 'create') {
    const targetUser = interaction.options.getUser('user');
    const isGmUser = await isGm(interaction.guild, callerId);
    const targetId = targetUser?.id ?? callerId;
    if (targetId !== callerId && !isGmUser) return interaction.reply({ content: '❌ Only GMs can set stats for other players.', ephemeral: true });
    // BUG 2: /char create skipped the approval lock entirely, so an approved
    // player could rewrite their whole sheet with it — the one door left open
    // after /char set, /char weaponemoji, /char profile load and sheet import were
    // all shut.
    {
      const lock = sheetEditLock(gid, callerId, targetId, isGmUser);
      if (lock) return interaction.reply({ content: lock, ephemeral: true });
    }
    const updates = {};
    // Validate stat ranges (0-99)
    for (const stat of ['str','con','dex','wis','lck']) {
      const v = interaction.options.getInteger(stat);
      if (v !== null && (v < 0 || v > 99)) return interaction.reply({ content: `❌ ${stat.toUpperCase()} must be between 0 and 99.`, ephemeral: true });
    }
    const str = interaction.options.getInteger('str'); if (str !== null) updates.str = str;
    const con = interaction.options.getInteger('con'); if (con !== null) updates.con = con;
    const dex = interaction.options.getInteger('dex'); if (dex !== null) updates.dex = dex;
    const wis = interaction.options.getInteger('wis'); if (wis !== null) updates.wis = wis;
    const lck = interaction.options.getInteger('lck'); if (lck !== null) updates.lck = lck;
    const order = interaction.options.getString('order'); if (order) updates.order_name = order;
    // Budget check, for players only. Runs against the sheet as it would stand
    // after this command, so filling the last stat in a second /char create is
    // still measured against the whole spread rather than just what was typed.
    const existingSheet = getChar(gid, targetId);
    if (!isGmUser) {
      const after = statsAfter(existingSheet, updates);
      const anyStatGiven = STATS.some(k => updates[k] !== undefined);
      const complete = STATS.every(k => (after[k] ?? 0) > 0) || anyStatGiven;
      const problems = statBudgetProblems(gid, after, { requireAll: complete, exact: complete });
      if (problems.length) return refuseStatBudget({ src: interaction, gid, uid: callerId, problems, stats: after,
        reply: replyThenFetch(interaction) });
    }
    // Max HP and rerolls off the finished sheet rather than off this one call.
    // Setting them only when con/lck happened to be typed meant a character
    // built over two commands could end up short of full.
    {
      const after = statsAfter(existingSheet, updates);
      updates.hp_current = maxHpFromCon(gid, after.con);
      updates.rerolls_current = after.lck ?? 0;
    }
    const charClass = interaction.options.getString('class');
    if (charClass && String(charClass).toLowerCase() === 'hero' && !isGmUser) {
      return interaction.reply({ content: '❌ **Hero** is granted by a GM, not chosen. Pick Vanguard, Defender or Siege Knight.', ephemeral: true });
    }
    if (charClass) updates.class = charClass;
    const weapon1 = interaction.options.getString('weapon1'); if (weapon1) updates.weapon1 = weapon1;
    const weapon2 = interaction.options.getString('weapon2'); if (weapon2) updates.weapon2 = weapon2;
    const weapon1emoji = interaction.options.getString('weapon1emoji');
    if (weapon1emoji) {
      const c1 = validateWeaponEmoji(interaction.guild, weapon1emoji);
      if (!c1) return interaction.reply({ content: `❌ Weapon 1 emoji invalid — use a standard emoji (${STANDARD_WEAPON_EMOJIS.join(' ')}) or a server custom emoji.`, ephemeral: true });
      updates.weapon1emoji = c1;
    }
    const weapon2emoji = interaction.options.getString('weapon2emoji');
    if (weapon2emoji) {
      const c2 = validateWeaponEmoji(interaction.guild, weapon2emoji);
      if (!c2) return interaction.reply({ content: `❌ Weapon 2 emoji invalid — use a standard emoji (${STANDARD_WEAPON_EMOJIS.join(' ')}) or a server custom emoji.`, ephemeral: true });
      updates.weapon2emoji = c2;
    }
    if (Object.keys(updates).length === 0) return interaction.reply({ content: '❌ No fields provided.', ephemeral: true });

    // Approval flow: a player creating/updating their OWN sheet while approval is
    // enabled must have it signed off. Sheets a GM builds are approved outright.
    const needsApproval = approvalEnabled(gid) && !isGmUser && targetId === callerId;
    if (needsApproval) {
      const prev = existingSheet?.approval_state;
      if (prev === 'approved') {
        return interaction.reply({ content: '🔒 Your sheet is already approved — stats can only be changed by a GM now.', ephemeral: true });
      }
      updates.approval_state = 'pending';
    } else if (approvalEnabled(gid) && isGmUser) {
      updates.approval_state = 'approved'; // GM-built sheets skip the queue
    }

    upsertChar(gid, targetId, updates);
    const mention = targetUser ? `<@${targetId}>` : 'Your';
    const summary = Object.entries(updates)
      .filter(([k]) => !['hp_current','rerolls_current','approval_state','approval_msg_id'].includes(k))
      .map(([k,v]) => `**${k.toUpperCase()}**: ${v}`).join(', ');

    if (needsApproval) {
      // Reply first so the approval post can link back to a real message.
      const chId = approvalDestination(gid, 'sheets');
      await interaction.reply({ content: chId
        ? `✅ Sheet submitted — ${summary}\n\n⏳ **Awaiting GM approval.** You can't roll or fight until it's approved.\n📬 **You'll get a DM as soon as a GM decides** — if your DMs are closed, the notice will be posted here instead.\n🔒 Once approved, only a GM can change your sheet, so check it over now with \`/char view show\`.`
        : `✅ Sheet saved — ${summary}\n\n⚠️ No approval channel set; ask a GM to check \`/config channels approvals\`.` });
      let submitId = null;
      try { const rep = await interaction.fetchReply(); submitId = rep?.id ?? null; } catch {}
      const posted = await requestSheetApproval(interaction, gid, targetId, submitId);
      if (!posted) {
        await interaction.followUp({ content: '⚠️ Couldn\'t reach the approval channel — ask a GM to check `/config channels approvals`.', ephemeral: true }).catch(()=>{});
      }
      return;
    }
    return interaction.reply({ content: `✅ ${mention} character updated — ${summary}` });
  }

  if (sub === 'weaponemoji') {
    const slot = interaction.options.getString('slot'); // weapon1emoji or weapon2emoji
    const emoji = interaction.options.getString('emoji');     // from dropdown
    const custom = interaction.options.getString('custom');   // pasted server emoji
    const targetUser = interaction.options.getUser('user');
    const targetId = targetUser ? targetUser.id : callerId;
    const isGmUser = await isGm(interaction.guild, callerId);
    if (targetId !== callerId && !isGmUser)
      return interaction.reply({ content: '❌ Only GMs can modify other players\' characters.', ephemeral: true });
    {
      const lock = sheetEditLock(gid, callerId, targetId, isGmUser);
      if (lock) return interaction.reply({ content: lock, ephemeral: true });
    }
    // Custom (pasted) emoji takes priority over the dropdown
    const chosen = (custom && custom.trim()) ? custom.trim() : emoji;
    if (!chosen) return interaction.reply({ content: `❌ Pick a standard emoji from the dropdown, or paste a server custom emoji in the **custom** field.`, ephemeral: true });
    const cleaned = validateWeaponEmoji(interaction.guild, chosen);
    if (!cleaned) return interaction.reply({ content: `❌ That isn't a valid emoji. Use a standard emoji (${STANDARD_WEAPON_EMOJIS.join(' ')}) or one of this server's own custom emojis.`, ephemeral: true });
    upsertChar(gid, targetId, { [slot]: cleaned, [`${slot}_set`]: 1 });
    const slotLabel = slot === 'weapon1emoji' ? 'Weapon 1' : 'Weapon 2';
    return finishSheetEdit({
      src: interaction, gid, callerId, targetId, isGmCaller: isGmUser,
      content: `✅ ${slotLabel} emoji set to ${cleaned}${targetId!==callerId?` for <@${targetId}>`:''}.`,
      reply: replyThenFetch(interaction),
    });
  }

  if (sub === 'page') {
    if (!(await isGm(interaction.guild, callerId)))
      return interaction.reply({ content: '❌ Only GMs can link character pages.', ephemeral: true });
    const who = interaction.options.getUser('user');
    const nm3 = await getDisplayName(interaction.guild, who.id);
    if (interaction.options.getBoolean('unlink')) {
      clearCharPage(gid, who.id);
      return interaction.reply({ content: `📖 **${nm3}** is no longer linked to a page. The thread itself is untouched.` });
    }
    const thread = interaction.options.getChannel('thread');
    if (thread) {
      setCharPage(gid, who.id, thread.id, `https://discord.com/channels/${gid}/${thread.id}`, nm3);
      return interaction.reply({ content: `📖 **${nm3}** is linked to <#${thread.id}>. It shows on \`/char view show\`.` });
    }
    await interaction.deferReply();
    try {
      const made = await ensureCharPage(interaction.client, interaction.guild, who.id, nm3);
      if (made.skipped) return interaction.editReply({ content: '❌ No character forum is set — `/config channels charforum channel:#character-sheets`, or pass a `thread:` to link one by hand.' });
      return interaction.editReply({ content: made.existing
        ? `📖 **${nm3}** already has a page: ${made.url}`
        : `📖 Made a page for **${nm3}**: ${made.url}` });
    } catch (err) {
      return interaction.editReply({ content: `❌ Couldn't make it: ${err?.message || err}` });
    }
  }

  if (sub === 'hero') {
    if (!(await isGm(interaction.guild, callerId)))
      return interaction.reply({ content: '❌ Only GMs can grant Hero status.', ephemeral: true });
    const who = interaction.options.getUser('user');
    const on = interaction.options.getBoolean('value');
    const nm2 = await getDisplayName(interaction.guild, who.id);
    if (!getChar(gid, who.id)) return interaction.reply({ content: `❌ **${nm2}** has no character sheet.`, ephemeral: true });
    upsertChar(gid, who.id, { is_hero: on ? 1 : 0, ...(on ? {} : { signature_stat: null }) });
    return interaction.reply({ content: on
      ? `🦸 **${nm2}** is now a **Hero**. Their class and knight order are unaffected — set a signature stat with \`/char signature\`.`
      : `**${nm2}** is no longer a Hero. Any signature stat has been cleared.` });
  }

  if (sub === 'signature') {
    if (!(await isGm(interaction.guild, callerId)))
      return interaction.reply({ content: '❌ Only GMs can set a Hero\'s signature stat.', ephemeral: true });
    const target = interaction.options.getUser('user');
    const stat = interaction.options.getString('stat');
    const ch = getChar(gid, target.id);
    if (!ch) return interaction.reply({ content: '❌ That player has no character sheet yet.', ephemeral: true });
    const nm = await getDisplayName(interaction.guild, target.id);
    if (!stat) {
      upsertChar(gid, target.id, { signature_stat: null });
      return interaction.reply({ content: `✅ Cleared **${nm}**'s signature stat.` });
    }
    if (!isHero(ch)) return interaction.reply({ content: `❌ **${nm}** isn't a Hero. Set their class first with \`/char set field:class value:Hero\`.`, ephemeral: true });
    const val = ch[stat] ?? 0;
    if (val < SIGNATURE_MIN) return interaction.reply({ content: `❌ **${nm}**'s ${STAT_LABELS[stat]} is **${val}** — a signature stat needs **${SIGNATURE_MIN}+**.`, ephemeral: true });
    upsertChar(gid, target.id, { signature_stat: stat });
    return interaction.reply({ content: `⭐ **${nm}**'s signature stat is **${STAT_LABELS[stat]}** (${val}) — their ${STAT_LABELS[stat]} rolls now have **advantage**.` });
  }

  if (sub === 'set') {
    const field = interaction.options.getString('field');
    const value = interaction.options.getString('value');
    const targetUser = interaction.options.getUser('user');
    const targetId = targetUser ? targetUser.id : callerId;
    const isGmUser = await isGm(interaction.guild, callerId);
    if (targetId !== callerId && !isGmUser)
      return interaction.reply({ content: '❌ Only GMs can modify other players\' stats.', ephemeral: true });
    // Approved sheets are frozen to their owner — every field needs a GM. This
    // has to come before the order branch, which used to write and return above
    // the check and so let an approved player re-pick their Knight Order.
    {
      const lock = sheetEditLock(gid, callerId, targetId, isGmUser);
      if (lock) return interaction.reply({ content: lock, ephemeral: true });
    }
    // Every edit below is a player-writable field, so route the reply through
    // finishSheetEdit — it re-queues the sheet for approval when it needs to be.
    const done = (content) => finishSheetEdit({
      src: interaction, gid, callerId, targetId, isGmCaller: isGmUser, content,
      reply: replyThenFetch(interaction),
    });
    if (field === 'order') {
      const knight = KNIGHTS.find(k=>k.toLowerCase()===value.toLowerCase());
      if (!knight) return interaction.reply({ content: `❌ Choose from: ${KNIGHTS.join(', ')}`, ephemeral: true });
      upsertChar(gid, targetId, { order_name: knight });
      const upd = getChar(gid, targetId);
      if (!isWhiteKnight(upd)) setHealCharges(gid, targetId, 0);
      else { const cfg = getConfig(gid); setHealCharges(gid, targetId, cfg.heal_charges??3); }
      return done(`${KNIGHT_EMOJIS[knight]??'⚪'} Order set to **${knight}**${targetId!==callerId?` for <@${targetId}>`:''}.`);
    }
    if (STATS.includes(field)) {
      // Same rules on a touch-up. The zero check applies to the stat being
      // written, so a half-built sheet isn't blocked by its unset stats.
      if (!isGmUser) {
        const num0 = parseInt(value);
        if (Number.isFinite(num0)) {
          const after = statsAfter(getChar(gid, targetId), { [field]: num0 });
          // Ceiling only while editing — see statBudgetProblems for why.
          const problems = statBudgetProblems(gid, after, { requireAll: false, exact: false });
          const { min: statFloor } = statRules(gid);
          if (num0 < statFloor) problems.push(`0️⃣ Every stat needs at least **${statFloor}** point${statFloor === 1 ? '' : 's'} — **${field.toUpperCase()}** can't be ${num0}.`);
          if (problems.length) return refuseStatBudget({ src: interaction, gid, uid: callerId, problems, stats: after,
            reply: replyThenFetch(interaction) });
        }
      }
      const num = parseInt(value);
      if (isNaN(num)||num<0) return interaction.reply({ content: '❌ Value must be a positive number.', ephemeral: true });
      if (num > 99) return interaction.reply({ content: '❌ Stat values are capped at 99.', ephemeral: true });
      const upd = setStatAndDerive(gid, targetId, field, num);
      if (field==='wis') {
        if (isWhiteKnight(upd)) { const cfg=getConfig(gid); setHealCharges(gid,targetId,cfg.heal_charges??3); }
        else setHealCharges(gid,targetId,0);
      }
      let extra = '';
      if (field==='con') extra=` HP maxed to **${upd.hp_current} / ${maxHp(upd, gid)}**`;
      if (field==='lck') extra=` Rerolls maxed to **${upd.rerolls_current} / ${maxRerolls(upd)}**`;
      return done(`✅ ${field.toUpperCase()} set to **${num}**${targetId!==callerId?` for <@${targetId}>`:''}.${extra}`);
    }
    // Handle class, weapon and weapon emoji fields
    if (['class','weapon1','weapon2','weapon1emoji','weapon2emoji'].includes(field)) {
      if (field === 'weapon1emoji' || field === 'weapon2emoji') {
        const cleaned = validateWeaponEmoji(interaction.guild, value);
        if (!cleaned) return interaction.reply({ content: `❌ Use a standard emoji (${STANDARD_WEAPON_EMOJIS.join(' ')}) or one of this server's custom emojis.`, ephemeral: true });
        upsertChar(gid, targetId, { [field]: cleaned, [`${field}_set`]: 1 });
        const lbl = field === 'weapon1emoji' ? 'Weapon 1 Emoji' : 'Weapon 2 Emoji';
        return done(`✅ **${lbl}** set to ${cleaned}${targetId!==callerId?` for <@${targetId}>`:''}.`);
      }
      if (field === 'class' && String(value).toLowerCase() === 'hero' && !isGmUser) {
        return interaction.reply({ content: '❌ **Hero** is granted by a GM, not chosen. Pick Vanguard, Defender or Siege Knight.', ephemeral: true });
      }
      if (['class','weapon1','weapon2'].includes(field) && value.length > 50) {
        return interaction.reply({ content: '❌ That name is too long (max 50 characters).', ephemeral: true });
      }
      upsertChar(gid, targetId, { [field]: value });
      const label = { class:'Class', weapon1:'Weapon 1', weapon2:'Weapon 2' }[field];
      return done(`✅ **${label}** set to **${value}**${targetId!==callerId?` for <@${targetId}>`:''}.`);
    }
  }
  // Resubmit for approval. A rejected sheet is editable by its owner and any
  // edit re-queues it, but a player who disagrees with the call — or whose GM
  // hit the wrong button — shouldn't have to invent a change to be seen again.
  if (sub === 'submit') {
    const ch = getChar(gid, callerId);
    if (!ch) return interaction.reply({ content: '❌ You don\'t have a character sheet yet — make one with `/char create`.', ephemeral: true });
    if (!approvalEnabled(gid)) return interaction.reply({ content: '✅ This server doesn\'t use sheet approval — your sheet is already usable.', ephemeral: true });
    if (ch.approval_state === 'pending') {
      const chId = approvalDestination(gid, 'sheets');
      return interaction.reply({ content: `⏳ Your sheet is already waiting${chId ? ` in <#${chId}>` : ''}. A GM will get to it.`, ephemeral: true });
    }
    if (ch.approval_state === 'approved') return interaction.reply({ content: '✅ Your sheet is already approved. Ask a GM if you need a change.', ephemeral: true });
    const problems = sheetSubmissionProblems(gid, ch);
    if (problems.length) return refuseStatBudget({ src: interaction, gid, uid: callerId, problems, stats: ch,
      reply: replyThenFetch(interaction) });
    return finishSheetEdit({
      src: interaction, gid, callerId, targetId: callerId, isGmCaller: false,
      content: '📤 **Sheet sent back to the GMs.**',
      reply: replyThenFetch(interaction),
    });
  }

  // ── Character pages ──
  if (['summary','inventory','standing','rollhistory','showlore'].includes(sub)) {
    const who = interaction.options.getUser('user');
    const tid = who?.id ?? callerId;
    const nm = await getDisplayName(interaction.guild, tid);
    const ch = getChar(gid, tid);
    if (!ch) return interaction.reply({ content: `❌ **${nm}** has no character sheet.`, ephemeral: true });

    const inventoryLines = () => {
      const items = listItems(gid, tid);
      if (!items.length) return ['🎒 **Inventory** — empty.'];
      return ['🎒 **Inventory**', ...items.map(i =>
        `\`#${i.id}\` **${i.item}**${i.note ? ` — ${i.note}` : ''}${i.source ? `  _(${i.source})_` : ''}`)];
    };
    const questSummaryLines = () => {
      const rows = db.prepare(`SELECT * FROM quest_summaries WHERE guild_id=? AND user_id=?
                               ORDER BY ended_at DESC LIMIT 10`).all(gid, tid);
      if (!rows.length) return [];
      return ['', '📜 **Quests completed**',
        ...rows.map(r => `${r.url ? `[${r.quest_name}](${r.url})` : `**${r.quest_name}**`}`
          + ` — ${fmtElapsed(r.duration_ms)} · <t:${Math.floor(r.ended_at / 1000)}:R>`)];
    };
    const standingLines = () => {
      const out = [`🏅 **Standing** — **${ch.merits ?? 0}** merit${(ch.merits ?? 0) === 1 ? '' : 's'} · 💠 **${ch.renown ?? 0}** renown`];
      const ev = standingEvents(gid, tid);
      if (!ev.length) { out.push('_Nothing recorded yet._'); return out; }
      out.push('');
      for (const e of ev) {
        out.push(`${e.kind === 'merit' ? '🏅' : '💠'} ${e.delta > 0 ? '+' : ''}${e.delta} · ${e.reason || 'no reason given'}`
          + (e.at ? ` · <t:${Math.floor(e.at / 1000)}:R>` : ''));
      }
      return out;
    };
    // Faces for one die size, then a breakdown of every size rolled, then the
    // headline figures. The face list is always printed in full, zeros and all,
    // so the shape of someone's luck is visible at a glance.
    const rollLines = (sides) => {
      const all = rollTallyAll(gid, tid);
      if (!all.total) return ['🎲 **Roll history** — nothing recorded yet.'];
      const face = all.bySize[sides] || { by: {}, total: 0, sum: 0 };
      const out = [`🎲 **Roll history**`, '', `**d${sides} faces**`];
      const times = (c) => `${c} time${c === 1 ? '' : 's'} rolled`;
      for (let f = 1; f <= sides; f++) {
        const mark = f === 1 ? '🔴 ' : f === sides ? '🟡 ' : '';
        out.push(`${mark}**${f}** — ${times(face.by[f] || 0)}`);
      }

      out.push('', '**Dice rolled**');
      const shown = [2, 4, 6, 8, 10, 12, 20];
      for (const sd of shown) out.push(`d${sd} — ${times(all.bySize[sd]?.total || 0)}`);
      for (const sd of Object.keys(all.bySize).map(Number).sort((a, b) => a - b)) {
        if (!shown.includes(sd)) out.push(`d${sd} — ${times(all.bySize[sd].total)}`);
      }

      out.push('', `**Total dice rolled** — ${all.total}`);
      if (face.total) {
        const avg = (face.sum / face.total).toFixed(2);
        const peak = Math.max(...Object.values(face.by));
        const commonest = Object.entries(face.by).filter(([, c]) => c === peak).map(([f]) => f);
        out.push(`**Average d${sides} result** — ${avg}`);
        out.push(`**Most rolled** — ${commonest.join(', ')} (${times(peak)})`);
      }
      return out;
    };
    const loreLines = () => {
      const l = getLore(gid, tid);
      if (!l || !l.body) return ['📜 **Lore** — none written yet.'];
      if (l.state !== 'approved') return [`📜 **Lore** — ⏳ ${l.state === 'pending' ? 'awaiting GM approval' : 'was rejected'}${l.reason ? ` — ${l.reason}` : ''}.`];
      return ['📜 **Lore**', l.body];
    };

    if (sub === 'inventory')   return replyLong(interaction, [`🎒 **${nm}**`, '', ...inventoryLines().slice(1)]);
    if (sub === 'standing')    return replyLong(interaction, [`**${nm}**`, ...standingLines(), ...questSummaryLines()]);
    if (sub === 'rollhistory') return replyLong(interaction, [`**${nm}**`, ...rollLines(interaction.options.getInteger('sides') ?? 20)]);
    if (sub === 'showlore')    return replyLong(interaction, [`**${nm}**`, ...loreLines()]);

    // summary — the sheet, then every page under it
    const cfg = getConfig(gid); const mc = cfg.heal_charges ?? 3;
    const hr = getHealCharges(gid, tid, mc);
    const card = buildCharCard(ch, nm, hr.current, mc, gid);
    const t = rollTally(gid, tid, 20);
    const nat20 = t.by[20] || 0, nat1 = t.by[1] || 0;
    return replyLong(interaction, [...card, '',
      ...standingLines(), ...questSummaryLines(), '',
      ...inventoryLines(), '',
      `🎲 **Rolls** — ${t.total} lifetime · 🌟 ${nat20} nat-20${nat20 === 1 ? '' : 's'} · 💀 ${nat1} nat-1${nat1 === 1 ? '' : 's'}`, '',
      ...loreLines()]);
  }

  // Everything the gates check, shown as a checklist — so a new player sees the
  // whole list once instead of discovering it one refusal at a time.
  if (sub === 'check') {
    const ch = getChar(gid, callerId);
    if (!ch) {
      return interaction.reply({ ephemeral: true, content: [
        '📝 **You have no character sheet yet.**', '',
        '☐ Stats — `/char create str:5 con:4 dex:3 wis:2 lck:1`',
        '☐ Weapons — add `weapon1:` and `weapon2:` in the same command',
        '☐ Emojis — `/char weaponemoji` for each',
        '', '_Then it goes to a GM automatically._',
      ].join('\n') });
    }
    const { budget, min } = statRules(gid);
    const spent = statTotal(ch);
    const box = (ok) => ok ? '☑' : '☐';   // not `tick` — that name is a scheduler elsewhere
    const budgetOk = spent === budget && STATS.every(k => (Number(ch[k]) || 0) >= min);
    const w1 = !!String(ch.weapon1 || '').trim(), w2 = !!String(ch.weapon2 || '').trim();
    const e1 = !!ch.weapon1emoji_set, e2 = !!ch.weapon2emoji_set;
    const gm = await isGm(interaction.guild, callerId);

    const out = ['📝 **Your sheet**', ''];
    out.push(`${box(budgetOk)} **Stats** — ${STATS.map(k => `${k.toUpperCase()} ${Number(ch[k]) || 0}`).join(' · ')}`);
    out.push(`   _${spent}/${budget} spent${gm ? ' — GMs are exempt' : ''}${!budgetOk && spent !== budget ? `, ${spent > budget ? `${spent - budget} over` : `${budget - spent} left`}` : ''}_`);
    out.push(`${box(w1)} **Weapon 1** — ${w1 ? `**${ch.weapon1}**` : '_not set_'}`);
    out.push(`${box(w2)} **Weapon 2** — ${w2 ? `**${ch.weapon2}**` : '_not set_'}`);
    out.push(`${box(e1 && e2)} **Weapon emojis** — ${e1 && e2 ? 'both chosen' : `${!e1 ? 'Weapon 1' : ''}${!e1 && !e2 ? ' and ' : ''}${!e2 ? 'Weapon 2' : ''} still to choose`}`);

    const problems = sheetSubmissionProblems(gid, ch);
    out.push('');
    if (!problems.length) {
      const state = sheetApproved(gid, ch) ? '✅ **Approved.**'
        : ch.approval_requested_at ? '⏳ **With a GM now.**'
        : '✅ **Ready** — `/char submit` sends it.';
      out.push(state);
    } else {
      out.push('**Still to do**', ...problems.map(x => `• ${x.replace(/^[^ ]+ /, '')}`));
    }
    return interaction.reply({ ephemeral: true, content: out.join('\n') });
  }

  if (sub === 'prefer') {
    const ch = getChar(gid, callerId);
    if (!ch) return interaction.reply({ content: '❌ You need a character sheet first — `/char create`.', ephemeral: true });
    const atk = interaction.options.getString('atk');
    const def = interaction.options.getString('def');
    if (atk === null && def === null) {
      const say = (v, kind) => {
        if (!v) return `_no preference — the bot uses your best allowed stat_`;
        const allowed = allowedFightStats(gid, ch, kind);
        const honoured = !allowed || allowed.includes(v);
        return `**${STAT_LABELS[v]}**` + (honoured ? '' : ' _(your weapons don\'t allow it, so your best is used instead)_');
      };
      return interaction.reply({ ephemeral: true, content: [
        '🎯 **When the bot rolls for you on auto**',
        `⚔️ Attack — ${say(ch.preferred_atk, 'atk')}`,
        `🛡️ Defend — ${say(ch.preferred_def, 'def')}`,
        '', '_`/char prefer atk:Dexterity` to set one, or `atk:Clear it` to remove it._',
      ].join('\n') });
    }
    const fields = {};
    if (atk !== null) fields.preferred_atk = atk === 'none' ? null : atk;
    if (def !== null) fields.preferred_def = def === 'none' ? null : def;
    upsertChar(gid, callerId, fields);
    const after = getChar(gid, callerId);
    const line = (v, kind, what) => {
      if (!v) return `${what} — _no preference, your best allowed stat is used_`;
      const allowed = allowedFightStats(gid, after, kind);
      return `${what} — **${STAT_LABELS[v]}**`
        + (allowed && !allowed.includes(v) ? ` ⚠️ _your weapons don't allow it, so your best is used instead_` : '');
    };
    return interaction.reply({ ephemeral: true, content: [
      '🎯 **Auto-roll preference saved.**',
      line(after.preferred_atk, 'atk', '⚔️ Attack'),
      line(after.preferred_def, 'def', '🛡️ Defend'),
    ].join('\n') });
  }

  if (sub === 'edit') {
    if (!(await isGm(interaction.guild, callerId)))
      return interaction.reply({ content: '❌ Only GMs can reword items.', ephemeral: true });
    const who = interaction.options.getUser('user');
    const id = interaction.options.getInteger('id');
    const item = interaction.options.getString('item');
    const note = interaction.options.getString('note');
    if (item === null && note === null)
      return interaction.reply({ content: '❌ Give a new `item` name, a new `note`, or both.', ephemeral: true });
    const row = db.prepare('SELECT * FROM inventory WHERE guild_id=? AND id=? AND user_id=?').get(gid, id, who.id);
    const nm = await getDisplayName(interaction.guild, who.id);
    if (!row) return interaction.reply({ content: `❌ **${nm}** has no item \`#${id}\`.`, ephemeral: true });
    const fields = {};
    if (item !== null) fields.item = item.trim();
    if (note !== null) fields.note = /^(none|clear|-)$/i.test(note.trim()) ? null : note.trim();
    const keys = Object.keys(fields);
    db.prepare(`UPDATE inventory SET ${keys.map(k => `${k}=?`).join(',')} WHERE guild_id=? AND id=?`)
      .run(...keys.map(k => fields[k]), gid, id);
    const after = db.prepare('SELECT * FROM inventory WHERE guild_id=? AND id=?').get(gid, id);
    return interaction.reply({ content:
      `🎒 **${nm}**'s item \`#${id}\` is now **${after.item}**${after.note ? ` — ${after.note}` : ''}.` });
  }

  if (sub === 'give' || sub === 'take') {
    if (!(await isGm(interaction.guild, callerId)))
      return interaction.reply({ content: '❌ Only GMs can hand out or take items.', ephemeral: true });
    const who = interaction.options.getUser('user');
    const nm = await getDisplayName(interaction.guild, who.id);
    if (!getChar(gid, who.id)) return interaction.reply({ content: `❌ **${nm}** has no character sheet.`, ephemeral: true });
    if (sub === 'give') {
      const item = interaction.options.getString('item').trim();
      addItem(gid, who.id, item, { note: interaction.options.getString('note'), source: 'given by a GM', by: callerId });
      return interaction.reply({ content: `🎒 **${nm}** receives **${item}**.` });
    }
    const id = interaction.options.getInteger('id');
    return interaction.reply({ content: removeItem(gid, id, who.id)
      ? `🎒 Item \`#${id}\` taken from **${nm}**.`
      : `❌ **${nm}** has no item \`#${id}\`.`, ephemeral: true });
  }

  if (sub === 'lore') {
    const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
    const existing = getLore(gid, callerId);
    const modal = new ModalBuilder().setCustomId('loresubmit').setTitle('Your character\'s lore');
    modal.addComponents(new ActionRowBuilder().addComponents(
      new TextInputBuilder().setCustomId('body').setLabel('Lore')
        .setPlaceholder('Where they came from, who they were, what they carry.')
        .setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(3500)
        .setValue(existing?.body || '')));
    return interaction.showModal(modal);
  }

  if (sub === 'export') return handleCharExport(interaction);
  if (sub === 'import') return handleCharImport(interaction);
  if (sub === 'show') {
    const tu = interaction.options.getUser('user') || interaction.user, tid = tu.id;
    const char = getChar(gid, tid);
    if (!char) return interaction.reply({ content: '❌ No character found. Use `/char set` to get started.', ephemeral: true });
    const dn = await getDisplayName(interaction.guild, tid);
    const cfg = getConfig(gid); const mc = cfg.heal_charges??3;
    const hr = getHealCharges(gid, tid, mc);
    const kn = char.order_name ? `${KNIGHT_EMOJIS[char.order_name]??'⚪'}  ${char.order_name}` : 'No order set';
    const lines = [`⚔️  **${dn}**`, kn];
    if (char.class) lines.push(`🏅  ${char.class}`);
    { const sig = signatureLine(char); if (sig) lines.push(sig); }
    lines.push(`❤️  HP          ${char.hp_current} / ${maxHp(char, gid)}`, `🔄  Rerolls      ${char.rerolls_current} / ${maxRerolls(char)}`);
    if (isWhiteKnight(char)) lines.push(`🛡️  Heal         ${hr.current} / ${mc}`);
    lines.push('', `💪  STR         ${char.str}`, `🫀  CON         ${char.con}`, `⚡  DEX         ${char.dex}`, `🧠  WIS         ${char.wis}`, `🍀  LCK         ${char.lck}`);
    if (char.weapon1 || char.weapon2) {
      lines.push('');
      if (char.weapon1) lines.push(`${char.weapon1emoji??'⚔️'}  ${char.weapon1}`);
      if (char.weapon2) lines.push(`${char.weapon2emoji??'🗡️'}  ${char.weapon2}`);
    }
    return interaction.reply({ content: lines.join('\n') });
  }
}

async function handleProfile(interaction) {
  const sub = interaction.options.getSubcommand(), gid = interaction.guild.id, uid = interaction.user.id;
  if (sub === 'card') {
    const style = interaction.options.getString('style');
    const want = style === 'off' ? CARD_OFF : style === 'compact' ? CARD_COMPACT : CARD_FULL;
    let ch = getChar(gid, uid);
    if (!ch) { upsertChar(gid, uid, {}); ch = getChar(gid, uid); }
    upsertChar(gid, uid, { profile_enabled: want });
    const sample = want === CARD_COMPACT ? `\n${statLine(getChar(gid, uid), gid)}`
                 : want === CARD_FULL ? '\n_The whole sheet — order, class, HP, rerolls, stats and weapons._'
                 : '\n_Just the dice._';
    return interaction.reply({ ephemeral: true, content:
      `🎴 Roll card set to **${CARD_NAME[want]}**.${sample}`
      + (want === CARD_OFF ? '\n_Stat rolls still show the compressed line, since a bare total says nothing about which stat it was._' : '') });
  }

  if (sub === 'on') {
    let ch = getChar(gid, uid);
    if (!ch) { upsertChar(gid, uid, {}); ch = getChar(gid, uid); }
    upsertChar(gid, uid, { profile_enabled:1, hp_current:maxHp(ch, gid), rerolls_current:maxRerolls(ch) });
    if (isWhiteKnight(ch)) { const cfg=getConfig(gid); setHealCharges(gid,uid,cfg.heal_charges??3); }
    return interaction.reply({ content: '✅ Profile enabled (full card). HP and rerolls maxed out. `/char profile card` picks a style.', ephemeral: true });
  }
  if (sub === 'off') {
    upsertChar(gid, uid, { profile_enabled: 0 });
    return interaction.reply({ content: '⏸️ Profile disabled. Rolls post as plain text. `/char profile card style:Compressed` gives a one-line version instead.', ephemeral: true });
  }
  if (sub === 'show') {
    const ch = getChar(gid, uid);
    if (!ch) return interaction.reply({ content: '❌ No character set up. Use `/char set` first.', ephemeral: true });
    const dn = await getDisplayName(interaction.guild, uid);
    const cfg = getConfig(gid); const mc = cfg.heal_charges??3;
    const hr = getHealCharges(gid, uid, mc);
    const card = buildCharCard(ch, dn, hr.current, mc, gid);
    const link = charPageLink(gid, uid);
    if (link) card.push('', `📖 ${link}`);
    return interaction.reply({ content: card.join('\n'), ephemeral: true });
  }
  if (sub === 'save') {
    const slot = interaction.options.getString('slotname');
    const ch = getChar(gid, uid);
    if (!ch) return interaction.reply({ content: '❌ No character to save.', ephemeral: true });
    const cfg = getConfig(gid);
    const hr = getHealCharges(gid, uid, cfg.heal_charges??3);
    saveProfile(gid, uid, slot, { ...ch, heal_current: hr.current });
    return interaction.reply({ content: `💾 Profile saved as **${slot}**.`, ephemeral: true });
  }
  if (sub === 'load') {
    const slot = interaction.options.getString('slotname');
    // A snapshot restore rewrites stats — it must obey the approval lock, and
    // put the sheet back in the queue, or it'd be a way around both.
    const isGmUser = await isGm(interaction.guild, uid);
    {
      const lock = sheetEditLock(gid, uid, uid, isGmUser);
      if (lock) return interaction.reply({ content: lock, ephemeral: true });
    }
    const snap = loadProfile(gid, uid, slot);
    if (!snap) return interaction.reply({ content: `❌ No save found with name **${slot}**.`, ephemeral: true });
    // Snapshots predate the budget, so an old save could smuggle an illegal
    // spread back in. Players get checked; GMs restore whatever they like.
    if (!isGmUser) {
      const problems = sheetSubmissionProblems(gid, getChar(gid, uid) ? { ...getChar(gid, uid), ...snap } : snap);
      if (problems.length) return refuseStatBudget({ src: interaction, gid, uid, problems, stats: snap,
        reply: replyThenFetch(interaction) });
    }
    upsertChar(gid, uid, { hp_current:snap.hp_current, rerolls_current:snap.rerolls_current, str:snap.str, con:snap.con, dex:snap.dex, wis:snap.wis, lck:snap.lck, order_name:snap.order_name, profile_enabled:snap.profile_enabled });
    setHealCharges(gid, uid, snap.heal_current??0);
    return finishSheetEdit({
      src: interaction, gid, callerId: uid, targetId: uid, isGmCaller: isGmUser,
      content: `📂 Profile **${slot}** loaded.`,
      link: false, // the reply is ephemeral, so a jump link would be dead for the GM
      reply: async (c) => { await interaction.reply({ content: c, ephemeral: true }); return null; },
    });
  }
  if (sub === 'saves') {
    const saves = listProfiles(gid, uid);
    if (!saves.length) return interaction.reply({ content: '❌ No saved profiles found.', ephemeral: true });
    return interaction.reply({ content: `📋 Your saves:\n${saves.map(s=>`• **${s.slot_name}** — ${s.saved_at}`).join('\n')}`, ephemeral: true });
  }
}

// ─────────────────────────────────────────────
//  PREFIX HANDLERS
// ─────────────────────────────────────────────

async function handleRoll(message, rest, mode, isReroll, successCheck = false) {
  const gid = message.guild.id, cid = message.channel.id, uid = message.author.id;
  const gateMsg = sheetGate(gid, uid);
  if (gateMsg) return replyQuietly(message, gateMsg);
  let notation, label, flavour, statRolled = null;

  if (isReroll) {
    const last = getLastRoll(gid, cid, uid);
    if (!last) return message.reply('❌ No previous roll found in this channel.');
    if (last.rerolled) return message.reply('❌ That roll has already been rerolled — one reroll per roll. Whatever it says, it stands.');
    const ch = getChar(gid, uid);
    if (!ch || ch.rerolls_current <= 0) return message.reply('❌ No rerolls remaining.');
    markRerolled(gid, cid, uid);
    notation = last.notation;
    const [rl, ...fp] = rest.split('\n');
    label = rl.trim() || last.label;
    flavour = fp.join('\n').trim() || null;
    statRolled = resolveStatWord(label);   // a reroll of a stat roll still shows the sheet
    upsertChar(gid, uid, { rerolls_current: ch.rerolls_current - 1 });
  } else {
    const ch = getChar(gid, uid);
    const parsed = parseRollInput(rest, ch);
    // Hero signature: a stat roll on the designated stat is made with advantage.
    // This used to test parsed.label, which only equals the stat when no label
    // was given — so "str atk" silently lost the Hero's advantage. parsed.stat
    // is the stat actually rolled, whichever spelling was typed.
    if (parsed?.stat) {
      mode = applySignatureMode(ch, parsed.stat, mode);
      statRolled = parsed.stat;
    }
    if (!parsed) return message.reply('❌ Invalid notation. Try `r1d20+5 attack`, `r2d6`, or `r str`.');
    notation = parsed.notation;
    label = parsed.label;
    flavour = parsed.flavour;
  }

  let result;
  mode = applyNextMark(gid, uid, mode);
  if (mode === 'adv') result = rollAdvantage(notation);
  else if (mode === 'dis') result = rollDisadvantage(notation);
  else result = rollNotation(notation);
  if (!result) return message.reply('❌ Could not parse dice notation.');

  saveRoll(gid, cid, uid, notation, label);
  const critType = detectCrit(result, mode);
  const naturalRoll = mode === 'normal' ? result.rolls[0] : result.chosen;
  const sides = result.sides ?? (mode === 'normal' ? result.sides : result.sides);
  const successResult = successCheck ? getSuccessResult(result.total, naturalRoll, result.sides ?? result.sides) : null;
  const rollLine = buildRollLine(result, mode, critType, successResult);
  recordRoll(gid, { userId: uid, channelId: cid, messageId: message.id, input: message.content,
    rollLine, result, context: isReroll ? 'reroll' : (successCheck ? 'success check' : null) });
  // A reroll does not overwrite the saved roll, so its own result can't be
  // rerolled in turn — the mark set above stays put.
  await sendRollEmbed(message, rollLine, label, isReroll, uid, flavour, result.total, critType, !!statRolled);
}

async function handleHeal(message, rest) {
  const gid = message.guild.id, uid = message.author.id, cid = message.channel.id;
  const gateMsg = sheetGate(gid, uid);
  if (gateMsg) return replyQuietly(message, gateMsg);
  // Accept the mention anywhere in the argument, not just flush at the start —
  // "!heal @user", "!heal  @user" and "!heal please @user" all work.
  const mentionMatch = rest.match(/<@!?(\d+)>/);
  if (!mentionMatch) return message.reply('❌ You must target a player. Usage: `!heal @user`');
  const targetId = mentionMatch[1];
  if (targetId === uid) return message.reply('❌ You cannot heal yourself.');
  const char = getChar(gid, uid);
  // This checks the HEALER's sheet — be explicit so it isn't mistaken for the target's.
  if (!char) return message.reply('❌ **You** have no character sheet yet — the healer needs one to roll WIS. Use `/char create` first.');
  if (!isWhiteKnight(char)) return message.reply('❌ Only **White Knights** with **WIS 5+** can use Heal. Your order and WIS are set with `/char set`.');
  const targetChar = getChar(gid, targetId);
  if (!targetChar) return message.reply(`❌ <@${targetId}> has no character sheet yet.`);
  const cfg = getConfig(gid); const mc = cfg.heal_charges??3;
  const hr = getHealCharges(gid, uid, mc);
  if (hr.current <= 0) return message.reply('❌ No Heal charges remaining.');
  const result = rollNotation(`1d20+${char.wis}`);
  const nat = result.rolls[0], total = result.total;
  const tn = await getDisplayName(message.guild, targetId);
  let healAmount = 0, chargesUsed = 0, resultText = '';
  if (nat === 20) { healAmount=2; chargesUsed=0; resultText=`*Natural 20! 2 HP restored to ${tn}. No charge consumed.*`; }
  else if (total >= 20) { healAmount=2; chargesUsed=1; resultText=`*2 HP restored to ${tn}. 1 charge consumed.*`; }
  else if (nat === 1) { chargesUsed=Math.min(2,hr.current); resultText=`*Natural 1! No heal. ${chargesUsed} charges consumed.*`; }
  else { chargesUsed=1; resultText=`*No heal. 1 charge consumed.*`; }
  const newTHp = Math.min(targetChar.hp_current + healAmount, maxHp(targetChar, gid));
  const newCharges = Math.max(0, hr.current - chargesUsed);
  upsertChar(gid, targetId, { hp_current: newTHp });
  setHealCharges(gid, uid, newCharges);
  const upd = getChar(gid, uid);
  const dn = await getDisplayName(message.guild, uid);
  const modStr = char.wis > 0 ? ` +${char.wis}` : '';
  const rollLine = `🎲  1d20+${char.wis} → [${nat}]${modStr} = **${total}**`;
  recordRoll(gid, { userId: uid, channelId: cid, messageId: message.id, input: message.content, rollLine, nat, sides: 20, context: 'heal' });
  let content;
  const healMode = cardMode(char);
  if (healMode === CARD_COMPACT) {
    content = `**heal**\n${rollLine}\n${statLine(upd, gid)}\n${resultText}`;
  } else if (healMode === CARD_FULL) {
    content = buildRollEmbed({ rollLine, label:'heal', isReroll:false, char:{...upd,displayName:dn}, healCharges:newCharges, maxCharges:mc, flavour:null, total, critType:null });
    content += `\n${resultText}`;
  } else {
    content = `**heal**\n${rollLine}\n${resultText}`;
  }
  await message.reply(content);
}

// Shared by !hp and !rerolls: "+5", "@user -3" and "-3 @user" all parse, and
// targeting anyone else needs the GM role. Returns { targetId, amount } or
// { error } for the caller to reply with.
async function parseTargetAmount(message, rest, resourceLabel, usage) {
  const uid = message.author.id;
  rest = String(rest || '').trim();
  const mm  = rest.match(/^<@!?(\d+)>\s*([+-]\d+)$/);   // @user +5
  const mm2 = rest.match(/^([+-]\d+)\s*<@!?(\d+)>$/);   // +5 @user
  const sm  = rest.match(/^([+-]\d+)$/);                 // +5  (self)
  if (mm || mm2) {
    if (!(await isGm(message.guild, uid)))
      return { error: `❌ Only GMs can modify other players' ${resourceLabel}.` };
    return mm ? { targetId: mm[1], amount: parseInt(mm[2]) }
              : { targetId: mm2[2], amount: parseInt(mm2[1]) };
  }
  if (sm) return { targetId: uid, amount: parseInt(sm[1]) };
  return { error: `❌ Usage: ${usage}` };
}

async function handleHp(message, rest) {
  const gid = message.guild.id, uid = message.author.id;
  const t = await parseTargetAmount(message, rest, 'HP', '`!hp +5` or `!hp @user -3`');
  if (t.error) return message.reply(t.error);
  const { targetId, amount } = t;
  const ch = getChar(gid, targetId);
  if (!ch) return message.reply('❌ No character found for that user.');
  const hm = maxHp(ch, gid);
  const newHp = Math.max(0, Math.min(ch.hp_current + amount, hm));
  upsertChar(gid, targetId, { hp_current: newHp });
  const dir = amount > 0 ? '💚 Healed' : '🩸 Damaged';
  await message.reply(`${dir} ${Math.abs(amount)} HP — ${targetId===uid?'Your':`<@${targetId}>'s`} HP: **${newHp} / ${hm}**`);
}

async function handleRerolls(message, rest) {
  const gid = message.guild.id, uid = message.author.id;
  const t = await parseTargetAmount(message, rest, 'rerolls', '`!rerolls +1` or `!rerolls @user -1`');
  if (t.error) return message.reply(t.error);
  const { targetId, amount } = t;
  const ch = getChar(gid, targetId);
  if (!ch) return message.reply('❌ No character found for that user.');
  const rm = maxRerolls(ch);
  const newR = Math.max(0, Math.min(ch.rerolls_current + amount, rm));
  upsertChar(gid, targetId, { rerolls_current: newR });
  await message.reply(`🔄 ${targetId===uid?'Your':`<@${targetId}>'s`} Rerolls: **${newR} / ${rm}**`);
}

// Resolve a rest token against a resource max.
//   "100%" / "50%" -> percentage of max (capped at max, uncapped input allowed)
//   "3"            -> flat: set the resource to exactly 3 (capped at max)
// Returns { value, changed } — changed=false means "don't touch this resource".
// Work out what a rest amount means. `current` is what the character has now,
// which only matters for the "+" forms.
//
//   50%   → set to half their maximum
//   +50%  → add half their maximum to what they have
//   4     → set to exactly 4
//   +4    → add 4 to what they have
//   0%    → leave it alone
//
// The "+" forms exist because "a short rest restores 4 HP" reads as *add 4* to
// most people, while a bare number has always meant *set to 4* — so both are
// spelled out rather than one silently winning.
function resolveRestToken(token, max, fallback, current = null) {
  let raw = (token === null || token === undefined || token === '') ? fallback : String(token).trim();
  if (raw === null || raw === undefined) return { value: null, changed: false };
  raw = String(raw).trim();

  const add = raw.startsWith('+');
  if (add) raw = raw.slice(1).trim();
  const base = (add && typeof current === 'number') ? current : 0;

  if (raw.endsWith('%')) {
    const p = parseInt(raw.slice(0, -1), 10);
    if (isNaN(p) || p <= 0) return { value: null, changed: false };
    const amount = Math.floor(max * p / 100);
    return { value: Math.max(0, Math.min(max, add ? base + amount : amount)), changed: true };
  }
  const n = parseInt(raw, 10);
  if (isNaN(n) || n < 0) return { value: null, changed: false };
  return { value: Math.max(0, Math.min(max, add ? base + n : n)), changed: true };
}

async function handleRest(message, rest, type) {
  const gid = message.guild.id, uid = message.author.id;
  const mm = String(rest || '').match(/<@!?(\d+)>/);
  let targetId = uid;
  if (mm) {
    if (!(await isGm(message.guild, uid))) return message.reply('❌ Only GMs can apply rests to other players.');
    targetId = mm[1];
  }
  const ch = getChar(gid, targetId);
  if (!ch) return message.reply('❌ No character found.');
  const cfg = getConfig(gid); const mc = cfg.heal_charges??3;
  const hm = maxHp(ch, gid), rm = maxRerolls(ch);
  const tn = targetId === uid ? 'Your' : `<@${targetId}>'s`;

  let label, hpTok, rTok, healTok;
  if (type==='lrest') {
    label = '🌙 Long Rest';
    hpTok = cfg.lrest_hp; rTok = cfg.lrest_rerolls; healTok = cfg.lrest_heal;
    hpTok ??= '100%'; rTok ??= '100%'; healTok ??= '100%';
  } else if (type==='srest') {
    label = '☀️ Short Rest';
    hpTok = cfg.srest_hp; rTok = cfg.srest_rerolls; healTok = cfg.srest_heal;
    hpTok ??= '50%'; rTok ??= '0%'; healTok ??= '0%';
  } else if (type==='hpfull') {
    // HP-only commands ignore rest config entirely
    upsertChar(gid, targetId, { hp_current: hm });
    return message.reply([`❤️ HP Restored applied to ${tn} character.`, `❤️ HP: **${hm} / ${hm}**`].join('\n'));
  } else if (type==='hphalf') {
    const half = Math.floor(hm/2);
    upsertChar(gid, targetId, { hp_current: half });
    return message.reply([`❤️ HP Half Restored applied to ${tn} character.`, `❤️ HP: **${half} / ${hm}**`].join('\n'));
  }

  // Long / short rest: resolve each resource's token and only touch ones that change
  const lines = [`${label} applied to ${tn} character.`];
  const updates = {};
  const hpR = resolveRestToken(hpTok, hm, '0%', ch.hp_current ?? 0);
  if (hpR.changed) { updates.hp_current = hpR.value; lines.push(`❤️ HP: **${hpR.value} / ${hm}**`); }
  const rR = resolveRestToken(rTok, rm, '0%', ch.rerolls_current ?? 0);
  if (rR.changed) { updates.rerolls_current = rR.value; lines.push(`🔄 Rerolls: **${rR.value} / ${rm}**`); }
  if (Object.keys(updates).length) upsertChar(gid, targetId, updates);
  const healR = resolveRestToken(healTok, mc, '0%', getHealCharges(gid, targetId, mc).current);
  if (healR.changed && isWhiteKnight(ch)) {
    setHealCharges(gid, targetId, healR.value);
    lines.push(`🛡️ Heal: **${healR.value} / ${mc}**`);
  }
  await message.reply(lines.join('\n'));
}

// /gm questwipe — the whole board, gone. Confirm-gated; book index entries are
// cleared best-effort; threads stay (deleting dozens is rate-limit suicide —
// re-running /config channels questplanning remakes clean books any time). The run
// ledger — the source of the DM cards' guided counters — survives unless
// runs:true says otherwise.
async function runGmQuestWipe(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs can wipe the board.', ephemeral: true });
  const wipeRuns = interaction.options.getBoolean('runs') ?? false;
  const qCount = db.prepare('SELECT COUNT(*) AS c FROM quests WHERE guild_id=?').get(gid).c;
  const rCount = db.prepare('SELECT COUNT(*) AS c FROM quest_runs WHERE guild_id=?').get(gid).c;
  if (!qCount && !(wipeRuns && rCount)) return interaction.reply({ content: '🗺️ The board is already empty.', ephemeral: true });
  return requestConfirm(interaction,
    `Delete **all ${qCount} quest${qCount === 1 ? '' : 's'}** on this server — rosters, timelines and book entries included${wipeRuns ? `, **plus the run ledger (${rCount} run${rCount === 1 ? '' : 's'}) and the DM guided-counters**` : ` (the run ledger's ${rCount} run${rCount === 1 ? '' : 's'} and DM counters stay)`}? Board and planning threads are left where they stand.`,
    async () => {
      const quests = db.prepare('SELECT number, index_thread_id, index_msg_id FROM quests WHERE guild_id=?').all(gid);
      let cleared = 0;
      for (const q of quests) {
        if (!q.index_thread_id || !q.index_msg_id) continue;
        try {
          const bk = await interaction.client.channels.fetch(q.index_thread_id);
          if (bk?.isThread?.()) { if (bk.archived) await wakeThread(bk); await bk.messages.delete(q.index_msg_id); cleared++; }
        } catch { /* already gone */ }
      }
      db.prepare('DELETE FROM quest_members WHERE guild_id=?').run(gid);
      db.prepare('DELETE FROM quest_events WHERE guild_id=?').run(gid);
      db.prepare('DELETE FROM quests WHERE guild_id=?').run(gid);
      if (wipeRuns) db.prepare('DELETE FROM quest_runs WHERE guild_id=?').run(gid);
      await refreshDmRoster(interaction.client, interaction.guild, gid);
      return `🗑️ **${qCount}** quest${qCount === 1 ? '' : 's'} wiped — ${cleared} book entr${cleared === 1 ? 'y' : 'ies'} cleared${wipeRuns ? `, run ledger erased (${rCount})` : ', run ledger kept'}. Threads remain; \`/config channels questplanning\` remakes clean books any time.`;
    });
}

// /gm reroll — the GM interrupts a mistaken roll and re-rolls it by decree.
// Token-free by design: this is a correction, not a spend, and the player's
// own once-per-roll reroll right is left exactly as it was.
async function runGmReroll(interaction) {
  const gid = interaction.guild.id, cid = interactionChannelId(interaction);
  if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs correct rolls.', ephemeral: true });
  const target = interaction.options.getUser('target');
  const tid = target.id;
  const stat = interaction.options.getString('stat');
  const gmMode = interaction.options.getString('mode');
  const flat = interaction.options.getBoolean('flat') ?? false;
  const flavour = interaction.options.getString('flavour');
  if (!stat && !gmMode && !flat) {
    return interaction.reply({ content: '❌ Name what was wrong — `stat:`, `mode:`, `flat:true`, or any mix.', ephemeral: true });
  }
  const ch = getChar(gid, tid);

  const termBits = [];
  if (flat) termBits.push('flat d20');
  else if (stat) termBits.push(STAT_LABELS[stat]);
  if (gmMode === 'adv') termBits.push('advantage');
  if (gmMode === 'dis') termBits.push('disadvantage');
  if (gmMode === 'normal') termBits.push('normal footing');

  // ── Fight path: the target holds a pending roll in a live fight here ──
  const fight = getFight(gid, cid);
  if (fight && fight.state === 'active') {
    const turnOrder = fightOrder(fight);
    const isAtk = turnOrder[fight.turn_index] === tid && !!fight.atk_stat;
    const isDef = fight.current_target === tid && fight.def_roll !== null;
    if (isAtk || isDef) {
      if (!ch) return interaction.reply({ content: '❌ They have no character sheet to roll from.', ephemeral: true });
      const useStat = stat ?? (isAtk ? fight.atk_stat : fight.def_stat);
      const mod = flat ? 0 : (ch[useStat] ?? 0);
      const effMode = flat ? (gmMode ?? 'normal') : applySignatureMode(ch, useStat, gmMode ?? 'normal');
      const icon = isAtk ? '⚔️' : '🛡️';
      const faceStr = flat ? '1d20 (flat)' : `1d20+${STAT_LABELS[useStat]}`;
      const modStr = mod > 0 ? ` +${mod}` : mod < 0 ? ` ${mod}` : '';
      let nat, total, rollLine;
      if (effMode === 'adv' || effMode === 'dis') {
        const r1 = rollDie(20), r2 = rollDie(20);
        nat = effMode === 'adv' ? Math.max(r1, r2) : Math.min(r1, r2);
        const dropped = effMode === 'adv' ? Math.min(r1, r2) : Math.max(r1, r2);
        total = nat + mod;
        rollLine = `${icon}  ${faceStr} (${effMode === 'adv' ? 'advantage' : 'disadvantage'}) → [${nat}, ~~${dropped}~~]${modStr} = ${fightTotalStr(total, nat, 20)}`;
      } else {
        nat = rollDie(20); total = nat + mod;
        rollLine = `${icon}  ${faceStr} → [${nat}]${modStr} = ${fightTotalStr(total, nat, 20)}`;
      }
      if (isAtk) upsertFight(gid, cid, { atk_roll: total, atk_nat: nat, atk_mode: effMode });
      else upsertFight(gid, cid, { def_roll: total, def_nat: nat, def_mode: effMode });
      recordRoll(gid, { userId: tid, channelId: cid, interaction, nat, sides: 20,
        input: '/gm reroll', rollLine, context: `GM correction — fight ${isAtk ? 'attack' : 'defence'} (${termBits.join(', ')})` });
      const nm = await getDisplayName(interaction.guild, tid);
      bookLog(gid, 'gmacts', `⚖️ <@${interaction.user.id}> corrected <@${tid}>'s fight ${isAtk ? 'attack' : 'defence'} — ${termBits.join(', ')}, no token spent.`, { channelId: cid });
      const lines = [`⚖️ **GM correction** — **${nm}**'s ${isAtk ? 'attack' : 'defence'} is rerolled: ${termBits.join(' · ')}. No token spent.`, rollLine];
      if (flavour) lines.push(`_${flavour}_`);
      lines.push('', fight.def_roll !== null || isDef ? '⚡ Use \`/fight resolve\` to resolve this exchange.' : '🛡️ The defence still stands to be rolled.');
      return interaction.reply({ content: lines.join('\n') });
    }
  }

  // ── Chat path: correct their last recorded roll in this channel ──
  const last = getLastRoll(gid, cid, tid);
  if (!last) return interaction.reply({ content: '❌ Nothing of theirs here to correct — their last roll lives where they rolled it.', ephemeral: true });
  if (stat && !ch) return interaction.reply({ content: '❌ They have no character sheet, so a stat correction has nothing to draw on.', ephemeral: true });
  const notation = flat ? '1d20' : stat ? `1d20+${ch[stat] ?? 0}` : last.notation;
  const effMode = flat ? (gmMode ?? 'normal') : stat ? applySignatureMode(ch, stat, gmMode ?? 'normal') : (gmMode ?? 'normal');
  const result = effMode === 'adv' ? rollAdvantage(notation)
               : effMode === 'dis' ? rollDisadvantage(notation)
               : rollNotation(notation);
  if (!result) return interaction.reply({ content: '❌ Their last roll\'s notation no longer reads.', ephemeral: true });
  const nat = effMode === 'normal' ? result.rolls[0] : result.chosen;
  const sides = result.sides ?? 20;
  const critType = sides === 20 ? (nat === 20 ? 'crit' : nat === 1 ? 'fail' : null) : null;
  const rollLine = buildRollLine(result, effMode, critType, null);
  recordRoll(gid, { userId: tid, channelId: cid, interaction, result,
    input: '/gm reroll', rollLine, context: `GM correction (was ${last.notation}${last.label ? ` · ${last.label}` : ''})` });
  saveRoll(gid, cid, tid, notation, last.label);
  const nm = await getDisplayName(interaction.guild, tid);
  bookLog(gid, 'gmacts', `⚖️ <@${interaction.user.id}> corrected <@${tid}>'s last roll (was \`${last.notation}\`) — ${termBits.join(', ')}, no token spent.`, { channelId: cid });
  const lines = [`⚖️ **GM correction** — **${nm}** rerolls (was \`${last.notation}\`): ${termBits.join(' · ')}. No token spent.`, rollLine];
  if (flavour) lines.push(`_${flavour}_`);
  return interaction.reply({ content: lines.join('\n') });
}

// /gm dc — call a check. Everything a press needs rides the customId
// (dcroll:uid:stat:dc:mode:flat:modifier ≈ 45 chars), so the card is
// stateless: a restart forgets nothing and a pressed button simply goes dark.
// One check roll under the called conditions — shared by player presses and
// the instant NPC rolls. `subject` carries stats; `sig` a signature row or null.
function rollDcCheck({ stat, notation, dc, gmMode, flat, modifier, subject, sig }) {
  const useNotation = notation || (flat || !stat ? '1d20+0' : `1d20+${subject?.[stat] ?? 0}`);
  const mode = (notation || flat || !stat) ? gmMode : applySignatureMode(sig ?? subject, stat, gmMode);
  const result = mode === 'adv' ? rollAdvantage(useNotation)
               : mode === 'dis' ? rollDisadvantage(useNotation)
               : rollNotation(useNotation);
  if (!result) return null;
  const nat = mode === 'normal' ? result.rolls[0] : result.chosen;
  const sides = result.sides ?? 20;
  const total = result.total + modifier;
  const passed = (sides === 20 && nat === 20) ? true : (sides === 20 && nat === 1) ? false : total >= dc;
  const critType = sides === 20 ? (nat === 20 ? 'crit' : nat === 1 ? 'fail' : null) : null;
  const band = critType === 'crit' ? '🌟 **Critical Success**' : critType === 'fail' ? '💀 **Critical Fail**'
             : passed ? '✅ **Success**' : '❌ **Fail**';
  const rollLine = buildRollLine(result, mode, critType, null) + (modifier ? ` ${modifier > 0 ? '+' : ''}${modifier} → **${total}**` : '');
  return { result, nat, total, passed, band, rollLine, mode };
}

// The check line from the form: a stat or a notation, a DC, and any of
// hidden · bare/flat · adv · dis · ±N. Order doesn't matter; the first
// bare number is the DC. Returns null when no DC is found.
function parseDcLine(text) {
  const out = { stat: null, notation: null, dc: null, mode: 'normal', flat: false, secret: false, modifier: 0 };
  for (const tk of String(text || '').trim().split(/[\s,]+/).filter(Boolean)) {
    const t = tk.toLowerCase();
    if (/^(str|con|dex|wis|lck)$/.test(t)) { out.stat = t; continue; }
    if (/^\d+$/.test(t) && out.dc === null) { out.dc = parseInt(t); continue; }
    if (/^\d*d\d+([+-]\d+)?$/.test(t)) { out.notation = t; continue; }
    if (/^(hidden|secret)$/.test(t)) { out.secret = true; continue; }
    if (/^(bare|flat)$/.test(t)) { out.flat = true; continue; }
    if (/^(adv|advantage)$/.test(t)) { out.mode = 'adv'; continue; }
    if (/^(dis|disadvantage)$/.test(t)) { out.mode = 'dis'; continue; }
    if (/^[+-]\d+$/.test(t)) { out.modifier = parseInt(t); continue; }
  }
  if (out.dc === null || out.dc < 1 || out.dc > 99) return null;
  if (out.notation && (out.notation.length > 12 || !parseNotation(out.notation))) return null;
  return out;
}

// An outcome box: a leading tag line carries the rules, everything after
// it is what the players read. `[dis dex-1 -3hp]` — any order, any subset,
// brackets optional on a first line that holds nothing else.
function parseOutcomeBlock(text) {
  const out = { mark: '', sanction: null, damage: 0, narration: null };
  let body = String(text || '').replace(/\r/g, '').trim();
  if (!body) return out;
  const lines = body.split('\n');
  const head = lines[0].trim();
  const bracket = /^\[([^\]]*)\]$/.exec(head);
  const tagsOnly = bracket ? bracket[1]
    : /^[a-z0-9+\-\s,]+$/i.test(head) && /\b(adv|dis|bare|flat|hp)\b|[+-]\d/i.test(head) && lines.length > 1 ? head : null;
  if (tagsOnly !== null) {
    for (const tk of tagsOnly.split(/[\s,]+/).filter(Boolean)) {
      const t = tk.toLowerCase().replace(/^\[|\]$/g, '');
      if (/^(adv|advantage)$/.test(t)) { out.mark = 'adv'; continue; }
      if (/^(dis|disadvantage)$/.test(t)) { out.mark = 'dis'; continue; }
      if (/^(bare|flat)$/.test(t)) { out.mark = 'flat'; continue; }
      const hp = /^-?(\d+)hp$/.exec(t);
      if (hp) { out.damage = Math.min(20, parseInt(hp[1])); continue; }
      const sx = parseSanction(t);
      if (sx) { out.sanction = sx; continue; }
    }
    body = lines.slice(1).join('\n').trim();
  }
  out.narration = body || null;
  return out;
}

// A signed stat shift like `dex-1` or `lck+2` — the check's sanction.
// Returns { stat, delta } or null when the text doesn't read.
function parseSanction(raw) {
  const m = /^\s*(str|con|dex|wis|lck)\s*([+-]\d)\s*$/i.exec(raw || '');
  if (!m) return null;
  const delta = parseInt(m[2]);
  if (!delta || Math.abs(delta) > 5) return null;
  return { stat: m[1].toLowerCase(), delta };
}
function sanctionLabel(sx) {
  return `${STAT_LABELS[sx.stat]} ${sx.delta > 0 ? '+' : '−'}${Math.abs(sx.delta)}`;
}
// Apply a sanction to whoever rolled — sheet-live, floor 0, noted in lines.
function applyDcSanction({ gid, id, isNpc, sanction, lines }) {
  if (!sanction) return;
  bookLog(gid, 'gmacts', `⚖️ ${isNpc ? `**${npcNameFromFighter(id)}**` : `<@${id}>`} — ${sanctionLabel(sanction)} by a called check.`);
  if (isNpc) {
    const npc = getNpc(gid, npcNameFromFighter(id));
    if (!npc) return;
    const now = Math.max(0, (npc[sanction.stat] ?? 0) + sanction.delta);
    upsertNpc(gid, npc.name, { [sanction.stat]: now });
    lines.push(`⚖️ ${sanctionLabel(sanction)} — now **${now}**.`);
  } else {
    const ch = getChar(gid, id);
    if (!ch) return;
    const now = Math.max(0, (ch[sanction.stat] ?? 0) + sanction.delta);
    upsertChar(gid, id, { [sanction.stat]: now });
    lines.push(`⚖️ ${sanctionLabel(sanction)} — now **${now}**.`);
  }
}
// The outcome trimmings a card carries — keyed by its message, pruned weekly.
function saveDcCard(gid, msgId, o) {
  try {
    db.prepare('DELETE FROM dc_cards WHERE created_at < ?').run(Date.now() - 7 * 86400_000);
    db.prepare(`INSERT OR REPLACE INTO dc_cards (guild_id, message_id, s_flavour, f_flavour, s_sanction, f_sanction, created_at)
                VALUES (?,?,?,?,?,?,?)`).run(gid, msgId, o.sF ?? null, o.fF ?? null, o.sS ?? null, o.fS ?? null, Date.now());
  } catch { /* trimmings only */ }
}
function getDcCard(gid, msgId) {
  try { return db.prepare('SELECT * FROM dc_cards WHERE guild_id=? AND message_id=?').get(gid, msgId) || null; }
  catch { return null; }
}

// A mark landing on whoever rolled. flat rides the fooled flag (fight-scoped,
// NPCs included — the autopilot honours it); adv/dis ride advNext/disNext,
// consumed by the player's next attack, grapple, feint, insight, defence or
// check press. NPC autopilot rolls its own weather, so adv/dis on an NPC is
// an honest note rather than a silent nothing.
function applyDcMark({ gid, cid, id, isNpc, mark, lines }) {
  if (!mark) return;
  const f = getFight(gid, cid);
  const inFight = f?.state === 'active' && fightOrder(f).includes(id);
  if (mark === 'flat') {
    if (inFight) { setEffectFlag(gid, cid, id, 'fooled'); lines.push('🎭 Their next fight action rolls **flat**.'); }
    else lines.push('_🎭 (no live fight here — the flat mark has nowhere to land)_');
    return;
  }
  if (isNpc) { lines.push(`_${mark === 'adv' ? '🔼' : '🔽'} (marks steer player rolls — the NPC autopilot rolls its own weather)_`); return; }
  upsertChar(gid, id, { next_mark: mark });
  lines.push(mark === 'adv'
    ? '🔼 Their next roll — **anywhere, fight or free RP** — is at **advantage**.'
    : '🔽 Their next roll — **anywhere, fight or free RP** — is at **disadvantage**.');
}

// The fail consequences: a flat-next-action mark when a fight is live here,
// and HP damage that the sheet-and-fight plumbing keeps in sync.
function applyDcOutcome({ gid, cid, id, isNpc, mark, damage, lines }) {
  applyDcMark({ gid, cid, id, isNpc, mark, lines });
  if (damage) {
    if (isNpc) {
      const npc = getNpc(gid, npcNameFromFighter(id));
      if (npc) { const hp = Math.max(0, (npc.hp_current ?? 0) - damage); upsertNpc(gid, npc.name, { hp_current: hp });
        lines.push(`💥 **-${damage} HP** — now **${hp}**${hp === 0 ? ' — at zero' : ''}.`); }
    } else {
      const ch = getChar(gid, id);
      if (ch) { const hp = Math.max(0, (ch.hp_current ?? 0) - damage); upsertChar(gid, id, { hp_current: hp });
        lines.push(`💥 **-${damage} HP** — now **${hp}**${hp === 0 ? ' — at zero' : ''}.`); }
    }
  }
}

// The writing window. Nothing may await before it opens — a deferred
// interaction cannot show a modal, and the GM check can be slow on a big
// server — so the gate moves to the submit, exactly as /gm scroll does.
// What the command picked waits in dc_drafts under this interaction's id.
function showDcForm(interaction) {
  const gid = interaction.guild.id;
  const one = interaction.options.getUser('target');
  const ids = [...new Set([...(one ? [one.id] : []), ...parsePlayerMentions(interaction.options.getString('targets') || '')])];
  const npcs = (interaction.options.getString('npcs') || '').split(',').map(x => x.trim()).filter(Boolean);
  const reveal = interaction.options.getString('reveal') || '';
  try {
    db.prepare('DELETE FROM dc_drafts WHERE created_at < ?').run(Date.now() - 86400_000);
    db.prepare('INSERT OR REPLACE INTO dc_drafts (guild_id, token, ids, npcs, reveal, created_at) VALUES (?,?,?,?,?,?)')
      .run(gid, interaction.id, ids.join(','), npcs.join(','), reveal, Date.now());
  } catch { /* the form still works — the targets box carries them */ }
  const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
  const modal = new ModalBuilder().setCustomId(`dcform:${interaction.id}`).setTitle('Call a check');
  const T = (id, label, style, placeholder, max, required = false) =>
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId(id).setLabel(label)
      .setStyle(style).setRequired(required).setMaxLength(max).setPlaceholder(placeholder));
  modal.addComponents(
    T('scene', 'The scene — shown on the card', TextInputStyle.Paragraph,
      'What they face. Left blank, the card is just the check.', 900),
    T('check', 'The check — e.g. dex 14 hidden', TextInputStyle.Short,
      'stat or dice, then the DC · add: hidden · bare · adv · dis · -2', 60, true),
    T('success', 'On success — tags, then the words', TextInputStyle.Paragraph,
      '[adv] or [lck+1] or [-2hp] on line one — then what they read', 900),
    T('fail', 'On failure — tags, then the words', TextInputStyle.Paragraph,
      '[dis] [dex-1] [-3hp] — same shape, and the words they dread', 900),
    T('targets', 'Targets — @players and/or NPCs', TextInputStyle.Short,
      'blank keeps the ones you picked · @Ari @Bo Orc, Goblin', 200),
  );
  return interaction.showModal(modal);
}

// The form comes back: read it, gate it, and post the very same card the
// options path posts — one machine, two doors.
async function handleDcFormSubmit(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id))) {
    return interaction.reply({ content: '❌ Only GMs call checks.', ephemeral: true });
  }
  const token = interaction.customId.split(':')[1];
  let draft = null;
  try { draft = db.prepare('SELECT * FROM dc_drafts WHERE guild_id=? AND token=?').get(gid, token) || null; } catch {}
  try { db.prepare('DELETE FROM dc_drafts WHERE guild_id=? AND token=?').run(gid, token); } catch {}

  const line = parseDcLine(interaction.fields.getTextInputValue('check'));
  if (!line) {
    return interaction.reply({ ephemeral: true, content: '❌ The check line needs a difficulty — something like `dex 14`, or `2d6+1 8 hidden`. Nothing was posted; call it again and the window reopens.' });
  }
  const succ = parseOutcomeBlock(interaction.fields.getTextInputValue('success'));
  const fail = parseOutcomeBlock(interaction.fields.getTextInputValue('fail'));
  const typed = interaction.fields.getTextInputValue('targets') || '';
  const typedIds = parsePlayerMentions(typed);
  const typedNpcs = typed.replace(/<@!?\d+>/g, '').split(/[\s,]+/).map(x => x.trim()).filter(Boolean);
  const ids = [...new Set([...(draft?.ids ? draft.ids.split(',').filter(Boolean) : []), ...typedIds])];
  const npcNames = [...new Set([...(draft?.npcs ? draft.npcs.split(',').filter(Boolean) : []), ...typedNpcs])];
  if (!ids.length && !npcNames.length) {
    return interaction.reply({ ephemeral: true, content: '❌ Nobody was named — pick targets on the command, or name them in the form\'s last box.' });
  }
  if (ids.length > 25) return interaction.reply({ content: '❌ Twenty-five player targets is the most one check can carry.', ephemeral: true });

  return postDcCheck(interaction, {
    stat: line.stat, notation: line.notation, dc: line.dc, gmMode: line.mode, flat: line.flat,
    modifier: line.modifier, secret: line.secret,
    revealSet: new Set(parsePlayerMentions(draft?.reveal || '')),
    onFail: fail.mark, onSucc: succ.mark, damage: fail.damage, sDamage: succ.damage,
    flavour: interaction.fields.getTextInputValue('scene') || null,
    sF: succ.narration, fF: fail.narration, sS: succ.sanction, fS: fail.sanction,
    ids, npcNames,
  });
}

async function runGmDcCheck(interaction) {
  // Bare of a difficulty, this is a writing window — nothing may await first.
  if (interaction.options.getInteger('dc') === null) return showDcForm(interaction);
  if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ Only GMs call checks.', ephemeral: true });
  const stat = interaction.options.getString('stat');
  const notation = (interaction.options.getString('dice') || '').trim() || null;
  if (notation && (notation.length > 12 || !parseNotation(notation))) {
    return interaction.reply({ content: '❌ `dice:` needs plain notation up to 12 characters, e.g. `2d6+1`.', ephemeral: true });
  }
  const dc = interaction.options.getInteger('dc');
  const modeRaw = interaction.options.getString('mode') || 'normal';
  const flat = modeRaw === 'flat';                 // 🎲 Bare d20 lives in mode: now
  const gmMode = flat ? 'normal' : modeRaw;
  const modifier = interaction.options.getInteger('modifier') ?? 0;
  const secret = interaction.options.getBoolean('secret') ?? false;
  const revealSet = new Set(parsePlayerMentions(interaction.options.getString('reveal') || ''));
  const onFail = interaction.options.getString('on_fail') || '';
  const onSucc = interaction.options.getString('on_success') || '';
  const damage = interaction.options.getInteger('fail_damage') ?? 0;
  const sDamage = interaction.options.getInteger('success_damage') ?? 0;
  const flavour = interaction.options.getString('flavour');
  const sF = interaction.options.getString('success_flavour');
  const fF = interaction.options.getString('fail_flavour');
  const sSRaw = interaction.options.getString('success_sanction');
  const fSRaw = interaction.options.getString('fail_sanction');
  const sS = parseSanction(sSRaw), fS = parseSanction(fSRaw);
  if (sSRaw && !sS) return interaction.reply({ content: '❌ `success_sanction:` reads like `lck+1` — a stat and a signed step, ±5 at most.', ephemeral: true });
  if (fSRaw && !fS) return interaction.reply({ content: '❌ `fail_sanction:` reads like `dex-1` — a stat and a signed step, ±5 at most.', ephemeral: true });
  const one = interaction.options.getUser('target');
  const ids = [...new Set([...(one ? [one.id] : []), ...parsePlayerMentions(interaction.options.getString('targets') || '')])];
  const npcNames = (interaction.options.getString('npcs') || '').split(',').map(x => x.trim()).filter(Boolean);
  if (!ids.length && !npcNames.length) return interaction.reply({ content: '❌ Name at least one target — `target:`, `targets:@a @b`, or `npcs:Orc, Goblin`.', ephemeral: true });
  if (ids.length > 25) return interaction.reply({ content: '❌ Twenty-five player targets is the most one check can carry.', ephemeral: true });

  return postDcCheck(interaction, { stat, notation, dc, gmMode, flat, modifier, secret, revealSet,
    onFail, onSucc, damage, sDamage, flavour, sF, fF, sS, fS, ids, npcNames });
}

// The card itself — reached from the options path and from the form alike.
async function postDcCheck(interaction, { stat, notation, dc, gmMode, flat, modifier, secret, revealSet,
                                          onFail, onSucc, damage, sDamage = 0, flavour, sF, fF, sS, fS, ids, npcNames }) {
  const gid = interaction.guild.id, cid = interactionChannelId(interaction);
  const face = notation ?? (stat ? STAT_LABELS[stat] : 'flat d20');
  const terms = [];
  if (gmMode === 'adv') terms.push('🔼 advantage');
  if (gmMode === 'dis') terms.push('🔽 disadvantage');
  if (flat && !notation && stat) terms.push('🎲 flat d20 — no stat bonus');
  if (modifier) terms.push(`${modifier > 0 ? '+' : ''}${modifier} to the total`);
  const markWord = { flat: '🎭 next fight action flat', adv: '🔼 next roll at advantage', dis: '🔽 next roll at disadvantage' };
  if (onFail) terms.push(`fail: ${markWord[onFail]}`);
  if (onSucc) terms.push(`success: ${markWord[onSucc]}`);
  if (damage) terms.push(`💥 fail: -${damage} HP`);
  if (sDamage) terms.push(`💥 success: -${sDamage} HP`);
  if (sS) terms.push(`⚖️ success: ${sanctionLabel(sS)}`);
  if (fS) terms.push(`⚖️ fail: ${sanctionLabel(fS)}`);
  const lines = [`🎯 **${stat && !notation ? STAT_LABELS[stat] + ' check' : face + ' check'} — DC ${secret ? '???' : dc}**`];
  if (ids.length) lines.push(`${ids.map(id => `<@${id}>`).join(' ')} — press your name to roll.`);
  if (terms.length) lines.push(`_${terms.join(' · ')}_`);
  if (flavour) lines.push('', flavour);

  // NPCs never press — they roll right here, in the open.
  for (const name of npcNames.slice(0, 10)) {
    const npc = getNpc(gid, name);
    if (!npc) { lines.push('', `❌ No NPC named **${name}**.`); continue; }
    const r = rollDcCheck({ stat, notation, dc, gmMode, flat, modifier, subject: npc, sig: npc });
    if (!r) continue;
    mirrorAutoRoll(gid, cid, npc.name, `${notation ?? '1d20'}${r.mode !== 'normal' ? ` (${r.mode})` : ''}`, r.nat, r.total, `GM check vs DC ${dc}`);
    lines.push('', `🎭 **${npc.name}** — ${r.rollLine}`, secret ? r.band : `${r.band} vs DC ${dc}`);
    const oFlav = r.passed ? sF : fF;
    if (oFlav) lines.push(`_${oFlav}_`);
    applyDcSanction({ gid, id: npcFighterId(npc.name), isNpc: true, sanction: r.passed ? sS : fS, lines });
    applyDcOutcome({ gid, cid, id: npcFighterId(npc.name), isNpc: true,
      mark: r.passed ? onSucc : onFail, damage: r.passed ? sDamage : damage, lines });
  }

  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  const buttons = [];
  const field = notation ?? (stat ?? 'x');
  for (const uid of ids) {
    const nm = await getDisplayName(interaction.guild, uid);
    const secCode = !secret ? 0 : revealSet.has(uid) ? 2 : 1;
    buttons.push(new ButtonBuilder().setCustomId(`dcroll:${uid}:${field}:${dc}:${gmMode}:${flat ? 1 : 0}:${modifier}:${secCode}:${onFail || '-'}:${damage}:${onSucc || '-'}:${sDamage}`)
      .setLabel(`🎲 ${nm.slice(0, 70)}`).setStyle(ButtonStyle.Primary));
  }
  const rows = [];
  for (let i = 0; i < buttons.length; i += 5) rows.push(new ActionRowBuilder().addComponents(...buttons.slice(i, i + 5)));

  await interaction.reply({ content: lines.join('\n'), components: rows,
    allowedMentions: { users: ids } });
  bookLog(gid, 'checks', [`🎯 **Check called** by <@${interaction.user.id}> in <#${cid}>`,
    `${face} vs DC ${dc}${secret ? ' (secret)' : ''}${terms.length ? ` · ${terms.join(' · ')}` : ''}`,
    ids.length ? `👥 ${ids.map(id => `<@${id}>`).join(' ')}` : '',
    npcNames.length ? `🎭 ${npcNames.join(', ')}` : ''].filter(Boolean).join('\n'));
  if (ids.length && (sF || fF || sS || fS)) {
    try { const rep = await interaction.fetchReply();
      saveDcCard(gid, rep.id, { sF, fF, sS: sS ? `${sS.stat}${sS.delta > 0 ? '+' : ''}${sS.delta}` : null,
                                        fS: fS ? `${fS.stat}${fS.delta > 0 ? '+' : ''}${fS.delta}` : null });
    } catch { /* trimmings only */ }
  }
  if (secret) await interaction.followUp({ ephemeral: true, content: `🤫 The DC is **${dc}**.` }).catch(() => {});
  return;
}
// A pressed check: rolls that player's own dice under the called conditions,
// mirrors to the audit, and darkens their button so nobody rolls twice.
async function runDcRollPress(interaction) {
  const gid = interaction.guild.id, cid = interactionChannelId(interaction);
  const [, uid, field, dcS, gmMode, flatS, modS, secS, onFailRaw, dmgS, onSuccRaw, sDmgS] = interaction.customId.split(':');
  if (interaction.user.id !== uid) return interaction.reply({ content: '🎯 That button belongs to someone else — yours has your name on it.', ephemeral: true });
  const dc = parseInt(dcS), flat = flatS === '1', modifier = parseInt(modS) || 0;
  const secret = secS !== '0', whisper = secS === '2', onFail = onFailRaw === '-' ? '' : (onFailRaw || ''), damage = parseInt(dmgS) || 0;
  const onSucc = onSuccRaw === '-' ? '' : (onSuccRaw || '');
  const sDmg = parseInt(sDmgS) || 0;
  const notation = field.includes('d') ? field : null;
  const stat = notation ? null : (field === 'x' ? null : field);
  const gate = sheetGate(gid, uid);
  if (gate && !(await isGm(interaction.guild, uid))) return interaction.reply({ content: gate, ephemeral: true });
  const ch = getChar(gid, uid);
  if (!ch) return interaction.reply({ content: '❌ You need a character sheet — `/char create`.', ephemeral: true });

  const markedMode = applyNextMark(gid, uid, gmMode);
  const r = rollDcCheck({ stat, notation, dc, gmMode: markedMode, flat, modifier, subject: ch, sig: ch });
  if (!r) return interaction.reply({ content: '❌ That check\'s notation no longer reads.', ephemeral: true });
  const { nat, total, passed, band, rollLine, result } = r;
  const faceLabel = notation ?? (stat ? STAT_LABELS[stat] : 'flat d20');
  recordRoll(gid, { userId: uid, channelId: cid, interaction, result,
    input: '/gm dc', rollLine, context: `GM check (${faceLabel} vs DC ${dc}${flat ? ', flat' : ''}${secret ? ', secret' : ''})` });

  // Darken the pressed button; everything else stays live.
  const { ActionRowBuilder, ButtonBuilder } = require('discord.js');
  const rebuilt = interaction.message.components.map(row => new ActionRowBuilder().addComponents(
    ...row.components.map(c => new ButtonBuilder().setCustomId(c.customId).setLabel(c.label)
      .setStyle(c.style).setDisabled(c.disabled || c.customId === interaction.customId))));
  await interaction.update({ components: rebuilt });
  const nm = await getDisplayName(interaction.guild, uid);
  const out = [`🎯 **${nm}** — ${faceLabel} vs **DC ${secret ? '???' : dc}**`, rollLine, band];
  const card = getDcCard(gid, interaction.message?.id);
  const oFlav = card ? (passed ? card.s_flavour : card.f_flavour) : null;
  if (oFlav) out.push(`_${oFlav}_`);
  applyDcSanction({ gid, id: uid, isNpc: false,
    sanction: parseSanction(card ? (passed ? card.s_sanction : card.f_sanction) : null), lines: out });
  applyDcOutcome({ gid, cid, id: uid, isNpc: false,
    mark: passed ? onSucc : onFail, damage: passed ? sDmg : damage, lines: out });
  await interaction.followUp({ content: out.join('\n') });
  bookLog(gid, 'checks', `🎯 <@${uid}> — ${faceLabel} vs DC ${secret ? '???' : dc} — ${band.replace(/\*\*/g, '')}`
    + (out.length > 3 ? `\n${out.slice(3).join(' · ').replace(/\*\*/g, '')}` : ''), { channelId: cid });
  if (whisper) await interaction.followUp({ ephemeral: true,
    content: `🤫 Your eyes catch what others miss — the DC is **${dc}**. You ${passed ? 'cleared' : 'missed'} it by **${Math.abs(total - dc)}**.` }).catch(() => {});
  return;
}

// The slash twin of the gmr / gmrs chat shorthands — same roll, same audit
// mirror; ‘secret’ lands as an ephemeral reply instead of a DM.
async function runGmRollSlash(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can use GM rolls.', ephemeral: true });
  const notation = interaction.options.getString('notation');
  const label = interaction.options.getString('label');
  const flavour = interaction.options.getString('flavour');
  const secret = interaction.options.getBoolean('secret') ?? false;
  const mode = interaction.options.getString('roll') || 'normal';
  const result = mode === 'adv' ? rollAdvantage(notation) : mode === 'dis' ? rollDisadvantage(notation) : rollNotation(notation);
  if (!result) return interaction.reply({ content: '❌ Invalid notation. Try `/gm roll notation:1d20+5 label:perception`.', ephemeral: true });
  const critType = detectCrit(result, mode);
  const rollLine = buildRollLine(result, mode, critType);
  const lc = critPrefix(critType);
  const lines = [];
  if (label) lines.push(`${lc}**${label}**`);
  lines.push(rollLine);
  if (flavour) {
    lines.push('', '─────────────────────────────');
    lines.push(`**${label ?? 'roll'}** — ${totalStr(result.total, critType)}`);
    lines.push(`*${flavour}*`);
  }
  const content = lines.join('\n');
  mirrorRoll(gid, {
    userId: uid, channelId: interactionChannelId(interaction), messageId: null,
    input: `/gm roll ${notation}${label ? ' ' + label : ''}${secret ? ' 🔒' : ''}`, rollLine,
    context: secret ? 'GM roll · 🔒 secret' : 'GM roll',
  });
  if (secret) return interaction.reply({ content: `🔒 **Secret GM Roll**\n${content}`, ephemeral: true });
  return interaction.reply({ content });
}

// /gm check — the setup mirror. Unset first (with the command that sets each),
// then the set ones with links, every stored id fetch-verified.
async function handleCheck(interaction) {
  // `run:true` builds whatever the code knows about and this server hasn't
  // got yet — the one switch to pull after an update adds a book.
  if (interaction.options?.getBoolean?.('run')) return runSetupRepair(interaction);
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id))) return interaction.reply({ content: '❌ The setup check is for GMs.', ephemeral: true });
  await interaction.deferReply({ ephemeral: true });
  const cfg = getConfig(gid) || {};
  const routes = (k) => { try { return JSON.parse(cfg[k] || '{}'); } catch { return {}; } };
  const auditR = routes('audit_routes');
  const apprR = routes('approval_routes');
  const planBooks = routes('quest_plan_books');
  const checks = [
    ['📌 Quest board forum', cfg.quest_forum, '`/config channels questforum channel:#forum`', null, 'questforum'],
    ['🗺️ GM quest planning forum', cfg.quest_plan_forum, '`/config channels questplanning channel:#gm-forum`',
      Object.keys(planBooks).length ? `${Object.keys(planBooks).length} books` : null, 'questplanning'],
    ['⚔️ Quest instance forum', cfg.quest_instance_forum, '`/config channels questinstances channel:#` (optional — a room per running party)',
      null, 'questinstances'],
    ['🧵 Quest threads forum', cfg.quest_thread_forum, '`/config channels questthreads channel:#` (optional — threads default into the planning forum)',
      cfg.quest_thread_forum ? 'per-quest threads + stage tags' : null, 'questthreads'],
    ['📜 Roll audit', auditR.forum ?? cfg.roll_audit_channel_id,
      '`/config channels rollauditforum forum:#forum` (books) · or `/config channels rollaudit channel:#`',
      auditR.forum ? 'books' : (cfg.roll_audit_channel_id ? 'single channel' : null), 'rollaudit'],
    ['📖 Character pages forum', cfg.char_forum, '`/config channels charforum channel:#forum`', null, 'charforum'],
    ['⚖️ Approvals', apprR.forum ?? cfg.approval_channel_id,
      '`/config channels approvalforum forum:#forum` · or `/config channels approvals channel:#`',
      apprR.forum ? 'threads per type' : (cfg.approval_channel_id ? 'single channel' : null), 'approvals'],
    ['🪶 Memorial — GM record', cfg.memorial_channel, '`/config channels memorial channel:#`', null, 'memorial'],
    ['🕯️ Memorial — public hall', cfg.memorial_public_channel, '`/config channels memorial public:#`', null],
    ['📜 Quest log', cfg.quest_log_channel, '`/config channels questlog channel:#`', null, 'questlog'],
    ['🖼️ NPC image bank', cfg.npc_channel_id, '`/config channels npcchannel channel:#`', null, 'npcchannel'],
    ['📚 GM docs (the PDFs)', cfg.docs_channel, '`/config channels docs channel:# repo:owner/name`', null],
    ['📜 Scroll library', cfg.scroll_archive_id, '`/config channels scrollarchive channel:#` — a forum gives per-GM threads', null, 'scrollarchive'],
    ['💾 Backups', cfg.backup_channel_id, '`/gm backup auto channel:#`', null],
  ];
  const unset = [], set = [];
  for (const [label, id, cmd, note] of checks) {
    if (!id) { unset.push(`• ${label} — ${cmd}`); continue; }
    let ok = false;
    try { const ch = await interaction.client.channels.fetch(id); ok = !!ch; } catch { /* gone or hidden */ }
    if (ok) set.push(`• ${label} — <#${id}>${note ? ` · ${note}` : ''}`);
    else set.push(`⚠️ ${label} — set but unreachable (deleted, or hidden from me) — re-run ${cmd}`);
  }
  const lines = ['🧭 **Channel & forum check**', ''];
  if (unset.length) { lines.push(`❌ **Not set** (${unset.length})`, ...unset, ''); }
  else lines.push('✅ Everything channel-backed is configured.', '');
  if (set.length) { lines.push(`✅ **Set** (${set.length})`, ...set); }
  await interaction.editReply({ content: lines.join('\n').slice(0, 2000) });
  // Up to five pickers for the unset channel configs — a pick runs the real
  // config branch, tags, books, threads and all. Forum configs filter to forums.
  try {
    const FORUMS = new Set(['charforum', 'questforum', 'questplanning', 'questthreads', 'rollauditforum', 'approvalforum']);
    const missing = checks.filter(r => !r[1] && r[4]).slice(0, 5);
    if (missing.length) {
      const { ActionRowBuilder, ChannelSelectMenuBuilder, ChannelType } = require('discord.js');
      const selects = missing.map(r => new ActionRowBuilder().addComponents(
        new ChannelSelectMenuBuilder().setCustomId(`checkset:${r[4]}`)
          .setPlaceholder(`${r[0].replace(/^\S+\s/, '').slice(0, 60)} — pick a ${FORUMS.has(r[4]) ? 'forum' : 'channel'}`)
          .setChannelTypes(r[4] === 'scrollarchive' ? [ChannelType.GuildText, ChannelType.GuildForum]
            : FORUMS.has(r[4]) ? [ChannelType.GuildForum] : [ChannelType.GuildText])));
      await interaction.followUp({ ephemeral: true, components: selects,
        content: `🔧 **Quick setup** — pick a channel to run each config right here${checks.filter(r => !r[1] && r[4]).length > 5 ? ' (more appear once these are set)' : ''}:` });
    }
  } catch (err) { console.error('[check] selects failed -', err?.message || err); }
  return;
}

async function handleGmRoll(message, rest, secret) {
  const gid = message.guild.id, uid = message.author.id;
  if (!(await isGm(message.guild, uid))) return message.reply('❌ Only GMs can use GM rolls.');
  const parsed = parseRollInput(rest, null);
  if (!parsed) return message.reply('❌ Invalid notation. Try `gmr 1d20+5 perception`.');
  const result = rollNotation(parsed.notation);
  if (!result) return message.reply('❌ Could not parse dice notation.');
  const critType = detectCrit(result, 'normal');
  const rollLine = buildRollLine(result, 'normal', critType);
  const lc = critPrefix(critType);
  const lines = [];
  if (parsed.label) lines.push(`${lc}**${parsed.label}**`);
  lines.push(rollLine);
  if (parsed.flavour) {
    lines.push('', '─────────────────────────────');
    lines.push(`**${parsed.label??'roll'}** — ${totalStr(result.total, critType)}`);
    lines.push(`*${parsed.flavour}*`);
  }
  const content = lines.join('\n');

  // Mirror GM rolls to the audit channel too — including secret ones, so other
  // GMs can see them. Secret rolls stay hidden from players (DM + private
  // audit channel); only the audit copy is marked so it's clear it was secret.
  mirrorRoll(gid, {
    userId: uid, channelId: message.channel.id, messageId: message.id,
    input: message.content, rollLine,
    context: secret ? 'GM roll · 🔒 secret' : 'GM roll',
  });

  if (secret) {
    try {
      await message.author.send(`🔒 **Secret GM Roll**\n${content}`);
      await message.reply('🔒 Roll sent to your DMs.');
    } catch { await message.reply('❌ Could not DM you. Check your privacy settings.'); }
  } else {
    await message.reply(content);
  }
}


function parseSheetImport(text) {
  // Strip code block markers
  const clean = text.replace(/```/g, '').trim();
  if (!clean.includes('[TTRPG SHEET]')) return null;

  const lines = clean.split('\n');
  const data = {};
  lines.forEach(line => {
    const [key, ...rest] = line.split(':');
    if (key && rest.length) data[key.trim()] = rest.join(':').trim();
  });

  // Validate required fields
  const required = ['STR','CON','DEX','WIS','LCK'];
  for (const f of required) {
    if (data[f] === undefined || isNaN(parseInt(data[f]))) return null;
  }

  return {
    order_name: data['ORDER'] || null,
    class: data['CLASS'] || null,
    str: parseInt(data['STR']),
    con: parseInt(data['CON']),
    dex: parseInt(data['DEX']),
    wis: parseInt(data['WIS']),
    lck: parseInt(data['LCK']),
    hp_current: data['HP'] ? parseInt(data['HP']) : null,
    rerolls_current: data['REROLLS'] ? parseInt(data['REROLLS']) : null,
    weapon1: data['WEAPON1'] || null,
    weapon1emoji: data['WEAPON1EMOJI'] || null,
    weapon2: data['WEAPON2'] || null,
    weapon2emoji: data['WEAPON2EMOJI'] || null,
  };
}

async function handleSheetImport(message, parsed) {
  // Sheets arrive from any channel the bot can read — text, thread, forum post,
  // or the text chat inside a voice or stage channel. Only a DM has no guild.
  if (!message.guild) return message.reply('❌ Import a sheet in a server channel, not a DM — I need to know which server it belongs to.').catch(()=>{});
  const gid = message.guild.id, uid = message.author.id;

  // Check if GM is importing for someone else via mention
  const mentionMatch = message.content.match(/<@!?(\d+)>/);
  let targetId = uid;
  if (mentionMatch && mentionMatch[1] !== uid) {
    if (!(await isGm(message.guild, uid))) return message.reply('\u274c Only GMs can import sheets for other players.');
    targetId = mentionMatch[1];
  }

  // Pasting a sheet rewrites everything — respect the approval lock, and send it
  // back to the queue afterwards, so it can't be used to sidestep a GM.
  const isGmImporter = await isGm(message.guild, uid);
  // A pasted sheet is a whole character, so both rules apply in full.
  if (!isGmImporter) {
    const problems = sheetSubmissionProblems(gid, { ...(getChar(gid, targetId) || {}), ...parsed });
    if (problems.length) return refuseStatBudget({ src: message, gid, uid, problems, stats: parsed,
      jumpId: message.id, reply: async (c) => message.reply(c).catch(() => null) });
  }
  {
    const lock = sheetEditLock(gid, uid, targetId, isGmImporter);
    if (lock) return message.reply(lock);
  }

  const KNIGHTS = ['White Knight','Black Knight','Gold Knight','Grey Knight','Blue Knight','Purple Knight','Green Knight','Red Knight'];

  // Validate order
  if (parsed.order_name && !KNIGHTS.includes(parsed.order_name)) {
    parsed.order_name = null;
  }

  // Apply stats — derive HP max and reroll max from CON and LCK
  const hpMax = maxHpFromCon(gid, parsed.con);
  const rerollMax = parsed.lck;

  // Use imported current values if valid, otherwise max out
  // A brand-new character always starts at full. Only a re-import over an
  // existing sheet keeps the pasted figures — that's a restore, not a creation,
  // and an exported block carries whatever HP the character happened to be on.
  const isNewSheet = !getChar(gid, targetId);
  const hpCurrent = (!isNewSheet && parsed.hp_current !== null && parsed.hp_current <= hpMax)
    ? parsed.hp_current : hpMax;
  const rerollsCurrent = (!isNewSheet && parsed.rerolls_current !== null && parsed.rerolls_current <= rerollMax)
    ? parsed.rerolls_current : rerollMax;

  upsertChar(gid, targetId, {
    order_name: parsed.order_name,
    class: parsed.class || null,
    str: parsed.str, con: parsed.con, dex: parsed.dex,
    wis: parsed.wis, lck: parsed.lck,
    hp_current: hpCurrent,
    rerolls_current: rerollsCurrent,
    weapon1: parsed.weapon1 || null,
    weapon1emoji: validateWeaponEmoji(message.guild, parsed.weapon1emoji) || '⚔️',
    weapon2: parsed.weapon2 || null,
    weapon2emoji: validateWeaponEmoji(message.guild, parsed.weapon2emoji) || '🗡️',
    // An exported sheet carries the emoji the character already had, so a
    // paste counts as a choice — otherwise a re-import would un-finish a sheet.
    ...(parsed.weapon1emoji ? { weapon1emoji_set: 1 } : {}),
    ...(parsed.weapon2emoji ? { weapon2emoji_set: 1 } : {}),
  });

  // Handle heal charges for White Knight
  const updatedChar = getChar(gid, targetId);
  if (isWhiteKnight(updatedChar)) {
    const cfg = getConfig(gid);
    setHealCharges(gid, targetId, cfg.heal_charges ?? 3);
  } else {
    setHealCharges(gid, targetId, 0);
  }

  const targetName = targetId === uid ? 'Your' : `<@${targetId}>'s`;
  const orderLine = parsed.order_name ? `${KNIGHT_EMOJIS[parsed.order_name]??'⚪'} ${parsed.order_name}` : 'No order';
  const lines = [
    `\u2705 ${targetName} character sheet imported.`,
    orderLine,
    `\u2764\ufe0f HP: **${hpCurrent} / ${hpMax}**`,
    `\U0001f504 Rerolls: **${rerollsCurrent} / ${rerollMax}**`,
    '',
    `\U0001f4aa STR ${parsed.str}  \U0001fac0 CON ${parsed.con}  \u26a1 DEX ${parsed.dex}  \U0001f9e0 WIS ${parsed.wis}  \U0001f340 LCK ${parsed.lck}`,
  ];
  await finishSheetEdit({
    src: message, gid, callerId: uid, targetId, isGmCaller: isGmImporter,
    content: lines.join('\n'),
    reply: async (c) => message.reply(c).catch(() => null),
  });
}

async function handleTag(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const sub = interaction.options.getSubcommand();

  // All tag commands are GM only
  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can manage tags.', ephemeral: true });

  if (sub === 'assign') {
    const targetUser = interaction.options.getUser('user');
    const tagName = interaction.options.getString('tag');
    const available = getAllAvailableTags(gid);
    if (!available.includes(tagName))
      return interaction.reply({ content: `❌ Unknown tag. Available: ${available.join(', ')}`, ephemeral: true });
    assignTag(gid, targetUser.id, tagName);
    const emoji = resolveTagEmoji(gid, tagName);
    return interaction.reply({ content: `${emoji} **${tagName}** assigned to <@${targetUser.id}>.` });
  }

  if (sub === 'remove') {
    const targetUser = interaction.options.getUser('user');
    const tagName = interaction.options.getString('tag');
    removeTag(gid, targetUser.id, tagName);
    return interaction.reply({ content: `✅ **${tagName}** removed from <@${targetUser.id}>.` });
  }

  if (sub === 'list') {
    const targetUser = interaction.options.getUser('user') || interaction.user;
    const tags = getPlayerTags(gid, targetUser.id);
    if (!tags.length) return interaction.reply({ content: `<@${targetUser.id}> has no tags assigned.`, ephemeral: true });
    const lines = tags.map(t => `${resolveTagEmoji(gid, t)}  ${t}`);
    return interaction.reply({ content: `**Tags for <@${targetUser.id}>:**\n${lines.join('\n')}`, ephemeral: true });
  }

  if (sub === 'custom') {
    const action = interaction.options.getString('action');

    if (action === 'create') {
      const emoji = interaction.options.getString('emoji');
      const name = interaction.options.getString('name');
      if (!emoji || !name) return interaction.reply({ content: '❌ Please provide both an emoji and a name.', ephemeral: true });

      // Validate emoji format
      const isUnicodeEmoji = /^\p{Emoji}/u.test(emoji);
      const isCustomEmoji = /^<a?:[a-zA-Z0-9_]+:\d+>$/.test(emoji);
      const looksLikeName = /^:[a-zA-Z0-9_]+:$/.test(emoji);

      if (looksLikeName) {
        return interaction.reply({
          content: `❌ **${emoji}** looks like an emoji name, not the emoji itself.\n\nTo get the correct format:\n1. Type \`\\${emoji}\` in any channel and send it\n2. Discord will show the full ID like \`<:name:123456789>\`\n3. Copy that and use it as the emoji`,
          ephemeral: true
        });
      }

      if (!isUnicodeEmoji && !isCustomEmoji) {
        return interaction.reply({
          content: `❌ Invalid emoji format. Use either:\n• A standard emoji: \`⚔️\`\n• A server emoji ID: \`<:emojiname:123456789012345678>\`\n\nTo get a server emoji ID, type \`\\:emojiname:\` in chat and copy the result.`,
          ephemeral: true
        });
      }

      addCustomTag(gid, name, emoji);
      return interaction.reply({ content: `${emoji} Custom tag **${name}** created.` });
    }

    if (action === 'delete') {
      const name = interaction.options.getString('name');
      if (!name) return interaction.reply({ content: '❌ Please provide the tag name to delete.', ephemeral: true });
      deleteCustomTag(gid, name);
      return interaction.reply({ content: `✅ Custom tag **${name}** deleted and removed from all players.` });
    }

    if (action === 'list') {
      const customs = getCustomTags(gid);
      const presets = Object.entries(PRESET_TAGS).map(([n,e]) => `${e}  ${n} *(preset)*`);
      const customLines = customs.map(t => `${t.emoji}  ${t.tag_name}`);
      const all = [...presets, ...customLines];
      if (!all.length) return interaction.reply({ content: 'No tags defined for this server.', ephemeral: true });
      return interaction.reply({ content: `**Available Tags:**\n${all.join('\n')}`, ephemeral: true });
    }
  }
}

async function handleStat(interaction) {
  const lines = [
    '**Strength** (**STR**) – Physical power, melee combat.',
    '',
    '**Constitution** (**CON**) – Durability, health.',
    '',
    '**Dexterity** (**DEX**) – Agility, ranged/finesse combat.',
    '',
    '**Wisdom** (**WIS**) – Insight, tactical awareness.',
    '',
    '**Luck** (**LUCK**) – Fortune, chance-based effects.',
  ];
  return interaction.reply({ content: lines.join('\n'), ephemeral: false });
}

