// Help categories that document GM-only tooling. Players shouldn't be able to
// browse them — both the listing and the detail view are gated.
const GM_HELP_CATEGORIES = ['gm', 'npc'];

// /gm scroll: gate, then hand the GM a writing modal. All the real checks run
// again on submit — the modal can sit open for a while.
// Pure aggregation over raw tally rows, so the shape is testable without a
// database: totals per player, the guild's d20 spread, hot and cold hands.
function aggregateDiceHealth(rows, { minD20 = 20 } = {}) {
  const perUser = new Map(); // uid -> { total, d20c, d20s, n1, n20 }
  const spread = Object.fromEntries(Array.from({ length: 20 }, (_, i) => [i + 1, 0]));
  for (const r of rows) {
    const u = perUser.get(r.user_id) ?? { total: 0, d20c: 0, d20s: 0, n1: 0, n20: 0 };
    u.total += r.count;
    if (r.sides === 20) {
      u.d20c += r.count; u.d20s += r.nat * r.count;
      if (r.nat === 1) u.n1 += r.count;
      if (r.nat === 20) u.n20 += r.count;
      spread[r.nat] = (spread[r.nat] ?? 0) + r.count;
    }
    perUser.set(r.user_id, u);
  }
  const users = [...perUser.entries()].map(([uid, u]) => ({ uid, ...u, avg: u.d20c ? u.d20s / u.d20c : null }));
  const eligible = users.filter(u => u.d20c >= minD20);
  return {
    totalRolls: users.reduce((a, u) => a + u.total, 0),
    d20Total: users.reduce((a, u) => a + u.d20c, 0),
    topRollers: [...users].sort((a, b) => b.total - a.total).slice(0, 5),
    hot: [...eligible].sort((a, b) => b.avg - a.avg).slice(0, 3),
    cold: [...eligible].sort((a, b) => a.avg - b.avg).slice(0, 3),
    natLeaders: {
      n20: [...users].sort((a, b) => b.n20 - a.n20).filter(u => u.n20)[0] ?? null,
      n1: [...users].sort((a, b) => b.n1 - a.n1).filter(u => u.n1)[0] ?? null,
    },
    spread,
  };
}

async function handleDiceReport(interaction) {
  const gid = interaction.guild.id;
  await interaction.deferReply({ ephemeral: true });
  if (!(await isGm(interaction.guild, interaction.user.id))) {
    return interaction.editReply({ content: '❌ GMs only — the table\'s dice are their business.' });
  }
  const rows = db.prepare('SELECT user_id, sides, nat, count FROM roll_tally WHERE guild_id=?').all(gid);
  if (!rows.length) return interaction.editReply({ content: '🎲 No dice history yet — the report writes itself as they roll.' });
  const h = aggregateDiceHealth(rows);
  const nameOf = async (uid) => uid.startsWith('npc_') ? `🎭 ${uid.slice(4)}` : await getDisplayName(interaction.guild, uid).catch(() => uid);
  const lines = [`🎲 **Dice health** — ${h.totalRolls} rolls on record, ${h.d20Total} of them d20s`, ''];
  lines.push('**Top rollers**');
  for (const u of h.topRollers) lines.push(`• ${await nameOf(u.uid)} — ${u.total} rolls${u.d20c ? ` · d20 avg ${u.avg.toFixed(1)}` : ''}`);
  if (h.hot.length) {
    lines.push('', '**Hot and cold hands** _(min 20 d20s)_');
    for (const u of h.hot) lines.push(`🔥 ${await nameOf(u.uid)} — avg ${u.avg.toFixed(1)} over ${u.d20c}`);
    for (const u of h.cold) lines.push(`🧊 ${await nameOf(u.uid)} — avg ${u.avg.toFixed(1)} over ${u.d20c}`);
  }
  if (h.natLeaders.n20 || h.natLeaders.n1) {
    lines.push('');
    if (h.natLeaders.n20) lines.push(`👑 Most nat 20s: ${await nameOf(h.natLeaders.n20.uid)} ×${h.natLeaders.n20.n20}`);
    if (h.natLeaders.n1) lines.push(`💀 Most nat 1s: ${await nameOf(h.natLeaders.n1.uid)} ×${h.natLeaders.n1.n1}`);
  }
  const maxCount = Math.max(...Object.values(h.spread), 1);
  lines.push('', '**The d20 spread**');
  for (let n = 1; n <= 20; n++) {
    const c = h.spread[n] ?? 0;
    lines.push(`\`${String(n).padStart(2)}\` ${'█'.repeat(Math.max(c ? 1 : 0, Math.round((c / maxCount) * 18)))} ${c}`);
  }
  return replyLong(interaction, lines, { ephemeral: true });
}

async function handleScroll(interaction) {
  const gid = interaction.guild.id;
  // Nothing may await before the ack: Discord allows three seconds, and a
  // cold member fetch for the GM check can eat them on a big server — that
  // is exactly the generic "Something went wrong" banner. The write path
  // must answer with a modal (which a deferred interaction cannot show), so
  // the gate moves to the submit; the read path defers first and gates after.
  // The PDF is the whole system: the parchment posts as one, the writing
  // rides invisibly after its EOF, and handing the file back reads it out.
  const att = interaction.options.getAttachment('file');
  if (att) return handleScrollImport(interaction, gid, att);
  try { require('@napi-rs/canvas'); }
  catch { return interaction.reply({ content: '❌ Image generation unavailable — install `@napi-rs/canvas` to enable.', ephemeral: true }); }
  if (!ensureScrollFont(gid)) {
    return interaction.reply({ content: '📜 No scroll font is stored — an Admin sets one with `/config mechanics scrollfont font:<file>`.', ephemeral: true });
  }
  const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
  const modal = new ModalBuilder().setCustomId('scrollwrite').setTitle('Write the scroll');
  modal.addComponents(
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('title')
      .setLabel('Title (optional)').setStyle(TextInputStyle.Short).setRequired(false).setMaxLength(80)),
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('body')
      .setLabel('The writing itself').setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(1600)),
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('flavour')
      .setLabel('Scene line above the image (optional)').setStyle(TextInputStyle.Short).setRequired(false).setMaxLength(200)),
    new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('filename')
      .setLabel('File name for archiving (optional)').setStyle(TextInputStyle.Short).setRequired(false).setMaxLength(48)
      .setPlaceholder('e.g. kings-pact — becomes kings-pact.png / .pdf')),
  );
  return interaction.showModal(modal);
}

// Hand a woven scroll back: the writing comes out as plain text, and when
// this server has a font and the canvas, a fresh parchment follows — rendered
// in THIS server's face and re-woven, so the new image round-trips too.
async function handleScrollImport(interaction, gid, att) {
  await interaction.deferReply({ ephemeral: true });
  if (!(await isGm(interaction.guild, interaction.user.id))) {
    return interaction.editReply({ content: '❌ Only GMs can unfurl props.' });
  }
  if (!/\.(png|pdf)$/i.test(att.name || '')) {
    return interaction.editReply({ content: '❌ That isn\'t a .png or .pdf — hand me a file made by `/gm scroll`.' });
  }
  if ((att.size ?? 0) > 8_000_000) {
    return interaction.editReply({ content: '❌ That file is over 8 MB — not one of mine.' });
  }
  let bytes;
  try { bytes = await fetchBytes(att.url); }
  catch (err) {
    console.error('[scroll] import fetch failed -', err?.message || err);
    return interaction.editReply({ content: `❌ Couldn't read that attachment — ${err?.message || err}` });
  }
  const scroll = validateScrollData(extractScrollData(bytes));
  if (!scroll) {
    return interaction.editReply({ content:
      '❌ No writing survives in that file. A **PDF** made by `/gm scroll` always carries it — a PNG loses its weave the moment Discord re-uploads it, so only PDFs make the trip.' });
  }
  return deliverScroll(interaction, gid, scroll);
}

// Text first, always; then a fresh woven PDF in this server's face when it
// can be rendered — the same kind of file that was handed in, ready to
// travel again.
async function deliverScroll(interaction, gid, scroll) {
  const lines = ['📜 **The scroll, read back:**', ''];
  if (scroll.title) lines.push(`**${scroll.title}**`, '');
  lines.push(scroll.body);
  if (scroll.flavour) lines.push('', `_${scroll.flavour}_`);
  await replyLong(interaction, lines, { ephemeral: true });
  // Best effort from here: the text above is already delivered. The readable
  // edition is set in plain type, so no stored scroll font is needed to read.
  try { require('@napi-rs/canvas'); }
  catch { return interaction.followUp({ content: '✂️ No files — `@napi-rs/canvas` isn\'t installed here.', ephemeral: true }); }
  try {
    const payload = { v: 1, kind: 'scroll', title: scroll.title, body: scroll.body, flavour: scroll.flavour, name: scroll.name ?? null };
    const stem = fileSlug(scroll.name || scroll.title, 'scroll');
    const png = renderScroll({ family: 'standard', title: scroll.title, body: scroll.body });
    const pdfBuf = embedScrollData(makeTextPdf({ title: scroll.title, body: scroll.body }), payload);
    const { AttachmentBuilder } = require('discord.js');
    const out = await interaction.followUp({ content: '📜 The readable edition, in plain type — the image to see, the PDF woven to travel (its text is selectable, too).',
      files: [
        new AttachmentBuilder(png, { name: `${stem}-readable.png` }),
        new AttachmentBuilder(pdfBuf, { name: `${stem}-readable.pdf` }),
      ], ephemeral: true });
    // The archive shows imports as well as exports — same record shape.
    // And it SAYS so, like the write path does: a silent archive is one the
    // GM can't trust.
    try {
      const arch = await scrollArchiveChannel(interaction.client, gid, interaction.user.id);
      if (arch) {
        await sendLong(arch, [
          `📖 **${stem}** · read back by <@${interaction.user.id}> in <#${interactionChannelId(interaction)}>`,
          '', ...(scroll.title ? [`**${scroll.title}**`, ''] : []), scroll.body,
          ...(scroll.flavour ? ['', `_${scroll.flavour}_`] : []),
        ], { files: [
          new AttachmentBuilder(renderScroll({ family: 'standard', title: scroll.title, body: scroll.body }), { name: `${stem}-readable.png` }),
          new AttachmentBuilder(pdfBuf, { name: `${stem}-readable.pdf` }),
        ], allowedMentions: { parse: [] } });
        await interaction.followUp({ content: `📚 Archived to <#${arch.id}>.`, ephemeral: true }).catch(() => {});
      }
    } catch (err) {
      console.error('[scroll] read-back archive failed -', err?.message || err);
      await interaction.followUp({ content: '⚠️ The archive copy failed — check my access to the archive.', ephemeral: true }).catch(() => {});
    }
    return out;
  } catch (err) {
    console.error('[scroll] remake failed -', err?.message || err);
    return interaction.followUp({ content: `❌ The remake wouldn't take ink — ${err?.message || err}`, ephemeral: true });
  }
}

async function handleScrollModal(interaction) {
  const gid = interaction.guild.id;
  // Ack first, gate second — the GM check can be slow on a big server and the
  // three-second window is unforgiving.
  await interaction.deferReply({ ephemeral: true });
  if (!(await isGm(interaction.guild, interaction.user.id))) {
    return interaction.editReply({ content: '❌ Only GMs can unfurl props.' });
  }
  const family = ensureScrollFont(gid);
  if (!family) return interaction.editReply({ content: '📜 The scroll font vanished — set one again with `/config mechanics scrollfont`.' });
  const title = interaction.fields.getTextInputValue('title')?.trim() || null;
  const body = interaction.fields.getTextInputValue('body')?.trim();
  const flavour = interaction.fields.getTextInputValue('flavour')?.trim() || null;
  const stem = fileSlug(interaction.fields.getTextInputValue('filename') || title, 'ancient-scroll');
  if (!body) return interaction.editReply({ content: '❌ Nothing written.' });
  try {
    // Two files, two jobs: the PNG is what everyone sees in the channel; the
    // PDF carries the writing woven after %%EOF and survives every Discord
    // re-upload — anyone who saves it can hand it to /gm scroll anywhere.
    const payload = { v: 1, kind: 'scroll', title, body, flavour, name: stem };
    const png = renderScroll({ family, title, body });
    const pdfBuf = embedScrollData(renderScroll({ family, title, body, pdf: true }), payload);
    const { AttachmentBuilder } = require('discord.js');
    const chan = await interactionChannel(interaction);
    await chan.send({
      content: flavour || '📜 *An ancient parchment is unfurled…*',
      files: [
        new AttachmentBuilder(png, { name: `${stem}.png` }),
        new AttachmentBuilder(pdfBuf, { name: `${stem}.pdf` }),
      ],
      allowedMentions: { parse: ['users'] }, // a scene line may name a player, never wake a room
    });
    // The library copy — the whole record: writing, parchment, woven PDF.
    // Best-effort, and the ack says whether it made it.
    let archived = '';
    try {
      const arch = await scrollArchiveChannel(interaction.client, gid, interaction.user.id);
      if (arch) {
        await sendLong(arch, [
          `📚 **${stem}** · unfurled by <@${interaction.user.id}> in <#${chan.id}>`,
          '', ...(title ? [`**${title}**`, ''] : []), body,
          ...(flavour ? ['', `_${flavour}_`] : []),
        ], { files: [
          new AttachmentBuilder(png, { name: `${stem}.png` }),
          new AttachmentBuilder(pdfBuf, { name: `${stem}.pdf` }),
        ], allowedMentions: { parse: [] } });
        archived = ` · archived to <#${arch.id}>`;
      }
    } catch (err) {
      console.error('[scroll] archive failed -', err?.message || err);
      archived = ' · ⚠️ archive copy failed — check my access to the archive';
    }
    return interaction.editReply({ content: `📜 Posted as **${stem}.png / .pdf** — the image to see, the PDF to keep. The writing rides inside the PDF.${archived}` });
  } catch (err) {
    console.error('[scroll] render failed -', err?.message || err);
    return interaction.editReply({ content: `❌ The scroll wouldn't take ink — ${err?.message || err}` });
  }
}

async function handleHelp(interaction) {
  const cat = interaction.options.getString('category');
  const gm = await isGm(interaction.guild, interaction.user.id);
  const handbook = playerHandbookLink(interaction.guild.id);

  if (cat && HELP_CATEGORIES[cat]) {
    if (GM_HELP_CATEGORIES.includes(cat) && !gm) {
      return interaction.reply({ content: '❌ That help section covers GM-only commands.', ephemeral: true });
    }
    // Pages like the Getting Started guide run past one message; replyLong
    // splits on line breaks so nothing is ever cut mid-sentence.
    const c = HELP_CATEGORIES[cat];
    const page = [`**${c.title}**`, ...c.body];
    if (cat === 'start' && handbook) page.push('', `📖 [The player handbook (PDF)](<${handbook}>)`);
    return replyLong(interaction, page, { ephemeral: true });
  }
  // Overview — hide GM sections from players entirely
  const lines = ['**🎲 DDice — Command Help**', '',
    '_New here? `/help category:start` walks the whole game in one page._', ''];
  for (const key of Object.keys(HELP_CATEGORIES)) {
    if (GM_HELP_CATEGORIES.includes(key) && !gm) continue;
    const c = HELP_CATEGORIES[key];
    lines.push(`${c.title} — ${c.blurb} · \`/help category:${key}\``);
  }
  if (handbook) lines.push('', `📖 [The player handbook (PDF)](<${handbook}>)`);
  lines.push('', '_Most dice commands also work with the `r` prefix or bare notation (e.g. `1d20`)._');
  return replyLong(interaction, lines, { ephemeral: true });
}

