async function handleLastRoll(interaction) {
  const gid = interaction.guild.id;
  const uid = interaction.user.id;
  const last = getLastRoll(gid, interactionChannelId(interaction), uid);
  if (!last) return interaction.reply({ content: '❌ You haven\'t rolled anything in this channel yet.', ephemeral: true });
  const label = last.label ? ` *(${last.label})*` : '';
  return interaction.reply({ content: `🎲 Your last roll here: \`${last.notation}\`${label}\n_Rolled at ${last.saved_at} UTC._\nUse \`rr\` to reroll it (costs a token).`, ephemeral: true });
}

// ─────────────────────────────────────────────
//  BACKUP SYSTEM
// ─────────────────────────────────────────────

// Take a consistent snapshot. Attaching the live database risks a torn file if
// a write lands mid-upload; VACUUM INTO writes a settled copy, and also drops
// free pages so the attachment is as small as it can be. Falls back to a plain
// copy on an older SQLite that lacks it.
function snapshotDb() {
  const out = path.join(require('os').tmpdir(), `ddice-snapshot-${Date.now()}.db`);
  try {
    db.exec(`VACUUM INTO '${out.replace(/'/g, "''")}'`);
  } catch (err) {
    console.error('[backup] VACUUM INTO unavailable, copying instead:', err?.message || err);
    fs.copyFileSync(DB_PATH, out);
  }
  return out;
}

// Post the newest backup and remove the one before it, so the channel always
// holds exactly one file. New goes up first — a failure part-way leaves the
// previous backup in place rather than none at all.
async function publishBackup(client, gid, channelId, { reason = 'automatic backup' } = {}) {
  const { AttachmentBuilder } = require('discord.js');
  const snap = snapshotDb();
  try {
    const size = fs.statSync(snap).size;
    const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
    const ch = await client.channels.fetch(channelId);
    const msg = await ch.send({
      content: `🗄️ **Database backup** — ${reason}\n`
        + `_${new Date().toUTCString()} · ${(size / 1024).toFixed(1)} KB. This replaces the previous backup._`,
      files: [new AttachmentBuilder(snap, { name: `ddice-backup-${stamp}.db` })],
      allowedMentions: { parse: [] },
    });
    const prev = getConfig(gid)?.backup_msg_id;
    if (prev) {
      try { const old = await ch.messages.fetch(prev); await old.delete(); } catch {}
    }
    setConfig(gid, { backup_msg_id: msg.id });
    return { size, url: `https://discord.com/channels/${gid}/${ch.id}/${msg.id}` };
  } finally {
    try { fs.unlinkSync(snap); } catch {}
  }
}

async function handleBackup(interaction) {
  const sub = interaction.options.getSubcommand();
  const gid = interaction.guild.id;
  const uid = interaction.user.id;

  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can manage backups.', ephemeral: true });

  if (sub === 'now') {
    await interaction.deferReply({ ephemeral: true });
    if (!fs.existsSync(DB_PATH)) return interaction.editReply({ content: '❌ Database file not found.' });
    const channelId = getConfig(gid)?.backup_channel_id;
    try {
      // With a backup channel set, a manual backup replaces the standing one
      // there too — otherwise it comes back privately as a one-off copy.
      if (channelId) {
        const out = await publishBackup(interaction.client, gid, channelId, { reason: 'taken by a GM' });
        // A fresh backup restarts the cycle — no point taking another an hour later.
        setConfig(gid, { backup_last: Date.now() });
        return interaction.editReply({ content:
          `✅ Backup posted to <#${channelId}> (${(out.size / 1024).toFixed(1)} KB), replacing the previous one.\n${out.url}` });
      }
      const { AttachmentBuilder } = require('discord.js');
      const snap = snapshotDb();
      try {
        const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
        return await interaction.editReply({
          content: `✅ Database backup (${(fs.statSync(snap).size / 1024).toFixed(1)} KB). Save this somewhere safe.\n`
            + '_Set a channel with `/gm backup auto` and each backup will replace the last there._',
          files: [new AttachmentBuilder(snap, { name: `ddice-backup-${stamp}.db` })] });
      } finally { try { fs.unlinkSync(snap); } catch {} }
    } catch (err) {
      console.error('Backup error:', err);
      return interaction.editReply({ content: `❌ Backup failed: ${err.message}` });
    }
  }

  if (sub === 'auto') {
    const raw = interaction.options.getString('channel');
    if (raw.toLowerCase() === 'off') {
      setConfig(gid, { backup_channel_id: null, backup_last: null });
      return interaction.reply({ content: '✅ Automatic backups disabled. The last file is left where it is.', ephemeral: true });
    }
    const channelId = raw.replace(/[<#>]/g, '').trim();
    const hours = interaction.options.getInteger('hours');
    // A new home means a new standing post — don't try to delete a message
    // that lives in a channel we're no longer watching.
    setConfig(gid, { backup_channel_id: channelId, backup_msg_id: null,
      ...(hours ? { backup_hours: hours } : {}) });
    const every = backupInterval(getConfig(gid)) / 3600000;
    await interaction.deferReply({ ephemeral: true });
    // Post one now, so the channel has a backup from the moment it is set up
    // rather than after the first full cycle.
    try {
      const out = await publishBackup(interaction.client, gid, channelId, { reason: 'backups switched on' });
      setConfig(gid, { backup_last: Date.now() });
      return interaction.editReply({ content:
        `✅ Automatic backups enabled — <#${channelId}>, every **${every}h**.\n`
        + `_Each one deletes and replaces the last, so the channel holds only the newest._\n`
        + `First backup posted (${(out.size / 1024).toFixed(1)} KB): ${out.url}` });
    } catch (err) {
      setConfig(gid, { backup_last: Date.now() });
      return interaction.editReply({ content:
        `⚠️ Set to <#${channelId}> every **${every}h**, but the first backup failed: ${err.message}\n`
        + '_Check I can see that channel and attach files there._' });
    }
  }
}

// A background job failing to the console is a job nobody knows has failed —
// and for backups that means believing you are covered when you are not. This
// reports to the channel the job belongs to, once per distinct problem, and
// says when it recovers.
function lastJobFailure(gid, job) {
  return db.prepare('SELECT message FROM job_failures WHERE guild_id=? AND job=?').get(gid, job)?.message ?? null;
}
async function reportJobFailure(client, gid, channelId, job, err) {
  const msg = err?.message || String(err);
  if (lastJobFailure(gid, job) === msg) return;   // already said this one
  db.prepare(`INSERT INTO job_failures (guild_id,job,message,at) VALUES (?,?,?,?)
              ON CONFLICT(guild_id,job) DO UPDATE SET message=excluded.message, at=excluded.at`)
    .run(gid, job, msg, Date.now());
  if (!channelId) return;
  try {
    const ch = await client.channels.fetch(channelId);
    await ch.send({ allowedMentions: { roles: getGmRoleIds(gid) },
      content: `${getGmRoleIds(gid).map(r => `<@&${r}>`).join(' ')} ⚠️ **${job} failed.**\n\`${msg}\`\n`
        + '_It will keep trying, and I will say so when it works again._' });
  } catch {}
}
async function reportJobRecovered(client, gid, channelId, job) {
  if (!lastJobFailure(gid, job)) return;
  db.prepare('DELETE FROM job_failures WHERE guild_id=? AND job=?').run(gid, job);
  if (!channelId) return;
  try {
    const ch = await client.channels.fetch(channelId);
    await ch.send(`✅ _${job} is working again._`);
  } catch {}
}

// Automatic backups. Each run replaces the standing post rather than adding to
// it, so the channel holds the newest file and nothing else.
//
// The tick is short and the decision is made from a stored timestamp: a deploy
// mid-cycle resumes where it left off instead of starting the count again, and
// a server that redeploys hourly still gets its daily backup.
const BACKUP_TICK_MS = 10 * 60 * 1000;
const BACKUP_HOURS_DEFAULT = 24;

function backupInterval(cfg) {
  const h = Number(cfg?.backup_hours);
  return (Number.isFinite(h) && h > 0 ? h : BACKUP_HOURS_DEFAULT) * 3600 * 1000;
}

async function backupTick() {
  try {
    if (!fs.existsSync(DB_PATH)) return;
    const rows = db.prepare('SELECT * FROM guild_config WHERE backup_channel_id IS NOT NULL').all();
    for (const row of rows) {
      try {
        const last = Number(row.backup_last) || 0;
        // First run after enabling: start the clock rather than firing at once,
        // since /gm backup auto already posts one immediately.
        if (!last) { setConfig(row.guild_id, { backup_last: Date.now() }); continue; }
        if (Date.now() - last < backupInterval(row)) continue;
        await publishBackup(client, row.guild_id, row.backup_channel_id, { reason: 'scheduled backup' });
        setConfig(row.guild_id, { backup_last: Date.now() });
        await reportJobRecovered(client, row.guild_id, row.backup_channel_id, 'Backup');
        console.log(`[backup] ${row.guild_id}: posted, previous removed`);
      } catch (e) {
        console.error('Auto-backup failed for guild', row.guild_id, e.message);
        // A backup nobody knows has failed is worse than no backup at all.
        await reportJobFailure(client, row.guild_id, row.backup_channel_id, 'Backup', e);
      }
    }
  } catch (err) { console.error('Backup scheduler error:', err.message); }
}

function startBackupScheduler() {
  setInterval(() => backupTick().catch(e => console.error('[backup] tick:', e?.message || e)), BACKUP_TICK_MS);
  setTimeout(() => backupTick().catch(()=>{}), 2 * 60 * 1000);   // catch up on anything missed while down
}

// ─────────────────────────────────────────────
//  CONFIRMATION BUTTON SYSTEM
// ─────────────────────────────────────────────

// Pending destructive actions keyed by a short token
const pendingConfirms = new Map();

function makeConfirmButtons(token) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`confirm:${token}`).setLabel('Confirm').setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId(`cancel:${token}`).setLabel('Cancel').setStyle(ButtonStyle.Secondary),
  );
  return row;
}


// ── /gm heal ───────────────────────────────────────────────────────────────────
// One GM command for restoring resources, on a player or an NPC (or every NPC).
// HP changes go through setFighterHp so any active fight stays in sync.
async function handleGmHeal(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  if (!(await isGm(interaction.guild, uid)))
    return interaction.reply({ content: '❌ Only GMs can use `/gm heal`.', ephemeral: true });

  const targetUser = interaction.options.getUser('user');
  const npcArg = (interaction.options.getString('npc') || '').trim();
  const scope = interaction.options.getString('global');
  const named = [targetUser, npcArg || null, scope || null].filter(Boolean).length;
  if (named !== 1)
    return interaction.reply({ content: '❌ Pick exactly one of `user`, `npc` or `global`.', ephemeral: true });

  const amount = interaction.options.getString('amount') || 'full';
  const restore = interaction.options.getString('restore') || 'hp';
  const value = interaction.options.getInteger('value');
  if (['add','sub','exact'].includes(amount) && value === null)
    return interaction.reply({ content: `❌ \`amount:${amount}\` needs a \`value\`.`, ephemeral: true });

  // Work out a new figure from the chosen mode.
  const compute = (cur, max) => {
    if (amount === 'full') return max;
    if (amount === 'half') return Math.ceil(max / 2);
    if (amount === 'add') return Math.min(max, cur + value);
    if (amount === 'sub') return cur - value;           // may go negative — GM's call
    return Math.min(max, value);                        // exact
  };

  // ── Everyone at once ──
  // Deliberately does not skip quest parties the way scheduled recovery does:
  // a GM typing this has decided to heal the room, and a silent exclusion would
  // be a nasty surprise mid-session.
  if (scope) {
    await interaction.deferReply();
    const cfg0 = getConfig(gid);
    const maxCharges0 = cfg0.heal_charges ?? 3;
    const lines = [];
    const entries = [];
    let players = 0, npcs = 0;
    // Counted across both branches below, so it has to live out here — it was
    // declared inside the players block and threw for a scope:NPCs heal.
    let fallenSkipped = 0;

    if (scope === 'players' || scope === 'all') {
      const sheets = db.prepare('SELECT * FROM characters WHERE guild_id=?').all(gid);
      // Gathered first so the whole roster can be put in reading order —
      // Heroes, then knight order, then class, then name.
      for (const ch of sheets) {
        // A heal is not a resurrection — that needs /gm revive and a decision.
        if (ch.died_at) { fallenSkipped++; continue; }
        const nm = await getDisplayName(interaction.guild, ch.user_id);
        const bits = [];
        if (restore === 'hp' || restore === 'all') {
          const max = maxHp(ch, gid), before = ch.hp_current ?? 0, after = compute(before, max);
          setFighterHp(gid, ch.user_id, after);
          bits.push(`❤️ ${before}→${after}`);
        }
        if (restore === 'rerolls' || restore === 'all') {
          const max = maxRerolls(ch), before = ch.rerolls_current ?? 0, after = Math.max(0, compute(before, max));
          upsertChar(gid, ch.user_id, { rerolls_current: after });
          bits.push(`🔄 ${before}→${after}`);
        }
        if ((restore === 'charges' || restore === 'all') && isWhiteKnight(ch)) {
          const before = getHealCharges(gid, ch.user_id, maxCharges0).current;
          const after = Math.max(0, compute(before, maxCharges0));
          setHealCharges(gid, ch.user_id, after);
          bits.push(`🛡️ ${before}→${after}`);
        }
        if (bits.length) { players++; entries.push({ row: ch, name: nm, text: `**${nm}** — ${bits.join(' · ')}` }); }
      }
    }

    if (scope === 'npcs' || scope === 'all') {
      if (restore !== 'hp' && restore !== 'all' && scope === 'npcs') {
        return interaction.editReply({ content: '❌ NPCs only have HP — use `restore:HP only`.' });
      }
      for (const npc of getAllNpcs(gid)) {
        if (npc.died_at) { fallenSkipped++; continue; }
        const max = maxHpFromCon(gid, npc.con), before = npc.hp_current ?? 0, after = compute(before, max);
        setFighterHp(gid, npcFighterId(npc.name), after);
        npcs++;
        entries.push({ row: npc, name: npc.name, isNpc: true, text: `**${npc.name}** — ❤️ ${before}→${after} / ${max}` });
      }
    }

    // One reading order for the whole list, grouped by heading.
    for (const g of groupRoster(entries)) {
      lines.push(`**${g.label}**`);
      for (const e of g.rows) lines.push(`  ${e.text}`);
      lines.push('');
    }
    if (lines.length && lines[lines.length - 1] === '') lines.pop();

    if (!lines.length) return interaction.editReply({ content: fallenSkipped
      ? `❌ Nothing to restore — the only characters here have fallen. \`/gm revive\` brings one back.`
      : '❌ Nothing to restore — no sheets or NPCs on this server.' });
    const what = scope === 'players' ? `${players} player${players === 1 ? '' : 's'}`
               : scope === 'npcs' ? `${npcs} NPC${npcs === 1 ? '' : 's'}`
               : `${players} player${players === 1 ? '' : 's'} and ${npcs} NPC${npcs === 1 ? '' : 's'}`;
    const head = `✨ **Restored ${what}** — ${amount === 'full' ? 'to full' : amount === 'half' ? 'to half' : `${amount} ${value}`}`
      + (fallenSkipped ? ` _(${fallenSkipped} fallen left as they are)_` : '')
      + (restore === 'all' ? ' (HP, rerolls and heal charges)' : restore === 'hp' ? ' (HP)' : ` (${restore})`);
    return replyLong(interaction, [head, '', ...lines]);
  }

  // ── NPC(s) ──
  if (npcArg) {
    const targets = npcArg.toLowerCase() === 'all'
      ? getAllNpcs(gid)
      : expandNpcList(gid, npcArg).map(n => getNpc(gid, n)).filter(Boolean);
    if (!targets.length) return interaction.reply({ content: `❌ No NPC matched **${npcArg}**.`, ephemeral: true });
    if (restore !== 'hp' && restore !== 'all')
      return interaction.reply({ content: '❌ NPCs only have HP — use `restore:HP only`.', ephemeral: true });

    const lines = [];
    for (const npc of targets) {
      const max = maxHpFromCon(gid, npc.con);
      const before = npc.hp_current ?? 0;
      const after = compute(before, max);
      setFighterHp(gid, npcFighterId(npc.name), after); // keeps any live fight in sync
      lines.push(`🎭 **${npc.name}** — ❤️ ${before} → **${after}** / ${max}`);
    }
    return replyLong(interaction, [`✨ Restored ${targets.length} NPC${targets.length === 1 ? '' : 's'}:`, '', ...lines]);
  }

  // ── Player ──
  const ch = getChar(gid, targetUser.id);
  if (!ch) return interaction.reply({ content: `❌ <@${targetUser.id}> has no character sheet yet.`, ephemeral: true });
  const nm = await getDisplayName(interaction.guild, targetUser.id);
  const cfg = getConfig(gid);
  const maxCharges = cfg.heal_charges ?? 3;
  const lines = [];

  if (restore === 'hp' || restore === 'all') {
    const max = maxHp(ch, gid), before = ch.hp_current ?? 0;
    const after = compute(before, max);
    setFighterHp(gid, targetUser.id, after);
    lines.push(`❤️ HP: **${before} → ${after}** / ${max}`);
  }
  if (restore === 'rerolls' || restore === 'all') {
    const max = maxRerolls(ch), before = ch.rerolls_current ?? 0;
    const after = Math.max(0, compute(before, max));
    upsertChar(gid, targetUser.id, { rerolls_current: after });
    lines.push(`🔄 Rerolls: **${before} → ${after}** / ${max}`);
  }
  if (restore === 'charges' || restore === 'all') {
    if (!isWhiteKnight(ch)) {
      lines.push('🛡️ Heal charges: _skipped — not a White Knight with WIS 5+_');
    } else {
      const before = getHealCharges(gid, targetUser.id, maxCharges).current;
      const after = Math.max(0, compute(before, maxCharges));
      setHealCharges(gid, targetUser.id, after);
      lines.push(`🛡️ Heal charges: **${before} → ${after}** / ${maxCharges}`);
    }
  }
  const downed = (getChar(gid, targetUser.id)?.hp_current ?? 0) <= 0;
  if (downed) lines.push('💀 _Still at 0 or less — they\'ll be left out of new fights._');
  return interaction.reply({ content: [`✨ **${nm}** restored:`, '', ...lines].join('\n') });
}

// ── /roll (slash) ─────────────────────────────────────────────────────────────
// Same roll engine and card format as the prefix commands, but every part is a
// dropdown or field so nothing has to be memorised. `stat` and `dice` are
// alternatives; a stat resolves to 1d20+STAT from the caller's sheet.
async function handleRollSlash(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const cid = interactionChannelId(interaction);
  // last:true is a pure read — show the most recent roll, touch nothing.
  if (interaction.options.getBoolean('last')) return handleLastRoll(interaction);
  // The fight bridge: an ability picked here rides the exact /fight machinery.
  const fightAction = interaction.options.getString('action');
  if (fightAction) return handleFight(interaction, fightAction);
  const stat = interaction.options.getString('stat');
  let dice = (interaction.options.getString('dice') || '').trim();
  const mode = interaction.options.getString('mode') || 'normal';
  const successCheck = interaction.options.getBoolean('success_check') ?? false;
  const label = (interaction.options.getString('label') || '').trim() || null;
  const flavour = (interaction.options.getString('flavour') || '').trim() || null;
  const intoFight = interaction.options.getBoolean('fight') ?? false;
  const fightTarget = interaction.options.getUser('target');

  if (stat && dice) return interaction.reply({ content: '❌ Pick either a **stat** or custom **dice**, not both.', ephemeral: true });
  // Bare /roll: a flat d20, no stat, no fuss.
  if (!stat && !dice) dice = '1d20';

  const gateMsg = sheetGate(gid, uid);
  if (gateMsg) return interaction.reply({ content: gateMsg, ephemeral: true });

  const char = getChar(gid, uid);
  let notation;
  if (stat) {
    if (!char) return interaction.reply({ content: '❌ No character sheet found. Use `/char create` first, or roll custom `dice`.', ephemeral: true });
    notation = `1d20+${char[stat] ?? 0}`;
  } else {
    const m = dice.match(/^\d+d\d+(?:[+-]\d+)?$/i);
    if (!m) return interaction.reply({ content: '❌ Invalid notation. Try `1d20`, `1d20+5` or `2d6+3`.', ephemeral: true });
    notation = dice;
  }

  // Hero signature advantage applies to stat rolls
  const effMode = applyNextMark(gid, uid, stat ? applySignatureMode(char, stat, mode) : mode);

  let result;
  if (effMode === 'adv') result = rollAdvantage(notation);
  else if (effMode === 'dis') result = rollDisadvantage(notation);
  else result = rollNotation(notation);
  if (!result) return interaction.reply({ content: '❌ Could not parse dice notation.', ephemeral: true });

  const finalLabel = label || (stat ? stat : null);
  saveRoll(gid, cid, uid, notation, finalLabel);
  const critType = detectCrit(result, effMode);
  const naturalRoll = effMode === 'normal' ? result.rolls[0] : result.chosen;
  const successResult = successCheck ? getSuccessResult(result.total, naturalRoll, result.sides) : null;

  const rollLine = buildRollLine(result, effMode, critType, successResult);

  // Feed this roll into the fight instead of standing alone. Explicit rather
  // than automatic: a player rolling casually mid-fight shouldn't accidentally
  // commit their turn.
  if (intoFight) {
    const waiting = fightAwaiting(gid, cid, uid);
    if (!waiting) {
      const f = getFight(gid, cid);
      const why = !f || f.state !== 'active' ? 'There is no fight running here.'
        : f.phase === 'attack' ? 'It is not your turn to attack.'
        : f.atk_kind === 'grapple' ? 'That is a grapple — answer with `/fight act action:Save` (STR only).'
        : f.atk_kind === 'feint' ? 'That is a feint — answer with `/fight act action:Insight` (WIS only).'
        : f.def_roll !== null ? 'That exchange already has both rolls — `/fight resolve` it.'
        : 'You are not the one being attacked.';
      return interaction.reply({ content: `❌ ${why} The roll was not submitted.`, ephemeral: true });
    }
    const rollLabel = label || (stat ? STAT_LABELS[stat] : dice);

    if (waiting.kind === 'atk') {
      const order = JSON.parse(waiting.fight.turn_order || '[]');
      let targetId = fightTarget?.id ?? null;
      if (!targetId) {
        // With exactly one opponent left there is nothing to disambiguate.
        const others = order.filter(x => x !== uid);
        if (others.length === 1) targetId = others[0];
        else return interaction.reply({ content: '❌ Say who you are attacking — add `target:@player`. (For an NPC, a GM should use `/fight atk`.)', ephemeral: true });
      }
      if (!order.includes(targetId)) return interaction.reply({ content: '❌ They are not in this fight.', ephemeral: true });
      submitFightRoll(gid, cid, 'atk', { total: result.total, nat: naturalRoll, sides: result.sides, label: rollLabel, targetId });
      const tF = await resolveFighter(interaction.guild, gid, targetId);
      const nm = await getDisplayName(interaction.guild, uid);
      recordRoll(gid, { userId: uid, channelId: cid, interaction, result,
        input: `/roll ${stat ? `stat:${stat}` : `dice:${dice}`} fight:true`, rollLine,
        context: `fight · custom attack on ${tF.name}` });
      return interaction.reply({ content: [
        `⚔️ **${nm}** attacks **${tF.name}${tF.isNpc ? ' 🎭' : ''}** with a custom roll — **${rollLabel}**`,
        rollLine, '',
        tF.isNpc ? `🛡️ A GM defends with \`/fight def stat:… npc:${tF.name}\`, or \`/roll … fight:true\`.`
                 : `🛡️ <@${targetId}> defends — \`/fight def stat:dex\`, or \`/roll … fight:true\` for a custom roll.`,
      ].join('\n') });
    }

    submitFightRoll(gid, cid, 'def', { total: result.total, nat: naturalRoll, sides: result.sides, label: rollLabel });
    const nm = await getDisplayName(interaction.guild, uid);
    recordRoll(gid, { userId: uid, channelId: cid, interaction, result,
      input: `/roll ${stat ? `stat:${stat}` : `dice:${dice}`} fight:true`, rollLine,
      context: 'fight · custom defence' });
    return interaction.reply({ content: [
      `🛡️ **${nm}** defends with a custom roll — **${rollLabel}**`,
      rollLine, '', '⚡ Use `/fight resolve` to resolve this exchange.',
    ].join('\n') });
  }

  recordRoll(gid, { userId: uid, channelId: cid, interaction, result,
    input: `/roll ${stat ? `stat:${stat}` : `dice:${dice}`}${effMode !== 'normal' ? ` mode:${effMode}` : ''}${successCheck ? ' success_check:true' : ''}`,
    rollLine, context: successCheck ? 'success check' : null });

  // Same rule as a typed stat roll: 1d20+4 says nothing about which stat it was
  // or where the 4 came from, so a stat roll always shows at least the
  // compressed line — even for someone who has their card switched off.
  const slashMode = char ? (stat && cardMode(char) === CARD_OFF ? CARD_COMPACT : cardMode(char)) : CARD_OFF;

  if (char && slashMode === CARD_COMPACT) {
    const lines = [];
    if (finalLabel) lines.push(`${critPrefix(critType)}**${finalLabel}**`);
    lines.push(rollLine, statLine(char, gid));
    if (flavour) lines.push(...flavourBlock(flavour, finalLabel, result.total, critType));
    return interaction.reply({ content: lines.join('\n') });
  }
  if (char && slashMode === CARD_FULL) {
    const cfg = getConfig(gid);
    const maxCharges = cfg.heal_charges ?? 3;
    const healRow = getHealCharges(gid, uid, maxCharges);
    const displayName = await getDisplayName(interaction.guild, uid);
    const tags = getPlayerTags(gid, uid);
    return interaction.reply({ content: buildRollEmbed({ rollLine, label: finalLabel, isReroll: false,
      char: { ...char, displayName }, healCharges: healRow.current, maxCharges, flavour,
      total: result.total, critType, tags, gid }) });
  }
  return interaction.reply({ content: buildPlainRoll({ rollLine, label: finalLabel, isReroll: false, flavour, total: result.total, critType }) });
}

// ── MERIT ─────────────────────────────────────────────────────────────────────
async function handleMerit(interaction) {
  {
    const sub0 = interaction.options.getSubcommand();
    if (sub0 === 'give') return handleMeritGive(interaction);
    if (sub0 === 'cancel') {
      const gid0 = interaction.guild.id, me = interaction.user.id;
      const id = interaction.options.getInteger('id');
      const t = getMeritTrade(gid0, id);
      if (!t) return interaction.reply({ content: `❌ There is no trade \`#${id}\`.`, ephemeral: true });
      if (t.state !== 'pending') return interaction.reply({ content: `❌ Trade \`#${id}\` was already ${t.state}.`, ephemeral: true });
      // The player who offered it may withdraw; a GM may clear any of them.
      const isGmUser0 = await isGm(interaction.guild, me);
      if (t.from_user !== me && !isGmUser0)
        return interaction.reply({ content: '❌ Only the player who offered it, or a GM, can withdraw a trade.', ephemeral: true });
      setMeritTrade(gid0, id, { state: 'cancelled', decided_by: me, decided_at: Date.now() });
      const chId0 = getConfig(gid0)?.approval_channel_id;
      if (chId0 && t.msg_id) {
        try {
          const ch0 = await interaction.client.channels.fetch(chId0);
          const old = await ch0.messages.fetch(t.msg_id);
          await old.edit({ content: `~~🤝 Merit trade #${id}~~\n↩️ *Withdrawn${t.from_user === me ? ' by the sender' : ' by a GM'}.*`, components: [] });
        } catch {}
      }
      const fromN = await getDisplayName(interaction.guild, t.from_user);
      const toN = await getDisplayName(interaction.guild, t.to_user);
      if (t.from_user !== me) {
        await notifyPlayer(interaction, gid0, t.from_user,
          `↩️ **Your merit trade was withdrawn** by a GM in **${interaction.guild.name}** — ${t.amount} merit to **${toN}**. No merit moved.`);
      }
      return interaction.reply({ content: `↩️ Trade \`#${id}\` withdrawn — **${t.amount}** merit from **${fromN}** to **${toN}**. Nothing moved.` });
    }
    if (sub0 === 'trades') {
      const gid0 = interaction.guild.id;
      const rows = pendingMeritTrades(gid0);
      if (!rows.length) return interaction.reply({ content: '🤝 No merit trades are waiting.', ephemeral: true });
      const lines = ['🤝 **Merit trades awaiting a GM**', ''];
      for (const t of rows) {
        lines.push(`\`#${t.id}\` **${await getDisplayName(interaction.guild, t.from_user)}** → `
          + `**${await getDisplayName(interaction.guild, t.to_user)}** · **${t.amount}** merit`
          + (t.reason ? ` · ${t.reason}` : '') + ` · <t:${Math.floor(t.created_at / 1000)}:R>`);
      }
      return replyLong(interaction, lines, { ephemeral: true });
    }
  }
  const gid = interaction.guild.id, uid = interaction.user.id;
  const sub = interaction.options.getSubcommand();

  if (sub === 'view') {
    const target = interaction.options.getUser('user') ?? interaction.user;
    const merits = getMerits(gid, target.id);
    const ch = getChar(gid, target.id);
    const { current, next } = rankProgress(gid, merits);
    const name = await getDisplayName(interaction.guild, target.id);
    const heldRank = ch?.rank_name;
    const lines = [`🎖️ **${name}** — **${merits}** merit${merits === 1 ? '' : 's'}`];
    if (heldRank) lines.push(`🏅 Current rank: **${heldRank}**`);
    if (current && current.name !== heldRank) lines.push(`✅ Eligible for: **${current.name}** (needs ${current.threshold})`);
    if (next) {
      const togo = next.threshold - merits;
      lines.push(`📈 Next rank: **${next.name}** — **${togo}** more merit${togo === 1 ? '' : 's'} (at ${next.threshold})`);
    } else if (current) {
      lines.push('🏔️ Highest rank threshold reached.');
    }
    if (!current && !next) lines.push('_No ranks defined yet — a GM can add them with `/standing rank add`._');
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'leaderboard') {
    const rows = db.prepare('SELECT user_id, merits FROM characters WHERE guild_id=? AND merits > 0 ORDER BY merits DESC LIMIT 15').all(gid);
    if (!rows.length) return interaction.reply({ content: '📋 No merits awarded yet.', ephemeral: true });
    const medals = ['🥇','🥈','🥉'];
    const lines = ['🏆 **Merit Leaderboard**', ''];
    for (let i = 0; i < rows.length; i++) {
      const nm = await getDisplayName(interaction.guild, rows[i].user_id);
      const ch = getChar(gid, rows[i].user_id);
      const rankTag = ch?.rank_name ? ` · ${ch.rank_name}` : '';
      lines.push(`${medals[i] ?? `**${i+1}.**`} ${nm} — **${rows[i].merits}**${rankTag}`);
    }
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'history') {
    const target = interaction.options.getUser('user');
    const nameCache = new Map();
    if (target) {
      const rows = getMeritHistory(gid, target.id, 20);
      if (!rows.length) return interaction.reply({ content: `📋 No merit history for **${await getDisplayName(interaction.guild, target.id)}** yet.`, ephemeral: true });
      const nm = await getDisplayNameCached(interaction.guild, target.id, nameCache);
      const lines = [`🎖️ **${nm}** — merit history (latest ${rows.length})`, ''];
      for (const r of rows) {
        const sign = (r.amount ?? 0) >= 0 ? `+${r.amount}` : `${r.amount}`;
        lines.push(`**${sign}** — ${r.reason ?? '—'} · ${formatHistDate(r.created_at)}`);
      }
      return replyLong(interaction, lines);
    }
    const rows = getRecentMeritHistory(gid, 20);
    if (!rows.length) return interaction.reply({ content: '📋 No merit activity recorded yet.', ephemeral: true });
    const lines = ['🎖️ **Recent merit activity**', ''];
    for (const r of rows) {
      const nm = await getDisplayNameCached(interaction.guild, r.user_id, nameCache);
      const sign = (r.amount ?? 0) >= 0 ? `+${r.amount}` : `${r.amount}`;
      lines.push(`**${sign}** ${nm} — ${r.reason ?? '—'} · ${formatHistDate(r.created_at)}`);
    }
    return replyLong(interaction, lines);
  }

  // add / remove / set are GM-only
  if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can change merits.', ephemeral: true });
  const target = interaction.options.getUser('user');
  const name = await getDisplayName(interaction.guild, target.id);

  if (sub === 'add' || sub === 'remove') {
    const amt = interaction.options.getInteger('amount') ?? 1;
    const before = getMerits(gid, target.id);
    const after = addMerits(gid, target.id, sub === 'add' ? amt : -amt);
    logHistory(gid, { kind: 'merit', userId: target.id, amount: after - before, reason: 'manual by GM', actorId: uid });
    const { current, next } = rankProgress(gid, after);
    const ch = getChar(gid, target.id);
    const lines = [`🎖️ **${name}**: ${before} → **${after}** merit${after === 1 ? '' : 's'} (${sub === 'add' ? '+' : '−'}${amt}).`];
    if (sub === 'add' && current && current.name !== ch?.rank_name) {
      lines.push(`✅ Now eligible for **${current.name}** — promote with \`/standing rank promote\`.`);
    } else if (next) {
      const togo = next.threshold - after;
      if (togo > 0) lines.push(`📈 ${togo} more to **${next.name}**.`);
    }
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'set') {
    const amt = interaction.options.getInteger('amount');
    const before = getMerits(gid, target.id);
    upsertChar(gid, target.id, { merits: amt });
    logHistory(gid, { kind: 'merit', userId: target.id, amount: amt - before, reason: `set to ${amt} by GM`, actorId: uid });
    const { current, next } = rankProgress(gid, amt);
    const lines = [`🎖️ **${name}** merits set to **${amt}**.`];
    if (current) lines.push(`✅ Eligible for **${current.name}**.`);
    if (next) lines.push(`📈 ${next.threshold - amt} more to **${next.name}**.`);
    return interaction.reply({ content: lines.join('\n') });
  }
}

// ── RANK ──────────────────────────────────────────────────────────────────────
async function handleRank(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const sub = interaction.options.getSubcommand();

  if (sub === 'list') {
    const ranks = getRanks(gid);
    if (!ranks.length) return interaction.reply({ content: '📋 No ranks defined. A GM can add them with `/standing rank add`.', ephemeral: true });
    const lines = ['🏅 **Ranks** (junior → senior)', ''];
    ranks.forEach((r, i) => lines.push(`**${i+1}. ${r.name}** — ${r.threshold} merit${r.threshold === 1 ? '' : 's'}`));
    return replyLong(interaction, lines);
  }

  // everything else GM-only
  if (!(await isGm(interaction.guild, uid))) return interaction.reply({ content: '❌ Only GMs can manage ranks.', ephemeral: true });

  if (sub === 'add') {
    const name = interaction.options.getString('name').trim();
    if (!name || name.length > 50) return interaction.reply({ content: '❌ Rank name must be 1–50 characters.', ephemeral: true });
    const threshold = interaction.options.getInteger('threshold');
    const order = interaction.options.getInteger('order') ?? threshold;
    const existed = getRanks(gid).some(r => r.name.toLowerCase() === name.toLowerCase());
    setRank(gid, name, threshold, order);
    return interaction.reply({ content: `🏅 Rank **${name}** ${existed ? 'updated' : 'created'} — threshold **${threshold}** merit${threshold === 1 ? '' : 's'}.` });
  }

  if (sub === 'remove') {
    const name = interaction.options.getString('name');
    const removed = removeRank(gid, name);
    if (!removed) return interaction.reply({ content: `❌ No rank named **${name}**.`, ephemeral: true });
    return interaction.reply({ content: `🗑️ Rank **${name}** removed. (Players keeping this rank label aren't changed.)` });
  }

  if (sub === 'promote') {
    const target = interaction.options.getUser('user');
    const rankName = interaction.options.getString('rank');
    const ranks = getRanks(gid);
    const rank = ranks.find(r => r.name.toLowerCase() === rankName.toLowerCase());
    if (!rank) return interaction.reply({ content: `❌ No rank named **${rankName}**. See \`/standing rank list\`.`, ephemeral: true });
    upsertChar(gid, target.id, { rank_name: rank.name });
    const name = await getDisplayName(interaction.guild, target.id);
    const merits = getMerits(gid, target.id);
    const note = merits < rank.threshold ? ` _(note: they have ${merits}/${rank.threshold} merits)_` : '';
    return interaction.reply({ content: `🎉 **${name}** is now **${rank.name}**!${note}` });
  }

  if (sub === 'eligible') {
    const ranks = getRanks(gid);
    if (!ranks.length) return interaction.reply({ content: '📋 No ranks defined yet.', ephemeral: true });
    const chars = db.prepare('SELECT user_id, merits, rank_name FROM characters WHERE guild_id=? AND merits > 0').all(gid);
    const out = [], eligibleIds = [];
    for (const c of chars) {
      const { current } = rankProgress(gid, c.merits);
      if (current && current.name !== c.rank_name) {
        const nm = await getDisplayName(interaction.guild, c.user_id);
        eligibleIds.push({ uid: c.user_id, nm });
        out.push(`• **${nm}** — ${c.merits} merits → eligible for **${current.name}**${c.rank_name ? ` (currently ${c.rank_name})` : ''}`);
      }
    }
    if (!out.length) return interaction.reply({ content: '✅ No one is awaiting a promotion right now.', ephemeral: true });
    // One press per person — the handler recomputes their earned rank fresh.
    const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
    const rows_ = [];
    for (let i = 0; i < Math.min(eligibleIds.length, 25); i += 5) {
      rows_.push(new ActionRowBuilder().addComponents(...eligibleIds.slice(i, i + 5).map(e =>
        new ButtonBuilder().setCustomId(`promoteok:${e.uid}`).setLabel(`⬆️ ${e.nm.slice(0, 70)}`).setStyle(ButtonStyle.Primary))));
    }
    return replyLong(interaction, ['📋 **Awaiting promotion:**', '', ...out], { components: rows_.slice(0, 5) });
  }
}


// Compose an NPC's post from an optional action and an optional speech line.
// Action is italicised, speech is wrapped in quote marks (unless the writer
// already quoted it), and both together stack on separate lines.
function composeNpcSay({ action, speech, raw }) {
  if (raw && raw.trim()) return raw.trim();
  const parts = [];
  const act = (action || '').trim();
  const say = (speech || '').trim();
  if (act) parts.push(`*${act}*`);
  if (say) {
    const alreadyQuoted = /^["\u201c][\s\S]*["\u201d]$/.test(say);
    parts.push(alreadyQuoted ? say : `"${say}"`);
  }
  return parts.join('\n');
}

// ── QUEST helpers (rendering + routing) ───────────────────────────────────────
function questStatusBadge(status) {
  return status === 'open' ? '🟢 Open' : status === 'active' ? '🟡 In progress' : status === 'completed' ? '🔵 Completed' : status;
}

// Build the full text block for a quest (used by post/show).
async function renderQuest(guild, quest, { applyHint = true } = {}) {
  const gid = guild.id;
  const party = getQuestMembers(gid, quest.number, 'party');
  const applied = getQuestMembers(gid, quest.number, 'applied');
  const lines = [];
  lines.push(`📜 **${questTag(quest)}**`);
  lines.push(`${questStatusBadge(quest.status)}`);
  // Who is running it and how they run a table — the two things a player wants
  // before applying, especially when several GMs are running the same adventure.
  const gmBits = [];
  if (quest.gm_id) gmBits.push(`🎲 GM: **${await getDisplayName(guild, quest.gm_id)}**`);
  const style = gmStyleLabel(quest.gm_style);
  if (style) gmBits.push(style);
  if (gmBits.length) lines.push(gmBits.join('  ·  '));
  if (quest.instance_of) {
    const runs = db.prepare('SELECT COUNT(*) AS c FROM quests WHERE guild_id=? AND (number=? OR instance_of=?)')
      .get(gid, quest.instance_of, quest.instance_of).c;
    lines.push(`_One of ${runs} separate runs of this adventure._`);
  }
  lines.push('─────────────────────────────');
  if (quest.lore) lines.push(`📖 *${quest.lore}*\n`);
  if (quest.objectives) lines.push(`🎯 **Objectives**\n${quest.objectives}\n`);
  if (quest.details) lines.push(`📋 **Details**\n${quest.details}\n`);

  const rewardBits = [];
  if (quest.merit_reward > 0) rewardBits.push(`🎖️ **${quest.merit_reward}** merit${quest.merit_reward === 1 ? '' : 's'} each (auto-awarded)`);
  if (quest.rewards) rewardBits.push(`🎁 ${quest.rewards}`);
  if (rewardBits.length) lines.push(`**Rewards**\n${rewardBits.join('\n')}\n`);

  if (quest.party_size) {
    const kind = quest.party_hard ? 'cap' : 'suggested';
    lines.push(`👥 Party: **${party.length}/${quest.party_size}** (${kind})`);
  } else {
    lines.push(`👥 Party: **${party.length}**`);
  }

  if (party.length) {
    const names = [];
    for (const id of party) names.push(`✅ ${await getDisplayName(guild, id)}`);
    lines.push(names.join('  '));
  }
  if (applied.length && quest.status === 'open') {
    const names = [];
    for (const id of applied) names.push(`⏳ ${await getDisplayName(guild, id)}`);
    lines.push(`Applicants: ${names.join('  ')}`);
  }
  if (quest.run_channel_id) lines.push(`\n📍 Runs in <#${quest.run_channel_id}>`);
  if (applyHint && quest.status === 'open') lines.push(`\n_Apply with the button below or_ \`/quest apply number:${quest.number}\``);
  return lines.join('\n');
}

function questApplyButton(number) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`questapply:${number}`).setLabel('Apply to Quest').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`questwithdraw:${number}`).setLabel('Withdraw').setStyle(ButtonStyle.Secondary),
  );
}

// The questline pipeline, expressed as forum tags on the planning forum.
const QUEST_STAGES = [
  ['concept',   '🌱', 'Concept'],
  ['awaiting',  '⏳', 'Awaiting Approval'],
  ['approved',  '✅', 'Approved'],
  ['board',     '📌', 'On the Board'],
  ['archived',  '🗄️', 'Archived'],
  ['completed', '🏁', 'Completed'],
];
// Make sure the planning forum carries every pipeline tag; returns the
// name→tagId map (and stores it). Idempotent — existing tags are kept.
async function ensurePlanTags(forum, gid) {
  const have = forum.availableTags ?? [];
  const missing = QUEST_STAGES.filter(([, , label]) => !have.some(t => t.name === label));
  if (missing.length) {
    await forum.setAvailableTags([
      ...have.map(t => ({ id: t.id, name: t.name, moderated: t.moderated,
        emoji: t.emoji ? { id: t.emoji.id ?? null, name: t.emoji.name ?? null } : undefined })),
      ...missing.map(([, emoji, label]) => ({ name: label, emoji: { id: null, name: emoji } })),
    ]);
  }
  const fresh = (await forum.fetch()).availableTags ?? [];
  const map = {};
  for (const [key, , label] of QUEST_STAGES) {
    const t = fresh.find(x => x.name === label);
    if (t) map[key] = t.id;
  }
  setConfig(gid, { quest_plan_tags: JSON.stringify(map) });
  return map;
}
// Re-tag a quest's planning thread for its current stage, keeping any
// non-pipeline tags a GM added by hand. Best-effort.
async function syncPlanStage(client, gid, quest) {
  if (!quest?.plan_thread_id || !quest.stage) return;
  try {
    const map = JSON.parse(getConfig(gid)?.quest_plan_tags || '{}');
    const want = map[quest.stage];
    if (!want) return;
    const thread = await client.channels.fetch(quest.plan_thread_id);
    if (!thread?.isThread?.()) return;
    if (thread.archived) await wakeThread(thread);
    const pipeline = new Set(Object.values(map));
    const keep = (thread.appliedTags ?? []).filter(id => !pipeline.has(id));
    await thread.setAppliedTags([...keep, want].slice(0, 5));
    // The advance button on the starter follows the stage too.
    try {
      const starter = await thread.fetchStarterMessage();
      await starter.edit({ components: questStageRow(quest) });
    } catch { /* starter gone — nothing to keep current */ }
  } catch { /* tags are decoration — never fail the command over them */ }
}
const questRootNumber = (quest) => quest.instance_of ?? quest.number;

// The stage-advance button for a planning thread's starter. One press walks
// 🌱 Concept → ⏳ Awaiting Approval → ✅ Approved; at Approved it becomes a
// disabled signpost toward /quest post, and past the hand stages it is gone.
// ✅ / 🚪 beside an application, for the GM reading the planning thread.
function questApplicantRow(number, userId) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`questok:${number}:${userId}`).setLabel('✅ Approve').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`questkick:${number}:${userId}`).setLabel('🚪 Kick').setStyle(ButtonStyle.Danger))];
}

function questStageRow(quest) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  if (quest.stage === 'concept' || quest.stage === 'awaiting') {
    const next = quest.stage === 'concept'
      ? { emoji: '⏳', label: 'Advance → Awaiting Approval' }
      : { emoji: '✅', label: 'Advance → Approved' };
    return [new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`queststage:${quest.number}`)
        .setLabel(`${next.emoji} ${next.label}`).setStyle(ButtonStyle.Primary))];
  }
  if (quest.stage === 'approved') {
    return [new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`questpost:${quest.number}`)
        .setLabel('📌 Post to board').setStyle(ButtonStyle.Primary))];
  }
  return [];
}

// The pipeline books — one thread per section, the audit-forum pattern.
const QUEST_BOOKS = [
  ['concept',   '🌱', 'Concept',            'Quests being written. `/quest stage` moves them onward.'],
  ['awaiting',  '⏳', 'Awaiting Approval',   'Concepts waiting on a nod.'],
  ['approved',  '✅', 'Approved',            'Ready to run — `/quest post` opens them on the public board (marked 📌 here while listed).'],
  ['running',   '⚔️', 'In Progress',         'Every run happening right now — its DM, its party, its room and how long the clock has been going.'],
  ['dms',       '🎲', 'DMs Available',       'Who can run for you, their style, and a short brief. GMs: `/quest dm`.'],
  ['archived',  '🗄️', 'Archived',            'Off the board. `/quest post` re-lists any of them.'],
  ['completed', '🏁', 'Completed',           'Every finished adventure, with its run counter.'],
];
const questBooks = (gid) => { try { return JSON.parse(getConfig(gid)?.quest_plan_books || '{}'); } catch { return {}; } };
// A started quest lives in ⚔️ In Progress until it completes — its stage
// still says where it came from, but the board is not where it IS.
const questBookKeyFor = (quest) => {
  const stage = typeof quest === 'string' ? quest : quest?.stage;
  const status = typeof quest === 'string' ? null : quest?.status;
  if (status === 'active' || status === 'paused') return 'running';
  return stage === 'board' ? 'approved' : stage;
};

// One index entry per quest: name · GM · party · links, run counter when done.
async function questIndexEntry(guild, gid, quest) {
  const gmName = quest.gm_id ? await getDisplayName(guild, quest.gm_id) : '—';
  const party = getQuestMembers(gid, quest.number, 'party').length;
  const cap = quest.party_size ? `/${quest.party_size}` : '';
  const bits = [`**${questTag(quest)}**${quest.stage === 'board' ? ' 📌 on the board' : ''}`,
    `🎲 GM **${gmName}** · 👥 ${party}${cap}`];
  if (quest.stage === 'completed') {
    const root = questRootNumber(quest);
    const runs = db.prepare('SELECT COUNT(*) AS c FROM quest_runs WHERE guild_id=? AND root_number=?').get(gid, root).c;
    bits.push(`🏁 completed ×${runs}`);
  }
  const links = [];
  if (quest.plan_thread_id) links.push(`🗺️ <#${quest.plan_thread_id}>`);
  if (quest.post_channel_id) links.push(`📌 <#${quest.post_channel_id}>`);
  if (quest.run_thread_id) links.push(`🚪 <#${quest.run_thread_id}>`);
  if (links.length) bits.push(links.join(' · '));
  // A live run says how long it has been going; anything else says how long
  // it has sat where it is, so a concept from June stops looking like one
  // written this morning.
  if (quest.status === 'active' || quest.status === 'paused') {
    bits.push(`⏱️ running ${fmtElapsed(questElapsed(quest))}${quest.paused ? ' · ⏸️ paused' : ''}`);
  } else if (quest.stage_at) {
    const days = Math.floor((Date.now() - quest.stage_at) / 86400000);
    if (days >= 3) bits.push(`📅 here ${days} day${days === 1 ? '' : 's'}`);
  }
  return bits.join('\n');
}

// Move (or refresh) a quest's index entry into the book its stage belongs to.
// Delete-and-repost keeps each book reading newest-last, like the audit books.
async function syncQuestBook(client, guild, gid, questRow) {
  const quest = getQuest(gid, questRow.number) ?? questRow;
  const books = questBooks(gid);
  const key = questBookKeyFor(quest);
  const bookId = key ? books[key] : null;
  // Clear the old entry wherever it sits.
  if (quest.index_thread_id && quest.index_msg_id) {
    try {
      const old = await client.channels.fetch(quest.index_thread_id);
      if (old?.isThread?.()) { if (old.archived) await wakeThread(old); await old.messages.delete(quest.index_msg_id); }
    } catch { /* already gone */ }
  }
  if (!bookId) { updateQuest(gid, quest.number, { index_thread_id: null, index_msg_id: null }); return; }
  try {
    const book = await client.channels.fetch(bookId);
    if (!book?.isThread?.()) return;
    if (book.archived) await wakeThread(book);
    const msg = await book.send(await questIndexEntry(guild, gid, quest));
    updateQuest(gid, quest.number, { index_thread_id: book.id, index_msg_id: msg.id });
  } catch { /* the kanban is decoration — never fail the command over it */ }
}

// The one live status line in the planning thread: each stage push deletes
// the previous line and posts the new — the thread never accumulates the
// walk, only where the quest stands now. Decoration-grade: any failure is
// swallowed and the command carries on.
async function announceStage(client, gid, quest, line) {
  if (!quest.plan_thread_id) return;
  try {
    const th = await client.channels.fetch(quest.plan_thread_id);
    if (!th?.isThread?.()) return;
    if (th.archived) await wakeThread(th);
    if (quest.stage_msg_id) { try { await th.messages.delete(quest.stage_msg_id); } catch { /* already gone */ } }
    const msg = await th.send(line);
    updateQuest(gid, quest.number, { stage_msg_id: msg.id });
  } catch { /* the status line is decoration */ }
}

// Every channel trace one quest owns, deleted in one call: the board
// thread (or post), the planning thread whole, the book entry, the create
// card. Used by /quest delete for the quest AND each of its instances.
async function sweepQuestChannels(client, gid, quest) {
  if (quest.post_channel_id) {
    try {
      const ch = await client.channels.fetch(quest.post_channel_id);
      if (ch?.isThread?.()) await ch.delete('quest deleted');
      else if (quest.post_message_id) { const m = await ch.messages.fetch(quest.post_message_id); await m.delete(); }
    } catch { /* already gone */ }
  }
  if (quest.plan_thread_id) {
    try {
      const th = await client.channels.fetch(quest.plan_thread_id);
      if (th?.isThread?.()) await th.delete('quest deleted');
    } catch { /* already gone */ }
  }
  if (quest.index_thread_id && quest.index_msg_id) {
    try {
      const bk = await client.channels.fetch(quest.index_thread_id);
      if (bk?.isThread?.()) { if (bk.archived) await wakeThread(bk); await bk.messages.delete(quest.index_msg_id); }
    } catch { /* already gone */ }
  }
  await sweepCreateCard(client, gid, quest);
}

// Build anything missing, then say plainly what changed and what was
// already there. Safe to run as often as you like: surviving threads are
// adopted by id, never remade.
async function runSetupRepair(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id))) {
    return interaction.reply({ content: '❌ The setup check is for GMs.', ephemeral: true });
  }
  await interaction.deferReply({ ephemeral: true });
  const lines = ['🔧 **Setup run**', ''];
  let built = 0;

  const audit = await ensureAuditBooks(interaction.client, gid).catch(err => ({ error: err?.message || String(err) }));
  if (!audit) lines.push('🎲 Roll audit forum — _not set; `/config channels rollauditforum` first_');
  else if (audit.error) lines.push(`🎲 Roll audit forum — ⚠️ ${audit.error}`);
  else {
    built += audit.made.length;
    lines.push(audit.made.length
      ? `🎲 Roll audit forum — **built ${audit.made.length}**: ${audit.made.join(', ')}`
      : `🎲 Roll audit forum — all ${audit.kept.length} shelves already there`);
  }

  const quests = await ensureQuestBooks(interaction.client, interaction.guild, gid).catch(err => ({ error: err?.message || String(err) }));
  if (!quests) lines.push('🗺️ Quest planning forum — _not set; `/config channels questplanning` first_');
  else if (quests.error) lines.push(`🗺️ Quest planning forum — ⚠️ ${quests.error}`);
  else {
    built += quests.made.length;
    lines.push(quests.made.length
      ? `🗺️ Quest pipeline — **built ${quests.made.length}**: ${quests.made.join(', ')}`
      : `🗺️ Quest pipeline — all ${quests.kept.length} books already there`);
  }

  // Tags follow the books — whichever forum the threads live in.
  try {
    const tagForumId = getConfig(gid)?.quest_thread_forum ?? getConfig(gid)?.quest_plan_forum;
    if (tagForumId) {
      const tagForum = await interaction.client.channels.fetch(tagForumId).catch(() => null);
      if (tagForum) { await ensurePlanTags(tagForum, gid); lines.push('🏷️ Pipeline tags — checked'); }
    }
  } catch (err) { lines.push(`🏷️ Pipeline tags — ⚠️ ${err?.message || err}`); }

  lines.push('', built ? `✅ Built **${built}** new thing${built === 1 ? '' : 's'}. Nothing existing was touched.`
                       : '✅ Everything the code knows about is already here.');
  lines.push('_Run this again after any update that adds a book._');
  return interaction.editReply({ content: lines.join('\n').slice(0, 1990) });
}

// Discord refuses a message whose allowed-mentions list repeats an id — and
// a DM is very often on their own party. Every list built from more than one
// place goes through here.
const mentionList = (...ids) => [...new Set(ids.flat().filter(Boolean))];

// Sweep the create card out of its channel — called when the board takes
// over (post) or the quest dies (delete). Best-effort.
async function sweepCreateCard(client, gid, quest) {
  if (!quest.create_channel_id || !quest.create_msg_id) return;
  try {
    const ch = await client.channels.fetch(quest.create_channel_id);
    await ch.messages.delete(quest.create_msg_id);
  } catch { /* already gone */ }
  updateQuest(gid, quest.number, { create_msg_id: null, create_channel_id: null });
}

// ➕ / ↩️ on a run's own card — a player can ask to join THIS table, or
// step back out, without going near the board.
function questJoinRow(number) {
  const { ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
  return [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`qapply:${number}`).setLabel('➕ Ask to join').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`qwithdraw:${number}`).setLabel('↩️ Withdraw').setStyle(ButtonStyle.Secondary))];
}

// The next free run seat for an adventure — the original is 1.
function nextRunSeq(gid, root) {
  const seqs = db.prepare('SELECT run_seq FROM quests WHERE guild_id=? AND instance_of=?').all(gid, root)
    .map(r => r.run_seq).filter(Number.isFinite);
  return (seqs.length ? Math.max(...seqs) : 1) + 1;
}

// Birth a run from a board quest: the writing is copied, the approved
// player seated, everyone still waiting carried across so nobody loses
// their place, and the board entry emptied for the next batch. Returns the
// new quest, or null when the copy fails.
async function spinOffRun(interaction, gid, root, approvedId) {
  const number = createQuest(gid, {
    name: root.name, objectives: root.objectives, lore: root.lore, details: root.details,
    rewards: root.rewards, merit_reward: root.merit_reward,
    party_size: root.party_size, party_hard: root.party_hard, created_by: interaction.user.id,
  });
  if (!number) return null;
  const rootNum = root.instance_of ?? root.number;
  updateQuest(gid, number, {
    gm_id: interaction.user.id, gm_style: root.gm_style ?? null,
    instance_of: rootNum, run_seq: nextRunSeq(gid, rootNum), stage: 'approved', stage_at: Date.now(),
  });
  // The approved player takes their seat; everyone still waiting comes too.
  setQuestMember(gid, number, approvedId, 'party');
  const waiting = getQuestMembers(gid, root.number, 'applied').filter(id => id !== approvedId);
  for (const id of waiting) setQuestMember(gid, number, id, 'applied');
  // And the board is clean again — same entry, same number, no party.
  for (const id of [...waiting, approvedId]) removeQuestMember(gid, root.number, id);
  for (const id of getQuestMembers(gid, root.number)) removeQuestMember(gid, root.number, id);
  updateQuest(gid, root.number, { full_pinged: 0 });

  const quest = getQuest(gid, number);
  const room = (await openRunThread(interaction.client, interaction.guild, gid, quest)).thread;
  const card = await renderQuest(interaction.guild, quest, { applyHint: false });
  const body = [`⚔️ **${questTag(quest)}** — this run is forming.`, '', card, '',
    '_Anyone may ask to join this run with the button; the DM decides._'].join('\n');
  if (room) {
    try { await room.send({ content: body, components: questJoinRow(number) }); } catch {}
  }
  await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, root.number));
  await syncQuestBook(interaction.client, interaction.guild, gid, quest);
  return { quest, room };
}

// Enough hands. Said once per quest, in the planning thread, to whoever
// holds it — approving the sixth of five shouldn't nag twice.
async function nudgeIfPartyFull(client, gid, quest) {
  if (!quest?.party_size || quest.full_pinged) return;
  const party = getQuestMembers(gid, quest.number, 'party');
  if (party.length < quest.party_size) return;
  updateQuest(gid, quest.number, { full_pinged: 1 });
  const who = quest.gm_id ? `<@${quest.gm_id}>` : 'GMs';
  await announceStage(client, gid, getQuest(gid, quest.number),
    `👥 **Party full** — ${party.length}/${quest.party_size}. ${who}, start it with \`/quest run start number:${quest.number}\` when you're ready.`);
}

// The party's own room. One thread per started quest in the instance forum,
// the DM and every member pulled in by mention so it lands in their sidebar.
// Best-effort: no forum, no room, and the quest runs exactly as before.
// Returns { thread, why } — `why` is a line the GM can act on when no room
// opened. Silence was the bug here: an unset forum, a channel that isn't a
// forum any more, and a missing permission all looked identical.
async function openRunThread(client, guild, gid, quest) {
  const forumId = getConfig(gid)?.quest_instance_forum;
  if (!forumId) return { thread: null, why: 'No instance forum is set — `/config channels questinstances channel:#your-forum` gives every party its own room.' };
  if (quest.run_thread_id) return { thread: null, why: null };
  try {
    const forum = await client.channels.fetch(forumId).catch(() => null);
    if (!forum) return { thread: null, why: `I can't see <#${forumId}> — check my access, or set the instance forum again.` };
    if (forum.type !== 15) return { thread: null, why: `<#${forumId}> isn't a forum channel any more — point \`/config channels questinstances\` at a **Forum**.` };
    const party = getQuestMembers(gid, quest.number, 'party');
    const roll = [];
    for (const id of party) roll.push(`<@${id}>`);
    const thread = await forum.threads.create({
      name: questTag(quest).slice(0, 100),
      autoArchiveDuration: 10080,
      message: { content: [
        `⚔️ **${questTag(quest)}** — the party assembles.`,
        quest.gm_id ? `🎲 DM: <@${quest.gm_id}>` : '',
        roll.length ? `👥 ${roll.join(' ')}` : '',
        '', '_This is your room: rolls, planning and the run itself. `/quest rally` calls everyone back._',
      ].filter(Boolean).join('\n'), allowedMentions: { users: mentionList(party, quest.gm_id) } },
    });
    updateQuest(gid, quest.number, { run_thread_id: thread.id, run_channel_id: thread.id });
    return { thread, why: null };
  } catch (err) {
    console.error('[quest] instance thread failed -', err?.message || err);
    const msg = String(err?.message || err);
    return { thread: null, why: /permission/i.test(msg)
      ? `I need **Create Posts** (and **Send Messages**) in <#${forumId}> to open the party's room.`
      : `Couldn't open the party's room in <#${forumId}> — ${msg}` };
  }
}

// Stage tag + book entry in one call — the single pipeline sync.
async function syncQuestPipeline(client, guild, gid, quest) {
  await syncPlanStage(client, gid, quest);
  await syncQuestBook(client, guild, gid, quest);
}

// Re-render the 🎲 DMs Available roster thread's starter from gm_profiles.
// Best-effort; a missing thread just means the roster isn't set up yet.
async function refreshDmRoster(client, guild, gid) {
  const threadId = questBooks(gid).dms ?? getConfig(gid)?.quest_dm_thread;
  if (!threadId) return false;
  try {
    const thread = await client.channels.fetch(threadId);
    if (!thread?.isThread?.()) return false;
    if (thread.archived) await wakeThread(thread);
    const rows = db.prepare('SELECT user_id, style, brief, available FROM gm_profiles WHERE guild_id=? ORDER BY available DESC, user_id').all(gid);
    const lines = ['🎲 **DMs Available**', ''];
    const avail = rows.filter(r => r.available);
    const away = rows.filter(r => !r.available);
    if (!avail.length) lines.push('_No DMs available right now._');
    for (const r of avail) {
      const nm = await getDisplayName(guild, r.user_id);
      // The tracker: quests they have authored (roots only — instances copy
      // someone else's writing) and parties they have guided to completion.
      const written = db.prepare('SELECT COUNT(*) AS c FROM quests WHERE guild_id=? AND created_by=? AND instance_of IS NULL').get(gid, r.user_id).c;
      const guided = db.prepare('SELECT COUNT(*) AS c FROM quest_runs WHERE guild_id=? AND gm_id=?').get(gid, r.user_id).c;
      lines.push(`**${nm}**${r.style ? ` — _${r.style}_` : ''}`);
      lines.push(`✍️ **${written}** written · 🧭 **${guided}** guided`);
      if (r.brief) lines.push(`> ${r.brief}`);
      lines.push('');
    }
    if (away.length) {
      const names = [];
      for (const r of away) names.push(await getDisplayName(guild, r.user_id));
      lines.push(`_Currently away: ${names.join(', ')}_`);
    }
    lines.push('', '_GMs: `/quest dm style:... brief:...` puts your card here; `available:false` steps back._');
    const starter = await thread.fetchStarterMessage();
    await starter.edit({ content: lines.join('\n').slice(0, 2000) });
    return true;
  } catch { return false; }
}

// A quest speaks in two places: its public board thread (when the board is a
// forum) and its GM planning thread. One-line lifecycle mirrors go to both,
// each woken first. Fire-safe — a missing or deleted thread is ignored.
async function questAnnounce(client, quest, line, { board = true, plan = true, planComponents = null, room = true } = {}) {
  const targets = [];
  if (board && quest.post_channel_id) targets.push(quest.post_channel_id);
  if (plan && quest.plan_thread_id && quest.plan_thread_id !== quest.post_channel_id) targets.push(quest.plan_thread_id);
  for (const id of targets) {
    try {
      const ch = await client.channels.fetch(id);
      if (!ch?.isThread?.()) continue;   // plain-channel posts don't get mirrors
      await wakeThread(ch);
      await ch.send(id === quest.plan_thread_id && planComponents
        ? { content: line, components: planComponents } : line);
    } catch { /* thread gone or unreadable — the mirror is best-effort */ }
  }
  // A run with its own room hears everything there too — for an instance
  // that's where the DM is reading, and the approve/kick buttons ride along.
  if (room && quest.run_thread_id && quest.run_thread_id !== quest.plan_thread_id) {
    try {
      const th = await client.channels.fetch(quest.run_thread_id);
      if (th?.isThread?.()) {
        await wakeThread(th);
        await th.send(planComponents ? { content: line, components: planComponents } : line);
      }
    } catch { /* the room is best-effort too */ }
  }
}

// Refresh a quest's posted message in place, if one exists.
async function refreshQuestPost(client, guild, quest) {
  if (!quest.post_channel_id || !quest.post_message_id) return;
  try {
    const ch = await client.channels.fetch(quest.post_channel_id);
    if (ch?.isThread?.() && ch.archived) await wakeThread(ch);
    const msg = await ch.messages.fetch(quest.post_message_id);
    const components = quest.status === 'open' ? [questApplyButton(quest.number)] : [];
    await msg.edit({ content: await renderQuest(guild, quest), components });
  } catch { /* message deleted or inaccessible — ignore */ }
}

// Shared apply logic for both the slash command and the button.
async function questApply(guild, quest, uid) {
  const gid = guild.id;
  if (quest.status !== 'open') return { error: '❌ This quest isn\'t open for applications.' };
  const members = getQuestMembers(gid, quest.number);
  const mine = members.find(m => m.user_id === uid);
  if (mine?.state === 'party') return { error: 'You\'re already on this quest\'s party.' };
  if (mine?.state === 'applied') return { error: 'You\'ve already applied — hang tight for the GM.' };
  setQuestMember(gid, quest.number, uid, 'applied');
  await questAnnounce(guild.client, quest, `⏳ **${await getDisplayName(guild, uid)}** applied to join.`,
    { planComponents: questApplicantRow(quest.number, uid) });
  return { ok: `⏳ Applied to **${questTag(quest)}**. A GM will review.` };
}
async function questWithdraw(guild, quest, uid) {
  const gid = guild.id;
  const removed = removeQuestMember(gid, quest.number, uid);
  if (!removed) return { error: 'You\'re not on this quest.' };
  await questAnnounce(guild.client, quest, `↩️ **${await getDisplayName(guild, uid)}** withdrew.`);
  return { ok: `↩️ Withdrawn from **${questTag(quest)}**.` };
}

// ── QUEST command ─────────────────────────────────────────────────────────────
// One modal text row — shared by the quest create and edit windows.
function questTextRow(id, label, style, required, value) {
  const { ActionRowBuilder, TextInputBuilder } = require('discord.js');
  const t = new TextInputBuilder().setCustomId(id).setLabel(label).setStyle(style)
    .setRequired(required).setMaxLength(id === 'name' ? 80 : 4000);
  if (value) t.setValue(String(value).slice(0, id === 'name' ? 80 : 4000));
  return new ActionRowBuilder().addComponents(t);
}

// The creation flow proper — slash path and modal path land here alike.
async function finishQuestCreate(interaction, gid, uid, f) {
  const name = (f.name || '').trim();
  if (!name || name.length > 80) return interaction.reply({ content: '❌ Quest name must be 1–80 characters.', ephemeral: true });
  // Forum thread creation can outlast the 3-second window — acknowledge first.
  if (!interaction.deferred && !interaction.replied) await interaction.deferReply();
  const number = createQuest(gid, {
    name,
    objectives: f.objectives ?? null,
    lore: f.lore ?? null,
    details: f.details ?? null,
    rewards: f.rewards ?? null,
    merit_reward: f.merit_reward ?? 0,
    party_size: f.party_size ?? null,
    party_hard: f.party_hard ?? false,
    created_by: uid,
  });
  updateQuest(gid, number, { gm_id: uid, gm_style: f.gm_style ?? null, stage: 'concept', stage_at: Date.now() });
  let quest = getQuest(gid, number);
  let planLine = '';
  const planForumId = getConfig(gid)?.quest_thread_forum ?? getConfig(gid)?.quest_plan_forum;
  if (planForumId) {
    try {
      const forum = await interaction.client.channels.fetch(planForumId);
      const tagMap = JSON.parse(getConfig(gid)?.quest_plan_tags || '{}');
      const thread = await forum.threads.create({ name: `#${number} — ${quest.name}`.slice(0, 100), autoArchiveDuration: 10080,
        appliedTags: tagMap.concept ? [tagMap.concept] : [],
        message: { components: questStageRow(quest), content: `🗺️ **GM planning** — ${questTag(quest)}\n\n${await renderQuest(interaction.guild, quest, { applyHint: false })}\n\n_Draft. \`/quest post number:${number}\` opens it on the public board; every application and turn of the quest will be mirrored here._` } });
      updateQuest(gid, number, { plan_thread_id: thread.id });
      quest = getQuest(gid, number);
      await syncQuestBook(interaction.client, interaction.guild, gid, quest);
      quest = getQuest(gid, number);
      planLine = `\n🗺️ Planning thread: <#${thread.id}>`;
    } catch (err) {
      planLine = `\n⚠️ Couldn't open a planning thread — ${err?.message || err}. Check my forum permissions there.`;
    }
  }
  await refreshDmRoster(interaction.client, interaction.guild, gid);
  await interaction.editReply({ content: `✅ Created **${questTag(quest)}**.${planLine}\n\n${await renderQuest(interaction.guild, quest, { applyHint: false })}\n\n_Post it with_ \`/quest post number:${number}\` _— or walk the stages below._`,
    components: questStageRow(quest) });
  try { // remember the card so posting can sweep it — the board takes over then
    const rep = await interaction.fetchReply();
    updateQuest(gid, number, { create_msg_id: rep.id, create_channel_id: rep.channelId });
  } catch { /* ephemeral-ish edge — the sweep just won't find it */ }
  return;
}

async function handleQuest(interaction, forced) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const sub = (forced && typeof forced === 'object') ? forced.sub : interaction.options.getSubcommand();
  const gm = await isGm(interaction.guild, uid);

  // Player-facing reads first
  if (sub === 'board') {
    const filter = interaction.options?.getString?.('filter') ?? 'open';
    const quests = filter === 'all' ? listQuests(gid) : listQuests(gid, filter);
    if (!quests.length) return interaction.reply({ content: `📋 No ${filter === 'all' ? '' : filter + ' '}quests on the board.`, ephemeral: true });
    const lines = [`📜 **Quest Board** — ${filter === 'all' ? 'all quests' : filter}`, ''];
    for (const q of quests) {
      const party = getQuestMembers(gid, q.number, 'party').length;
      const cap = q.party_size ? `${party}/${q.party_size}${q.party_hard ? '' : '~'}` : `${party}`;
      const merit = q.merit_reward > 0 ? ` · 🎖️${q.merit_reward}` : '';
      lines.push(`${questStatusBadge(q.status)} **${questTag(q)}** — 👥 ${cap}${merit}`);
    }
    lines.push('', '_Use_ `/quest show number:N` _for full details._');
    return replyLong(interaction, lines);
  }

  if (sub === 'show' || sub === 'roster') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    if (sub === 'show') return interaction.reply({ content: await renderQuest(interaction.guild, quest) });
    // roster
    const party = getQuestMembers(gid, number, 'party');
    const applied = getQuestMembers(gid, number, 'applied');
    const lines = [`👥 **${questTag(quest)}** — roster`, ''];
    if (party.length) {
      lines.push('**Party:**');
      for (const id of party) lines.push(`✅ ${await getDisplayName(interaction.guild, id)}`);
    } else lines.push('_No party members yet._');
    if (applied.length) {
      lines.push('', '**Applicants:**');
      for (const id of applied) lines.push(`⏳ ${await getDisplayName(interaction.guild, id)}`);
    }
    return interaction.reply({ content: lines.join('\n') });
  }

  if (sub === 'apply' || sub === 'withdraw') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    // Withdrawing is always allowed — a fallen character should still be able to
    // come off a roster. Signing up for new work is not.
    if (sub === 'apply' && isFallen(gid, uid))
      return interaction.reply({ content: '🕯️ Your character has fallen and cannot take on new work. A GM can bring them back with `/gm revive`.', ephemeral: true });
    const res = sub === 'apply' ? await questApply(interaction.guild, quest, uid) : await questWithdraw(interaction.guild, quest, uid);
    if (res.error) return interaction.reply({ content: res.error, ephemeral: true });
    await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, number));
    return interaction.reply({ content: res.ok, ephemeral: true });
  }

  if (sub === 'log') {
    const target = interaction.options?.getUser?.('user') ?? interaction.user;
    const done = getPlayerCompletedQuests(gid, target.id);
    const nm = await getDisplayName(interaction.guild, target.id);
    if (!done.length) return interaction.reply({ content: `📋 **${nm}** hasn't completed any quests yet.`, ephemeral: true });
    const totalMerits = done.reduce((a, q) => a + (q.merit_reward ?? 0), 0);
    const lines = [`📜 **${nm}** — ${done.length} completed quest${done.length === 1 ? '' : 's'}${totalMerits ? ` · 🎖️ ${totalMerits} earned from quests` : ''}`, ''];
    for (const q of done) {
      const merit = q.merit_reward > 0 ? ` · 🎖️${q.merit_reward}` : '';
      lines.push(`🔵 **${questTag(q)}**${merit}`);
    }
    return replyLong(interaction, lines);
  }

  // ── GM-only from here ──
  if (!gm) return interaction.reply({ content: '❌ Only GMs can manage quests.', ephemeral: true });

  if (sub === 'create') {
    const fromN = interaction.options?.getInteger?.('from');
    const srcQ = fromN ? getQuest(gid, fromN) : null;
    if (fromN && !srcQ) return interaction.reply({ content: `❌ No quest #${String(fromN).padStart(3, '0')} to copy from.`, ephemeral: true });
    const f = {
      name: interaction.options?.getString?.('name')?.trim() || null,
      objectives: interaction.options?.getString?.('objectives') ?? srcQ?.objectives ?? null,
      lore: interaction.options?.getString?.('lore') ?? srcQ?.lore ?? null,
      details: interaction.options?.getString?.('details') ?? srcQ?.details ?? null,
      rewards: interaction.options?.getString?.('rewards') ?? srcQ?.rewards ?? null,
      merit_reward: interaction.options?.getInteger?.('merit_reward') ?? srcQ?.merit_reward ?? 0,
      party_size: interaction.options?.getInteger?.('party_size') ?? srcQ?.party_size ?? null,
      party_hard: interaction.options?.getBoolean?.('hard_cap') ?? (srcQ ? !!srcQ.party_hard : false),
      gm_style: interaction.options?.getString?.('gm_style') ?? srcQ?.gm_style ?? null,
    };
    if (!f.name) {
      // No name given — open the writing window. The numeric choices ride the
      // customId so the modal submit can carry them into the creation.
      const { ModalBuilder, TextInputStyle } = require('discord.js');
      const modal = new ModalBuilder()
        .setCustomId(`questcreate:${f.merit_reward}:${f.party_size ?? ''}:${f.party_hard ? 1 : 0}:${f.gm_style ?? ''}`)
        .setTitle(srcQ ? `New quest from #${fromN}`.slice(0, 45) : 'Write a quest')
        .addComponents(
          questTextRow('name', 'Quest name', TextInputStyle.Short, true, srcQ ? `${srcQ.name} (copy)` : null),
          questTextRow('objectives', 'Objectives — what the party must do', TextInputStyle.Paragraph, false, f.objectives),
          questTextRow('lore', 'Lore / background', TextInputStyle.Paragraph, false, f.lore),
          questTextRow('details', 'Details / conditions', TextInputStyle.Paragraph, false, f.details),
          questTextRow('rewards', 'Rewards, distributed by the GM', TextInputStyle.Paragraph, false, f.rewards),
        );
      return interaction.showModal(modal);
    }
    return finishQuestCreate(interaction, gid, uid, f);
  }

  if (sub === 'edit') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const mr = interaction.options?.getInteger?.('merit_reward');
    const ps = interaction.options?.getInteger?.('party_size');
    const hc = interaction.options?.getBoolean?.('hard_cap');
    const gs = interaction.options?.getString?.('gm_style');
    if (mr !== null || ps !== null || hc !== null || gs !== null) {
      // Numeric tweaks apply on the spot — no modal needed.
      const upd = {};
      if (mr !== null) upd.merit_reward = mr;
      if (ps !== null) upd.party_size = ps;
      if (hc !== null) upd.party_hard = hc ? 1 : 0;
      if (gs !== null) upd.gm_style = gs;
      updateQuest(gid, quest.number, upd);
      const fresh = getQuest(gid, quest.number);
      await refreshQuestPost(interaction.client, interaction.guild, fresh);
      await syncQuestBook(interaction.client, interaction.guild, gid, fresh);
      await questAnnounce(interaction.client, fresh, '✏️ Quest numbers updated.', { board: false });
      return interaction.reply({ content: `✏️ **${questTag(fresh)}** updated.\n\n${await renderQuest(interaction.guild, fresh)}` });
    }
    // Bare edit — the writing window again, prefilled with what stands.
    const { ModalBuilder, TextInputStyle } = require('discord.js');
    const modal = new ModalBuilder()
      .setCustomId(`questedit:${quest.number}`)
      .setTitle(`Edit #${String(quest.number).padStart(3, '0')}`.slice(0, 45))
      .addComponents(
        questTextRow('name', 'Quest name', TextInputStyle.Short, true, quest.name),
        questTextRow('objectives', 'Objectives — what the party must do', TextInputStyle.Paragraph, false, quest.objectives),
        questTextRow('lore', 'Lore / background', TextInputStyle.Paragraph, false, quest.lore),
        questTextRow('details', 'Details / conditions', TextInputStyle.Paragraph, false, quest.details),
        questTextRow('rewards', 'Rewards, distributed by the GM', TextInputStyle.Paragraph, false, quest.rewards),
      );
    return interaction.showModal(modal);
  }

  if (sub === 'post') {
    let quest = await requireQuest(interaction, gid, forced?.number);
    if (!quest) return;
    const number = quest.number;
    const explicit = interaction.options?.getChannel?.('channel');
    const forumId = getConfig(gid)?.quest_forum;
    if (forumId && !explicit) {
      // The board is a forum: this quest gets (or already has) its own thread.
      try {
        const forum = await interaction.client.channels.fetch(forumId);
        if (quest.status === 'archived') {
          // Re-listing an archived quest: applications reopen.
          updateQuest(gid, number, { status: 'open' });
          quest = getQuest(gid, number);
        }
        if (quest.post_channel_id) {
          const old = await interaction.client.channels.fetch(quest.post_channel_id).catch(() => null);
          if (old?.isThread?.() && old.parentId === forum.id) {
            await old.setLocked(false).catch(() => {});
            await wakeThread(old);
            await refreshQuestPost(interaction.client, interaction.guild, quest);
            updateQuest(gid, number, { stage: 'board', stage_at: Date.now() });
            await syncQuestPipeline(interaction.client, interaction.guild, gid, getQuest(gid, number));
            return interaction.reply({ content: `📌 **${questTag(quest)}** is ${quest.status === 'open' ? 'back on' : 'already on'} the board — <#${old.id}> (refreshed).`, ephemeral: true });
          }
        }
        const components = quest.status === 'open' ? [questApplyButton(number)] : [];
        const thread = await forum.threads.create({ name: `#${number} — ${quest.name}`.slice(0, 100), autoArchiveDuration: 10080,
          message: { content: await renderQuest(interaction.guild, quest), components } });
        // A forum starter message shares its thread's id — the refresh plumbing
        // needs nothing new.
        updateQuest(gid, number, { post_channel_id: thread.id, post_message_id: thread.id, stage: 'board', stage_at: Date.now() });
        await syncQuestPipeline(interaction.client, interaction.guild, gid, getQuest(gid, number));
        await announceStage(interaction.client, gid, getQuest(gid, number), `📌 Opened on the public board — <#${thread.id}>.`);
        await sweepCreateCard(interaction.client, gid, getQuest(gid, number));
        return interaction.reply({ content: `📌 **${questTag(quest)}** is on the board — <#${thread.id}>.`, ephemeral: true });
      } catch (err) {
        return interaction.reply({ content: `❌ Couldn't open the board thread — ${err?.message || err}. Check my **Create Posts** and **Send Messages in Posts** permissions in <#${forumId}>, or pass a \`channel:\` to post plainly.`, ephemeral: true });
      }
    }
    const channel = explicit ?? await interactionChannel(interaction);
    if (!channel) return interaction.reply({ content: '❌ I can\'t access that channel. Pick one explicitly with `channel:`.', ephemeral: true });
    if (!channel.isTextBased?.() && !channel.isThread?.()) return interaction.reply({ content: '❌ Pick a text channel or thread.', ephemeral: true });
    const components = quest.status === 'open' ? [questApplyButton(number)] : [];
    const msg = await channel.send({ content: await renderQuest(interaction.guild, quest), components });
    updateQuest(gid, number, { post_channel_id: channel.id, post_message_id: msg.id });
    return interaction.reply({ content: `📌 Posted **${questTag(quest)}** to <#${channel.id}>.`, ephemeral: true });
  }

  if (sub === 'runchannel') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    const channel = interaction.options?.getChannel?.('channel') ?? await interactionChannel(interaction);
    if (!channel) return interaction.reply({ content: '❌ I can\'t access that channel. Pick one explicitly with `channel:`.', ephemeral: true });
    updateQuest(gid, number, { run_channel_id: channel.id });
    await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, number));
    return interaction.reply({ content: `📍 **${questTag(quest)}** will be run and rewarded in <#${channel.id}>.` });
  }

  if (sub === 'approve') {
    const quest = await requireQuest(interaction, gid, forced?.number);
    if (!quest) return;
    const number = quest.number;
    const target = forced?.userId ? { id: forced.userId } : interaction.options?.getUser?.('user');
    const force = interaction.options?.getBoolean?.('force') ?? false;
    const party = getQuestMembers(gid, number, 'party');
    if (party.includes(target.id)) return interaction.reply({ content: 'They\'re already on the party.', ephemeral: true });
    // A GM can still do it — but knowingly, not by forgetting.
    if (isFallen(gid, target.id) && !force) {
      return interaction.reply({ ephemeral: true, content:
        `🕯️ **${await getDisplayName(interaction.guild, target.id)}** has fallen. Bring them back with \`/gm revive\`, or re-run with \`force:true\` if they are joining as a ghost.` });
    }
    if (quest.party_size && quest.party_hard && party.length >= quest.party_size && !force) {
      return interaction.reply({ content: `❌ Party is at the hard cap (${quest.party_size}). Re-run with \`force:true\` to override.`, ephemeral: true });
    }
    // With spin-off on, approving on a BOARD quest births its run instead of
    // filling the board entry — the entry stays open for the next group.
    if ((getConfig(gid)?.quest_spinoff ?? 0) && !quest.instance_of) {
      const born = await spinOffRun(interaction, gid, quest, target.id);
      if (born) {
        const nm2 = await getDisplayName(interaction.guild, target.id);
        return interaction.reply({ content:
          `⚔️ **${questTag(born.quest)}** begins forming with **${nm2}** — you're its DM.`
          + (born.room ? `\n🚪 Their room: <#${born.room.id}> — others can ask to join with the button there.` : '')
          + `\n📋 **${questTag(quest)}** is clear on the board for the next group.` });
      }
    }
    setQuestMember(gid, number, target.id, 'party');
    // Whoever opens the door runs the room — unless a GM already holds it.
    let tookIt = false;
    if (!quest.gm_id) { updateQuest(gid, number, { gm_id: uid }); tookIt = true; }
    await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, number));
    const nm = await getDisplayName(interaction.guild, target.id);
    const over = quest.party_size && party.length + 1 > quest.party_size ? ' (over suggested size)' : '';
    await questAnnounce(interaction.client, getQuest(gid, number), `✅ **${nm}** joins the party${over}.`);
    await syncQuestBook(interaction.client, interaction.guild, gid, getQuest(gid, number));
    await nudgeIfPartyFull(interaction.client, gid, getQuest(gid, number));
    return interaction.reply({ content: `✅ **${nm}** added to **${questTag(quest)}**${over}.`
      + (tookIt ? `\n🎲 You're the DM for this one now — \`/quest handoff\` passes it to another GM.` : '') });
  }

  if (sub === 'kick') {
    const quest = await requireQuest(interaction, gid, forced?.number);
    if (!quest) return;
    const number = quest.number;
    const target = (forced?.userId ? { id: forced.userId } : interaction.options?.getUser?.('user'));
    const removed = removeQuestMember(gid, number, target.id);
    if (!removed) return interaction.reply({ content: 'They\'re not on this quest.', ephemeral: true });
    await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, number));
    const nm = await getDisplayName(interaction.guild, target.id);
    await questAnnounce(interaction.client, getQuest(gid, number), `👢 **${nm}** was removed from the party.`);
    await syncQuestBook(interaction.client, interaction.guild, gid, getQuest(gid, number));
    return interaction.reply({ content: `👢 Removed **${nm}** from **${questTag(quest)}**.` });
  }

  if (sub === 'room') {
    const doAll = interaction.options?.getBoolean?.('all') ?? false;
    if (!doAll && interaction.options?.getInteger?.('number') === null) {
      return interaction.reply({ content: '❌ Name a quest with `number:`, or use `all:true` to catch every running quest at once.', ephemeral: true });
    }
    await interaction.deferReply();
    // Quests that started before the forum was set have no room — this is
    // the catch-up. Anything that already has one is left exactly as it is.
    const targets = doAll
      ? db.prepare("SELECT * FROM quests WHERE guild_id=? AND status IN ('active','paused') AND (run_thread_id IS NULL OR run_thread_id='')").all(gid)
      : [getQuest(gid, interaction.options.getInteger('number'))].filter(Boolean);
    if (!targets.length) {
      return interaction.editReply({ content: doAll
        ? '✅ Every running quest already has its room.'
        : '❌ No quest with that number.' });
    }
    const done = [], skipped = [];
    let why = null;
    for (const q of targets) {
      if (q.run_thread_id) { skipped.push(`${questTag(q)} — already has <#${q.run_thread_id}>`); continue; }
      const opened = await openRunThread(interaction.client, interaction.guild, gid, q);
      if (opened.thread) {
        done.push(`${questTag(q)} → <#${opened.thread.id}>`);
        await syncQuestBook(interaction.client, interaction.guild, gid, getQuest(gid, q.number));
      } else { why = opened.why; skipped.push(questTag(q)); }
    }
    const lines = [];
    if (done.length) lines.push(`🚪 **Rooms opened (${done.length}):**`, ...done.map(d => `• ${d}`));
    if (skipped.length) lines.push(`⚠️ **Not opened (${skipped.length}):**`, ...skipped.map(d => `• ${d}`));
    if (why) lines.push('', why);
    if (done.length) lines.push('', '_The party has been pulled in, and the clock and reminders now follow them there._');
    return interaction.editReply({ content: lines.join('\n').slice(0, 1990) });
  }

  if (sub === 'handoff') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const target = interaction.options?.getUser?.('gm');
    if (!(await isGm(interaction.guild, target.id))) {
      return interaction.reply({ content: `❌ <@${target.id}> isn't a GM here — give them the GM role first.`, ephemeral: true });
    }
    if (quest.gm_id === target.id) return interaction.reply({ content: 'They already run it.', ephemeral: true });
    updateQuest(gid, quest.number, { gm_id: target.id });
    const fresh = getQuest(gid, quest.number);
    await refreshQuestPost(interaction.client, interaction.guild, fresh);
    await syncQuestBook(interaction.client, interaction.guild, gid, fresh);
    const line = `🎲 **${questTag(quest)}** is now run by <@${target.id}>.`;
    await announceStage(interaction.client, gid, fresh, line);
    if (fresh.run_thread_id) {
      try {
        const th = await interaction.client.channels.fetch(fresh.run_thread_id);
        if (th?.isThread?.()) { if (th.archived) await wakeThread(th); await th.send({ content: line, allowedMentions: { users: [target.id] } }); }
      } catch { /* the room may be gone */ }
    }
    return interaction.reply({ content: line, allowedMentions: { users: [target.id] } });
  }

  if (sub === 'rally') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const party = getQuestMembers(gid, quest.number, 'party');
    if (!party.length) return interaction.reply({ content: '❌ Nobody on the party yet.', ephemeral: true });
    const note = interaction.options?.getString?.('message');
    const here = interaction.options?.getBoolean?.('here') ?? false;
    const lines = [`📣 **${questTag(quest)}** — ${party.map(id => `<@${id}>`).join(' ')}`];
    if (quest.gm_id) lines.push(`🎲 Your DM: <@${quest.gm_id}>`);
    lines.push(note ? `\n${note}` : '\n_Called to gather._');
    const payload = { content: lines.join('\n'), allowedMentions: { users: mentionList(party) } };
    let where = null;
    if (!here && quest.run_thread_id) {
      try {
        const th = await interaction.client.channels.fetch(quest.run_thread_id);
        if (th?.isThread?.()) { if (th.archived) await wakeThread(th); await th.send(payload); where = th.id; }
      } catch { /* the room is gone — fall back to here */ }
    }
    if (where) return interaction.reply({ ephemeral: true, content: `📣 Rallied ${party.length} in <#${where}>.` });
    return interaction.reply(payload);
  }

  if (sub === 'start') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    if (quest.status === 'completed') return interaction.reply({ content: '❌ That quest is already completed.', ephemeral: true });
    const party = getQuestMembers(gid, number, 'party');
    if (!party.length) return interaction.reply({ content: '❌ No party members yet — approve applicants first.', ephemeral: true });
    // Start the stopwatch fresh, and clear any log from a previous run.
    db.prepare('DELETE FROM quest_events WHERE guild_id=? AND number=?').run(gid, number);
    updateQuest(gid, number, { status: 'active', started_at: Date.now(), elapsed_ms: 0,
      paused: 0, last_tick_ms: 0, last_recap_ms: 0,
      // Whoever starts it is running it, unless one was already recorded.
      gm_id: quest.gm_id ?? uid });
    logQuestEvent(gid, number, 'start', `Quest begins — ${party.length} on the party`, uid);
    const opened = await openRunThread(interaction.client, interaction.guild, gid, getQuest(gid, number));
    const room = opened.thread;
    const fresh = getQuest(gid, number);
    await refreshQuestPost(interaction.client, interaction.guild, fresh);
    await syncQuestBook(interaction.client, interaction.guild, gid, fresh);
    await questAnnounce(interaction.client, fresh, `▶️ **Quest begins** — ${party.length} on the party. The clock is running.${room ? ` The party gathers in <#${room.id}>.` : ''}`);
    return interaction.reply({ content:
      `🟡 **${questTag(quest)}** is now in progress with ${party.length} member${party.length === 1 ? '' : 's'}. Applications are closed.\n`
      + (room ? `🚪 The party's room: <#${room.id}> — the clock and reminders run there. \`/quest rally\` calls them back.`
              : `⏱️ The clock is running${fresh.run_channel_id ? ` in <#${fresh.run_channel_id}>` : ''}.`)
      + (opened.why ? `\n⚠️ **No room opened.** ${opened.why}` : '') });
  }

  // A quest row carries one party, one clock and one status, so two GMs running
  // the same adventure need two rows. This copies the writing and leaves
  // everything else fresh — new number, empty party, clock at zero.
  if (sub === 'instance') {
    const from = interaction.options?.getInteger?.('number');
    const src = getQuest(gid, from);
    if (!src) return interaction.reply({ content: `❌ No quest #${String(from).padStart(3,'0')}.`, ephemeral: true });
    const number = createQuest(gid, {
      name: src.name, objectives: src.objectives, lore: src.lore, details: src.details,
      rewards: src.rewards, merit_reward: src.merit_reward,
      party_size: src.party_size, party_hard: src.party_hard, created_by: uid,
    });
    // Which run of this adventure is this? The original is 1; every copy
    // takes the next free seat, so deleting run 2 doesn't make two run 3s.
    const root = src.instance_of ?? from;
    const seqs = db.prepare('SELECT run_seq FROM quests WHERE guild_id=? AND instance_of=?').all(gid, root)
      .map(r => r.run_seq).filter(Number.isFinite);
    updateQuest(gid, number, {
      gm_id: uid,
      gm_style: interaction.options?.getString?.('gm_style') ?? src.gm_style ?? null,
      instance_of: root,
      run_seq: (seqs.length ? Math.max(...seqs) : 1) + 1,
      run_label: (interaction.options?.getString?.('label') || '').trim() || null,
    });
    const quest = getQuest(gid, number);
    const siblings = db.prepare('SELECT COUNT(*) AS c FROM quests WHERE guild_id=? AND (number=? OR instance_of=?)')
      .get(gid, quest.instance_of, quest.instance_of).c;
    return interaction.reply({ content:
      `✅ **${questTag(quest)}** — your own run of **${src.name}**, separate from any other.\n`
      + `_${siblings} run${siblings === 1 ? '' : 's'} of this adventure exist. Yours has its own party, clock and log._\n\n`
      + `${await renderQuest(interaction.guild, quest)}\n\n_Post it with_ \`/quest post number:${number}\`_._` });
  }

  if (sub === 'pause' || sub === 'resume') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    if (quest.status !== 'active') return interaction.reply({ content: '❌ That quest is not running.', ephemeral: true });
    const paused = !!quest.paused;
    if (sub === 'pause') {
      if (paused) return interaction.reply({ content: '❌ It is already paused.', ephemeral: true });
      // Bank the running stretch, then stop the clock.
      updateQuest(gid, number, { elapsed_ms: questElapsed(quest), paused: 1, started_at: null });
      await syncQuestBook(interaction.client, interaction.guild, gid, getQuest(gid, number));
      logQuestEvent(gid, number, 'pause', 'Paused', uid);
      await questAnnounce(interaction.client, getQuest(gid, number), `⏸️ Paused at **${fmtElapsed(questElapsed(getQuest(gid, number)))}**.`);
      return interaction.reply({ content: `⏸️ **${questTag(quest)}** paused at **${fmtElapsed(questElapsed(getQuest(gid, number)))}**. The clock and the log are kept.` });
    }
    if (!paused) return interaction.reply({ content: '❌ It is already running.', ephemeral: true });
    updateQuest(gid, number, { paused: 0, started_at: Date.now() });
    await syncQuestBook(interaction.client, interaction.guild, gid, getQuest(gid, number));
    logQuestEvent(gid, number, 'resume', 'Resumed', uid);
    await questAnnounce(interaction.client, getQuest(gid, number), `▶️ Resumed at **${fmtElapsed(questElapsed(getQuest(gid, number)))}**.`);
    return interaction.reply({ content: `▶️ **${questTag(quest)}** resumed at **${fmtElapsed(questElapsed(getQuest(gid, number)))}**.` });
  }

  if (sub === 'dm') {
    if (!gm) return interaction.reply({ content: '❌ The DM roster is for GMs.', ephemeral: true });
    const style = interaction.options?.getString?.('style');
    const brief = interaction.options?.getString?.('brief');
    const available = interaction.options?.getBoolean?.('available');
    const cur = db.prepare('SELECT * FROM gm_profiles WHERE guild_id=? AND user_id=?').get(gid, uid);
    db.prepare(`INSERT INTO gm_profiles (guild_id, user_id, style, brief, available) VALUES (?,?,?,?,?)
      ON CONFLICT(guild_id, user_id) DO UPDATE SET style=excluded.style, brief=excluded.brief, available=excluded.available`)
      .run(gid, uid, style ?? cur?.style ?? null, brief ?? cur?.brief ?? null,
           available === null || available === undefined ? (cur?.available ?? 1) : (available ? 1 : 0));
    const posted = await refreshDmRoster(interaction.client, interaction.guild, gid);
    return interaction.reply({ ephemeral: true, content: posted
      ? `🎲 Your DM card is on the roster${available === false ? ' (marked away)' : ''} — <#${getConfig(gid)?.quest_dm_thread}>.`
      : '🎲 Card saved. No roster thread yet — an Admin sets one up with `/config channels questplanning channel:#gm-forum`.' });
  }

  if (sub === 'npc') {
    if (!gm) return interaction.reply({ content: '❌ Only GMs attach NPCs.', ephemeral: true });
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const name = interaction.options?.getString?.('name');
    const npc = getNpc(gid, name);
    if (!npc) return interaction.reply({ content: `❌ No NPC named **${name}**.`, ephemeral: true });
    const fid = npcFighterId(npc.name);
    if (interaction.options?.getBoolean?.('remove')) {
      const removed = removeQuestMember(gid, quest.number, fid);
      if (!removed) return interaction.reply({ content: `🎭 **${npc.name}** wasn't attached.`, ephemeral: true });
      await questAnnounce(interaction.client, quest, `🎭 NPC detached: **${npc.name}**.`, { board: false });
      return interaction.reply({ content: `🎭 **${npc.name}** detached from **${questTag(quest)}**.` });
    }
    setQuestMember(gid, quest.number, fid, 'npc');
    await questAnnounce(interaction.client, quest, `🎭 NPC attached: **${npc.name}**.`, { board: false });
    return interaction.reply({ content: `🎭 **${npc.name}** attached to **${questTag(quest)}** — they'll be on the run record.` });
  }

  if (sub === 'history') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const root = questRootNumber(quest);
    const rootQuest = root === quest.number ? quest : (getQuest(gid, root) ?? quest);
    const runs = db.prepare('SELECT * FROM quest_runs WHERE guild_id=? AND root_number=? ORDER BY completed_at').all(gid, root);
    if (!runs.length) return interaction.reply({ content: `🏁 **${questTag(rootQuest)}** has no completed runs yet.`, ephemeral: true });
    const lines = [`🏁 **${questTag(rootQuest)}** — completed **${runs.length}** time${runs.length === 1 ? '' : 's'}`, ''];
    let k = 0;
    for (const r of runs) {
      k++;
      const gmName = r.gm_id ? await getDisplayName(interaction.guild, r.gm_id) : '—';
      const partyIds = JSON.parse(r.party || '[]');
      const partyNames = [];
      for (const id of partyIds) partyNames.push(await getDisplayName(interaction.guild, id));
      const npcNames = JSON.parse(r.npcs || '[]');
      lines.push(`**#${k}** — <t:${Math.floor(r.completed_at / 1000)}:d> · GM **${gmName}**${r.number !== root ? ` · _instance #${r.number}_` : ''}`);
      lines.push(`👥 ${partyNames.join(', ') || '—'}   🎭 ${npcNames.join(', ') || '—'}`);
      lines.push('');
    }
    return replyLong(interaction, lines, { ephemeral: true });
  }

  if (sub === 'stage') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const stage = interaction.options?.getString?.('stage');
    updateQuest(gid, quest.number, { stage });
    const fresh = getQuest(gid, quest.number);
    await syncQuestPipeline(interaction.client, interaction.guild, gid, fresh);
    const S = QUEST_STAGES.find(([k]) => k === stage);
    await announceStage(interaction.client, gid, fresh, `${S[1]} Stage → **${S[2]}**.`);
    return interaction.reply({ content: `${S[1]} **${questTag(quest)}** → **${S[2]}**.` });
  }

  if (sub === 'archive') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    if (quest.status === 'completed') return interaction.reply({ content: '❌ Completed quests keep their record — nothing to archive.', ephemeral: true });
    updateQuest(gid, quest.number, { status: 'archived', stage: 'archived' });
    const fresh = getQuest(gid, quest.number);
    await refreshQuestPost(interaction.client, interaction.guild, fresh);   // the Apply button drops
    await questAnnounce(interaction.client, fresh, '🗄️ Taken off the board — applications are closed. `/quest post` re-lists it.');
    if (fresh.post_channel_id) {
      try {
        const bt = await interaction.client.channels.fetch(fresh.post_channel_id);
        if (bt?.isThread?.()) { await bt.setLocked(true).catch(() => {}); await bt.setArchived(true); }
      } catch { /* best-effort */ }
    }
    await syncQuestPipeline(interaction.client, interaction.guild, gid, fresh);
    return interaction.reply({ content: `🗄️ **${questTag(quest)}** is off the board.` });
  }

  if (sub === 'note') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    if (quest.status !== 'active') return interaction.reply({ content: '❌ That quest is not running.', ephemeral: true });
    const text = interaction.options?.getString?.('text');
    const kind = interaction.options?.getString?.('kind') || 'note';
    logQuestEvent(gid, number, kind, text, uid);
    const pub = interaction.options?.getBoolean?.('public') ?? false;
    await questAnnounce(interaction.client, quest, `${QUEST_EVENT_ICON[kind] ?? '📝'} \`${fmtElapsed(questElapsed(quest))}\` — ${text}`, { board: pub });
    return interaction.reply({ content: `${QUEST_EVENT_ICON[kind] ?? '📝'} \`${fmtElapsed(questElapsed(quest))}\` — ${text}` });
  }

  if (sub === 'timeline') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    const events = questEvents(gid, number);
    if (!events.length) return interaction.reply({ content: `📜 **${questTag(quest)}** has nothing logged yet.`, ephemeral: true });
    return replyLong(interaction, [
      `📜 **${questTag(quest)}** — ${quest.paused ? '⏸️ paused at' : 'running,'} **${fmtElapsed(questElapsed(quest))}**`, '',
      ...events.map(questEventLine)], { ephemeral: true });
  }

  if (sub === 'complete') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    if (quest.status === 'completed') return interaction.reply({ content: '❌ That quest is already completed.', ephemeral: true });
    const party = getQuestMembers(gid, number, 'party');
    if (!party.length) return interaction.reply({ content: '❌ No party members to reward. Approve applicants first.', ephemeral: true });

    // This does several network round-trips (name lookups, post refresh, optional
    // cross-channel announce) — defer so we never miss Discord's 3s ack window.
    await interaction.deferReply();
    const nameCache = new Map();

    // Auto-award merits to each party member
    const awarded = [];
    for (const id of party) {
      const after = quest.merit_reward > 0 ? addMerits(gid, id, quest.merit_reward) : getMerits(gid, id);
      if (quest.merit_reward > 0) {
        logHistory(gid, { kind: 'merit', userId: id, amount: quest.merit_reward, reason: questTag(quest), questNumber: quest.number, actorId: uid });
      }
      awarded.push({ id, after });
    }
    // Stop the stopwatch before anything else, so the summary reports the run
    // rather than however long the paperwork took.
    const runMs = questElapsed(quest);
    logQuestEvent(gid, number, 'end', 'Quest complete', uid);
    updateQuest(gid, number, { status: 'completed', elapsed_ms: runMs, paused: 1, started_at: null });
    await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, number));

    const lines = [`🎉 **${questTag(quest)}** complete!`, `⏱️ Ran for **${fmtElapsed(runMs)}**.`, ''];
    if (quest.merit_reward > 0) {
      lines.push(`🎖️ **+${quest.merit_reward}** merit${quest.merit_reward === 1 ? '' : 's'} awarded to:`);
      for (const a of awarded) {
        const nm = await getDisplayNameCached(interaction.guild, a.id, nameCache);
        const { current } = rankProgress(gid, a.after);
        const ch = getChar(gid, a.id);
        const elig = current && current.name !== ch?.rank_name ? ` ✅ eligible for **${current.name}**` : '';
        lines.push(`• ${nm} — now **${a.after}**${elig}`);
      }
    } else {
      lines.push('_No merit reward set for this quest._');
    }
    if (quest.rewards) {
      const partyNames = [];
      for (const id of party) partyNames.push(await getDisplayNameCached(interaction.guild, id, nameCache));
      lines.push('', `🎁 **GM to distribute:** ${quest.rewards}`);
      lines.push(`Party: ${partyNames.join(', ')}`);
    }
    {
      const done = getQuest(gid, number);
      updateQuest(gid, number, { stage: 'completed', stage_at: Date.now() });
      // The run record: who ran it, who was on it, which NPCs took part —
      // keyed to the ROOT quest so instances share one counter.
      const root = questRootNumber(done);
      const npcIds = getQuestMembers(gid, number, 'npc');
      const npcNames = npcIds.map(id => npcNameFromFighter(id));
      db.prepare('INSERT INTO quest_runs (guild_id, root_number, number, completed_at, gm_id, party, npcs) VALUES (?,?,?,?,?,?,?)')
        .run(gid, root, number, Date.now(), done.gm_id ?? uid, JSON.stringify(party), JSON.stringify(npcNames));
      const runCount = db.prepare('SELECT COUNT(*) AS c FROM quest_runs WHERE guild_id=? AND root_number=?').get(gid, root).c;
      await syncQuestPipeline(interaction.client, interaction.guild, gid, getQuest(gid, number));
      const rootQuest = root === number ? getQuest(gid, number) : getQuest(gid, root);
      if (rootQuest?.plan_thread_id) {
        const gmName = await getDisplayNameCached(interaction.guild, done.gm_id ?? uid, nameCache);
        const rec = `🏁 **Run #${runCount}** — <t:${Math.floor(Date.now() / 1000)}:d> · ⏱️ ${fmtElapsed(runMs)} · GM **${gmName}**\n👥 ${partyNames.join(', ') || '—'}\n🎭 ${npcNames.join(', ') || '—'}`;
        await questAnnounce(interaction.client, rootQuest, rec, { board: false });
      }
      await refreshDmRoster(interaction.client, interaction.guild, gid);
      await questAnnounce(interaction.client, done, `🎉 **Complete!** Run **#${runCount}** of this adventure — ran for **${fmtElapsed(runMs)}**${quest.merit_reward > 0 ? ` — **+${quest.merit_reward}** merit${quest.merit_reward === 1 ? '' : 's'} to the party` : ''}.`);
      // The board thread's tale is told — tuck it away.
      if (done.post_channel_id) {
        try {
          const bt = await interaction.client.channels.fetch(done.post_channel_id);
          if (bt?.isThread?.()) await bt.setArchived(true);
        } catch { /* best-effort */ }
      }
    }

    // The summary: the whole timeline, the party, and how long it took.
    const partyNames = [];
    for (const id of party) partyNames.push(await getDisplayNameCached(interaction.guild, id, nameCache));
    const events = questEvents(gid, number);
    const runner = getQuest(gid, number)?.gm_id ?? uid;
    const runnerName = await getDisplayNameCached(interaction.guild, runner, nameCache);
    const styleLabel = gmStyleLabel(quest.gm_style);
    const summary = [
      `📜 **${questTag(quest)}** — quest summary`,
      `🎲 Run by **${runnerName}**${styleLabel ? ` · ${styleLabel}` : ''}`,
      `⏱️ **${fmtElapsed(runMs)}** · 👥 ${partyNames.join(', ')}`,
      '─────────────────────────────',
      ...(events.length ? events.map(questEventLine) : ['_Nothing was logged._']),
    ];
    if (quest.merit_reward > 0) summary.push('', `🎖️ +${quest.merit_reward} merit each.`);
    if (quest.rewards) summary.push(`🎁 ${quest.rewards}`);

    // Post it where a GM asked for it, and keep the link so it can hang off
    // each player's standing page.
    let summaryUrl = null;
    const logChId = getConfig(gid)?.quest_log_channel;
    if (logChId) {
      try {
        const logCh = await interaction.client.channels.fetch(logChId);
        const chunks = chunkLines(summary);
        let first = null;
        for (const [i, c] of chunks.entries()) {
          const m = await logCh.send({ content: c, allowedMentions: { parse: [] } });
          if (i === 0) first = m;
        }
        if (first) summaryUrl = `https://discord.com/channels/${gid}/${logCh.id}/${first.id}`;
      } catch (err) { console.error('[quest] could not post summary:', err?.message || err); }
    }
    const ins = db.prepare(`INSERT INTO quest_summaries (guild_id,number,user_id,quest_name,url,duration_ms,ended_at)
                            VALUES (?,?,?,?,?,?,?)
                            ON CONFLICT(guild_id,number,user_id) DO UPDATE SET url=excluded.url, duration_ms=excluded.duration_ms`);
    for (const id of party) ins.run(gid, number, id, questTag(quest), summaryUrl, runMs, Date.now());

    lines.push('', ...(summaryUrl
      ? [`📜 [Read the full summary](${summaryUrl}) — it is on everyone's \`/char view standing\` too.`]
      : ['_No quest log channel set, so the summary was not posted — a GM can set one with `/config channels questlog`._']));
    if (!logChId) lines.push(...summary.slice(2, 14));

    // Announce in the designated run channel if set and different from here
    const announce = lines.join('\n');
    if (quest.run_channel_id && quest.run_channel_id !== interactionChannelId(interaction)) {
      try { const rc = await interaction.client.channels.fetch(quest.run_channel_id); await rc.send(announce); } catch {}
      return interaction.editReply({ content: `${announce}\n\n_(Also posted in <#${quest.run_channel_id}>.)_` });
    }
    return interaction.editReply({ content: announce });
  }

  if (sub === 'delete') {
    const quest = await requireQuest(interaction, gid);
    if (!quest) return;
    const number = quest.number;
    const kids = db.prepare('SELECT number, name FROM quests WHERE guild_id=? AND instance_of=?').all(gid, number);
    const kidNote = kids.length ? ` **Its ${kids.length} instance${kids.length > 1 ? 's' : ''}** (${kids.map(k => `#${k.number}`).join(', ')}) **go with it, threads and all.**` : '';
    return requestConfirm(interaction, `Delete **${questTag(quest)}** permanently? This clears its roster and **deletes every trace in the related channels** — its board ${getConfig(gid)?.quest_forum ? 'thread' : 'post'}, its planning thread (applications and notes included), its book entry and its create card.${kidNote}`, async () => {
      const doomed = [...db.prepare('SELECT * FROM quests WHERE guild_id=? AND instance_of=?').all(gid, number), quest];
      for (const q of doomed) {
        await sweepQuestChannels(interaction.client, gid, q);
        deleteQuest(gid, q.number);
      }
      return `🗑️ **${questTag(quest)}** deleted${doomed.length > 1 ? ` — with ${doomed.length - 1} instance${doomed.length > 2 ? 's' : ''}, threads and all` : ''}.`;
    });
  }
}

// Ask for confirmation. `action` is an async fn run if confirmed.
async function requestConfirm(interaction, promptText, action) {
  const token = `${interaction.user.id}_${Date.now()}_${Math.floor(Math.random()*1000)}`;
  pendingConfirms.set(token, { action, userId: interaction.user.id, expires: Date.now() + 60000 });
  // Auto-expire after 60s
  setTimeout(() => pendingConfirms.delete(token), 60000);
  await interaction.reply({ content: `⚠️ ${promptText}`, components: [makeConfirmButtons(token)], ephemeral: true });
}

// Ask the GM why before turning something down. The reason is optional — a GM
// in a hurry can submit it blank — but asking is the point: "rejected" with no
// note leaves the player guessing at what to change before they resubmit.
// showModal must be the first reply to the button, so nothing may be deferred
// or replied to before this runs.
function showRejectReasonModal(interaction, customId, title, placeholder) {
  const { ModalBuilder, TextInputBuilder, TextInputStyle, ActionRowBuilder } = require('discord.js');
  const modal = new ModalBuilder().setCustomId(customId.slice(0, 100)).setTitle(title.slice(0, 45));
  const reason = new TextInputBuilder()
    .setCustomId('reason').setLabel('Reason (optional)')
    .setPlaceholder(placeholder).setStyle(TextInputStyle.Paragraph)
    .setRequired(false).setMaxLength(900);
  modal.addComponents(new ActionRowBuilder().addComponents(reason));
  return interaction.showModal(modal);
}

// Trim a GM's note to something that fits a Discord message comfortably.
function cleanReason(raw) {
  const t = String(raw ?? '').trim();
  return t ? t.slice(0, 900) : null;
}

async function handleSheetApprovalButton(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can approve sheets.', ephemeral: true });
  const [action, uid] = interaction.customId.split(':');
  const ch = getChar(gid, uid);
  if (!ch) return interaction.reply({ content: '❌ That character sheet no longer exists.', ephemeral: true });
  // Turning a sheet down asks for a reason first; the decision is applied when
  // the modal comes back.
  if (action === 'sheetno') {
    return showRejectReasonModal(interaction, `sheetreject:${uid}`,
      'Reject character sheet', 'e.g. STR is too high for a starting character — 5 max.');
  }
  const nm = await getDisplayName(interaction.guild, uid);
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  const approved = true;
  upsertChar(gid, uid, { approval_state: 'approved', approval_reason: null });

  // An approved character earns a page of their own, if a forum is set. Purely
  // additive — a failure here must never undo an approval.
  let pageNote = '';
  try {
    const who = await getDisplayName(interaction.guild, uid);
    const made = await ensureCharPage(interaction.client, interaction.guild, uid, who);
    if (made?.url) pageNote = `\n📖 Their page: ${made.url}`;
  } catch (err) {
    console.error('[charpage] could not create:', err?.message || err);
    pageNote = `\n⚠️ _Couldn't make their forum page: ${err?.message || err}_`;
  }

  // Update the request post so the queue reflects the decision
  try {
    await interaction.message.edit({
      content: `${interaction.message.content}\n\n${approved ? '✅' : '🚫'} **${approved ? 'Approved' : 'Rejected'}** by ${gmName}`,
      components: [],
    });
  } catch {}

  const notice = `✅ **Your character sheet was approved** by ${gmName} in **${interaction.guild.name}** — you can roll and fight now.`;
  const told = await notifyPlayer(interaction, gid, uid, notice);
  return interaction.reply({
    content: `✅ <@${uid}> (**${nm}**) approved — they can roll and fight now.` + deliveryNote(told),
    allowedMentions: { parse: [] } });
}

// A GM's decision lands in a channel the player can't see, so tell them: DM
// first, then the channel they submitted from. Returns how it got through.
async function notifyPlayer(interaction, gid, uid, notice) {
  try {
    const user = await interaction.client.users.fetch(uid);
    await user.send(notice);
    return 'DM';
  } catch {
    const srcId = getChar(gid, uid)?.approval_src_channel;
    if (srcId) {
      try {
        const srcChan = await interaction.client.channels.fetch(srcId);
        await srcChan.send({ content: `<@${uid}> ${notice}`, allowedMentions: { users: [uid] } });
        return 'channel';
      } catch {}
    }
    return null;
  }
}
function deliveryNote(told) {
  return told === 'DM' ? ' _(player notified by DM)_'
       : told === 'channel' ? ' _(DM blocked — notified in their submission channel)_'
       : ' ⚠️ _couldn\'t reach the player — tell them directly._';
}

// The reason modal came back — apply the rejection and pass the note on.
async function handleSheetRejectModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can reject sheets.', ephemeral: true });
  const uid = interaction.customId.split(':')[1];
  const ch = getChar(gid, uid);
  if (!ch) return interaction.reply({ content: '❌ That character sheet no longer exists.', ephemeral: true });
  const reason = cleanReason(interaction.fields.getTextInputValue('reason'));
  const nm = await getDisplayName(interaction.guild, uid);
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  upsertChar(gid, uid, { approval_state: 'rejected', approval_reason: reason });

  // Stamp the queue post. Opened from a button, so the message is available —
  // but don't assume it, and never let a failed edit block the decision.
  try {
    await interaction.message?.edit({
      content: `${interaction.message.content}\n\n🚫 **Rejected** by ${gmName}${reason ? `\n💬 ${reason}` : ''}`,
      components: [],
    });
  } catch {}

  const notice = `🚫 **Your character sheet was rejected** by ${gmName} in **${interaction.guild.name}**.\n`
    + (reason ? `💬 **Reason:** ${reason}\n` : '')
    + `You can fix it and try again yourself — change whatever needs changing with \`/char set\` or \`/char create\` and it goes straight back to the GMs.\n`
    + `If you think it was fine as it stands, \`/char submit\` sends it again unchanged.`;
  const told = await notifyPlayer(interaction, gid, uid, notice);
  return interaction.reply({
    content: `🚫 <@${uid}> (**${nm}**) rejected${reason ? ` — “${reason}”` : ' with no reason given'}.` + deliveryNote(told),
    allowedMentions: { parse: [] } });
}

// Same again for a declined export. Nothing is stored — the request is simply
// dropped — so the reason only has to reach the player and the queue post.
async function handleExportRejectModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can decline exports.', ephemeral: true });
  const uid = interaction.customId.split(':')[1];
  const req = getExportRequest(gid, uid);
  const nm = await getDisplayName(interaction.guild, uid);
  const gmName = await getDisplayName(interaction.guild, interaction.user.id);
  const reason = cleanReason(interaction.fields.getTextInputValue('reason'));
  if (!req) return interaction.reply({ content: '⏰ That export request is no longer pending.', ephemeral: true });
  clearExportRequest(gid, uid);

  try {
    await interaction.message?.edit({
      content: `${interaction.message.content}\n\n🚫 **Declined** by ${gmName}${reason ? `\n💬 ${reason}` : ''}`,
      components: [],
    });
  } catch {}

  const notice = `🚫 **Your sheet export was declined** by ${gmName} in **${interaction.guild.name}**.\n`
    + (reason ? `💬 **Reason:** ${reason}\n` : '')
    + `You can ask again whenever you like — run \`/char export\` and it goes back to the GMs.`;
  let told = 'DM';
  try {
    const user = await interaction.client.users.fetch(uid);
    await user.send(notice);
  } catch {
    told = null;
    if (req.src_channel) {
      try {
        const srcChan = await interaction.client.channels.fetch(req.src_channel);
        await srcChan.send({ content: `<@${uid}> ${notice}`, allowedMentions: { users: [uid] } });
        told = 'channel';
      } catch {}
    }
  }
  return interaction.reply({
    content: `🚫 Export declined for <@${uid}> (**${nm}**)${reason ? ` — “${reason}”` : ''}.` + deliveryNote(told),
    allowedMentions: { parse: [] } });
}

// Submission from the /npc say writing box.
async function handleNpcSayModal(interaction) {
  const gid = interaction.guild.id;
  if (!(await isGm(interaction.guild, interaction.user.id)))
    return interaction.reply({ content: '❌ Only GMs can post as NPCs.', ephemeral: true });
  const npcName = interaction.customId.slice('npcsay:'.length);
  const npc = getNpc(gid, npcName);
  if (!npc) return interaction.reply({ content: `❌ NPC **${npcName}** no longer exists.`, ephemeral: true });

  const action = interaction.fields.getTextInputValue('action');
  const speech = interaction.fields.getTextInputValue('speech');
  const body = composeNpcSay({ action, speech });
  if (!body) return interaction.reply({ content: '❌ Both boxes were empty — nothing posted.', ephemeral: true });
  if (body.length > 1800) return interaction.reply({ content: '❌ Too long (max 1800 characters).', ephemeral: true });

  const chan = await interactionChannel(interaction);
  if (!chan) return interaction.reply({ content: '❌ I can\'t access this channel.', ephemeral: true });
  const said = await postAsNpc(chan, gid, npc.name, body);
  if (!said) return interaction.reply({ content: `❌ I couldn't post in this channel — check my permissions here.`, ephemeral: true });
  mirrorNpcSay(gid, { gmId: interaction.user.id, npcName: npc.name, channelId: chan.id,
    messageId: said?.id ?? null, text: body });
  return interaction.reply({ content: `🎭 Posted as **${npc.name}**.`, ephemeral: true });
}

async function handleQuestButton(interaction) {
  const gid = interaction.guild.id, uid = interaction.user.id;
  const [action, numStr] = interaction.customId.split(':');
  const number = parseInt(numStr, 10);
  const quest = getQuest(gid, number);
  if (!quest) return interaction.reply({ content: '\u274c That quest no longer exists.', ephemeral: true });
  const res = action === 'questapply'
    ? await questApply(interaction.guild, quest, uid)
    : await questWithdraw(interaction.guild, quest, uid);
  if (res.error) return interaction.reply({ content: res.error, ephemeral: true });
  await refreshQuestPost(interaction.client, interaction.guild, getQuest(gid, number));
  return interaction.reply({ content: res.ok, ephemeral: true });
}

async function handleConfirmButton(interaction) {
  const [decision, token] = interaction.customId.split(':');
  const pending = pendingConfirms.get(token);

  if (!pending) {
    return interaction.update({ content: '⏰ This confirmation has expired. Please run the command again.', components: [] }).catch(()=>{});
  }
  if (interaction.user.id !== pending.userId) {
    return interaction.reply({ content: '❌ This confirmation isn\'t for you.', ephemeral: true }).catch(()=>{});
  }

  pendingConfirms.delete(token);

  if (decision === 'cancel') {
    return interaction.update({ content: '❌ Cancelled — nothing was changed.', components: [] }).catch(()=>{});
  }

  // Confirmed — run the action
  try {
    await interaction.update({ content: '⏳ Working...', components: [] });
    const result = await pending.action();
    await interaction.editReply({ content: result || '✅ Done.', components: [] });
  } catch (err) {
    console.error('Confirm action error:', err);
    await interaction.editReply({ content: `❌ Action failed: ${err.message}`, components: [] }).catch(()=>{});
  }
}
